// Згенеровано tools/build_grammar.py з grammar/*.json. Не редагувати вручну.
window.GRAMMAR = {"sections":[{"id":"basics","title":"Основи речення","topics":["word-order","to-be","pronouns","plurals","articles","this-that","there-is","questions","negatives","imperatives"]},{"id":"present","title":"Теперішній час","topics":["present-simple","present-continuous","simple-vs-continuous","present-perfect","perfect-vs-past","present-perfect-continuous"]},{"id":"past","title":"Минулий час","topics":["past-simple","irregular-verbs","past-continuous","past-perfect","used-to"]},{"id":"future","title":"Майбутній час","topics":["will","going-to","time-clauses","future-continuous-perfect"]},{"id":"modals","title":"Модальні дієслова","topics":["can-could","must-have-to","should","might-must-cant","requests-offers"]},{"id":"describe","title":"Опис і кількість","topics":["adjectives-adverbs","comparatives","too-enough-so-such","quantifiers"]},{"id":"prepositions","title":"Прийменники","topics":["prepositions-time","prepositions-place"]},{"id":"complex","title":"Складні речення","topics":["conditionals-0-1","conditionals-2","conditionals-3-wish","passive","reported-speech","relative-clauses","gerund-infinitive","linking-words","indirect-questions","question-tags"]},{"id":"everyday","title":"Корисне щодня","topics":["phrasal-verbs","make-do-get-have"]}],"topics":{"word-order":{"id":"word-order","level":"A1","title":"Word order","uk":"Порядок слів у реченні","summary":"хто → що робить → що: Tom paints the walls; It's cold","minutes":7,"blocks":[{"t":"p","text":"В українській порядок слів вільний: «Я люблю каву», «Каву я люблю», «Люблю я каву» — усе правильно, бо закінчення показують, хто що робить. В англійській закінчень майже немає, тому роль слова показує **його місце**. Порядок жорсткий: **підмет** (хто або що виконує дію) → **дієслово** (що робить) → **додаток** (кого або що)."},{"t":"rule","title":"Основна схема","lines":["**хто** + **що робить** + **кого / що** + **де** + **коли**","Tom + painted + the walls + in the hall + yesterday."]},{"t":"ex","items":[["Sarah **called** Tom.","Сара подзвонила Томові."],["Tom **called** Sarah.","Том подзвонив Сарі."],["I **don't drink** coffee.","Каву я не п'ю."],["We **fixed** the roof yesterday.","Учора ми полагодили дах."]]},{"t":"p","text":"Поміняв місцями Sarah і Tom — і зміст став протилежним. Українською «Томові подзвонила Сара» означає те саме, що «Сара подзвонила Томові», а англійською так не вийде. Тому будуй речення не так, як звучить по-нашому, а за схемою: спочатку той, хто діє."},{"t":"h","text":"Підмет обов'язковий"},{"t":"p","text":"Українською ми часто обходимося без підмета: «Холодно», «Уже пізно», «Працюю в Дубліні». В англійському реченні підмет є **завжди**. Навіть коли й так зрозуміло, хто діє, його називаємо: **I** work in Dublin. А коли справжнього «хто» немає (погода, час, відстань, загальна оцінка), ставимо **it**, яке не перекладається."},{"t":"ex","items":[["**It's** cold today.","Сьогодні холодно."],["**It's** raining again.","Знову йде дощ."],["**It's** half past seven.","Пів на восьму."],["**It's** ten kilometres to Gorey.","До Горі десять кілометрів."],["**It's** too late to start now.","Уже запізно починати."],["**I** work in Dublin.","Працюю в Дубліні."]]},{"t":"tip","text":"Наше «є, існує» («Є проблема», «На об'єкті є вода») — це не it, а **there is / there are**: There's a problem. Про це окрема тема."},{"t":"mistake","wrong":"Is cold today.","right":"It's cold today.","why":"Без підмета речення неповне. Для погоди, часу й відстані підмет — it: It's cold. It's late."},{"t":"h","text":"Дієслово і додаток не розриваємо"},{"t":"p","text":"Те, на що спрямована дія (додаток), стоїть **одразу після дієслова**. Слова «добре», «дуже», «щодня» між ними не вставляємо: вони йдуть після додатка. Слова часу (every day, yesterday) можна ще поставити на початок речення."},{"t":"ex","items":[["I speak **English** well.","Я добре розмовляю англійською."],["I like **this job** very much.","Мені дуже подобається ця робота."],["We clean **the van** every Friday.","Ми щоп'ятниці миємо фургон."]]},{"t":"mistake","wrong":"I like very much football.","right":"I like football very much.","why":"Like football — одне ціле. Very much ставимо після додатка, а не між дієсловом і додатком."},{"t":"h","text":"Спочатку де, потім коли"},{"t":"p","text":"Коли в реченні є і місце, і час, зазвичай кажуть спочатку **де**, потім **коли**: I work **in Wexford** **every day**. Час також можна поставити на початок речення: **Every day** I work in Wexford."},{"t":"ex","items":[["I go **to the gym** **three times a week**.","Я ходжу в спортзал тричі на тиждень."],["She arrived **at the site** **at seven**.","Вона приїхала на об'єкт о сьомій."],["We're working **in Dublin** **this week**.","Цього тижня ми працюємо в Дубліні."],["**On Monday** we start a new job in Gorey.","У понеділок ми починаємо новий об'єкт у Горі."]]},{"t":"h","text":"Прикметник перед іменником"},{"t":"p","text":"Ознака (прикметник: big, new, wet) стоїть **перед** предметом: a **big** van, **new** boots. В українській можна сказати й «черевики нові купив», а англійською — лише new boots. Якщо прикметників два, розмір зазвичай перед кольором: a **big white** van. Після am, is, are прикметник може стояти й без іменника, після них: The wall is **wet**."},{"t":"ex","items":[["She's got a **big white** van.","У неї великий білий фургон."],["I need a **long** ladder.","Мені потрібна довга драбина."],["I bought **new** boots.","Я купив нові черевики."],["The wall is still **wet**.","Стіна ще мокра."]]},{"t":"h","text":"Кому і що: give me the trowel"},{"t":"p","text":"Після give, pass, send, show, bring, lend часто є і **кому**, і **що**. Для цього є два порядки:"},{"t":"rule","title":"Два варіанти","lines":["give + **кому** + **що**: Give **me** the trowel.","give + **що** + **to** + **кому**: Give the trowel **to me**.","з it / them: Give **it to me**. Send **them to Tom**."]},{"t":"p","text":"Запам'ятай: **to** ставимо тільки тоді, коли «кому» йде **після** речі. Якщо «кому» одразу після дієслова — просто give me, pass him, без to."},{"t":"ex","items":[["Can you pass **me** the drill?","Можеш передати мені дриль?"],["I'll show **you** the kitchen.","Я покажу тобі кухню."],["Tom sent the photos **to Sarah**.","Том надіслав фото Сарі."],["Give **it to me**, please.","Дай мені це, будь ласка."]]},{"t":"mistake","wrong":"Give to me the trowel.","right":"Give me the trowel.","why":"Коли «кому» стоїть одразу після give, to не потрібне. З to — тільки після речі: Give the trowel to me."},{"t":"mistake","wrong":"Explain me the job.","right":"Explain the job to me.","why":"Explain (пояснити) і say (сказати) так не працюють: «кому» в них тільки з to. Explain it to me. What did he say to you?"},{"t":"h","text":"Куди ставити always, usually, never"},{"t":"p","text":"Слова «як часто» (always, usually, often, never) ставимо **перед** звичайним дієсловом, але **після** am, is, are. Детальніше — у темі Present Simple."},{"t":"ex","items":[["I **always start** at eight.","Я завжди починаю о восьмій."],["He's **never** late.","Він ніколи не запізнюється."],["We **usually have** lunch in the van.","Ми зазвичай обідаємо у фургоні."]]},{"t":"h","text":"У питаннях порядок інший"},{"t":"p","text":"В українській питання часто відрізняється від ствердження лише інтонацією: «Ти готовий?» В англійській міняється порядок: допоміжне дієслово (am, is, are, do, does, did) або can стає **перед** підметом. Детальніше — у темі «Questions»."},{"t":"ex","items":[["**Are you** ready?","Ти готовий?"],["**Is it** far to Dublin?","До Дубліна далеко?"],["Where **do you** live?","Де ти живеш?"],["What time **does the shop** open?","О котрій відчиняється магазин?"]]},{"t":"mistake","wrong":"Where you live?","right":"Where do you live?","why":"Після питального слова потрібне допоміжне дієслово перед підметом: Where do you live? Where is the van?"}],"tasks":[{"type":"choice","q":"___ cold in the van this morning.","uk":"Сьогодні вранці у фургоні холодно.","opts":["Is","It's","It"],"a":1,"why":"Підмет обов'язковий: для погоди й температури це it. І дієслово is пропустити не можна: It's cold."},{"type":"input","q":"___ raining again.","uk":"Знову йде дощ.","a":["It's","It is"],"why":"Про погоду кажемо з підметом it: It's raining. Без it речення неповне."},{"type":"choice","q":"Sarah has got a ___.","uk":"У Сари великий білий фургон.","opts":["van big white","big white van","white van big"],"a":1,"why":"Прикметники стоять перед іменником, а розмір (big) зазвичай перед кольором (white)."},{"type":"choice","q":"I like ___.","uk":"Мені дуже подобається ця робота.","opts":["very much this job","this job very much","this very much job"],"a":1,"why":"Дієслово й додаток (like this job) не розриваємо. Very much ставимо після додатка."},{"type":"order","uk":"Учора я пофарбував кухню.","words":["painted","yesterday","the","I","kitchen"],"a":["I painted the kitchen yesterday.","Yesterday I painted the kitchen."],"why":"Хто (I) + що зробив (painted) + що (the kitchen). Час — у кінці або на початку, але не між дієсловом і додатком."},{"type":"choice","q":"He ___ on time.","uk":"Він завжди приходить вчасно.","opts":["always comes","comes always","is always come"],"a":0,"why":"Always ставимо перед звичайним дієсловом: he always comes. Is перед звичайним дієсловом у такому реченні не потрібне."},{"type":"choice","q":"Where ___?","uk":"Де ти живеш?","opts":["you live","do you live","you do live"],"a":1,"why":"У питанні допоміжне дієслово do стоїть перед підметом: Where do you live?"},{"type":"order","uk":"На вулиці холодно?","words":["cold","it","outside","is"],"a":["Is it cold outside?"],"why":"Підмет it потрібен і в питанні, а is переходить на початок: Is it cold outside?"},{"type":"input","q":"Can you pass ___ the hammer?","uk":"Можеш передати мені молоток?","a":["me"],"why":"Кому + що: pass me the hammer. To не потрібне, бо «кому» стоїть одразу після дієслова."},{"type":"input","q":"Give the trowel ___ me, please.","uk":"Дай мені кельму, будь ласка.","a":["to"],"why":"Коли «кому» йде після речі, перед ним ставимо to: give the trowel to me."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Поясни мені це, будь ласка.","opts":["Explain me it, please.","Explain it to me, please.","Explain to me it, please."],"a":1,"why":"Після explain «кому» завжди з to, а it ставимо перед to me: explain it to me. Explain me — помилка."},{"type":"order","uk":"Можеш мені це дати?","words":["me","can","it","you","to","give"],"a":["Can you give it to me?"],"why":"Питання: can стоїть перед підметом you. Коли річ — it, кажемо give it to me."}],"section":"basics"},"to-be":{"id":"to-be","level":"A1","title":"To be: am, is, are, was, were","uk":"Дієслово to be","summary":"бути: I'm tired, she's at work, we were late","minutes":7,"blocks":[{"t":"p","text":"**To be** означає «бути». В українській у теперішньому часі ми це слово пропускаємо: «Я втомлений», «Він на роботі». В англійській без нього не можна: **I am** tired, **he is** at work. Якщо в реченні немає іншого дієслова, потрібне **am**, **is** або **are**."},{"t":"ex","items":[["I**'m** a plasterer.","Я штукатур."],["She**'s** at work.","Вона на роботі."],["We**'re** from Ukraine.","Ми з України."],["It**'s** cold today.","Сьогодні холодно."]]},{"t":"h","text":"Теперішній час: am, is, are"},{"t":"table","head":["Хто","Повна форма","Скорочено"],"rows":[["I","I am","I**'m**"],["he / she / it","he is","he**'s**"],["you / we / they","you are","you**'re**"]]},{"t":"p","text":"Якщо підмет (хто або що виконує дію) — одна людина чи річ, ставимо **is**: my boss is, the van is. Якщо їх кілька — **are**: the tools are, Tom and Sarah are. Винятки: з **I** — am, а з **you** завжди are, навіть коли це одна людина."},{"t":"p","text":"У розмові майже завжди кажуть скорочено: I'm, he's, it's, we're, they're. Повну форму пишуть в офіційних листах або вживають для наголосу. Скорочення працює і після імені: **Tom's** at work = Tom is at work."},{"t":"h","text":"Заперечення: not"},{"t":"rule","title":"Заперечення","lines":["I **am not** = I**'m not**","he / she / it **is not** = **isn't**","you / we / they **are not** = **aren't**"]},{"t":"tip","text":"У стандартній англійській форми «amn't» немає (хоча в Ірландії її іноді почуєш), кажи **I'm not**. Для інших осіб є два однаково правильні варіанти: he **isn't** = he**'s not**, they **aren't** = they**'re not**."},{"t":"ex","items":[["I**'m not** ready yet.","Я ще не готовий."],["The boss **isn't** here today.","Боса сьогодні немає."],["They**'re not** from Dublin.","Вони не з Дубліна."],["It **isn't** far.","Це недалеко."]]},{"t":"h","text":"Питання й короткі відповіді"},{"t":"rule","title":"Питання","lines":["**Am** I …?","**Is** he / she / it …?","**Are** you / we / they …?"]},{"t":"p","text":"Щоб поставити питання, просто міняємо місцями підмет і am / is / are. Ніякого do тут не треба: **Are you** tired? (а не Do you tired?). Відповідаємо коротко тим самим словом: Yes, I am. No, he isn't."},{"t":"ex","items":[["**Are** you cold? — **Yes, I am.**","Тобі холодно? — Так."],["**Is** Tom at work? — **No, he isn't.**","Том на роботі? — Ні."],["**Where's** the van? — It's outside.","Де фургон? — Надворі."],["How old **are** you?","Скільки тобі років?"]]},{"t":"tip","text":"У короткій відповіді «так» скорочення **не** вживаємо: Yes, I **am**. Yes, she **is**. «Yes, I'm» — помилка. А в «ні» скорочення звичайне: No, I'm not. No, it isn't."},{"t":"h","text":"Минулий час: was, were"},{"t":"p","text":"У минулому все ще простіше — лише дві форми: **was** для I, he, she, it (і однини: the van was) і **were** для you, we, they (і множини: the tools were). Питання й короткі відповіді будуємо так само: **Were** you at work? — Yes, I **was**. / No, I **wasn't**."},{"t":"table","head":["Хто","Був / була","Не був"],"rows":[["I / he / she / it","was","wasn't"],["you / we / they","were","weren't"]]},{"t":"ex","items":[["I **was** tired yesterday.","Учора я був утомлений."],["We **were** in Dublin last week.","Минулого тижня ми були в Дубліні."],["The shop **wasn't** open.","Магазин не працював."],["It **was** very windy this morning.","Сьогодні вранці був сильний вітер."],["**Were** you at work on Saturday? — **No, I wasn't.**","Ти був на роботі в суботу? — Ні."]]},{"t":"h","text":"Коли вживаємо to be"},{"t":"list","items":["**Хто ти і звідки**: I'm Andrii. I'm from Ukraine.","**Професія** (з a / an): I'm **a** plasterer. She's **an** electrician.","**Вік**: I'm 24. Tom is 30.","**Стан і відчуття**: I'm cold. I'm hungry. I'm tired.","**Місце**: He's at work. The keys are in the van.","**Погода й час**: It's windy. It's six o'clock.","**Опис**: The wall is wet. The job is easy."]},{"t":"p","text":"Будь уважний: багато фраз, які в українській будуються з «мені» чи «маю», англійською кажуть через to be. Дослівно **I'm cold** — «я холодний», а означає «мені холодно»."},{"t":"ex","items":[["I'm **24**.","Мені 24 роки."],["I'm **cold**.","Мені холодно."],["Are you **hungry**?","Ти голодний?"],["You're **right**.","Ти маєш рацію."],["Sorry, I'm **late**.","Вибач, я запізнився."],["I'm **afraid** of dogs.","Я боюся собак."]]},{"t":"tip","text":"Перед професією в однині завжди **a** або **an**: I'm **a** plasterer, he's **an** electrician. У множині без них: They're plasterers."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I have 24 years.","right":"I'm 24.","why":"Вік — через to be: I'm 24 або I'm 24 years old. Have тут не підходить, а «I'm 24 years» без old — теж помилка."},{"t":"mistake","wrong":"She tired.","right":"She's tired.","why":"Без is речення неповне. Там, де в українській «є» пропускаємо, англійською ставимо am, is або are."},{"t":"mistake","wrong":"I am agree.","right":"I agree.","why":"Agree — звичайне дієслово «погоджуватися», am перед ним не потрібне. «Я не згоден» — I don't agree."},{"t":"mistake","wrong":"I am work here.","right":"I work here.","why":"Am, is, are не ставимо перед звичайним дієсловом. «Я тут працюю» — просто I work here."},{"t":"mistake","wrong":"I'm plasterer.","right":"I'm a plasterer.","why":"Перед професією в однині потрібне a або an."}],"tasks":[{"type":"choice","q":"My brother ___ a plasterer.","uk":"Мій брат штукатур.","opts":["am","is","are"],"a":1,"why":"My brother — це він (he), тому is."},{"type":"input","q":"The tools ___ in the van.","uk":"Інструменти у фургоні.","a":["are"],"why":"The tools — кілька речей (they), тому are."},{"type":"input","q":"I ___ cold. Can you close the window?","uk":"Мені холодно. Можеш зачинити вікно?","a":["am"],"why":"«Мені холодно» англійською — I am cold (I'm cold): стан і відчуття передаємо через to be."},{"type":"choice","q":"Is Sarah at home? — No, she ___.","uk":"Сара вдома? — Ні.","opts":["isn't","doesn't","not"],"a":0,"why":"Питання з is — і коротка відповідь з is: No, she isn't. Doesn't — для звичайних дієслів."},{"type":"choice","q":"Are you hungry? — Yes, ___.","uk":"Ти голодний? — Так.","opts":["I'm","I am","I do"],"a":1,"why":"У короткій відповіді «так» скорочення не вживаємо: Yes, I am. Do не підходить, бо в питанні are."},{"type":"order","uk":"Ти втомився?","words":["tired","you","are"],"a":["Are you tired?"],"why":"У питанні are стоїть перед підметом: Are you tired? Do тут не потрібне."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Мені 24 роки.","opts":["I have 24 years.","I'm 24.","I'm 24 years."],"a":1,"why":"Вік — через to be: I'm 24 або I'm 24 years old. Have не підходить, а years без old не кажуть."},{"type":"choice","q":"I ___ with you.","uk":"Я з тобою згоден.","opts":["am agree","agree","agreeing"],"a":1,"why":"Agree — звичайне дієслово «погоджуватися», тому am не потрібне: I agree."},{"type":"choice","q":"___ you at work yesterday?","uk":"Ти був учора на роботі?","opts":["Was","Were","Did"],"a":1,"why":"Минуле to be для you — were (навіть про одну людину). Did не підходить, бо іншого дієслова в реченні немає."},{"type":"input","q":"They ___ (not) ready yet.","uk":"Вони ще не готові.","a":["aren't","are not"],"why":"Заперечення для they: are not, скорочено aren't."},{"type":"input","q":"Tom ___ (not) at work yesterday. He was ill.","uk":"Учора Тома не було на роботі. Він хворів.","a":["wasn't","was not"],"why":"Минулий час, Tom — він, тому was not, скорочено wasn't."},{"type":"order","uk":"Чому ти вчора запізнився?","words":["late","you","why","yesterday","were"],"a":["Why were you late yesterday?"],"why":"«Запізнитися» — be late. Питання: why + were + you, а час у кінці."}],"section":"basics"},"pronouns":{"id":"pronouns","level":"A1","title":"Pronouns: I, me, my, mine","uk":"Займенники і присвійні форми","summary":"I – me – my – mine, it для речей, Tom's van, myself","minutes":8,"blocks":[{"t":"p","text":"Займенник — слово замість імені: я, він, вона, вони. В англійській у кожного займенника кілька форм, і вибір залежить від ролі в реченні: **I** — хто діє, **me** — кого / кому, **my** — чий (перед іменником), **mine** — чий (замість іменника). В українській ідея схожа (я, мене, мій), тож головне — запам'ятати таблицю."},{"t":"table","head":["Хто","Кого / кому","Чий + річ","Чий (сам)"],"rows":[["I","me","my","mine"],["you","you","your","yours"],["he","him","his","his"],["she","her","her","hers"],["it","it","its","—"],["we","us","our","ours"],["they","them","their","theirs"]]},{"t":"h","text":"I чи me"},{"t":"p","text":"**I, he, she, we, they** — підмет (хто виконує дію), стоять перед дієсловом: **I** work, **they** live. **Me, him, her, us, them** — після дієслова або після прийменника (for, with, to): call **me**, come with **us**. Наші «мене», «мені», «мною» — усе це **me**."},{"t":"ex","items":[["**She** called **me** yesterday.","Учора вона мені дзвонила."],["I don't know **him**.","Я його не знаю."],["Can you help **us**?","Можеш нам допомогти?"],["Wait for **me**!","Зачекай мене!"],["Tell **them** we're late.","Скажи їм, що ми запізнюємося."]]},{"t":"tip","text":"Коли ти і ще хтось виконуєте дію, кажи **Tom and I**: себе називаємо останнім, і форма — I. Перевірка: прибери Tom — залишиться «I went», а не «me went». Після дієслова — me: The boss called Tom and **me**."},{"t":"mistake","wrong":"Me and Tom went to Lidl.","right":"Tom and I went to Lidl.","why":"Підмет — I, а не me. У розмові «me and Tom» почуєш, але правильно Tom and I: себе називаємо останнім."},{"t":"h","text":"My чи mine"},{"t":"p","text":"**My, your, his, her, its, our, their** — завжди перед іменником: **my** van, **our** boss. **Mine, yours, his, hers, ours, theirs** — без іменника, замість нього: This van is **mine**. Whose is it? — It's **hers**."},{"t":"ex","items":[["**Our** boss is Irish.","Наш бос — ірландець."],["Is this **your** jacket? — No, it's not **mine**.","Це твоя куртка? — Ні, не моя."],["**Their** house is near Gorey.","Їхній будинок біля Горі."],["This drill is **hers**.","Цей дриль її."],["Kate is a friend of **mine**.","Кейт — моя подруга."]]},{"t":"tip","text":"Слова «свій» в англійській немає. Обираєш за тим, **хто власник**: я — my, ти — your, він — his, вона — her, ми — our, вони — their. «Він узяв свої інструменти» → He took **his** tools. «Я бачив свого брата» → I saw **my** brother."},{"t":"tip","text":"Англійською «чий» кажуть навіть там, де ми його пропускаємо: «Я пошкодив спину» → I hurt **my** back. «Помий руки» → Wash **your** hands. «Він забув телефон» → He forgot **his** phone."},{"t":"mistake","wrong":"Sarah forgot his phone.","right":"Sarah forgot her phone.","why":"«Свій» перекладаємо за власником. Sarah — вона, тож her phone. His — лише коли власник — чоловік."},{"t":"h","text":"It — для речей і тварин"},{"t":"p","text":"В українській речі мають рід: стіна — вона, фургон — він. В англійській про будь-яку річ кажемо **it**, а про кілька — **they**. **He** і **she** — лише про людей (і хіба що про свого собаку чи кота). «Його / її» для речі — **its**."},{"t":"ex","items":[["Where's the drill? — **It's** in the van.","Де дриль? — У фургоні."],["I like this van, but **it's** old.","Мені подобається цей фургон, але він старий."],["The wall is dry. You can paint **it** now.","Стіна суха. Тепер її можна фарбувати."],["The company changed **its** name.","Компанія змінила свою назву."]]},{"t":"mistake","wrong":"I've got a new ladder. She's very light.","right":"I've got a new ladder. It's very light.","why":"Драбина — річ, тому it, хоча українською «вона». He і she — тільки про людей."},{"t":"h","text":"Its чи it's"},{"t":"rule","title":"Не плутай","lines":["**its** = чий (його, її): the van and **its** doors","**it's** = it is або it has: **It's** late."]},{"t":"tip","text":"Перевірка: якщо можна сказати **it is** або **it has** — пиши it's. Якщо ні — its. І запам'ятай: у присвійних займенниках апострофа немає ніколи: its, yours, hers, ours, theirs."},{"t":"mistake","wrong":"The van lost it's wing mirror.","right":"The van lost its wing mirror.","why":"«The van lost it is wing mirror» — безглуздя, тож тут its (його). It's = it is."},{"t":"h","text":"Чий: Tom's van"},{"t":"p","text":"Щоб сказати, чия річ, до імені чи слова-людини додаємо **'s**: **Tom's** van — фургон Тома. Порядок навпаки, ніж у нас: спочатку власник, потім річ. Якщо слово — множина на -s, додаємо лише апостроф: my **parents'** house."},{"t":"table","head":["Власник","Додаємо","Приклад"],"rows":[["одна людина","'s","Tom**'s** van"],["однина на -s","'s","the boss**'s** office"],["множина на -s","'","my parents**'** house"],["множина без -s","'s","the children**'s** room"]]},{"t":"ex","items":[["This is **Tom's** van.","Це фургон Тома."],["**Sarah's** brother works with us.","Брат Сари працює з нами."],["The keys are in **the boss's** office.","Ключі в кабінеті боса."],["My **parents'** house is in Lviv.","Будинок моїх батьків у Львові."]]},{"t":"p","text":"Для речей замість 's зазвичай вживаємо **of**: the top **of** the wall (верх стіни), the end **of** the day (кінець дня), the back **of** the van (задня частина фургона). Порядок як в українській: спочатку що, потім чого."},{"t":"ex","items":[["The tools are in **the back of the van**.","Інструменти ззаду у фургоні."],["What's **the name of the street**?","Як називається ця вулиця?"],["I'm free at **the end of the month**.","Наприкінці місяця я вільний."]]},{"t":"mistake","wrong":"This is my friend car.","right":"This is my friend's car.","why":"Щоб показати власника, додаємо 's: my friend's car — машина мого друга."},{"t":"h","text":"Myself, yourself: сам, себе"},{"t":"p","text":"Коли дія повертається на того, хто її робить (наше «себе» або «-ся»), вживаємо **myself, yourself, himself, herself, itself, ourselves, yourselves, themselves**: I cut **myself** — я порізався. Ці ж слова означають «сам, без допомоги»: I did it **myself**."},{"t":"ex","items":[["I cut **myself** at work.","Я порізався на роботі."],["Be careful, don't hurt **yourself**.","Обережно, не травмуйся."],["He built the house **himself**.","Він сам збудував будинок."],["Help **yourself**!","Пригощайся!"]]},{"t":"tip","text":"Не кожне «-ся» — це myself. Кажемо просто: We **met** at the site (ми зустрілися), I **feel** tired (я почуваюся втомленим), I **got dressed** (я одягнувся), **Relax**! (розслабся)."}],"tasks":[{"type":"choice","q":"Sarah is my friend. I see ___ every day.","uk":"Сара — моя подруга. Я бачу її щодня.","opts":["she","her","hers"],"a":1,"why":"Після дієслова (see) потрібна форма «кого»: her. She — лише перед дієсловом, коли вона виконує дію."},{"type":"choice","q":"Where's the drill? — ___ in the van.","uk":"Де дриль? — У фургоні.","opts":["She's","He's","It's"],"a":2,"why":"Дриль — річ, а про речі кажемо it, хоча українською «він»."},{"type":"input","q":"Can you help ___? We can't lift this board.","uk":"Можеш нам допомогти? Ми не можемо підняти цей лист гіпсокартону.","a":["us"],"why":"Після дієслова help потрібна форма «кого / кому»: we → us."},{"type":"choice","q":"Is this your phone? — Yes, it's ___.","uk":"Це твій телефон? — Так, мій.","opts":["my","mine","me"],"a":1,"why":"Без іменника «мій» — це mine. My — тільки перед іменником: my phone."},{"type":"input","q":"Mick and Kate live near Gorey. ___ house is very big.","uk":"Мік і Кейт живуть біля Горі. Їхній будинок дуже великий.","a":["Their"],"why":"Mick and Kate — вони (they), а «їхній» перед іменником — their."},{"type":"choice","q":"Sarah forgot ___ keys at home.","uk":"Сара забула свої ключі вдома.","opts":["his","her","hers","its"],"a":1,"why":"«Свій» перекладаємо за власником: Sarah — вона, тому her keys. Hers вживаємо без іменника."},{"type":"choice","q":"This is my ___ car.","uk":"Це машина мого друга.","opts":["friend","friends","friend's"],"a":2,"why":"Власник + 's + річ: my friend's car. Friends без апострофа — це просто «друзі»."},{"type":"order","uk":"Ця куртка не моя.","words":["jacket","this","isn't","mine"],"a":["This jacket isn't mine."],"why":"Без іменника «моя» — це mine: This jacket isn't mine."},{"type":"choice","q":"Our van is old. ___ doors don't close properly.","uk":"Наш фургон старий. Його двері погано зачиняються.","opts":["It's","Its","His"],"a":1,"why":"«Його» для речі — its, без апострофа. It's = it is, а his — лише про людину."},{"type":"input","q":"Be careful! Don't cut ___.","uk":"Обережно! Не поріжся.","a":["yourself"],"why":"Дія повертається на того, хто її робить (-ся): you → yourself."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Ми з Томом ходили в Лідл.","opts":["Me and Tom went to Lidl.","Tom and I went to Lidl.","Tom and me went to Lidl."],"a":1,"why":"«Ми з Томом» — підмет, тому I, а не me. Себе називаємо останнім: Tom and I."},{"type":"order","uk":"Почни з верху стіни.","words":["start","the","top","of","at","the","wall"],"a":["Start at the top of the wall."],"why":"Для речей «чого» передаємо через of: the top of the wall — верх стіни."}],"section":"basics"},"plurals":{"id":"plurals","level":"A1","title":"Plurals, countable and uncountable","uk":"Множина; злічувані й незлічувані іменники","summary":"bricks, men, people; money, advice, news — без -s","minutes":8,"blocks":[{"t":"p","text":"Іменник — слово, що називає людину, річ чи явище: brick, man, sand. Множину більшості іменників утворюємо просто — додаємо **-s**: a brick → two brick**s**. Але є дві пастки: **неправильна множина** (man → men) і **незлічувані** іменники (money, advice, news), які взагалі не мають множини, хоча в українській вони часто саме у множині: «гроші», «поради», «новини»."},{"t":"h","text":"Правопис: -s, -es, -ies, -ves"},{"t":"table","head":["Слово закінчується на","Додаємо","Приклад"],"rows":[["більшість слів","-s","brick → brick**s**"],["-s, -ss, -sh, -ch, -x","-es","box → box**es**"],["приголосна + y","y → -ies","delivery → deliver**ies**"],["голосна + y","-s","day → day**s**"],["-f / -fe (часто)","f → -ves","knife → kni**ves**"],["-o (деякі)","-es","tomato → tomato**es**"]]},{"t":"p","text":"Після -s, -sh, -ch, -x закінчення **-es** читається як окремий склад [із]: bus — bus**es**, sandwich — sandwich**es**. Слова на -o: деякі з -es (tomato**es**, potato**es**), але photo**s**, radio**s**. І не всі слова на -f міняються: shelf → shel**ves**, але roof → roof**s**."},{"t":"ex","items":[["Two **boxes** of screws, please.","Дві коробки шурупів, будь ласка."],["I need three new **brushes**.","Мені потрібні три нові пензлі."],["We worked there for five **days**.","Ми працювали там п'ять днів."],["The **shelves** are in the van.","Полиці у фургоні."],["We've got two **deliveries** today.","Сьогодні в нас дві доставки."]]},{"t":"h","text":"Неправильна множина"},{"t":"table","head":["Один","Багато"],"rows":[["a man","two **men**"],["a woman","two **women**"],["a child","two **children**"],["a person","two **people**"],["a foot","two **feet**"],["a tooth","two **teeth**"],["a mouse","two **mice**"],["a sheep","two **sheep**"]]},{"t":"tip","text":"**People** — це вже множина: one person, two **people**, a lot of **people**. Слово «peoples» означає «народи» і в побуті майже не трапляється."},{"t":"ex","items":[["There are ten **people** on the site today.","Сьогодні на об'єкті десять людей."],["Two **women** work in the office.","У конторі працюють дві жінки."],["My **feet** hurt.","У мене болять ноги."],["How many **children** have you got?","Скільки в тебе дітей?"]]},{"t":"h","text":"Злічувані й незлічувані"},{"t":"p","text":"**Злічувані** (countable) — те, що можна порахувати штуками: a brick, two bricks; a job, three jobs. **Незлічувані** (uncountable) — речовини, матеріали, абстрактні поняття: water, sand, money, advice. Множини в них немає, тому: **без a / an**, **без -s**, дієслово як для однини (**is**), а «скільки» — **much**."},{"t":"list","items":["**Матеріали й речовини**: water, sand, cement, plaster, concrete, paint, wood, bread, milk","**Абстрактні**: work, advice, information, news, help, weather, time, fun","**Збірні**: money, furniture, equipment, luggage, rubbish, traffic"]},{"t":"table","head":["Що","Злічувані","Незлічувані"],"rows":[["одне","a brick","sand (без a)"],["багато","brick**s**","sand (без -s)"],["дієслово","the bricks **are**","the sand **is**"],["скільки?","how **many** bricks","how **much** sand"],["трохи, кілька","some bricks","some sand"]]},{"t":"ex","items":[["The sand **is** wet.","Пісок мокрий."],["We need **some** cement.","Нам потрібно трохи цементу."],["How **much** paint have we got?","Скільки в нас фарби?"],["Can I give you **some advice**?","Можна тобі дещо порадити?"],["The furniture **is** in the van.","Меблі у фургоні."],["The money **is** on the table.","Гроші на столі."]]},{"t":"tip","text":"Пастка для українців: **гроші, меблі, новини, поради, відомості** в нас — множина, а англійською money, furniture, news, advice, information — незлічувані. Тому The money **is**…, The news **is**…, Your advice **was**…"},{"t":"h","text":"Як порахувати незлічуване"},{"t":"p","text":"Щоб порахувати незлічуване, додай слово-«упаковку» чи «порцію»: **a bag of** cement, **a bottle of** water, **a piece of** advice, **a loaf of** bread, **a cup of** tea. Множину отримує саме це слово: two **bags** of cement (а не two cements)."},{"t":"ex","items":[["Get five **bags of plaster**.","Візьми п'ять мішків штукатурки."],["Let me give you **a piece of advice**.","Дам тобі одну пораду."],["Can you buy **a loaf of bread**?","Можеш купити хлібину?"],["I'll have **a cup of tea**, thanks.","Мені чашку чаю, дякую."]]},{"t":"h","text":"News і people"},{"t":"p","text":"**News** закінчується на -s, але це незлічуване слово в однині: The news **is** good. «Одна новина» — просто news або **a piece of news**, але не «a news». А **people**, навпаки, множина: People **are** friendly here."},{"t":"ex","items":[["I've got **good news**!","У мене хороша новина!"],["The news **is** on at nine.","Новини о дев'ятій."],["People **are** very friendly in Wexford.","Люди у Вексфорді дуже привітні."],["How many people **are** coming?","Скільки людей прийде?"]]},{"t":"h","text":"Job чи work"},{"t":"p","text":"**Job** — злічуване: a job, two jobs. Це посада («у мене нова робота») або конкретне завдання, об'єкт. **Work** — незлічуване: робота взагалі, справи, зайнятість. Тому a lot of **work**, але ніколи не «a work» і не «works» у цьому значенні."},{"t":"ex","items":[["I've got **a new job**.","У мене нова робота."],["He's got **two jobs**.","У нього дві роботи."],["I'm looking for **work**.","Я шукаю роботу."],["There's **no work** on Sunday.","У неділю роботи немає."]]},{"t":"h","text":"Much чи many"},{"t":"rule","title":"Скільки?","lines":["**many** + множина: many bricks, many people","**much** + незлічуване: much sand, much money","**a lot of** + будь-що: a lot of work, a lot of jobs"]},{"t":"tip","text":"У стверджувальних реченнях природніше **a lot of**: There's a lot of work this week (а не much work). Much і many частіше в питаннях і запереченнях: How much? I haven't got many tools."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Thanks for the informations and advices.","right":"Thanks for the information and advice.","why":"Information і advice незлічувані: без -s і без a. Одна порада — a piece of advice."},{"t":"mistake","wrong":"We need new equipments.","right":"We need new equipment.","why":"Equipment (обладнання) незлічуване, форми з -s немає. Так само furniture, luggage."},{"t":"mistake","wrong":"I have a good news.","right":"I have good news.","why":"News незлічуване, тому без a. Можна ще a piece of good news."},{"t":"mistake","wrong":"The news are bad.","right":"The news is bad.","why":"News — однина, хоча закінчується на -s: the news is."},{"t":"mistake","wrong":"There were a lot of peoples.","right":"There were a lot of people.","why":"People — уже множина від person. Peoples означає «народи»."}],"tasks":[{"type":"choice","q":"Two ___ came to fix the roof.","uk":"Двоє чоловіків прийшли полагодити дах.","opts":["mans","men","mens"],"a":1,"why":"Man має неправильну множину: one man — two men. Закінчення -s тут не додаємо."},{"type":"input","q":"My ___ (foot) hurt after work.","uk":"Після роботи в мене болять ноги.","a":["feet"],"why":"Foot — неправильна множина: one foot, two feet."},{"type":"input","q":"We need three new ___ (shelf) in the kitchen.","uk":"Нам потрібні три нові полиці на кухні.","a":["shelves"],"why":"Багато слів на -f / -fe змінюють f на -ves: shelf → shelves, knife → knives (але roof → roofs)."},{"type":"choice","q":"How ___ people work for your boss?","uk":"Скільки людей працює на твого боса?","opts":["much","many"],"a":1,"why":"People — множина, тож many. Much — лише з незлічуваними: much money."},{"type":"choice","q":"Can you give me some ___?","uk":"Можеш мені щось порадити?","opts":["advice","advices","an advice"],"a":0,"why":"Advice незлічуване: без -s і без an. Одна порада — a piece of advice."},{"type":"choice","q":"The news ___ good today.","uk":"Сьогодні новини хороші.","opts":["is","are"],"a":0,"why":"News — незлічуване слово в однині, хоч і закінчується на -s: the news is."},{"type":"input","q":"These people ___ (work) for Mick.","uk":"Ці люди працюють на Міка.","a":["work","are working"],"why":"People — множина (вони), тому дієслово без -s: people work."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Нам потрібне нове обладнання.","opts":["We need a new equipment.","We need new equipments.","We need new equipment."],"a":2,"why":"Equipment незлічуване: без a і без -s."},{"type":"choice","q":"Sorry, I can't come. I've got too much ___ today.","uk":"Вибач, не можу прийти. У мене сьогодні забагато роботи.","opts":["work","works","job"],"a":0,"why":"Work у значенні «робота, справи» незлічуване: much work, без -s. Job злічуване (a job), з much не вживається."},{"type":"input","q":"We need ten ___ (bag) of cement.","uk":"Нам потрібно десять мішків цементу.","a":["bags"],"why":"Цемент не рахуємо, рахуємо мішки: ten bags of cement. Множину отримує bag."},{"type":"order","uk":"Можеш купити дві пляшки води?","words":["water","can","two","you","of","buy","bottles"],"a":["Can you buy two bottles of water?"],"why":"Воду не рахуємо штуками, тож two bottles of water. У питанні can стоїть перед you."},{"type":"order","uk":"Скільки грошей тобі потрібно?","words":["need","money","you","how","do","much"],"a":["How much money do you need?"],"why":"Money незлічуване, тому how much (не many) і без -s."}],"section":"basics"},"articles":{"id":"articles","level":"A2","title":"Articles: a, an, the","uk":"Артиклі a, an, the","summary":"коли a/an, коли the, а коли без артикля: a job, the boss, at work","minutes":12,"blocks":[{"t":"p","text":"**Артикль** — коротке слово перед іменником (іменник — назва людини, предмета чи місця: boss, van, job). В українській артиклів немає, тому здається, що це дрібниця. Але англієць одразу чує, коли їх бракує, як ми чуємо «я хотіти кава». Добра новина: варіантів лише три — **a/an**, **the** або **нічого**."},{"t":"table","head":["Що ставимо","Коли","Приклад"],"rows":[["**a / an**","якийсь, один із багатьох","I need **a** ladder."],["**the**","той самий, відомий обом","Hold **the** ladder."],["нічого","загалом, не про конкретне","**Cement** is heavy."]]},{"t":"ex","items":[["I need **a** ladder.","Мені потрібна драбина (якась, будь-яка)."],["Can you hold **the** ladder?","Можеш потримати драбину? (ось цю, що тут стоїть)"],["**Cement** is heavy.","Цемент важкий (будь-який, загалом)."]]},{"t":"h","text":"A чи an: слухай перший звук"},{"t":"p","text":"**A** і **an** — одне й те саме слово, просто an легше вимовити перед голосним. **A** ставимо перед приголосним **звуком**, **an** — перед голосним звуком (а, е, і, о). Важить саме **звук**, а не буква. І дивимося на **перше слово після артикля**, навіть якщо це прикметник: **an** old van, але **a** new van."},{"t":"table","head":["a + приголосний звук","an + голосний звук"],"rows":[["a **v**an","an **a**pple"],["a **h**ard job","an **e**asy job"],["a **u**niform [ю-]","an **u**mbrella [а-]"],["a **e**uro [ю-]","an **X**-ray [екс-]"],["a **h**ammer [г-]","an **h**our [ау-], h не чути"]]},{"t":"ex","items":[["We get **an** hour for lunch.","У нас година на обід."],["He wears **a** uniform at work.","Він носить на роботі форму."],["Take **an** umbrella, it's going to rain.","Візьми парасолю, буде дощ."],["Can you lend me **a** euro?","Можеш позичити мені євро?"],["It's **an** old house, but it's warm.","Це старий будинок, але теплий."]]},{"t":"h","text":"Коли ставимо a/an"},{"t":"list","items":["**Одна якась річ**, будь-яка з багатьох: Have you got **a** pen?","**Згадуємо вперше**, співрозмовник ще не знає, про що мова: There's **a** man at the door.","**Професія або хто ти**: I'm **a** plasterer. She's **a** nurse.","**Описуємо**, що це таке: It's **a** good van. He's **a** nice guy.","**«На», «за»** в ціні й частоті: €15 **an** hour, twice **a** week.","**Вигуки**: What **a** mess! What **a** day!"]},{"t":"ex","items":[["I'm **a** plasterer.","Я штукатур."],["Olena is **a** nurse.","Олена — медсестра."],["There's **a** man at the door.","Біля дверей якийсь чоловік."],["We work five days **a** week.","Ми працюємо п'ять днів на тиждень."],["He gets €18 **an** hour.","Він отримує 18 євро за годину."],["What **a** mess!","Ну й безлад!"]]},{"t":"tip","text":"Українською професію називаємо просто: «Я штукатур». Англійською в однині **обов'язково** a/an: I'm **a** plasterer, he's **an** electrician. А в множині артикля немає: We're plasterers."},{"t":"p","text":"A/an означає «один», тому стоїть лише з **однією** річчю, яку можна порахувати. **Злічуване** — те, що рахуємо поштучно: a van, two vans. **Незлічуване** — те, що поштучно не рахуємо: water, cement, sand, money, work, advice, information. З незлічуваним a/an **не буває**: some advice, some money."},{"t":"h","text":"The: обидва знаємо, про що мова"},{"t":"p","text":"**The** — ніби вказати пальцем: і ти, і співрозмовник розумієте, про яку **саме** річ ідеться. Українською тут часто можна підставити «цей», «той самий», «наш». The ставимо перед будь-яким іменником: в однині, у множині, перед незлічуваним (the van, the vans, the cement)."},{"t":"list","items":["**Згадуємо вдруге**: I bought **a** drill. **The** drill was cheap.","**Зрозуміло з обставин**: Close **the** door. Where's **the** boss? (наш бос, на нашому об'єкті)","**Єдине у світі чи тут**: **the** sun, **the** sky, **the** sea, **the** government","**Найвищий ступінь, порядок і same**:**the** best, **the** biggest, **the** first, **the** last, **the** same","**Уточнюємо, яке саме**: **the** van outside, **the** man from Gorey"]},{"t":"ex","items":[["I bought **a** drill and **a** level. **The** drill was cheap.","Я купив дриль і рівень. Дриль був дешевий."],["Where's **the** boss?","Де бос? (наш, усі знають, який)"],["Can you close **the** window?","Можеш зачинити вікно?"],["**The** sun's out today.","Сьогодні світить сонце."],["This is **the** best café in Gorey.","Це найкраще кафе в Горі."],["He's always **the** first one on site.","Він завжди приходить на об'єкт першим."],["**The** van outside is Mick's.","Фургон надворі — Міків."]]},{"t":"tip","text":"Порівняй: Is there **a** toilet here? — чи є тут якийсь туалет? Where's **the** toilet? — де туалет? (він тут точно є, питаю, де саме)."},{"t":"h","text":"The з місцями й назвами"},{"t":"p","text":"Звичні місця, куди ми ходимо в місті, зазвичай з **the**, навіть якщо їх там кілька: **the** bank, **the** station, **the** cinema, **the** shops, **the** gym, **the** post office, **the** doctor's (у лікаря). А країни й міста — **без артикля**: Ireland, Dublin. The мають лише країни зі словами Kingdom, States, Republic у назві (**the** UK, **the** USA), а ще річки, моря, океани й траси (**the** Slaney, **the** Atlantic, **the** N11)."},{"t":"ex","items":[["I'm going to **the** bank.","Я йду в банк."],["Let's go to **the** cinema on Saturday.","Ходімо в суботу в кіно."],["He's at **the** doctor's.","Він у лікаря."],["I go to **the** gym after work.","Я ходжу в спортзал після роботи."],["Tom is from **the** UK, but he lives in Ireland.","Том з Великої Британії, але живе в Ірландії."],["Take **the** N11 to Gorey.","Їдь до Горі трасою N11."]]},{"t":"table","head":["Без артикля","З the"],"rows":[["Ireland, Ukraine, Poland","**the** UK, **the** USA"],["Dublin, Wexford, Gorey","**the** Republic of Ireland"],["Europe, Africa","**the** Atlantic, **the** Slaney"],["Main Street","**the** N11, **the** M50"]]},{"t":"h","text":"Без артикля: говоримо загалом"},{"t":"p","text":"Коли говоримо про речі **взагалі**, а не про конкретні, артикля немає: множина (dogs, tools, people) або незлічуване (cement, money, life, work). Тут українці найчастіше ставлять зайве the, бо «життя» чи «гроші» звучать як щось конкретне. Але **Life** is hard — без the. The з'являється, лише коли маємо на увазі конкретне."},{"t":"ex","items":[["I like **dogs**.","Я люблю собак (усіх, загалом)."],["I like **the** dogs next door.","Мені подобаються сусідські собаки (саме ці)."],["**Cement** is heavy.","Цемент важкий (будь-який)."],["**The** cement is in the van.","Цемент у фургоні (той, що ми купили)."],["**Life** is hard sometimes.","Життя іноді буває важким."],["**Money** isn't everything.","Гроші — це ще не все."],["**Good tools** are expensive.","Хороші інструменти дорогі."]]},{"t":"h","text":"Без артикля: сталі вирази"},{"t":"p","text":"У деяких звичних виразах артикля немає, бо думаємо про **дію**, а не про будівлю чи предмет. Їх найпростіше запам'ятати готовими."},{"t":"table","head":["Вираз","Значення"],"rows":[["at work / go to work","на роботі / іти на роботу"],["at home / go home","вдома / іти додому"],["in bed / go to bed","у ліжку / лягати спати"],["by bus / by car / by train","автобусом / машиною / потягом"],["have breakfast / lunch / dinner","снідати / обідати / вечеряти"],["speak English","говорити англійською"],["on Monday, in May, at night","у понеділок, у травні, вночі"],["next week, last year","наступного тижня, торік"]]},{"t":"ex","items":[["I'm **at work** till six.","Я на роботі до шостої."],["Let's **go home**.","Ходімо додому."],["I go to work **by bus**.","Я їжджу на роботу автобусом."],["We **have lunch** at one.","Ми обідаємо о першій."],["Do you **speak English**?","Ти розмовляєш англійською?"],["See you **next week**.","Побачимося наступного тижня."]]},{"t":"tip","text":"**Go home** — без to і без артикля: home тут уже означає «додому». А от частини дня з the: **in the morning**, **in the afternoon**, **in the evening**. Без артикля лише **at night**."},{"t":"h","text":"Якщо сумніваєшся"},{"t":"rule","title":"Перевір по черзі","lines":["Обидва знаємо, яке саме? → **the**","Одне якесь, можна порахувати? → **a / an**","Множина чи незлічуване загалом? → **нічого**","Ім'я, місто, більшість країн, мова, день → **нічого**"]},{"t":"tip","text":"Найгірше для однієї злічуваної речі — **голий іменник**: «I need ladder» звучить найбільш ламано. Не знаєш, a чи the, — постав хоч щось. І не зупиняйся посеред речення: помилка в артиклі майже ніколи не заважає тебе зрозуміти."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I am plasterer.","right":"I'm a plasterer.","why":"Професію в однині кажемо з a/an. Так само: He's an electrician."},{"t":"mistake","wrong":"The life is hard.","right":"Life is hard.","why":"Про життя, гроші, роботу загалом кажемо без артикля."},{"t":"mistake","wrong":"I go to the work at seven.","right":"I go to work at seven.","why":"Go to work, at work, go home, by bus — сталі вирази без артикля."},{"t":"mistake","wrong":"She plays the football.","right":"She plays football.","why":"Види спорту без артикля: play football, play golf. А от музичні інструменти з the: play the guitar."},{"t":"mistake","wrong":"Can I give you a advice?","right":"Can I give you some advice?","why":"Advice незлічуване, тому a/an з ним не буває: some advice або a piece of advice. І перед голосним звуком було б an, а не a."}],"tasks":[{"type":"choice","q":"I'm ___ plasterer.","uk":"Я штукатур.","opts":["a","an","— (без артикля)"],"a":0,"why":"Професію в однині кажемо з a/an. Plasterer починається з приголосного звуку, тому a."},{"type":"choice","q":"We waited for ___ hour.","uk":"Ми чекали годину.","opts":["a","an","the"],"a":1,"why":"У hour літера h не читається, слово починається з голосного звуку [ау], тому an."},{"type":"input","q":"We work five days ___ (a / an / the) week.","uk":"Ми працюємо п'ять днів на тиждень.","a":["a"],"why":"«На тиждень», «за годину» — через a/an: five days a week, €15 an hour. Week починається з приголосного, тому a."},{"type":"input","q":"Andrii works as ___ (a / an / the) electrician.","uk":"Андрій працює електриком.","a":["an"],"why":"Професія — з a/an, а electrician починається з голосного звуку [і], тому an."},{"type":"choice","q":"I bought a drill and a level. ___ drill was really cheap.","uk":"Я купив дриль і рівень. Дриль був дуже дешевий.","opts":["A","The","— (без артикля)"],"a":1,"why":"Дриль уже згадали, тепер ми обидва знаємо, який саме. Удруге — the."},{"type":"input","q":"___ (a / an / the) sun is very hot today.","uk":"Сонце сьогодні дуже пече.","a":["the"],"why":"Сонце одне на всіх, тому the. Так само the sky, the sea."},{"type":"choice","q":"___ is hard sometimes.","uk":"Життя іноді буває важким.","opts":["Life","The life","A life"],"a":0,"why":"Про життя загалом — без артикля. Українці часто ставлять тут the, але це помилка."},{"type":"choice","q":"Sarah lives in ___.","uk":"Сара живе у Великій Британії.","opts":["UK","the UK","a UK"],"a":1,"why":"Більшість країн без артикля (Ireland, Poland), але назви з Kingdom, States, Republic — з the: the UK, the USA."},{"type":"choice","task":"Яке речення правильне?","q":"","opts":["I go to work by bus.","I go to the work by bus.","I go to work by the bus."],"a":0,"why":"Go to work і by bus — сталі вирази без артикля, як at home, go home, have lunch."},{"type":"choice","q":"Can you give me ___ advice?","uk":"Можеш мені щось порадити?","opts":["a","an","some"],"a":2,"why":"Advice незлічуване (поштучно не рахуємо), тому a/an з ним не буває. Кажемо some advice або a piece of advice."},{"type":"input","q":"He's ___ (a / an / the) best plasterer I know.","uk":"Він найкращий штукатур, якого я знаю.","a":["the"],"why":"Найвищий ступінь (the best, the biggest, the cheapest) завжди з the."},{"type":"order","uk":"Ходімо в суботу в кіно.","words":["go","cinema","let's","on","the","Saturday","to"],"a":["Let's go to the cinema on Saturday.","On Saturday, let's go to the cinema."],"why":"Звичні місця в місті — з the (the cinema), а дні тижня без артикля (on Saturday). Коли — зазвичай у кінці."}],"section":"basics"},"this-that":{"id":"this-that","level":"A1","title":"This, that, these, those","uk":"Цей, той: this, that, these, those, one","summary":"цей/той, ці/ті й one замість повтору: this one, the red ones","minutes":5,"blocks":[{"t":"p","text":"Ці чотири слова вказують, **про яку саме** річ мова, як українські «цей» і «той». Вибір залежить від двох питань: річ **близько чи далеко** і чи вона **одна, чи їх кілька**."},{"t":"table","head":["Де","Одна річ","Кілька речей"],"rows":[["близько, тут","**this** — цей","**these** — ці"],["далеко, там","**that** — той","**those** — ті"]]},{"t":"ex","items":[["**This** drill is new.","Цей дриль новий (він у мене в руках)."],["**That** van over there is Mick's.","Он той фургон — Міків."],["**These** boots are really comfortable.","Ці черевики дуже зручні."],["Who are **those** men?","Хто ті чоловіки?"],["I like **this** song.","Мені подобається ця пісня (що грає зараз)."]]},{"t":"tip","text":"Не плутай на слух: **this** — коротке «і» і глухе «с» у кінці, **these** — довге «іі» і дзвінке «з»: [зііз]. Якщо вимовиш these коротко, почують this."},{"t":"h","text":"This is…, That's…: без іменника"},{"t":"p","text":"This, that, these, those можуть стояти самі, без іменника, коли показуєш на щось, знайомиш людей або називаєш себе в телефонній розмові. **That is** у розмові скорочують до **that's**, а this is на письмі не скорочують ніколи."},{"t":"ex","items":[["**This is** my van.","Це мій фургон."],["Kate, **this is** Andrii.","Кейт, познайомся, це Андрій."],["**What's that**?","Що то таке?"],["**Is this** your phone?","Це твій телефон?"],["**These are** my tools.","Це мої інструменти."],["Hello, **this is** Tom.","Алло, це Том."]]},{"t":"tip","text":"Українське «це» буває і про одну річ, і про кілька: «Це мої інструменти». Англійською дивись на кількість: **This is** my tool, але **These are** my tools."},{"t":"h","text":"That's great! — про щойно сказане"},{"t":"p","text":"Коли реагуєш на чиїсь слова, кажи **that**: слова вже прозвучали, вони ніби «там». Українською тут просто «Це…», «Чудово!», «Правильно»."},{"t":"ex","items":[["I got the job! — **That's** great!","Мене взяли на роботу! — Це чудово!"],["Let's start at seven. — **That's** a good idea.","Почнімо о сьомій. — Гарна ідея."],["Is it twenty euros? — Yes, **that's** right.","Це двадцять євро? — Так, правильно."],["Sorry I'm late. — **That's** OK.","Вибач, що запізнився. — Нічого страшного."],["**That's** not true!","Це неправда!"]]},{"t":"h","text":"Про час: this morning, that day"},{"t":"p","text":"З часом **this** означає «цей, сьогоднішній, найближчий»: **this** morning (сьогодні вранці), **this** evening (сьогодні ввечері), **this** week (цього тижня), **this** Saturday (цієї суботи). Без in, on і без the! А **that** — про інший, частіше минулий час: **that** day (того дня)."},{"t":"ex","items":[["I saw Mick **this** morning.","Я бачив Міка сьогодні вранці."],["I'm busy **this** week.","Цього тижня я зайнятий."],["We finished early **that** day.","Того дня ми закінчили рано."],["**These** days everything is expensive.","Тепер усе дороге."]]},{"t":"h","text":"One / ones: щоб не повторювати"},{"t":"p","text":"Щоб не повторювати той самий іменник, англійці ставлять **one** (замість однієї речі) або **ones** (замість кількох). Українською ми просто кажемо «чорні» чи «оцей». Англійською після прикметника one/ones **обов'язкове** (the black ones), а після this, that, which його дуже часто додають: this one, which one?"},{"t":"rule","title":"Замість повтору","lines":["this **one** / that **one** — оцей / он той","the red **one** — червоний (одна річ)","the red **ones** — червоні (кілька)","which **one**? / which **ones**? — котрий? / котрі?","a big **one** — якийсь великий"]},{"t":"ex","items":[["Which drill do you want? — **This one**.","Який дриль тобі дати? — Оцей."],["These gloves are too small. Have you got any bigger **ones**?","Ці рукавиці замалі. У тебе є більші?"],["My van is the white **one**.","Мій фургон — білий."],["**Which one** is yours?","Котрий твій?"],["I need a ladder. — There's **one** in the van.","Мені потрібна драбина. — У фургоні є одна."]]},{"t":"tip","text":"One/ones — лише замість того, що можна порахувати. З незлічуваним (water, cement, money) one не вживають: I need some cement. — There's **some** in the van. Без прикметника a перед one не ставимо: There's **one** in the van (а не a one). А після these і those ones зазвичай не потрібне: I'll take **these**."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"This cars are new.","right":"These cars are new.","why":"Cars — кілька, тому these. This лише з однією річчю: this car."},{"t":"mistake","wrong":"I like those car.","right":"I like that car.","why":"Car — одна, тому that. Those лише з множиною: those cars."},{"t":"mistake","wrong":"These is my tools.","right":"These are my tools.","why":"These — множина, тому are, а не is."},{"t":"mistake","wrong":"I want the red.","right":"I want the red one.","why":"Після прикметника потрібен іменник або one: the red one, the red ones."}],"tasks":[{"type":"choice","q":"___ boots are new.","uk":"Ці черевики нові.","opts":["This","These","That"],"a":1,"why":"Boots — кілька, і вони близько («ці»), тому these."},{"type":"choice","q":"Look at ___ van over there!","uk":"Подивись он на той фургон!","opts":["this","that","those"],"a":1,"why":"Фургон один і далеко (over there), тому that. Those — лише для кількох речей."},{"type":"choice","q":"Who are ___ people over there?","uk":"Хто он ті люди?","opts":["this","that","these","those"],"a":3,"why":"People — множина, і вони далеко (over there), тому those."},{"type":"input","q":"___ (this) are my tools.","uk":"Це мої інструменти.","a":["These"],"why":"Tools — кілька, тому this змінюємо на these. І дієслово are, бо множина."},{"type":"input","q":"Kate, ___ is my friend Andrii.","uk":"Кейт, познайомся, це мій друг Андрій.","a":["this"],"why":"Коли знайомимо людей, кажемо this is: людина поруч із нами."},{"type":"choice","q":"I got the job! — ___ great!","uk":"Мене взяли на роботу! — Це чудово!","opts":["That's","This's","Those are"],"a":0,"why":"Реагуємо на щойно сказане — that's. This is до this's не скорочують, а those — для кількох речей."},{"type":"input","q":"I'll see you ___ evening.","uk":"Побачимося сьогодні ввечері.","a":["this"],"why":"«Сьогодні ввечері» — this evening, без in і без the. Так само this morning, this week."},{"type":"choice","task":"Яке речення правильне?","q":"","opts":["Those car is mine.","That car is mine.","That cars are mine."],"a":1,"why":"Car — одна, тому that. Those і these — лише з множиною: those cars."},{"type":"choice","q":"Which gloves do you want? — The black ___.","uk":"Які рукавиці ти хочеш? — Чорні.","opts":["one","ones","— (нічого)"],"a":1,"why":"Щоб не повторювати gloves, ставимо ones, бо рукавиць кілька. Голий прикметник (the black) тут не можна."},{"type":"input","q":"This ladder is too short. Have you got a longer ___ (one / ones)?","uk":"Ця драбина закоротка. У тебе є довша?","a":["one"],"why":"Драбина одна, тому замість повтору слова ladder ставимо one: a longer one."},{"type":"order","uk":"Ці рукавиці кращі за ті.","words":["those","gloves","better","these","than","are"],"a":["These gloves are better than those."],"why":"Ці (близько, кілька) — these, ті (далі, кілька) — those. Після those іменник gloves не повторюємо."},{"type":"order","uk":"Мій фургон — отой білий.","words":["white","van","that","my","one","is"],"a":["My van is that white one.","That white one is my van."],"why":"That one — «отой», а one замінює слово van, щоб його не повторювати."}],"section":"basics"},"there-is":{"id":"there-is","level":"A1","title":"There is, there are","uk":"Конструкція there is / there are","summary":"що є і де: There's a problem. Are there any shops near here?","minutes":6,"blocks":[{"t":"p","text":"Коли хочеш сказати, що щось **є, існує** десь (у кімнаті, у місті, на об'єкті), англійською кажуть **there is / there are**. Українською ми просто говоримо «Є…», «У селі два магазини», «На столі лежить ключ». Англійцям потрібне **there** на початку, хоча «там» воно тут не означає."},{"t":"ex","items":[["**There's** a problem with the van.","З фургоном проблема."],["**There are** two shops in the village.","У селі два магазини."],["**There's** a Lidl in Gorey.","У Горі є Lidl."],["**There are** some sandwiches in the fridge.","У холодильнику є бутерброди."]]},{"t":"tip","text":"Порядок слів інший, ніж в українській. Ми починаємо з місця: «На столі лежить ключ». Англійці починають з there is, а місце ставлять у кінець: **There's a key on the table.**"},{"t":"h","text":"Is чи are"},{"t":"rule","title":"Ствердження","lines":["**There is** + одна річ або незлічуване","**There are** + кілька речей (множина)","there is → **there's** (у розмові майже завжди)"]},{"t":"p","text":"**Незлічуване** — те, що поштучно не рахуємо: water, cement, sand, money, time. З ним завжди **is**, навіть якщо його багато: There's a lot of dust."},{"t":"ex","items":[["**There's** some milk in the fridge.","У холодильнику є трохи молока."],["**There's** a lot of dust in here.","Тут дуже багато пилу."],["**There are** three vans outside.","Надворі три фургони."],["**There are** a lot of people in Lidl today.","Сьогодні в Lidl багато людей."]]},{"t":"h","text":"Заперечення"},{"t":"rule","title":"Заперечення","lines":["There **isn't a** + одна річ","There **isn't any** + незлічуване","There **aren't any** + множина","There's **no** / There are **no** + що завгодно"]},{"t":"ex","items":[["**There isn't a** bus on Sundays.","У неділю автобуса немає."],["**There isn't any** milk left.","Молока не залишилося."],["**There aren't any** screws in the box.","У коробці немає шурупів."],["**There's no** time.","Немає часу."],["Sorry, **there are no** tickets left.","На жаль, квитків не залишилося."]]},{"t":"tip","text":"**No** — уже заперечення, тому not з ним не ставимо: There's **no** problem (а не There isn't no problem). Подвійного заперечення, як у нас «немає нічого», в англійській немає."},{"t":"h","text":"Питання й короткі відповіді"},{"t":"rule","title":"Питання","lines":["**Is there** a / any…? — Yes, there is. / No, there isn't.","**Are there** any…? — Yes, there are. / No, there aren't.","**How many** + множина + **are there**?","**How much** + незлічуване + **is there**?"]},{"t":"ex","items":[["**Is there** a toilet here? — **Yes, there is.**","Тут є туалет? — Так, є."],["**Are there** any shops near here? — **No, there aren't.**","Тут поблизу є якісь магазини? — Ні, немає."],["**How many** people **are there** on the site today?","Скільки сьогодні людей на об'єкті?"],["**Is there** any coffee left?","Кава ще залишилася?"],["**How much** sand **is there** in the van?","Скільки піску у фургоні?"]]},{"t":"tip","text":"У короткій відповіді «так» не скорочуй: **Yes, there is.** (а не Yes, there's). А «ні» скорочуй спокійно: No, there isn't."},{"t":"h","text":"Минуле й майбутнє"},{"t":"table","head":["Коли","Одна / незлічуване","Кілька"],"rows":[["зараз","there **is**","there **are**"],["минуле","there **was**","there **were**"],["майбутнє","there **will be**","there **will be**"]]},{"t":"ex","items":[["**There was** an accident on the N11 this morning.","Сьогодні вранці на N11 була аварія."],["**There were** a lot of people at the match.","На матчі було багато людей."],["**There wasn't** any hot water yesterday.","Учора не було гарячої води."],["**Were there** any problems? — No, there weren't.","Були якісь проблеми? — Ні."],["**There'll be** a meeting on Monday.","У понеділок буде нарада."],["**Will there be** a break?","Буде перерва?"]]},{"t":"tip","text":"«Буде нарада» англійською не Will be a meeting, а **There will be** a meeting (скорочено there'll be): потрібні і there, і be."},{"t":"h","text":"There is чи it is"},{"t":"p","text":"Обидва часто перекладаються як «є» чи «це», тому їх плутають. **There is** — повідомляємо, що щось **є**, згадуємо вперше. **It is** — описуємо те, про що вже знаємо (it — «воно», «він», «вона»). А ще it ставимо, коли говоримо про погоду, час і відстань."},{"t":"ex","items":[["**There's** a van outside. **It's** white.","Надворі стоїть фургон. Він білий."],["**There's** a new café in Gorey. **It's** really good.","У Горі відкрилося нове кафе. Воно дуже добре."],["**It's** cold today.","Сьогодні холодно."],["**It's** a long way to Dublin.","До Дубліна далеко."]]},{"t":"tip","text":"У живій розмові ірландці й англійці часто кажуть **there's** і з множиною: There's two vans outside. Почуєш — не дивуйся, у розмові це звична річ. Але на письмі й у завданнях пиши правильно: **There are** two vans."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"In the room is a table.","right":"There's a table in the room.","why":"Коли кажемо, що щось десь є, починаємо з there is, а місце ставимо в кінець."},{"t":"mistake","wrong":"Have a problem with the van.","right":"There's a problem with the van.","why":"«Є проблема» — це there is. Have (мати) потребує підмета — того, хто має: I have a problem — у мене проблема."},{"t":"mistake","wrong":"There are much people here.","right":"There are a lot of people here.","why":"Much — лише з незлічуваним (much time). З people кажи a lot of або many."},{"t":"mistake","wrong":"Is there any shops near here?","right":"Are there any shops near here?","why":"Shops — множина, тому питання починаємо з Are there."}],"tasks":[{"type":"choice","q":"___ a bank in the village.","uk":"У селі є банк.","opts":["There is","There are","It is"],"a":0,"why":"Кажемо, що щось є в якомусь місці, — there is. Банк один, тому is, а не are."},{"type":"choice","q":"___ three vans outside.","uk":"Надворі три фургони.","opts":["There is","There are","They are"],"a":1,"why":"Повідомляємо, що щось є, — there. Фургонів кілька, тому are."},{"type":"choice","q":"There ___ some cement in the van.","uk":"У фургоні є трохи цементу.","opts":["is","are","be"],"a":0,"why":"Cement незлічуваний (поштучно не рахуємо), тому is."},{"type":"choice","q":"___ any shops near here?","uk":"Тут поблизу є якісь магазини?","opts":["Is there","Are there","There are"],"a":1,"why":"Shops — множина, тому питання Are there…? There are — це ствердження, а не питання."},{"type":"input","q":"There ___ (not / be) any chairs in the kitchen.","uk":"На кухні немає стільців.","a":["aren't"],"why":"Chairs — множина, тому заперечення there aren't any."},{"type":"input","q":"How many people ___ there on the site today?","uk":"Скільки сьогодні людей на об'єкті?","a":["are"],"why":"People — множина: How many + множина + are there?"},{"type":"input","q":"Sorry, there are ___ tickets left for Saturday.","uk":"На жаль, на суботу квитків не залишилося.","a":["no","not any"],"why":"There are no — «немає жодного». No вже заперечення, тому not з ним не ставимо. Можна й there are not any (there aren't any)."},{"type":"choice","q":"There's a new shop in Gorey. ___ very big.","uk":"У Горі відкрився новий магазин. Він дуже великий.","opts":["It's","There's","There are"],"a":0,"why":"Магазин уже згадали, тепер описуємо його — it's. There's лише вводить щось нове."},{"type":"input","q":"There ___ (be) an accident on the N11 yesterday.","uk":"Учора на N11 була аварія.","a":["was"],"why":"Минуле: there was для однієї речі, there were для кількох. Аварія одна, тому was."},{"type":"choice","q":"___ a meeting on Monday.","uk":"У понеділок буде нарада.","opts":["There will be","There will","Will be"],"a":0,"why":"Майбутнє — there will be (there'll be). Без there або без be речення неповне."},{"type":"choice","task":"Яке речення правильне?","q":"","opts":["Have a problem with the van.","There's a problem with the van.","Is a problem with the van."],"a":1,"why":"«Є проблема» — there's a problem. Без there таке речення не будують, а have потребує підмета: I have a problem."},{"type":"order","uk":"Тут поблизу є банкомат?","words":["machine","there","near","a","is","cash","here"],"a":["Is there a cash machine near here?"],"why":"Питання: Is there + що + де. Місце (near here) ставимо в кінець."}],"section":"basics"},"questions":{"id":"questions","level":"A2","title":"Questions","uk":"Як ставити питання","summary":"порядок слів: Do you…? Where do you…? Who called? Who did you call?","minutes":9,"blocks":[{"t":"p","text":"В українській питання часто відрізняється від ствердження лише інтонацією: «Ти тут працюєш?» В англійській так зазвичай не роблять: треба змінити **порядок слів**. Допоміжне дієслово (do, does, did, be, can, will, have) стає **перед підметом** — тим, хто або що виконує дію (you, he, my boss, the van)."},{"t":"h","text":"Питання «так чи ні»"},{"t":"p","text":"Якщо в реченні вже є **am, is, are, was, were**, **can**, **will** або допоміжне **have**, просто переставляємо це слово на початок, перед підметом."},{"t":"rule","title":"Є be, can, will, have","lines":["You **are** tired. → **Are** you tired?","He **can** drive. → **Can** he drive?","It **will** rain. → **Will** it rain?","They **have** finished. → **Have** they finished?"]},{"t":"p","text":"Якщо в реченні звичайне дієслово (work, live, go), переставляти нема чого. Тоді на початок додаємо **do / does / did**, а дієслово стоїть у **початковій формі** (як у словнику: work, live, leave)."},{"t":"rule","title":"Звичайне дієслово: додаємо do","lines":["You work here. → **Do** you work here?","She lives here. → **Does** she live here?","They left early. → **Did** they leave early?"]},{"t":"tip","text":"Після **does** і **did** дієслово завжди в початковій формі: Does she **live**…? (не lives), Did they **leave**…? (не left). Закінчення -s і минулий час уже «сидять» у does і did."},{"t":"ex","items":[["**Are** you ready?","Ти готовий?"],["**Can** you give me a hand with this board?","Допоможеш мені з цим листом гіпсокартону?"],["**Will** you be on site tomorrow?","Ти завтра будеш на об'єкті?"],["**Have** you finished the ceiling?","Ти закінчив стелю?"],["**Do** you need a lift?","Тебе підвезти?"],["**Did** Tom call you yesterday?","Том тобі вчора дзвонив?"]]},{"t":"tip","text":"Коли have означає «мати», питай **Do you have** a car? або **Have you got** a car? Обидва варіанти правильні. Просто «Have you a car?» сьогодні звучить застаріло."},{"t":"h","text":"Короткі відповіді"},{"t":"p","text":"Відповідаємо тим самим словом, з якого почалося питання (do, is, can, did…), без основного дієслова. Просто Yes чи No може звучати різкувато, а повторювати все речення не треба."},{"t":"ex","items":[["Do you like it here? — **Yes, I do.**","Тобі тут подобається? — Так."],["Is Sarah at work? — **No, she isn't.**","Сара на роботі? — Ні."],["Can you drive? — **Yes, I can.**","Ти вмієш водити? — Так."],["Did they pay you? — **No, they didn't.**","Вони тобі заплатили? — Ні."]]},{"t":"tip","text":"У короткій відповіді «так» не скорочуємо: **Yes, I am.** **Yes, he is.** Неправильно: Yes, I'm."},{"t":"h","text":"Питання з питальним словом"},{"t":"p","text":"Коли питаєш не «так чи ні», а «де? коли? чому?», питальне слово стає на самий початок. Далі все як у питанні «так чи ні». Якщо в реченні є be, can чи will, do не додаємо: Where **is** the van? What time **will** you be here?"},{"t":"rule","title":"Порядок слів","lines":["питальне слово + допоміжне + підмет + дієслово","**Where** do you live?","**When** does the bus come?","**Why** did he leave?","**What** are you doing?"]},{"t":"table","head":["Слово","Значення","Приклад"],"rows":[["what","що? який?","What do you want?"],["what time","о котрій?","What time do you finish?"],["where","де? куди?","Where are you going?"],["when","коли?","When does the shop open?"],["why","чому?","Why are you late?"],["who","хто? кого? кому?","Who is your boss?"],["which","який (з кількох)?","Which van is yours?"],["whose","чий?","Whose phone is this?"],["how","як?","How do you get to work?"]]},{"t":"table","head":["Слово","Значення","Приклад"],"rows":[["how much","скільки (не лічимо)","How much is it?"],["how many","скільки (лічимо)","How many boards do we need?"],["how long","як довго?","How long does it take?"],["how often","як часто?","How often do you go to the gym?"],["how old","скільки років?","How old are you?"]]},{"t":"tip","text":"**How much** — для того, що не рахуємо поштучно: money, time, water. **How many** — для того, що можна порахувати: people, days, boards. How much is it? — «Скільки це коштує?»"},{"t":"ex","items":[["**What time** do you finish today?","О котрій ти сьогодні закінчуєш?"],["**How long** does it take to get to Gorey?","Скільки часу їхати до Горі?"],["**How many** sheets of plasterboard do we need?","Скільки листів гіпсокартону нам треба?"],["**Whose** jacket is this?","Чия це куртка?"],["**Where** is the nearest Lidl?","Де найближчий Лідл?"],["**Why** didn't you tell me?","Чому ти мені не сказав?"]]},{"t":"h","text":"Хто зробив? Питання без do"},{"t":"p","text":"Коли **who** або **what** питає саме про підмет (хто зробив? що сталося?), do / does / did **не потрібні**. Порядок слів як у звичайному реченні, просто замість підмета стоїть who чи what. Дієслово після них — як після he: Who **lives** here? Так само, коли підмет — which або what з іменником: **Which bus goes** to Wexford?"},{"t":"p","text":"В українській різниця видна в самому слові: «**Хто** тобі дзвонив?» і «**Кому** ти дзвонив?». В англійській обидва рази who, тому різницю показує did."},{"t":"rule","title":"Хто? чи Кому?","lines":["**Who called** you? — **Tom** called me.","**Who did** you **call**? — I called **Tom**."]},{"t":"ex","items":[["**Who called** you?","Хто тобі дзвонив?"],["**Who did** you **call**?","Кому ти дзвонив?"],["**What happened**?","Що сталося?"],["**What did** he **say**?","Що він сказав?"],["**Who wants** a cup of tea?","Хто хоче чаю?"],["**Which bus goes** to Wexford?","Який автобус їде до Вексфорда?"]]},{"t":"h","text":"Прийменник — у кінці"},{"t":"p","text":"В українській прийменник стоїть перед питальним словом: «**Для кого** це?», «**Про що** ти говориш?», «**З ким** ти працюєш?». В англійській прийменник (for, about, with, from) зазвичай іде **в самий кінець** питання: Who do you work **with**? Так само «Звідки ти?» — Where are you **from**?"},{"t":"ex","items":[["Where are you **from**?","Звідки ти?"],["Who is it **for**?","Для кого це?"],["What are you talking **about**?","Про що ти говориш?"],["Who do you work **for**?","На кого ти працюєш?"],["What's this tool **for**?","Для чого цей інструмент?"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Where you live?","right":"Where do you live?","why":"Без допоміжного дієслова питання не складається: питальне слово + do + підмет + дієслово."},{"t":"mistake","wrong":"Who did call you?","right":"Who called you?","why":"Питаємо про підмет (хто дзвонив?), тому did не потрібне. Who did you call? — уже інше питання: «Кому ти дзвонив?»"},{"t":"mistake","wrong":"What means this word?","right":"What does this word mean?","why":"Підмет тут this word (саме воно щось означає), а what питає, що саме. Тому does + this word + mean без -s."},{"t":"mistake","wrong":"Why you didn't come?","right":"Why didn't you come?","why":"Didn't, як і did, стоїть перед підметом."},{"t":"mistake","wrong":"From where are you?","right":"Where are you from?","why":"Прийменник іде в кінець питання."}],"tasks":[{"type":"choice","q":"___ you be at home tonight?","uk":"Ти будеш удома сьогодні ввечері?","opts":["Will","Do","Are"],"a":0,"why":"«Будеш» — це will. Will стає перед підметом you, а be залишається після нього. Do і are з be так не поєднуються."},{"type":"choice","q":"___ your brother at home now?","uk":"Твій брат зараз удома?","opts":["Is","Does","Do"],"a":0,"why":"Звичайного дієслова тут немає: «бути вдома» — це be (is). Тому is переходить на початок, а do / does не потрібні."},{"type":"choice","q":"What time ___ you get home yesterday?","uk":"О котрій ти вчора повернувся додому?","opts":["did","do","were"],"a":0,"why":"Минулий час (yesterday) зі звичайним дієсловом — did, а get стоїть у початковій формі."},{"type":"input","q":"___ phone is this? — It's Mick's.","uk":"Чий це телефон? — Міка.","a":["Whose"],"why":"«Чий?» — whose. Не плутай з who's (= who is): звучить так само, але означає «хто є»."},{"type":"choice","q":"How ___ sheets of plasterboard do we need?","uk":"Скільки листів гіпсокартону нам треба?","opts":["many","much","long"],"a":0,"why":"Листи можна порахувати поштучно, тому how many. How much — для того, що не лічимо: money, time, water."},{"type":"input","q":"Did they pay you on Friday? — No, they ___.","uk":"Вони заплатили тобі в п'ятницю? — Ні.","a":["didn't","did not"],"why":"Коротка відповідь повторює допоміжне дієслово з питання: Did…? — No, they didn't."},{"type":"order","uk":"О котрій починається твоя зміна?","words":["time","your","start","does","what","shift"],"a":["What time does your shift start?"],"why":"Спочатку what time, потім does (your shift — це it), далі підмет your shift і start без -s."},{"type":"input","q":"Who ___ (live) in that house?","uk":"Хто живе в тому будинку?","a":["lives","is living"],"why":"Who питає про підмет (хто живе?), тому does не потрібне, а дієслово як після he: lives."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Кому ти дзвонив?","opts":["Who did you call?","Who called you?","Who you called?"],"a":0,"why":"Дзвонив ти, а питаємо, кому. Це питання не про підмет, тому потрібне did. Who called you? означає «Хто тобі дзвонив?»"},{"type":"choice","q":"What ___?","uk":"Що означає це слово?","opts":["does this word mean","means this word","does mean this word","does this word means"],"a":0,"why":"Підмет тут this word (воно щось означає), тому does + this word + mean. Після does дієслово без -s."},{"type":"order","uk":"Чому ти мені не подзвонив?","words":["call","didn't","me","you","why"],"a":["Why didn't you call me?"],"why":"Didn't, як і did, стоїть перед підметом: Why + didn't + you + call."},{"type":"order","uk":"Що ти шукаєш?","words":["for","you","what","looking","are"],"a":["What are you looking for?"],"why":"«Шукати» — look for. Прийменник for іде в самий кінець питання."}],"section":"basics"},"negatives":{"id":"negatives","level":"A2","title":"Negatives","uk":"Заперечення","summary":"not, don't, no, never, nothing: одне заперечення в реченні","minutes":8,"blocks":[{"t":"p","text":"В українській «не» просто ставимо перед дієсловом: «я не працюю». В англійській так не можна: **not** потребує опори — допоміжного дієслова (be, can, will, have або do). І друга важлива відмінність: у реченні має бути лише **одне** заперечення (про це нижче)."},{"t":"ex","items":[["I'm **not** sure.","Я не впевнений."],["I **don't** understand.","Я не розумію."],["She **can't** come today.","Вона сьогодні не може прийти."],["**Nobody** knows.","Ніхто не знає."]]},{"t":"h","text":"not після be, can, will, have"},{"t":"p","text":"Якщо в реченні є **am, is, are, was, were**, **can**, **will**, **must**, **should** або допоміжне **have**, просто ставимо **not** після цього слова. У розмові майже завжди скорочуємо. Зверни увагу: will not → **won't**, а cannot пишеться **разом**."},{"t":"table","head":["Повна форма","Скорочено"],"rows":[["I am not","I'm not"],["is not / are not","isn't / aren't"],["was not / were not","wasn't / weren't"],["cannot","can't"],["will not","won't"],["have not / has not","haven't / hasn't"],["must not / should not","mustn't / shouldn't"]]},{"t":"ex","items":[["The van **isn't** ready yet.","Фургон ще не готовий."],["Sorry, I **can't** come tomorrow.","Вибач, завтра я не можу прийти."],["It **won't** rain today.","Сьогодні дощу не буде."],["We **haven't** finished yet.","Ми ще не закінчили."]]},{"t":"h","text":"don't, doesn't, didn't зі звичайними дієсловами"},{"t":"p","text":"Зі звичайними дієсловами (work, know, go) not саме не стоїть. Додаємо **do + not**: don't, doesn't, didn't. Дієслово після них — у **початковій формі** (як у словнику): I didn't **go** (не didn't went), she doesn't **know** (не doesn't knows)."},{"t":"rule","title":"Заперечення зі звичайним дієсловом","lines":["I / you / we / they + **don't** + work","he / she / it + **doesn't** + work","минуле, усі особи: **didn't** + work"]},{"t":"ex","items":[["I **don't drink** coffee.","Я не п'ю кави."],["Mick **doesn't work** on Fridays.","Мік не працює по п'ятницях."],["We **didn't finish** the ceiling yesterday.","Ми вчора не закінчили стелю."]]},{"t":"h","text":"no + іменник"},{"t":"p","text":"**No** означає «жодного, ніякого» і стоїть **перед іменником**: There's **no** milk. Це те саме, що not … any: There **isn't any** milk. Після no не ставимо a чи the."},{"t":"ex","items":[["Sorry, there's **no** time.","Вибач, немає часу."],["I have **no** idea.","Гадки не маю."],["We've got **no** plasterboard left.","У нас закінчився гіпсокартон."],["There are **no** buses on Sundays.","У неділю автобусів немає."]]},{"t":"rule","title":"not чи no","lines":["**not** — з дієсловом: I'm **not** tired.","**no** — з іменником: I have **no** money.","те саме: I **don't** have **any** money."]},{"t":"h","text":"Одне заперечення на речення"},{"t":"p","text":"Це головна відмінність від української. Ми кажемо «Я **нічого не** знаю», «**Ніхто не** прийшов» — два заперечення, і так правильно. В англійській у реченні заперечення **одне**: або not (don't, didn't…), або слово-заперечення (nothing, nobody, nowhere, never)."},{"t":"rule","title":"Слова на no- і any-","lines":["nobody / no one = not … anybody / anyone (ніхто)","nothing = not … anything (нічого)","nowhere = not … anywhere (ніде, нікуди)","never = not … ever (ніколи)"]},{"t":"table","head":["Українською","З not","Без not"],"rows":[["Я нічого не знаю.","I don't know anything.","I know nothing."],["Я нікого не бачив.","I didn't see anybody.","I saw nobody."],["Немає де сісти.","There isn't anywhere to sit.","There's nowhere to sit."]]},{"t":"p","text":"Обидва варіанти правильні. З not … anything звучить звичайніше, по-розмовному, а nothing, nobody — твердіше. Але коли «ніхто» чи «ніщо» стоїть на початку як підмет (той, хто або що виконує дію), можливий лише варіант на no-: **Nobody** came. І дієслово після нього **ствердне**."},{"t":"ex","items":[["**Nobody** called.","Ніхто не дзвонив."],["**Nothing** happened.","Нічого не сталося."],["I **didn't** say **anything**.","Я нічого не сказав."],["I **can't** find my keys **anywhere**.","Я ніде не можу знайти ключі."],["**No one** told me.","Мені ніхто не сказав."]]},{"t":"tip","text":"**Never** теж уже заперечення: She **never** drinks coffee (не She doesn't never drink). Never стоїть перед звичайним дієсловом, але після am, is, are: He's **never** late."},{"t":"tip","text":"У піснях і на вулиці можна почути **I can't get no…** чи **I don't know nothing**. Це просторіччя, у нормальній англійській воно вважається помилкою. Сам так не кажи."},{"t":"h","text":"either — «теж не»"},{"t":"p","text":"Українське «теж» у запереченні — це **either** у кінці речення. Too і also — лише для ствердження. У короткій відповіді «я теж ні» — **Me neither**."},{"t":"rule","title":"Теж чи теж не","lines":["I like it **too**.","I don't like it **either**.","— I can't swim. — **Me neither.**"]},{"t":"ex","items":[["She didn't come **either**.","Вона теж не прийшла."],["Tom can't come **either**.","Том теж не може прийти."],["— I'm not hungry. — **Me neither.**","— Я не голодний. — Я теж."]]},{"t":"h","text":"Корисні короткі фрази"},{"t":"ex","items":[["**I don't think so.**","Не думаю. / Здається, ні."],["Is it ready? — **Not yet.**","Готово? — Ще ні."],["Are you tired? — **Not really.**","Ти втомився? — Не дуже."],["Do you mind if I open the window? — **Not at all.**","Ти не проти, якщо я відчиню вікно? — Зовсім ні."]]},{"t":"tip","text":"Англійці заперечують саме think: **I don't think** he's coming — «Думаю, він не прийде». Варіант I think he isn't coming теж можливий, але звучить менш природно."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I don't know nothing.","right":"I don't know anything.","why":"Два заперечення в одному реченні не можна: або don't + anything, або I know nothing."},{"t":"mistake","wrong":"Nobody didn't come.","right":"Nobody came.","why":"Nobody уже заперечення, тому дієслово ствердне: came, без didn't."},{"t":"mistake","wrong":"I not understand.","right":"I don't understand.","why":"Not не стоїть перед звичайним дієсловом сам: потрібне don't."},{"t":"mistake","wrong":"I don't have no money.","right":"I don't have any money.","why":"Після don't — any. Або коротше: I have no money."},{"t":"mistake","wrong":"I don't like it too.","right":"I don't like it either.","why":"У запереченні «теж» — either, а не too."}],"tasks":[{"type":"choice","q":"I ___ understand.","uk":"Я не розумію.","opts":["don't","not","am not"],"a":0,"why":"Understand — звичайне дієслово, тому заперечення don't. Саме not перед ним не ставлять, а am з understand не поєднується."},{"type":"choice","q":"She ___ eat meat.","uk":"Вона не їсть м'яса.","opts":["doesn't","don't","isn't"],"a":0,"why":"Eat — звичайне дієслово, а she — he / she / it, тому doesn't. Isn't — це is + not, зі звичайним дієсловом eat він не поєднується."},{"type":"input","q":"We ___ (not / go) to the pub last night.","uk":"Учора ввечері ми не ходили в паб.","a":["didn't go","did not go"],"why":"Минуле (last night): didn't + початкова форма go. Не didn't went: минулий час уже є в didn't."},{"type":"choice","q":"Don't worry, it ___ take long.","uk":"Не хвилюйся, це не займе багато часу.","opts":["won't","willn't","not will"],"a":0,"why":"Will not скорочується до won't. Форми willn't не існує, а not не ставлять перед will."},{"type":"choice","q":"There's ___ milk in the fridge.","uk":"У холодильнику немає молока.","opts":["no","not","any"],"a":0,"why":"Перед іменником, коли в реченні немає іншого заперечення, — no. Not іде з дієсловом (There isn't any milk), а any без not тут не підходить."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я нічого не знаю.","opts":["I don't know anything.","I don't know nothing.","I not know anything."],"a":0,"why":"В англійській одне заперечення: don't + anything. Don't + nothing — це два заперечення, а not перед know без do не ставлять."},{"type":"choice","q":"___ answered the phone.","uk":"Ніхто не взяв слухавку.","opts":["Nobody","Anybody","Somebody"],"a":0,"why":"«Ніхто» як підмет — nobody, і дієслово після нього ствердне: answered. Anybody без not не означає «ніхто», а somebody — це «хтось»."},{"type":"input","q":"I didn't see ___ on the site this morning.","uk":"Сьогодні вранці я нікого не бачив на об'єкті.","a":["anybody","anyone"],"why":"У реченні вже є didn't, тому далі anybody (anyone). Nobody тут дало б два заперечення."},{"type":"choice","q":"I ___ on Sundays.","uk":"Я ніколи не працюю в неділю.","opts":["never work","don't never work","never don't work"],"a":0,"why":"Never уже заперечення, тому don't не потрібне. Never стоїть перед дієсловом: I never work."},{"type":"input","q":"Kate can't swim, and I can't ___.","uk":"Кейт не вміє плавати, і я теж не вмію.","a":["either","swim either"],"why":"«Теж» у запереченні — either у кінці речення. Too — лише для ствердження: Kate can swim, and I can too."},{"type":"order","uk":"Сьогодні ми нікуди не їдемо.","words":["anywhere","aren't","today","going","we"],"a":["We aren't going anywhere today.","Today we aren't going anywhere."],"why":"Одне заперечення: aren't + anywhere. Today можна поставити в кінець або на початок."},{"type":"order","uk":"Не думаю, що він прийде.","words":["coming","don't","he's","think","I"],"a":["I don't think he's coming."],"why":"Англійці заперечують think: I don't think + ствердження he's coming. Так природніше, ніж I think he isn't coming."}],"section":"basics"},"imperatives":{"id":"imperatives","level":"A1","title":"Imperatives and let's","uk":"Наказовий спосіб і let's","summary":"прохання й інструкції: Close the door. Don't touch it. Let's go.","minutes":5,"blocks":[{"t":"p","text":"**Наказовий спосіб** — це коли просимо, наказуємо, даємо інструкцію чи пораду: «Подай», «Зачини», «Не чіпай». В англійській він найпростіший: береш **початкову форму дієслова** (як у словнику: pass, close, go) і нічого не додаєш. **Підмета** (того, хто виконує дію, тут you) теж немає. Форма одна для всіх: **Sit down** — і «сідай», і «сідайте»."},{"t":"ex","items":[["**Pass** me the trowel.","Подай мені кельму."],["**Close** the door.","Зачини двері."],["**Come** here a minute.","Підійди сюди на хвилинку."],["**Wait** for me!","Зачекай на мене!"],["**Turn** left at the roundabout.","На кільці поверни ліворуч."]]},{"t":"h","text":"Заперечення: don't"},{"t":"rule","title":"Заперечення","lines":["**Don't** + початкова форма дієслова","на знаках повна форма: **Do not** enter","на знаках ще **No** + -ing: No smoking, No parking"]},{"t":"ex","items":[["**Don't touch** that, it's hot.","Не чіпай, воно гаряче."],["**Don't worry**.","Не хвилюйся."],["**Don't forget** your keys.","Не забудь ключі."],["**Don't park** in front of the gate.","Не паркуйся перед воротами."]]},{"t":"tip","text":"Після don't — **без to** і без -s: Don't **go** (а не Don't to go). І заперечення завжди через don't: просто not на початку наказу не ставлять. **Don't touch**, а не Not touch."},{"t":"h","text":"З be: Be careful! Don't be late"},{"t":"p","text":"Коли далі йде не дія, а стан чи якість (careful — обережний, quiet — тихий, late — пізній, ready — готовий), потрібне дієслово **be**: **Be** careful. У запереченні — **Don't be**. Am, is, are тут не вживаємо. Українське «не запізнюйся» — дієслово, а англійською буквально «не будь пізнім»: **Don't be late**."},{"t":"ex","items":[["**Be careful!**","Обережно!"],["**Be quiet**, please.","Тихіше, будь ласка."],["**Be** ready at seven.","Будь готовий о сьомій."],["**Don't be late** tomorrow.","Не запізнюйся завтра."],["**Don't be** shy.","Не соромся."]]},{"t":"h","text":"Ввічливіше: please, just, could you"},{"t":"p","text":"Голий наказ англійською звучить **різкіше**, ніж український. Між колегами на роботі «Pass me the level» — нормально, але англійці майже завжди трохи пом'якшують:"},{"t":"list","items":["**please** на початку чи в кінці: **Please** close the door. Pass me the level, **please**.","**just** — «лише, на хвилинку»: **Just** hold this for a second.","питання замість наказу: **Can you** help me? **Could you** open the door?","до незнайомих і до боса краще **Could you…?** (докладно — у темі про прохання)","побажання й запрошення — теж наказовий спосіб, і вони зовсім не грубі: **Have** a good weekend! **Help** yourself."]},{"t":"ex","items":[["Pass me the level, **please**.","Подай мені рівень, будь ласка."],["**Just** hold this for a second.","Потримай це секунду."],["**Could you** open the door, please?","Ви не могли б відчинити двері?"],["**Have** a good weekend!","Гарних вихідних!"],["**Help** yourself.","Пригощайся."],["**Take** care!","Бережи себе!"]]},{"t":"h","text":"Let's: пропонуємо зробити разом"},{"t":"p","text":"**Let's** (скорочено від let us) — українське «ходімо», «почнімо», «давай…». Пропонуєш зробити щось **разом**, і ти теж це робиш. Після let's — початкова форма дієслова **без to**. У розмові завжди кажи let's: повне let us звучить офіційно."},{"t":"rule","title":"Пропозиція","lines":["**Let's** + початкова форма: Let's **go**.","**Let's not** + початкова форма: Let's not **wait**."]},{"t":"ex","items":[["**Let's go**.","Ходімо."],["**Let's start** at eight.","Почнімо о восьмій."],["**Let's have** a break.","Зробімо перерву."],["**Let's not** tell the boss yet.","Не кажімо поки що босові."],["**Let's get** a takeaway tonight.","Візьмімо сьогодні їжу на виніс."],["I don't know. **Let's see**.","Не знаю. Подивимося."]]},{"t":"tip","text":"Не плутай **let's** і **let me**. Let's — «давай разом». Let me — «дай я», «дозволь мені»: **Let me** help you (дай я допоможу)."},{"t":"h","text":"Always, never: правила й безпека"},{"t":"p","text":"В інструкціях і правилах безпеки на початок часто ставлять **always** (завжди) або **never** (ніколи). **Never** уже означає «ніколи не», тому don't з ним не потрібне."},{"t":"ex","items":[["**Always wear** a helmet on site.","На об'єкті завжди носи каску."],["**Never leave** the site open.","Ніколи не залишай об'єкт відчиненим."],["**Always check** the scaffolding first.","Завжди спершу перевіряй риштування."],["**Never stand** on the top step of a ladder.","Ніколи не ставай на верхню сходинку драбини."],["**Mind** your head!","Обережно, голова!"],["**Watch out!**","Стережися!"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Not touch it!","right":"Don't touch it!","why":"Заперечний наказ починається з don't, а не з not."},{"t":"mistake","wrong":"Don't to go there.","right":"Don't go there.","why":"Після don't іде початкова форма дієслова без to."},{"t":"mistake","wrong":"Let's to start.","right":"Let's start.","why":"Після let's теж без to: Let's start, Let's go."},{"t":"mistake","wrong":"Don't late tomorrow.","right":"Don't be late tomorrow.","why":"Late — не дієслово, а «пізній», тому потрібне be: Don't be late."},{"t":"mistake","wrong":"Don't be worry.","right":"Don't worry.","why":"Worry — уже дієслово («хвилюватися»), тому be не потрібне. Be ставимо лише перед словами-станами: Don't be late, Don't be shy."}],"tasks":[{"type":"choice","q":"___ the door, please.","uk":"Зачини, будь ласка, двері.","opts":["Close","Closes","To close"],"a":0,"why":"Наказ — це початкова форма дієслова без підмета, без -s і без to."},{"type":"choice","q":"___ touch that, it's hot!","uk":"Не чіпай, воно гаряче!","opts":["Not","Don't","No"],"a":1,"why":"Заперечний наказ — don't + дієслово. Not чи no перед дієсловом у наказі не ставлять."},{"type":"choice","q":"___ me a hand with this, please.","uk":"Допоможи мені з цим, будь ласка.","opts":["Give","Gives","Giving"],"a":0,"why":"Give me a hand — «допоможи». Наказ — початкова форма дієслова, без -s і без -ing."},{"type":"input","q":"___ (not / be) late tomorrow.","uk":"Не запізнюйся завтра.","a":["Don't be"],"why":"Late — не дієслово, тому потрібне be. Заперечення: Don't be late."},{"type":"choice","q":"Let's ___ a break.","uk":"Зробімо перерву.","opts":["have","to have","having"],"a":0,"why":"Після let's — початкова форма дієслова без to: Let's have a break."},{"type":"input","q":"___ go home, it's late.","uk":"Ходімо додому, вже пізно.","a":["Let's"],"why":"Пропонуємо щось зробити разом — Let's + дієслово."},{"type":"input","q":"___ wear a helmet on site.","uk":"На об'єкті завжди носи каску.","a":["Always"],"why":"У правилах always ставимо на початок, перед дієсловом: Always wear…"},{"type":"choice","q":"Let's ___ the boss yet.","uk":"Не кажімо поки що босові.","opts":["not tell","don't tell","not to tell"],"a":0,"why":"Заперечення з let's — Let's not + дієслово, без don't і без to."},{"type":"choice","q":"___ stand on the top step of a ladder.","uk":"Ніколи не ставай на верхню сходинку драбини.","opts":["Never","Don't never","Not ever"],"a":0,"why":"Never уже означає «ніколи не», тому don't з ним не потрібне, а Not на початку наказу не ставлять."},{"type":"choice","task":"Як найввічливіше попросити незнайому людину?","q":"","opts":["Give me the pen.","You give me the pen!","Could you pass me the pen, please?"],"a":2,"why":"Голий наказ до незнайомої людини звучить різко, а з you і знаком оклику — ще й сердито. Краще питання: Could you…, please?"},{"type":"order","uk":"Будь ласка, не паркуйся біля воріт.","words":["park","the","please","near","don't","gate"],"a":["Please don't park near the gate.","Don't park near the gate, please."],"why":"Please можна поставити на початок або в кінець. Далі don't + дієслово."},{"type":"order","uk":"Обережно на цій драбині.","words":["ladder","careful","this","be","on"],"a":["Be careful on this ladder."],"why":"Careful — не дієслово, а «обережний», тому наказ будуємо з be: Be careful."}],"section":"basics"},"present-simple":{"id":"present-simple","level":"A1","title":"Present Simple","uk":"Теперішній простий час","summary":"звички, факти, розклад: I work, she works","minutes":6,"blocks":[{"t":"p","text":"**Present Simple** — час для того, що відбувається **регулярно** або є **завжди правдою**: звички, робота, факти, розклад. Не «зараз, у цю хвилину», а «взагалі, зазвичай»."},{"t":"ex","items":[["I **work** on a building site.","Я працюю на будівництві."],["We **start** at eight every morning.","Ми починаємо щоранку о восьмій."],["Water **boils** at 100 degrees.","Вода кипить за 100 градусів."],["The bus **leaves** at 6:40.","Автобус відходить о 6:40."]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Ствердження","lines":["I / you / we / they + **work**","he / she / it + work**s**"]},{"t":"p","text":"Головне правило: після **he, she, it** до дієслова додаємо **-s**. Те саме, коли підмет (хто або що виконує дію) — одна людина чи річ: **my boss works**, **the van needs** petrol. Це найчастіша помилка українців, бо в нас дієслово змінюється по-іншому."},{"t":"table","head":["Дієслово закінчується на","Додаємо","Приклад"],"rows":[["більшість дієслів","-s","work → work**s**"],["-s, -sh, -ch, -x","-es","watch → watch**es**"],["go, do","-es","go → go**es**, do → do**es**"],["приголосна + y","y → -ies","carry → carr**ies**"],["голосна + y","-s","play → play**s**"],["have (виняток)","has","she **has**"]]},{"t":"h","text":"Заперечення і питання"},{"t":"rule","title":"Заперечення","lines":["I / you / we / they + **don't** + work","he / she / it + **doesn't** + work"]},{"t":"rule","title":"Питання","lines":["**Do** + I / you / we / they + work?","**Does** + he / she / it + work?"]},{"t":"tip","text":"Коли з'являється **does** або **doesn't**, закінчення -s у дієслові **зникає**: воно вже «сидить» у does. Правильно: She doesn't **work**. Does he **live** here?"},{"t":"ex","items":[["She **doesn't drive** to work.","Вона не їздить на роботу машиною."],["**Do** you **speak** Polish?","Ти розмовляєш польською?"],["**Does** your boss **pay** on Fridays?","Твій бос платить щоп'ятниці?"],["Where **do** you **live**? — I **live** in Courtown.","Де ти живеш? — Я живу в Кортауні."]]},{"t":"h","text":"Короткі відповіді"},{"t":"p","text":"На питання з do/does можна відповісти просто Yes або No, але природніше звучить коротка відповідь з тим самим допоміжним дієсловом."},{"t":"ex","items":[["Do you like your job? — **Yes, I do.**","Тобі подобається твоя робота? — Так."],["Does he speak English? — **No, he doesn't.**","Він розмовляє англійською? — Ні."]]},{"t":"h","text":"Слова-підказки"},{"t":"p","text":"Present Simple часто стоїть поруч зі словами, що відповідають на питання «як часто?»: **always** (завжди), **usually** (зазвичай), **often** (часто), **sometimes** (іноді), **never** (ніколи), **every day** (щодня), **on Mondays** (щопонеділка), **twice a week** (двічі на тиждень)."},{"t":"tip","text":"Always, usually, often, sometimes, never ставимо **перед** звичайним дієсловом, але **після** am, is, are: I **usually get** up at six. He **is always** late."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"He work in Dublin.","right":"He works in Dublin.","why":"Після he, she, it дієслово отримує -s."},{"t":"mistake","wrong":"She doesn't works on Sundays.","right":"She doesn't work on Sundays.","why":"Після doesn't дієслово без -s: закінчення вже в doesn't."},{"t":"mistake","wrong":"Do he like football?","right":"Does he like football?","why":"Для he, she, it питання починаємо з does."},{"t":"mistake","wrong":"I am work here.","right":"I work here.","why":"Am, is, are не додаємо до звичайного дієслова: «я працюю» — просто I work."}],"tasks":[{"type":"choice","q":"My brother ___ in a factory.","uk":"Мій брат працює на заводі.","opts":["work","works","working"],"a":1,"why":"My brother — це він (he), тому до work додаємо -s."},{"type":"choice","q":"They ___ English at home.","uk":"Вони не розмовляють англійською вдома.","opts":["don't speak","doesn't speak","not speak"],"a":0,"why":"Для they заперечення don't. Doesn't лише для he, she, it, а саме not перед дієсловом не ставлять."},{"type":"choice","q":"___ your friend live in Dublin?","uk":"Твій друг живе в Дубліні?","opts":["Do","Does","Is"],"a":1,"why":"Your friend — це він або вона, тому питання починаємо з Does."},{"type":"choice","q":"The shop ___ at nine in the morning.","uk":"Магазин відчиняється о дев'ятій ранку.","opts":["open","opens","opening"],"a":1,"why":"Розклад — це Present Simple, а the shop — це it, тому opens."},{"type":"choice","task":"Яке речення правильне?","q":"","opts":["She doesn't likes coffee.","She don't like coffee.","She doesn't like coffee."],"a":2,"why":"Для she заперечення doesn't, а після нього дієслово без -s."},{"type":"input","q":"He ___ (watch) football every weekend.","uk":"Він дивиться футбол щовихідних.","a":["watches"],"why":"Дієслово на -ch отримує -es: watch → watches."},{"type":"input","q":"My boss ___ (have) two vans.","uk":"У мого боса два фургони.","a":["has","has got"],"why":"Have для he, she, it перетворюється на has. Можна й has got — те саме значення."},{"type":"input","q":"We ___ (not / work) on Sundays.","uk":"Ми не працюємо в неділю.","a":["don't work","do not work"],"why":"We + don't + дієслово без змін."},{"type":"input","q":"___ he usually take the bus?","uk":"Він зазвичай їздить автобусом?","a":["Does"],"why":"Питання про he починаємо з Does, а дієслово take залишається без -s."},{"type":"input","q":"The baby often ___ (cry) at night.","uk":"Дитина часто плаче вночі.","a":["cries"],"why":"Приголосна + y: y змінюємо на -ies (cry → cries)."},{"type":"order","uk":"Де ти зазвичай обідаєш?","words":["usually","you","do","where","lunch","have"],"a":["Where do you usually have lunch?"],"why":"Питання: питальне слово + do + you, далі usually перед дієсловом have."},{"type":"order","uk":"Він ніколи не запізнюється на роботу.","words":["late","is","work","never","he","for"],"a":["He is never late for work."],"why":"Never стоїть після is, але перед звичайним дієсловом."}],"section":"present"},"present-continuous":{"id":"present-continuous","level":"A1","title":"Present Continuous","uk":"Теперішній тривалий час","summary":"що відбувається зараз: I'm working, she's sleeping","minutes":6,"blocks":[{"t":"p","text":"**Present Continuous** — час для того, що відбувається **зараз**, у цю хвилину, або **тимчасово**, у цей період. В українській «я працюю» може означати і «взагалі», і «саме зараз». В англійській це два різні часи: I **work** (взагалі) і I'**m working** (зараз)."},{"t":"ex","items":[["**I'm working** at the moment.","Я зараз працюю."],["Look! **It's raining**.","Дивись! Іде дощ."],["Mick **is talking** to the boss.","Мік розмовляє з босом."],["**We're painting** the hall today.","Сьогодні ми фарбуємо коридор."]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Ствердження","lines":["I + **am** + work**ing**","he / she / it + **is** + work**ing**","you / we / they + **are** + work**ing**"]},{"t":"p","text":"Обов'язкові **дві частини**: am / is / are і **форма з -ing** (дієслово + -ing: work → working). Am, is, are тут — допоміжне дієслово: окремо не перекладається, але без нього речення неправильне. Яке саме — залежить від **підмета** (хто або що виконує дію)."},{"t":"tip","text":"У розмові am, is, are скорочуємо: **I'm**, **he's**, **she's**, **it's**, **we're**, **you're**, **they're** working."},{"t":"h","text":"Правопис -ing"},{"t":"table","head":["Дієслово","Що робимо","Приклад"],"rows":[["більшість дієслів","+ ing","work → work**ing**"],["німе -e в кінці","e відкидаємо","make → mak**ing**"],["-ee в кінці","нічого не міняємо","see → see**ing**"],["-ie в кінці","ie → y","lie → l**y**ing"],["одна голосна + одна приголосна","подвоюємо приголосну","run → ru**nn**ing"]]},{"t":"tip","text":"Німе e — те, що не вимовляється: make → making, come → coming, write → writing, have → having. Останню приголосну подвоюємо, коли слово закінчується на **одну голосну + одну приголосну** і наголос падає на цей останній склад: sit → sitting, stop → stopping, get → getting, begin → beginning. Але rain → raining (дві голосні), visit → visiting (наголос на початку), а w, x, y не подвоюємо: fix → fixing, play → playing. У британській англійській l подвоюють і без наголосу: travel → trave**ll**ing."},{"t":"h","text":"Заперечення і питання"},{"t":"rule","title":"Заперечення","lines":["I'm **not** working.","he / she / it **isn't** working.","you / we / they **aren't** working."]},{"t":"rule","title":"Питання","lines":["**Am** I working?","**Is** he / she / it working?","**Are** you / we / they working?","What **are** you do**ing**?"]},{"t":"p","text":"Do і does тут не потрібні: для питання am, is, are просто стають перед підметом. Коротка відповідь — теж з ними: Yes, I **am**. No, he **isn't**."},{"t":"ex","items":[["They **aren't working** today.","Вони сьогодні не працюють."],["**Are** you **coming**? — Yes, I **am**.","Ти йдеш? — Так."],["**Is** Tom **working** today? — No, he **isn't**.","Том сьогодні працює? — Ні."],["Why **are** you **laughing**?","Чому ти смієшся?"]]},{"t":"h","text":"Коли вживаємо"},{"t":"p","text":"**1. Зараз, у цю хвилину.** Дія відбувається, поки ми говоримо."},{"t":"ex","items":[["Sorry, I can't talk, **I'm driving**.","Вибач, не можу говорити, я за кермом."],["**Listen!** Somebody **is knocking** at the door.","Слухай! Хтось стукає у двері."]]},{"t":"p","text":"**2. Тимчасово, у цей період.** Не обов'язково саме цієї секунди: щось триває якийсь час, але не завжди."},{"t":"ex","items":[["**I'm living** with a friend this month.","Цього місяця я живу в друга."],["**We're working** on a big house in Gorey this week.","Цього тижня ми працюємо над великим будинком у Горі."],["Kate **is learning** to drive.","Кейт учиться водити."]]},{"t":"p","text":"**3. Зміни.** Щось поступово стає більшим, кращим, дорожчим."},{"t":"ex","items":[["Prices **are going up**.","Ціни ростуть."],["Your English **is getting** better.","Твоя англійська покращується."],["The days **are getting** shorter.","Дні стають коротшими."]]},{"t":"h","text":"Слова-підказки"},{"t":"p","text":"**now** (зараз), **right now** (просто зараз), **at the moment** (зараз, у цей момент), **today** (сьогодні), **this week** (цього тижня), **these days** (останнім часом), а також **Look!** (Дивись!) і **Listen!** (Слухай!) на початку."},{"t":"tip","text":"Деякі дієслова майже не бувають з -ing навіть «зараз»: **know**, **want**, **like**, **need**, **understand**. Кажемо I **know**, I **want** a coffee. Детальніше — у темі «Present Simple чи Continuous»."},{"t":"tip","text":"Present Continuous буває й про майбутнє, коли вже домовилися: **I'm meeting** Tom tomorrow. — «Завтра я зустрічаюся з Томом». Про це — у темі про going to."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I working now.","right":"I'm working now.","why":"Без am, is, are не можна: потрібні обидві частини, am і форма з -ing."},{"t":"mistake","wrong":"She is play in the garden.","right":"She's playing in the garden.","why":"Після is дієслово отримує -ing. Is + play — це лише половина форми."},{"t":"mistake","wrong":"Are you work today?","right":"Are you working today?","why":"Про «сьогодні, зараз» — Are you working? Про роботу взагалі — Do you work? Are + work без -ing не буває."},{"t":"mistake","wrong":"I am go to Lidl.","right":"I'm going to Lidl.","why":"Am + початкова форма не буває. Зараз — I'm going (am + форма з -ing), а регулярно, взагалі — I go."},{"t":"mistake","wrong":"We're siting in the van.","right":"We're sitting in the van.","why":"Sit — коротке слово на голосну + приголосну, тому t подвоюємо: sitting."}],"tasks":[{"type":"choice","q":"Be quiet! The baby ___.","uk":"Тихо! Дитина спить.","opts":["is sleeping","sleeps","sleeping"],"a":0,"why":"Зараз, у цю хвилину — Present Continuous: is + форма з -ing. Без is (просто sleeping) не можна."},{"type":"choice","q":"___ you listening to me?","uk":"Ти мене слухаєш?","opts":["Are","Do","Is"],"a":0,"why":"Питання в Present Continuous починаємо з am / is / are. Для you — are. Do з формою з -ing не поєднується."},{"type":"choice","q":"They ___ lunch at the moment.","uk":"Вони зараз обідають.","opts":["are having","is having","having"],"a":0,"why":"They — are, далі форма з -ing. Have lunch (обідати) — це дія, тому з -ing можна."},{"type":"choice","q":"Is it still raining? — No, it ___.","uk":"Ще йде дощ? — Ні.","opts":["isn't","doesn't","not"],"a":0,"why":"Коротка відповідь повторює допоміжне дієслово з питання: Is it…? — No, it isn't. Doesn't тут не підходить."},{"type":"input","q":"I can't talk now. I ___ (make) dinner.","uk":"Не можу зараз говорити. Я готую вечерю.","a":["am making"],"why":"Зараз — Present Continuous: am + форма з -ing. Німе e в кінці відкидаємо: make → making."},{"type":"input","q":"Look! Tom ___ (run) for the bus.","uk":"Дивись! Том біжить до автобуса.","a":["is running"],"why":"Look! — дія відбувається зараз: is + форма з -ing. Run — коротке слово на голосну + приголосну, тому n подвоюємо: running."},{"type":"input","q":"The dog ___ (lie) on my bed again!","uk":"Пес знову лежить на моєму ліжку!","a":["is lying"],"why":"Пес лежить саме зараз — is + форма з -ing. У дієсловах на -ie: ie → y, тому lie → lying."},{"type":"input","q":"Mick ___ (not / work) at the moment. He's on his break.","uk":"Мік зараз не працює, у нього перерва.","a":["isn't working","is not working"],"why":"At the moment — мова про «зараз». Заперечення: isn't + форма з -ing."},{"type":"choice","q":"Look, it ___ dark. Let's go home.","uk":"Дивись, уже темніє. Ходімо додому.","opts":["is getting","gets","getting"],"a":0,"why":"Зміна, що відбувається зараз (стає темно), — Present Continuous: is getting. It gets dark — про те, що буває взагалі."},{"type":"order","uk":"Що ти зараз робиш?","words":["doing","now","what","you","are"],"a":["What are you doing now?"],"why":"Питальне слово, потім are перед підметом you, далі форма з -ing. Now — у кінці."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Цього тижня Андрій живе в нас.","opts":["Andrii is staying with us this week.","Andrii stays with us this week.","Andrii staying with us this week."],"a":0,"why":"Тимчасово (this week) — Present Continuous: is + форма з -ing. Stays — для постійного, а без is речення неповне."},{"type":"order","uk":"Вона зараз не слухає.","words":["listening","the","isn't","she","at","moment"],"a":["She isn't listening at the moment.","At the moment she isn't listening."],"why":"Підмет she, далі isn't і форма з -ing. At the moment можна поставити в кінець або на початок."}],"section":"present"},"simple-vs-continuous":{"id":"simple-vs-continuous","level":"A2","title":"Present Simple or Continuous","uk":"Present Simple чи Continuous","summary":"I work чи I'm working; know, want, like зазвичай без -ing","minutes":6,"blocks":[{"t":"p","text":"Головне питання: це **взагалі** чи **зараз**? **Present Simple** (I work) — звички, факти, те, що постійно. **Present Continuous** (I'm working) — те, що відбувається зараз або тимчасово. В українській обидва — «я працюю», тому щоразу треба вирішувати."},{"t":"table","head":["Present Simple","Present Continuous"],"rows":[["звичка, регулярно","зараз, у цю хвилину"],["постійне, факти","тимчасове, у цей період"],["usually, often, every day","now, at the moment, this week"],["I **work** in Dublin.","**I'm working** from home today."]]},{"t":"ex","items":[["I **drive** to work every day.","Я щодня їжджу на роботу машиною."],["Sorry, I can't talk, **I'm driving**.","Вибач, не можу говорити, я за кермом."],["Sarah **works** in a shop.","Сара працює в магазині."],["Sarah **is working** from home this week.","Цього тижня Сара працює з дому."],["It **rains** a lot in Ireland.","В Ірландії часто йде дощ."],["Take an umbrella, **it's raining**.","Візьми парасольку, іде дощ."]]},{"t":"h","text":"What do you do? чи What are you doing?"},{"t":"p","text":"Класична пастка. **What do you do?** — питання про роботу: «Ким ти працюєш?», «Чим займаєшся?». **What are you doing?** — «Що ти (зараз) робиш?»."},{"t":"ex","items":[["What **do** you **do**? — I'm a builder.","Ким ти працюєш? — Я будівельник."],["What **are** you **doing**? — **I'm fixing** the door.","Що ти робиш? — Лагоджу двері."],["What **does** Kate **do**? — She's a nurse.","Ким працює Кейт? — Вона медсестра."]]},{"t":"h","text":"Дієслова стану: зазвичай без -ing"},{"t":"p","text":"Деякі дієслова означають не дію, а **стан**: що ти знаєш, відчуваєш, хочеш, що кому належить. Стан — не процес, тому -ing до таких дієслів зазвичай не додаємо, навіть коли мова про «зараз»: I **know** (не I'm knowing), I **want** a coffee (не I'm wanting)."},{"t":"table","head":["Значення","Дієслова"],"rows":[["знати, розуміти, пам'ятати","know, understand, remember"],["вірити, означати, здаватися","believe, mean, seem"],["почуття: подобається чи ні","like, love, hate, prefer"],["хотіти, потребувати","want, need"],["володіти, належати","own, belong"],["коштувати","cost"]]},{"t":"ex","items":[["I **don't understand**. Can you say it again?","Я не розумію. Можеш повторити?"],["Do you **know** where Tom is?","Ти знаєш, де Том?"],["I **need** a bigger ladder.","Мені потрібна більша драбина."],["This van **belongs** to my boss.","Цей фургон належить моєму босу."],["You **seem** tired.","Ти, здається, втомився."],["How much **does** it **cost**?","Скільки це коштує?"]]},{"t":"tip","text":"У рекламі чи розмові можна почути **I'm loving it** або **I'm loving this weather**. Це емоційний розмовний стиль. Сам спокійно кажи **I love it**, **I like it** — так завжди правильно."},{"t":"h","text":"Дієслова з двома значеннями"},{"t":"p","text":"Деякі дієслова бувають і станом, і дією. Коли це стан — без -ing, коли дія — з -ing."},{"t":"rule","title":"think: вважати чи обмірковувати","lines":["**I think** it's fine. = я вважаю (думка)","**I'm thinking** about it. = обмірковую (процес)"]},{"t":"rule","title":"have: мати чи робити щось","lines":["**I have** a van. / **I've got** a van. = у мене є","**I'm having** lunch / a shower / a break. = дія"]},{"t":"rule","title":"see і taste","lines":["**I see.** = зрозуміло","**I'm seeing** Tom tonight. = зустрічаюся","It **tastes** good. = має смак","He's **tasting** the soup. = куштує"]},{"t":"ex","items":[["Do you **think** it will rain?","Думаєш, буде дощ?"],["**I'm thinking** about a new job.","Я подумую про нову роботу."],["Kate **has** two kids.","У Кейт двоє дітей."],["**We're having** a break.","У нас перерва."],["I **see** what you mean.","Я розумію, що ти маєш на увазі."],["This coffee **tastes** strange.","У цієї кави дивний смак."]]},{"t":"tip","text":"«Бачу» й «чую» про те, що відбувається зараз, англійці зазвичай кажуть з can, а не з -ing: I **can see** the bus. I **can hear** you."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I am knowing him.","right":"I know him.","why":"Know — стан, а не дія, тому без -ing навіть «зараз»."},{"t":"mistake","wrong":"I'm wanting a coffee.","right":"I want a coffee.","why":"Want — бажання, тобто стан, тому без -ing. Ще ввічливіше: I'd like a coffee."},{"t":"mistake","wrong":"What are you do?","right":"What are you doing?","why":"Після are — форма з -ing. А якщо питаєш про професію, то What do you do?"},{"t":"mistake","wrong":"I am working here every day.","right":"I work here every day.","why":"Every day — звичка, а для звичок Present Simple."}],"tasks":[{"type":"choice","q":"Tom usually ___ to work by bus.","uk":"Том зазвичай їздить на роботу автобусом.","opts":["goes","is going","go"],"a":0,"why":"Usually — звичка, отже Present Simple. Tom — це he, тому goes."},{"type":"choice","q":"Listen! The phone ___.","uk":"Слухай! Телефон дзвонить.","opts":["is ringing","rings","ring"],"a":0,"why":"Listen! — дія відбувається саме зараз, тому Present Continuous: is ringing."},{"type":"choice","q":"What ___? — I'm an electrician.","uk":"Ким ти працюєш? — Я електрик.","opts":["do you do","are you doing","you do"],"a":0,"why":"Про професію питають What do you do? What are you doing? — це «Що ти зараз робиш?», а без do питання неправильне."},{"type":"input","q":"This jacket ___ (cost) 80 euros.","uk":"Ця куртка коштує 80 євро.","a":["costs"],"why":"Cost — стан (ціна), а не дія, тому без -ing. This jacket — це it, тому costs."},{"type":"choice","q":"Sorry, I ___ your name.","uk":"Вибач, я не пам'ятаю, як тебе звати.","opts":["don't remember","am not remembering","not remember"],"a":0,"why":"Remember — стан, тому Present Simple: don't remember. Саме not перед дієсловом без don't не ставлять."},{"type":"input","q":"She ___ (not / like) her new job.","uk":"Їй не подобається її нова робота.","a":["doesn't like","does not like"],"why":"Like — стан, тому без -ing навіть зараз. Для she — doesn't, а like без -s."},{"type":"input","q":"We ___ (work) on a new school in Wexford this month.","uk":"Цього місяця ми працюємо на будівництві школи у Вексфорді.","a":["are working"],"why":"This month — тимчасово, на певний період, тому Present Continuous: are working."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Мені зараз потрібна твоя допомога.","opts":["I need your help now.","I'm needing your help now.","I needing your help now."],"a":0,"why":"Need — стан, тому навіть із now буде Present Simple: I need."},{"type":"choice","q":"I ___ about moving to Dublin.","uk":"Я подумую про переїзд до Дубліна.","opts":["am thinking","think","thinks"],"a":0,"why":"Think about у значенні «обмірковувати» — процес, тому з -ing: I'm thinking. I think = «я вважаю»."},{"type":"input","q":"Can you call back later? We ___ (have) dinner.","uk":"Можеш передзвонити пізніше? Ми вечеряємо.","a":["are having"],"why":"Have dinner — дія (вечеряти), а не «мати», тому з -ing можна. Вечеряємо саме зараз — are having."},{"type":"order","uk":"Що ти думаєш про цей план?","words":["plan","you","of","think","what","this","do"],"a":["What do you think of this plan?"],"why":"Тут think — думка (вважати), тобто стан, тому Present Simple: What do you think of…?"},{"type":"order","uk":"Про що ти думаєш?","words":["about","you","thinking","are","what"],"a":["What are you thinking about?"],"why":"Тут think — процес, що йде зараз, тому are + thinking. Прийменник about — у кінці питання."}],"section":"present"},"present-perfect":{"id":"present-perfect","level":"A2","title":"Present Perfect","uk":"Теперішній доконаний час: have done","summary":"досвід, результат зараз, just/already/yet: I've done it","minutes":8,"blocks":[{"t":"p","text":"**Present Perfect** (have/has + V3, тобто третя форма дієслова) пов'язує минуле з **теперішнім**. Дія вже сталася, але важливо не коли, а що з цього маємо **зараз**: досвід («я бував у Дубліні»), результат («я загубив ключі — їх досі немає»), свіжу новину або те, що почалося раніше й триває досі. Українською ми просто скажемо «я зробив», а англієць обирає між I did і I have done."},{"t":"ex","items":[["I**'ve lost** my keys.","Я загубив ключі. (Їх досі немає.)"],["**Have** you ever **been** to Spain?","Ти колись був в Іспанії?"],["The boss **has** just **paid** us.","Бос щойно нам заплатив."]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Ствердження","lines":["I / you / we / they + **have** + V3","he / she / it + **has** + V3"]},{"t":"p","text":"**Have** і **has** тут — допоміжні дієслова: службові слова, які будують час. «Мати» вони тут не означають. Зміст несе **V3** — третя форма дієслова (V2 — друга, для Past Simple). У правильних дієслів V2 і V3 однакові й пишуться за тими самими правилами, що в Past Simple: work → **worked**, stop → **stopped**, study → **studied**. Неправильні треба знати: go → went → **gone**, see → saw → **seen**, do → did → **done**. Найчастіші з них зібрано в темі «Неправильні дієслова»."},{"t":"table","head":["Повна форма","Скорочено"],"rows":[["I have, you have","I've, you've"],["we have, they have","we've, they've"],["he has, she has, it has","he's, she's, it's"],["have not, has not","haven't, hasn't"]]},{"t":"tip","text":"У розмові майже завжди скорочують. **He's** буває і he is, і he has. Підказка — наступне слово: якщо далі V3 (left, gone, been), то це зазвичай has. She**'s** tired = she **is**. She**'s** left = she **has**."},{"t":"h","text":"Заперечення і питання"},{"t":"rule","title":"Заперечення","lines":["I / you / we / they + **haven't** + V3","he / she / it + **hasn't** + V3"]},{"t":"rule","title":"Питання","lines":["**Have** + I / you / we / they + V3?","**Has** + he / she / it + V3?"]},{"t":"p","text":"Do, does і did у цьому часі не потрібні: їхню роботу виконують have і has. Коротка відповідь — теж з have або has: Yes, I **have**. No, she **hasn't**."},{"t":"ex","items":[["I **haven't met** his wife.","Я ще не знайомився з його дружиною."],["**Has** Mick **called** you? — Yes, he **has**.","Мік тобі дзвонив? — Так."],["**Have** you **finished**? — No, I **haven't**.","Ти закінчив? — Ні."]]},{"t":"h","text":"Досвід: ever, never, скільки разів"},{"t":"p","text":"Тут ідеться про те, що людина **робила чи не робила** щось за життя (до сьогодні), а коли саме — неважливо. У питаннях часто **ever** (колись, хоч раз), у відповідях **never** (ніколи), **before** (раніше), а ще **once** (раз), **twice** (двічі), **three times** (тричі)."},{"t":"ex","items":[["**Have** you ever **worked** on a farm?","Ти колись працював на фермі?"],["I**'ve never driven** a van.","Я ніколи не водив фургон."],["She**'s been** to Dublin three times.","Вона тричі бувала в Дубліні."],["This is the best pizza I**'ve** ever **eaten**.","Це найкраща піца, яку я коли-небудь їв."]]},{"t":"tip","text":"**Never** уже означає «ніколи не», тому haven't з ним не ставимо: I've never been there. В українському «я ніколи **не** був» два заперечення, а в англійському — лише одне."},{"t":"h","text":"Результат зараз"},{"t":"p","text":"Дія відбулася раніше, а **наслідок є зараз**. Англієць думає не «коли це було», а «що маємо тепер»."},{"t":"ex","items":[["Someone **has broken** the window.","Хтось розбив вікно. (Воно й досі розбите.)"],["The price of petrol **has gone up**.","Бензин подорожчав."],["Tom **has cut** his hand. He can't work.","Том порізав руку. Він не може працювати."]]},{"t":"h","text":"Слова just, already, yet"},{"t":"table","head":["Слово","Значення","Приклад"],"rows":[["just","щойно","has **just** left"],["already","вже (раніше, ніж чекали)","have **already** paid"],["yet — у питанні","вже?","Have you eaten **yet**?"],["yet — у запереченні","ще не","I haven't eaten **yet**."]]},{"t":"p","text":"**Just** і **already** ставимо між have/has і V3, а **yet** — у кінці речення. У цьому значенні yet буває лише в питаннях і запереченнях."},{"t":"ex","items":[["The boss **has just arrived**.","Бос щойно приїхав."],["We**'ve already plastered** the kitchen.","Ми вже заштукатурили кухню."],["**Have** you **paid** for the tiles **yet**?","Ти вже заплатив за плитку?"],["The paint **hasn't dried yet**.","Фарба ще не висохла."]]},{"t":"tip","text":"В Ірландії часто почуєш **I'm after finishing** — це те саме, що I've just finished (я щойно закінчив). Це ірландська особливість: розумій цей вираз, а в листах і на іспитах пиши I've just finished."},{"t":"h","text":"been чи gone"},{"t":"p","text":"Для «поїхав, пішов» є дві «треті форми» з різним змістом. **been** (V3 від be) — з'їздив і повернувся (бував). **gone** (V3 від go) — поїхав і досі там, тут його немає."},{"t":"ex","items":[["Mick **has been** to Dublin.","Мік їздив у Дублін. (Уже повернувся.)"],["Mick **has gone** to Dublin.","Мік поїхав у Дублін. (Він зараз там.)"],["Where **have** you **been**? — I**'ve** just **been** to Lidl.","Де ти був? — Щойно ходив у Лідл."]]},{"t":"h","text":"Досі триває: for і since"},{"t":"p","text":"Ще одне значення: щось почалося в минулому й **триває досі**, а ти кажеш, скільки часу (**for** two years) чи з якого моменту (**since** 2024). Українською тут теперішній час («живу», «знаю»), а англійською — Present Perfect. Докладніше — у темах «Present Perfect чи Past Simple» і «Present Perfect Continuous»."},{"t":"ex","items":[["I**'ve lived** in Wexford for two years.","Я живу у Вексфорді вже два роки."],["How long **have** you **known** Tom?","Як давно ти знаєш Тома?"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Tom has went home.","right":"Tom has gone home.","why":"Після have/has потрібна V3: go → went → gone. Went — це V2, вона лише для Past Simple."},{"t":"mistake","wrong":"Have you finish?","right":"Have you finished?","why":"Після have завжди V3, а не початкова форма дієслова: finish → finished."},{"t":"mistake","wrong":"Did you ever be in Spain?","right":"Have you ever been to Spain?","why":"Про досвід за життя питаємо в Present Perfect: Have you ever been…? До того ж did з be не вживається взагалі."},{"t":"mistake","wrong":"I haven't never been to London.","right":"I've never been to London.","why":"Never уже заперечення, друге (haven't) не потрібне."},{"t":"mistake","wrong":"I have seen him yesterday.","right":"I saw him yesterday.","why":"Коли названо, коли саме (yesterday, last week, in 2023), — тільки Past Simple. Докладніше в темі «Present Perfect чи Past Simple»."}],"tasks":[{"type":"choice","q":"They ___ painted the kitchen.","uk":"Вони пофарбували кухню.","opts":["have","has","did"],"a":0,"why":"They + have + V3. Has — лише для he, she, it, а did з V3 не поєднується."},{"type":"choice","q":"I've ___ this film before.","uk":"Я вже бачив цей фільм.","opts":["saw","seen","see"],"a":1,"why":"Після have потрібна V3: see → saw → seen. Saw — це V2, її вживаємо без have, у Past Simple."},{"type":"input","q":"___ Tom finished the wall yet?","uk":"Том уже закінчив стіну?","a":["Has"],"why":"Tom — це he, тому питання починаємо з Has. Yet у кінці питання означає «вже?»."},{"type":"input","q":"Have you ever ___ (eat) Irish stew?","uk":"Ти колись куштував ірландське рагу?","a":["eaten"],"why":"Після have — V3. Eat — неправильне дієслово: eat → ate → eaten."},{"type":"choice","q":"___ you ever been to Cork?","uk":"Ти колись бував у Корку?","opts":["Have","Did","Were"],"a":0,"why":"Питання про досвід за життя: Have + you + ever + V3. Did і were з been не поєднуються."},{"type":"input","q":"She ___ (not / call) me yet.","uk":"Вона мені ще не подзвонила.","a":["hasn't called","has not called"],"why":"Заперечення для she: hasn't + V3 (called). Yet у кінці речення означає «ще не»."},{"type":"choice","q":"Sarah isn't here. She ___ to Gorey.","uk":"Сари тут немає. Вона поїхала в Горі.","opts":["has been","has gone","have gone"],"a":1,"why":"Gone — поїхала і досі там. Has been означало б, що вона вже повернулася. Have не підходить, бо для she — has."},{"type":"input","q":"We've already ___ (do) the ceiling.","uk":"Ми вже зробили стелю.","a":["done"],"why":"Після have — V3: do → did → done. Did — це V2 для Past Simple."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я ніколи не був у Лондоні.","opts":["I haven't never been to London.","I've never been to London.","I've never went to London."],"a":1,"why":"Never уже означає «ніколи не», тому haven't не додаємо. А після have — V3 been, а не V2 went."},{"type":"input","q":"I ___ (be) to Dublin three times.","uk":"Я тричі бував у Дубліні.","a":["have been"],"why":"Скільки разів за життя — Present Perfect: have + V3. Be → was/were → been, а been to означає «бував у»."},{"type":"order","uk":"Я ще не заплатив за оренду.","words":["paid","rent","I","yet","the","haven't"],"a":["I haven't paid the rent yet.","I haven't yet paid the rent."],"why":"Заперечення: I + haven't + V3 (paid), а yet — у кінці речення."},{"type":"order","uk":"Бос щойно приїхав.","words":["just","boss","arrived","the","has"],"a":["The boss has just arrived."],"why":"Just стоїть між has і V3: has just arrived."}],"section":"present"},"perfect-vs-past":{"id":"perfect-vs-past","level":"A2","title":"Present Perfect or Past Simple","uk":"Present Perfect чи Past Simple","summary":"I've seen it чи I saw it yesterday: як обрати час","minutes":7,"blocks":[{"t":"p","text":"Українське «я бачив» годиться і для «вчора», і для «колись у житті». Англійською це два різні часи, і вибір залежить від одного питання: **чи йдеться про конкретний час, який уже минув?** Так (yesterday, in 2023 або зі змісту ясно, коли саме) — **Past Simple**. Ні (коли саме — неважливо, або період ще триває) — **Present Perfect**."},{"t":"ex","items":[["I **saw** Tom yesterday.","Я бачив Тома вчора."],["I**'ve seen** this film.","Я бачив цей фільм. (Коли — неважливо.)"],["She **moved** to Ireland in 2023.","Вона переїхала до Ірландії 2023 року."],["She**'s lived** in three countries.","Вона жила в трьох країнах."]]},{"t":"table","head":["Past Simple","Present Perfect"],"rows":[["час відомий і вже минув","час неважливий або ще триває"],["yesterday, last week","ever, never, before"],["two days ago, in 2023","just, already, yet"],["When…? What time…?","so far, lately"],["this morning (уже минув)","today, this week (ще триває)"]]},{"t":"h","text":"Час названий — Past Simple"},{"t":"p","text":"Якщо в реченні є **завершений** момент чи період — yesterday, last night, last week, two days ago (два дні тому), in 2023, on Monday, at five o'clock, when I was a child, — потрібен **Past Simple**. Навіть якщо результат видно досі."},{"t":"ex","items":[["We **finished** the job last Friday.","Ми закінчили роботу минулої п'ятниці."],["I **lost** my keys two days ago.","Я загубив ключі два дні тому."],["**When did** you **arrive**? — At eight.","Коли ти приїхав? — О восьмій."]]},{"t":"tip","text":"Питання про минуле з **When…?** (коли?) і **What time…?** (о котрій?) — у Past Simple, бо відповідь на них — конкретний час. When **did** you **arrive**? — правильно. When have you arrived? — помилка. Про майбутнє, звісно, питаємо інакше: When **will** you **finish**?"},{"t":"h","text":"Час не названий — Present Perfect"},{"t":"p","text":"Коли час не названий (досвід, новина, результат) або період **ще не закінчився** — today, this week, this year, so far (поки що), lately (останнім часом), — потрібен **Present Perfect**. Сюди ж ever, never, just, already, yet."},{"t":"ex","items":[["I**'ve had** three coffees today.","Я сьогодні випив три кави."],["We**'ve plastered** four rooms so far.","Поки що ми заштукатурили чотири кімнати."],["**Have** you **seen** Kate this week?","Ти бачив Кейт цього тижня?"]]},{"t":"tip","text":"**Today**, **this morning**, **this week**: дивись, чи період ще триває. О десятій ранку: I**'ve had** two coffees this morning. Увечері, коли ранок уже минув: I **had** two coffees this morning."},{"t":"h","text":"Спершу новина, потім подробиці"},{"t":"p","text":"У розмові часто так: перше речення — новина або досвід (**Present Perfect**). Щойно переходимо до подробиць — коли, де, як, — **Past Simple**."},{"t":"ex","items":[["I**'ve been** to Spain. I **went** there in 2022.","Я був в Іспанії. Їздив туди 2022 року."],["Mick**'s had** an accident! — How **did** it **happen**?","Мік потрапив в аварію! — Як це сталося?"],["**Have** you ever **been** to Cork? — Yes, I **went** last summer.","Ти колись бував у Корку? — Так, їздив минулого літа."]]},{"t":"h","text":"for: досі чи вже ні"},{"t":"p","text":"**for** (протягом, стільки-то часу) буває в обох часах, але сенс різний. Past Simple — це вже закінчилося. Present Perfect — це триває досі."},{"t":"ex","items":[["I **lived** in Dublin for two years.","Я жив у Дубліні два роки. (Уже не живу.)"],["I**'ve lived** in Wexford for two years.","Я живу у Вексфорді вже два роки. (І досі.)"],["I**'ve known** Andrii since 2024.","Я знаю Андрія з 2024 року."],["How long **have** you **had** this van?","Як давно в тебе цей фургон?"]]},{"t":"tip","text":"Українською кажемо «**живу** вже два роки», «**знаю** з 2024 року» — теперішнім часом. Англійською так не можна: якщо щось почалося в минулому й триває досі, а ти кажеш «скільки» (**for**) чи «відколи» (**since**, з якогось моменту), потрібен Present Perfect. Для дій (work, wait) тут часто кажуть have been working — див. тему «Present Perfect Continuous»."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I have seen him yesterday.","right":"I saw him yesterday.","why":"Yesterday — завершений час, тому тільки Past Simple."},{"t":"mistake","wrong":"When have you arrived?","right":"When did you arrive?","why":"When…? про минуле питає про конкретний момент, тому Past Simple, а не Present Perfect."},{"t":"mistake","wrong":"I live here since 2024.","right":"I've lived here since 2024.","why":"Почалося в минулому й триває досі — Present Perfect. Present Simple із since не вживають, хоч українською й кажемо «живу з 2024 року»."},{"t":"mistake","wrong":"I've finished work at five.","right":"I finished work at five.","why":"At five — названий час, тому Past Simple."}],"tasks":[{"type":"choice","q":"I ___ Tom yesterday.","uk":"Я бачив Тома вчора.","opts":["saw","have seen","see"],"a":0,"why":"Yesterday — завершений час, тому Past Simple. Present Perfect з yesterday не вживаємо."},{"type":"choice","q":"We ___ four rooms so far.","uk":"Поки що ми пофарбували чотири кімнати.","opts":["painted","have painted","paint"],"a":1,"why":"So far (поки що) — період ще триває, тому Present Perfect: have + V3."},{"type":"input","q":"She ___ (move) to Wexford two years ago.","uk":"Вона переїхала до Вексфорда два роки тому.","a":["moved"],"why":"Ago (тому) — завершений момент у минулому, тому Past Simple: moved."},{"type":"choice","q":"When ___ you arrive in Ireland?","uk":"Коли ти приїхав в Ірландію?","opts":["did","have","do"],"a":0,"why":"When…? про минуле питає про конкретний момент, тому Past Simple: When did you arrive? Present Perfect з when не вживаємо, а do — теперішній час."},{"type":"input","q":"I ___ (not / see) Mick yet.","uk":"Я ще не бачив Міка.","a":["haven't seen","have not seen"],"why":"Yet (ще не) — дія ще може статися, тому Present Perfect: haven't + V3 (see → saw → seen)."},{"type":"choice","q":"I've been to Spain. I ___ there in 2022.","uk":"Я був в Іспанії. Їздив туди 2022 року.","opts":["went","have been","have gone"],"a":0,"why":"Спершу досвід (Present Perfect), а подробиця з роком (in 2022) — уже Past Simple."},{"type":"input","q":"I ___ (work) in Poland for two years. Now I work in Ireland.","uk":"Я два роки працював у Польщі. Тепер працюю в Ірландії.","a":["worked"],"why":"Робота в Польщі вже закінчилася, тому for + Past Simple: worked."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я закінчив роботу о п'ятій.","opts":["I've finished work at five.","I finished work at five.","I've finish work at five."],"a":1,"why":"At five — названий час, тому Past Simple. Present Perfect з конкретним часом не вживаємо."},{"type":"input","q":"I ___ (know) Kate since 2023.","uk":"Я знаю Кейт з 2023 року.","a":["have known"],"why":"Since (з якогось моменту й досі) — Present Perfect: have + V3. Українською «знаю», а англійською have known."},{"type":"choice","q":"I ___ here since 2024.","uk":"Я живу тут з 2024 року.","opts":["live","have lived","lived"],"a":1,"why":"Почалося 2024 року й триває досі — Present Perfect. Present Simple і Past Simple із since тут не підходять."},{"type":"order","uk":"Коли ти купив цей фургон?","words":["when","you","buy","did","this","van"],"a":["When did you buy this van?"],"why":"When…? про минуле — Past Simple: When + did + you + початкова форма дієслова (buy)."},{"type":"order","uk":"Ти колись працював на фермі?","words":["worked","farm","ever","on","have","you","a"],"a":["Have you ever worked on a farm?"],"why":"Досвід за життя без названого часу — Present Perfect: Have + you + ever + V3."}],"section":"present"},"present-perfect-continuous":{"id":"present-perfect-continuous","level":"B1","title":"Present Perfect Continuous","uk":"Теперішній доконано-тривалий: have been doing","summary":"скільки вже триває дія: I've been working here for two years","minutes":7,"blocks":[{"t":"p","text":"**Present Perfect Continuous** (have/has been + форма з -ing) — для дії, що **почалася в минулому й триває досі**, коли ми кажемо, **як довго** вона триває. Українською тут теперішній час: «я працюю тут два роки». Англійською ні: I work — це «взагалі», I'm working — «зараз», а для «вже два роки» кажуть I've been working."},{"t":"ex","items":[["I**'ve been working** here for two years.","Я працюю тут уже два роки."],["How long **have** you **been waiting**?","Скільки ти вже чекаєш?"],["It**'s been raining** since this morning.","Дощ іде з самого ранку."]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Ствердження","lines":["I / you / we / they + **have been** + -ing","he / she / it + **has been** + -ing"]},{"t":"p","text":"**Форма з -ing** — дієслово із закінченням -ing: work → working, make → making, sit → sitting (правопис той самий, що в Present Continuous). **Been** не змінюється ніколи. У розмові скорочують: I've been, she's been, haven't been, hasn't been."},{"t":"rule","title":"Заперечення","lines":["I / you / we / they + **haven't been** + -ing","he / she / it + **hasn't been** + -ing"]},{"t":"rule","title":"Питання","lines":["**Have** + I / you / we / they + **been** + -ing?","**Has** + he / she / it + **been** + -ing?"]},{"t":"ex","items":[["**Has** Tom **been working** here long?","Том давно тут працює?"],["She **hasn't been sleeping** well lately.","Вона останнім часом погано спить."],["We**'ve been living** in Gorey since March.","Ми живемо в Горі з березня."]]},{"t":"h","text":"for чи since"},{"t":"p","text":"**for** — скільки часу, тобто відрізок: for two hours, for a year. **since** — з якого моменту (година, день, рік чи подія): since eight o'clock, since Monday, since 2024, since I came here (відколи я сюди приїхав)."},{"t":"table","head":["for (скільки)","since (з якого моменту)"],"rows":[["for ten minutes","since eight o'clock"],["for three days","since Monday"],["for two years","since 2024"],["for a long time","since I came here"]]},{"t":"ex","items":[["How long **have** you **been learning** English? — For about a year.","Скільки ти вже вчиш англійську? — Близько року."],["He**'s been driving** since six this morning.","Він за кермом з шостої ранку."]]},{"t":"h","text":"Недавня дія, наслідки якої видно"},{"t":"p","text":"Ще одне значення: дія тривала до недавнього часу (може, щойно закінчилася), і зараз видно її **наслідки**: втому, бруд, мокру землю. Скільки вона тривала, можна й не казати."},{"t":"ex","items":[["I'm tired because I**'ve been plastering** all day.","Я втомився, бо цілий день штукатурив."],["Your hands are dirty. What **have** you **been doing**?","У тебе брудні руки. Що ти робив?"],["The ground is wet. It**'s been raining**.","Земля мокра: ішов дощ."]]},{"t":"h","text":"have been doing чи have done"},{"t":"p","text":"**have done** (Present Perfect Simple) — про **результат**: що зроблено, скільки штук, скільки разів. **have been doing** — про **процес**: чим займався і як довго. Якщо називаєш кількість зробленого — тільки have done."},{"t":"table","head":["have been doing","have done"],"rows":[["процес, як довго","результат, скільки"],["може ще тривати","уже зроблено"],["How long…?","How many…? How much…?"]]},{"t":"ex","items":[["I**'ve been painting** all morning.","Я фарбую з самого ранку."],["I**'ve painted** two rooms.","Я пофарбував дві кімнати."],["She**'s been calling** you all day.","Вона дзвонить тобі цілий день."],["She**'s called** you three times.","Вона дзвонила тобі тричі."]]},{"t":"h","text":"Дієслова стану: зазвичай have done"},{"t":"p","text":"Деякі дієслова означають **стан**, а не дію: know (знати), like, love, hate, want, need, believe, understand, own (володіти), be, а також have у значенні «мати». Їх зазвичай не вживають з -ing, навіть коли кажемо «як довго». Тоді просто Present Perfect: have/has + V3 (третя форма дієслова)."},{"t":"ex","items":[["I**'ve known** him for years.","Я знаю його багато років."],["We**'ve had** this van since 2020.","Цей фургон у нас з 2020 року."],["She**'s been** in Ireland for six months.","Вона в Ірландії вже пів року."]]},{"t":"tip","text":"З **live** і **work** можна обидва варіанти майже без різниці: I've lived here for five years = I've been living here for five years."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I am working here for two years.","right":"I've been working here for two years.","why":"Present Continuous — лише про «зараз». Коли кажеш, скільки вже триває, — have been + -ing."},{"t":"mistake","wrong":"I work here since 2024.","right":"I've been working here since 2024.","why":"Почалося в минулому й триває досі — have been + -ing, а не Present Simple, як в українському «працюю з 2024 року»."},{"t":"mistake","wrong":"I've been knowing him for years.","right":"I've known him for years.","why":"Know — дієслово стану, з -ing його не вживають."},{"t":"mistake","wrong":"I've been waiting since two hours.","right":"I've been waiting for two hours.","why":"Two hours — відрізок часу, тому for. Since — лише перед моментом: since two o'clock."}],"tasks":[{"type":"choice","q":"I ___ waiting for twenty minutes.","uk":"Я чекаю вже двадцять хвилин.","opts":["have been","am","have"],"a":0,"why":"Чекаю досі й кажу, скільки, — have been + -ing. Am waiting — лише «зараз», без тривалості, а have waiting — такої форми немає."},{"type":"choice","q":"She's been working here ___ March.","uk":"Вона працює тут з березня.","opts":["for","since","from"],"a":1,"why":"March — момент, з якого все почалося, тому since. For — перед відрізком часу (for two months), а from без to чи until тут не вживаємо."},{"type":"input","q":"I've been learning English ___ a year.","uk":"Я вчу англійську вже рік.","a":["for"],"why":"A year — відрізок часу (скільки), тому for. Since — лише перед моментом: since May."},{"type":"input","q":"It ___ been raining since Monday.","uk":"Дощ іде з понеділка.","a":["has"],"why":"It — як he і she, тому has been + -ing."},{"type":"choice","q":"___ Mick been working here long?","uk":"Мік давно тут працює?","opts":["Has","Have","Is"],"a":0,"why":"Питання: Has + he/she/it + been + -ing. Mick — це he, тому Has."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я працюю тут з 2024 року.","opts":["I work here since 2024.","I've been working here since 2024.","I'm working here since 2024."],"a":1,"why":"Почалося 2024 року й триває досі — have been + -ing. Present Simple і Present Continuous із since не вживаємо."},{"type":"input","q":"He ___ (drive) since six this morning.","uk":"Він за кермом з шостої ранку.","a":["has been driving"],"why":"Дія почалася о шостій і триває досі: he + has been + форма з -ing."},{"type":"choice","q":"I ___ Tom since we were kids.","uk":"Я знаю Тома з дитинства.","opts":["have known","have been knowing","know"],"a":0,"why":"Know — дієслово стану, тому без -ing: have known. Present Simple know із since не вживаємо."},{"type":"choice","q":"Kate ___ three walls today.","uk":"Кейт сьогодні заштукатурила три стіни.","opts":["has plastered","has been plastering","have plastered"],"a":0,"why":"Скільки зроблено (три стіни) — результат, тому has + V3. Has been plastering — про процес і тривалість. Have не підходить, бо Kate — це she."},{"type":"choice","q":"I'm tired because I ___ plasterboard all morning.","uk":"Я втомився, бо цілий ранок носив гіпсокартон.","opts":["have been carrying","am carrying","have been carried"],"a":0,"why":"Дія тривала весь ранок, і зараз видно наслідок (втому) — have been + -ing. Am carrying — лише «зараз», а have been carried означало б «мене носили»."},{"type":"order","uk":"Скільки ти вже чекаєш?","words":["long","you","been","how","have","waiting"],"a":["How long have you been waiting?"],"why":"Питання: How long + have + you + been + форма з -ing."},{"type":"order","uk":"Ми живемо тут з березня.","words":["living","since","we've","here","March","been"],"a":["We've been living here since March.","Since March we've been living here."],"why":"We've been + -ing, далі місце (here), а since March — зазвичай у кінці речення."}],"section":"present"},"past-simple":{"id":"past-simple","level":"A1","title":"Past Simple","uk":"Минулий простий час","summary":"завершені дії в минулому: I worked, I went, did you…?","minutes":8,"blocks":[{"t":"p","text":"**Past Simple** — минулий час для дій, які **сталися й закінчилися** в минулому: вчора, минулого тижня, у 2020 році. Українською це звичайне «працював», «купив», «поїхав». Дія вже позаду, і зрозуміло, коли вона була."},{"t":"ex","items":[["I **worked** in Gorey yesterday.","Я вчора працював у Горі."],["We **finished** the ceiling on Friday.","Ми закінчили стелю в п'ятницю."],["Tom **bought** a new van last month.","Том купив новий фургон минулого місяця."],["It **was** really cold this morning.","Сьогодні вранці було дуже холодно."]]},{"t":"h","text":"Правильні дієслова: додаємо -ed"},{"t":"rule","title":"Ствердження","lines":["I / you / he / she / it / we / they + work**ed**"]},{"t":"p","text":"Більшість дієслів **правильні**: їхня минула форма (її називають **V2**, друга форма дієслова) утворюється за правилом: до **початкової форми** (як у словнику: work, start) додаємо **-ed**. Добра новина: форма **однакова для всіх**. I worked, he worked, they worked, без жодного -s для he, she, it."},{"t":"table","head":["Дієслово","Що робимо","Приклад"],"rows":[["більшість дієслів","+ -ed","work → work**ed**"],["закінчується на -e","+ -d","live → live**d**"],["приголосна + y","y → -ied","carry → carr**ied**"],["голосна + y","+ -ed","play → play**ed**"],["короткі: stop, plan, drop","подвоюємо + -ed","stop → sto**pped**"],["одна голосна + l (британське)","подвоюємо l","travel → trave**lled**"]]},{"t":"tip","text":"Коли подвоювати: дієслово **з одного складу** закінчується на **одну голосну + одну приголосну**: stop → stopped, plan → planned, rob → robbed. Не подвоюємо, якщо голосних дві (rain → rained), приголосних дві (help → helped) або в кінці w, x (fix → fixed)."},{"t":"h","text":"Як вимовляти -ed"},{"t":"p","text":"-ed пишеться однаково, але звучить трьома способами. Запам'ятай головне: **окремий склад «ід»** буває лише після звуків **t** і **d** (want-ed, need-ed). В інших словах -ed складу не додає: worked — це одне коротке «воркт», а не «воркед». Дивимося на останній **звук**, а не на літеру: like закінчується на звук k, тому liked — «лайкт»."},{"t":"table","head":["Звучить","Коли","Приклади"],"rows":[["/t/ «т»","після p, k, s, f, sh, ch","work**ed**, stopp**ed**, wash**ed**"],["/d/ «д»","після інших звуків","play**ed**, clean**ed**, liv**ed**"],["/ɪd/ «ід»","після t і d","want**ed**, need**ed**, start**ed**"]]},{"t":"ex","items":[["I **worked** late and **washed** the van.","Я працював допізна й помив фургон."],["We **cleaned** up and **played** cards.","Ми прибрали й пограли в карти."],["He **started** at seven and **wanted** to finish early.","Він почав о сьомій і хотів закінчити раніше."]]},{"t":"h","text":"Неправильні дієслова"},{"t":"p","text":"Частина дієслів, і саме найчастіших, **неправильні**: у них своя V2 без -ed, яку треба просто запам'ятати. Ось ті, без яких не обійтися й дня. Понад 60 найчастіших, розбитих на групи, — у наступній темі «Неправильні дієслова»."},{"t":"table","head":["Дієслово","V2","Переклад"],"rows":[["go","went","іти, їхати"],["have","had","мати"],["get","got","отримувати, діставатися"],["do","did","робити"],["make","made","робити, виготовляти"],["see","saw","бачити"],["come","came","приходити, приїжджати"],["take","took","брати"],["buy","bought","купувати"],["say","said","казати"],["tell","told","розповідати, казати"],["leave","left","іти, їхати звідкись; залишати"]]},{"t":"ex","items":[["I **went** to Lidl after work.","Я після роботи сходив у Lidl."],["We **had** a long day yesterday.","У нас учора був довгий день."],["Sarah **got** a new job last week.","Сара минулого тижня отримала нову роботу."],["Mick **left** the site at five.","Мік поїхав з об'єкта о п'ятій."]]},{"t":"h","text":"Заперечення і питання: did"},{"t":"p","text":"Для заперечення й питання потрібне **did** — **допоміжне дієслово**: службове слово, яке будує питання й заперечення, а окремо не перекладається. Воно однакове для всіх осіб."},{"t":"rule","title":"Заперечення","lines":["I / he / we / they + **didn't** + work","didn't = did not"]},{"t":"rule","title":"Питання","lines":["**Did** + you / he / they + work?","Where / When / Why + **did** + you + work?"]},{"t":"tip","text":"Головне правило: коли в реченні є **did** або **didn't**, дієслово стоїть у **початковій формі**. Минулий час уже «сидить» у did, двічі його не показуємо. Не didn't went, а didn't **go**. Не Did you saw, а Did you **see**."},{"t":"ex","items":[["I **didn't go** to work on Monday.","Я не ходив на роботу в понеділок."],["Mick **didn't finish** the wall.","Мік не закінчив стіну."],["**Did** you **see** the match last night? — **Yes, I did.**","Ти бачив учорашній матч? — Так."],["**Did** Olena **call** you? — **No, she didn't.**","Олена тобі дзвонила? — Ні."],["Where **did** you **buy** that drill?","Де ти купив цей дриль?"],["What time **did** the bus **come**?","О котрій приїхав автобус?"]]},{"t":"p","text":"Порівняй з українською: «Ти бачив матч?» — питання лише інтонацією. В англійській так не можна, на початку потрібне **Did**. З питальними словами (where, when, what, why) схема та сама: питальне слово + **did** + **підмет** (хто виконує дію) + дієслово."},{"t":"h","text":"Was і were"},{"t":"p","text":"Дієслово **be** (бути) — особливе: у минулому має дві форми, **was** і **were**, і будує заперечення й питання **без did**. Детально — у темі «Дієслово to be»."},{"t":"rule","title":"Be в минулому","lines":["I / he / she / it + **was**","you / we / they + **were**","**wasn't**, **weren't**","**Was** he…? **Were** you…?"]},{"t":"ex","items":[["**Were** you at work yesterday? — No, I **wasn't**.","Ти вчора був на роботі? — Ні."],["The shop **was** closed, so we **went** home.","Магазин був зачинений, тож ми поїхали додому."]]},{"t":"h","text":"Слова-підказки"},{"t":"p","text":"Past Simple майже завжди поруч зі словами, які називають **конкретний час у минулому**: **yesterday** (учора), **last night** (учора ввечері), **last week / month / year** (минулого тижня / місяця / року), **two days ago** (два дні тому), **in 2020** (у 2020 році), **when I was a child** (коли я був дитиною)."},{"t":"tip","text":"**Ago** («тому») стоїть **після** проміжку часу, як і в українській: three years **ago** — три роки тому. Не кажи before three years. А з **last** не потрібні ні the, ні in: I was in Dublin **last week**."},{"t":"ex","items":[["Andrii came to Ireland three years **ago**.","Андрій приїхав в Ірландію три роки тому."],["We moved to Wexford **in 2021**.","Ми переїхали у Вексфорд у 2021 році."],["**When I was a child**, I lived in a small village.","Коли я був дитиною, я жив у маленькому селі."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I didn't went to work.","right":"I didn't go to work.","why":"Після didn't — початкова форма дієслова. Минулий час уже показує did."},{"t":"mistake","wrong":"Did you saw the boss?","right":"Did you see the boss?","why":"У питанні з did дієслово теж у початковій формі: see, а не saw."},{"t":"mistake","wrong":"I goed home early.","right":"I went home early.","why":"Go — неправильне дієслово, його V2 — went. -ed додаємо лише до правильних."},{"t":"mistake","wrong":"Where you went yesterday?","right":"Where did you go yesterday?","why":"Після питального слова потрібне did, а дієслово — у початковій формі."},{"t":"mistake","wrong":"He didn't came on time.","right":"He didn't come on time.","why":"Після didn't — come, а не came: двічі минулий час не показуємо."}],"tasks":[{"type":"choice","q":"We ___ the kitchen yesterday.","uk":"Ми вчора пофарбували кухню.","opts":["paint","painted","painting"],"a":1,"why":"Yesterday — це минуле, а paint — правильне дієслово, тому додаємо -ed: painted."},{"type":"input","q":"We ___ (stop) for lunch at one.","uk":"О першій ми зробили перерву на обід.","a":["stopped"],"why":"Stop — один склад, у кінці голосна + приголосна, тому подвоюємо p: stopped."},{"type":"input","q":"Tom ___ (carry) the boards to the van.","uk":"Том відніс дошки до фургона.","a":["carried"],"why":"Приголосна + y: y змінюємо на -ied (carry → carried). Після голосної y лишається: play → played."},{"type":"choice","task":"У якому слові -ed звучить як окремий склад «ід»?","q":"","opts":["worked","played","wanted"],"a":2,"why":"Склад «ід» з'являється лише після звуків t і d: want-ed. Worked звучить «воркт», played — «плейд»."},{"type":"choice","q":"Mick ___ to Dublin last weekend.","uk":"Мік їздив у Дублін на минулих вихідних.","opts":["goed","went","go"],"a":1,"why":"Go — неправильне дієслово, його V2 — went. До неправильних дієслів -ed не додаємо."},{"type":"choice","q":"They ___ very tired after work yesterday.","uk":"Учора після роботи вони були дуже втомлені.","opts":["was","were","did"],"a":1,"why":"Be в минулому: was для I, he, she, it, а для you, we, they — were."},{"type":"input","q":"I saw him two days ___.","uk":"Я бачив його два дні тому.","a":["ago"],"why":"«Тому» — це ago, і воно стоїть після проміжку часу: two days ago."},{"type":"input","q":"We ___ (not / finish) the job on time.","uk":"Ми не закінчили роботу вчасно.","a":["didn't finish","did not finish"],"why":"Заперечення в минулому: didn't + початкова форма (finish, а не finished)."},{"type":"input","q":"___ you call the boss this morning?","uk":"Ти подзвонив босові сьогодні вранці?","a":["Did"],"why":"Питання в Past Simple починаємо з Did, а дієслово call лишається в початковій формі."},{"type":"choice","q":"Where ___ yesterday?","uk":"Куди ти ходив учора?","opts":["you went","did you went","did you go"],"a":2,"why":"Питання: Where + did + you + початкова форма (go). Без did не можна, а went після did — помилка."},{"type":"order","uk":"Він учора не прийшов.","words":["come","he","yesterday","didn't"],"a":["He didn't come yesterday.","Yesterday he didn't come."],"why":"Заперечення: he + didn't + початкова форма come. Yesterday зазвичай ставимо в кінці."},{"type":"order","uk":"Що ти робив на минулих вихідних?","words":["you","last","did","what","do","weekend"],"a":["What did you do last weekend?"],"why":"Питальне слово + did + you + початкова форма do. Did тут допоміжне, а do — саме дієслово «робити»."}],"section":"past"},"irregular-verbs":{"id":"irregular-verbs","level":"A2","title":"Irregular verbs","uk":"Неправильні дієслова","summary":"go – went – gone: понад 60 найчастіших дієслів групами","minutes":10,"blocks":[{"t":"p","text":"Більшість англійських дієслів **правильні**: минула форма з -ed (work → worked). Але найчастіші дієслова — go, have, make, take — **неправильні**: у них свої форми, які треба запам'ятати. Їх не так багато, і понад 60 дієслів з цієї теми покривають більшість щоденних розмов на роботі й удома."},{"t":"h","text":"Три форми: V1, V2, V3"},{"t":"p","text":"Кожне неправильне дієслово має три форми. **V1** — початкова форма, як у словнику: go. **V2** — друга форма, минулий час: went. **V3** — третя форма: gone. У правильних дієслів V2 і V3 однакові й закінчуються на -ed (worked – worked), тому з ними проблем немає."},{"t":"table","head":["Форма","Де вживаємо","Приклад"],"rows":[["V1: go","теперішній; після did, will, can","Did you **go**?"],["V2: went","Past Simple (минулий час)","I **went** home."],["V3: gone","після have / has / had","She **has gone** home."],["V3: made","пасив: be + V3","It **was made** in Italy."]]},{"t":"p","text":"Простими словами: **V2** — коли розповідаєш, що сталося (вчора, минулого тижня). **V3** сама як минулий час не вживається: перед нею потрібне **have / has / had** (часи Present Perfect і Past Perfect, це окремі теми) або **be** (пасив: «щось зроблено»). Українською V3 часто схожа на слова на -но, -то: done — «зроблено», broken — «зламано», built — «збудовано»."},{"t":"ex","items":[["I **took** the van this morning.","Я взяв фургон сьогодні вранці."],["Have you ever **taken** the ferry to Wales?","Ти колись плавав поромом до Уельсу?"],["The house **was built** in 1990.","Будинок збудували в 1990 році."],["When we arrived, the boss **had** already **left**.","Коли ми приїхали, бос уже поїхав."]]},{"t":"tip","text":"Не вчи список за алфавітом. Вчи **групами**, де форми змінюються однаково: sleep – slept, keep – kept, feel – felt. Шаблон запам'ятати легше, ніж кожне слово окремо. Кажи всі три форми вголос, як скоромовку: **buy – bought – bought**."},{"t":"h","text":"Група 1: усі три форми однакові"},{"t":"p","text":"Найлегша група: V1, V2 і V3 пишуться однаково, а час видно з речення. Підказка: у теперішньому часі з he, she, it є -s (he **cuts**), а в минулому його немає (he **cut**)."},{"t":"table","head":["V1","V2","V3"],"rows":[["cut (різати)","cut","cut"],["put (класти, ставити)","put","put"],["let (дозволяти)","let","let"],["hit (вдаряти)","hit","hit"],["cost (коштувати)","cost","cost"],["set (ставити, налаштовувати)","set","set"],["shut (зачиняти)","shut","shut"],["hurt (боліти, травмувати)","hurt","hurt"],["read «рід» (читати)","read «ред»","read «ред»"]]},{"t":"tip","text":"**Read** пишеться однаково, але V2 і V3 звучать «ред», як колір red. I **read** («рід») the news every day. I **read** («ред») it yesterday."},{"t":"ex","items":[["I **cut** my finger yesterday.","Я вчора порізав палець."],["Mick **put** the tools in the van.","Мік поклав інструменти у фургон."],["How much **did** the drill **cost**?","Скільки коштував дриль?"],["I **read** the instructions last night.","Я прочитав інструкцію вчора ввечері."]]},{"t":"h","text":"Група 2: V2 і V3 однакові"},{"t":"p","text":"Найбільша група: друга й третя форми однакові, тож вивчив одну — знаєш обидві. Усередині є «сімейки» зі схожими закінченнями: **-ought / -aught** (bought, taught), на **-t** (sent, kept, felt), **-aid** (paid, said), **-old** (sold, told), **-ood** (stood, understood)."},{"t":"table","head":["V1","V2","V3"],"rows":[["buy (купувати)","bought","bought"],["bring (приносити)","brought","brought"],["think (думати)","thought","thought"],["teach (навчати)","taught","taught"],["catch (ловити; встигати на)","caught","caught"],["send (надсилати)","sent","sent"],["spend (витрачати)","spent","spent"],["build (будувати)","built","built"],["lend (позичати комусь)","lent","lent"],["keep (тримати, зберігати)","kept","kept"],["sleep (спати)","slept","slept"],["feel (відчувати)","felt","felt"],["leave (іти, їхати; залишати)","left","left"],["meet (зустрічати)","met","met"]]},{"t":"table","head":["V1","V2","V3"],"rows":[["pay (платити)","paid","paid"],["say (казати)","said","said"],["sell (продавати)","sold","sold"],["tell (розповідати, казати)","told","told"],["find (знаходити)","found","found"],["have (мати)","had","had"],["make (робити, виготовляти)","made","made"],["hear (чути)","heard","heard"],["lose (губити, програвати)","lost","lost"],["stand (стояти)","stood","stood"],["understand (розуміти)","understood","understood"],["sit (сидіти)","sat","sat"],["get (отримувати, ставати)","got","got"]]},{"t":"tip","text":"Вимова: **said** — «сед» (не «сейд»), **heard** — «хьорд». У bought, brought, thought, caught, taught звучить довге «о»: «боот», «коот». **Get – got – got**: у британській англійській V3 — got: The weather **has got** worse (погода погіршилася). Gotten — американський варіант, хоча в Ірландії його теж почуєш."},{"t":"tip","text":"Кілька дієслів мають дві правильні V2 і V3: **learn – learnt / learned**, **burn – burnt / burned**, **dream – dreamt / dreamed**, **spell – spelt / spelled**, **smell – smelt / smelled**. В Америці зазвичай кажуть з -ed, а в Британії та Ірландії вживають обидві. Обидва варіанти правильні."},{"t":"ex","items":[["We **built** the extension in two weeks.","Ми збудували прибудову за два тижні."],["I've **lost** my keys again.","Я знову загубив ключі."],["Sarah **told** me about the new job.","Сара розповіла мені про нову роботу."],["Tom **paid** for the coffee.","Том заплатив за каву."],["Have you **heard** the news?","Ти чув новину?"]]},{"t":"h","text":"Група 3: усі три форми різні"},{"t":"p","text":"Тут треба вчити всі три форми. Допомагає те, що в багатьох дієслів V3 закінчується на **-n / -en**: gone, seen, taken, written, done."},{"t":"table","head":["V1","V2","V3"],"rows":[["go (іти, їхати)","went","gone"],["see (бачити)","saw","seen"],["take (брати)","took","taken"],["give (давати)","gave","given"],["write (писати)","wrote","written"],["drive (кермувати)","drove","driven"],["ride (їздити на велосипеді)","rode","ridden"],["eat (їсти)","ate","eaten"],["do (робити)","did","done"],["break (ламати)","broke","broken"],["speak (розмовляти)","spoke","spoken"],["choose (вибирати)","chose","chosen"],["fall (падати)","fell","fallen"],["forget (забувати)","forgot","forgotten"],["wear (носити одяг)","wore","worn"]]},{"t":"p","text":"Ще дві сімейки: **-ew / -own** (know – knew – known) і **i – a – u**, де змінюється лише голосна (begin – began – begun)."},{"t":"table","head":["V1","V2","V3"],"rows":[["know (знати)","knew","known"],["grow (рости, вирощувати)","grew","grown"],["throw (кидати)","threw","thrown"],["fly (літати)","flew","flown"],["begin (починати)","began","begun"],["drink (пити)","drank","drunk"],["swim (плавати)","swam","swum"],["ring (дзвонити)","rang","rung"],["sing (співати)","sang","sung"]]},{"t":"p","text":"І кілька особливих: у **come**, **become** і **run** V3 збігається з V1, а **be** має дві V2: **was** (I, he, she, it) і **were** (you, we, they)."},{"t":"table","head":["V1","V2","V3"],"rows":[["come (приходити)","came","come"],["become (ставати)","became","become"],["run (бігати)","ran","run"],["be (бути)","was / were","been"]]},{"t":"ex","items":[["I **forgot** my lunch today.","Я сьогодні забув обід."],["Someone **has broken** the window.","Хтось розбив вікно."],["The meeting **began** at nine.","Нарада почалася о дев'ятій."],["Olena **has** never **flown** before.","Олена ще ніколи не літала літаком."],["Have you ever **driven** on the left?","Тобі доводилося їздити з лівостороннім рухом?"]]},{"t":"h","text":"V1, V2 чи V3: як вибрати"},{"t":"table","head":["Що в реченні","Форма","Приклад"],"rows":[["ствердження в минулому","V2","I **saw** him."],["did / didn't","V1","I didn't **see** him."],["have / has / had","V3","I've **seen** him."],["be (пасив)","V3","It was **made** here."]]},{"t":"tip","text":"Найважливіше: **V2 ніколи не стоїть після did і have**. Після did — завжди V1, після have / has / had — завжди V3."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"They have went home.","right":"They have gone home.","why":"Після have / has — V3: go – went – gone. Went — це V2, вона буває лише без have."},{"t":"mistake","wrong":"I buyed a new phone.","right":"I bought a new phone.","why":"Buy — неправильне дієслово, -ed до нього не додаємо: buy – bought – bought."},{"t":"mistake","wrong":"I have saw this film.","right":"I have seen this film.","why":"Після have — V3 (seen). Saw — V2, вона для Past Simple без have: I saw it yesterday."},{"t":"mistake","wrong":"Did you went to the gym?","right":"Did you go to the gym?","why":"Після did — завжди V1. Минулий час уже показує did."}],"tasks":[{"type":"choice","q":"I ___ a new drill last week.","uk":"Я купив новий дриль минулого тижня.","opts":["buyed","bought","buy"],"a":1,"why":"Buy — неправильне дієслово: buy – bought – bought. Last week — минуле, тому V2: bought."},{"type":"input","q":"We ___ (meet) Sarah at the bus stop yesterday.","uk":"Ми вчора зустріли Сару на зупинці.","a":["met"],"why":"Meet – met – met. Yesterday — це Past Simple, тому V2: met."},{"type":"input","q":"Mick ___ (put) the ladder in the van an hour ago.","uk":"Мік поклав драбину у фургон годину тому.","a":["put"],"why":"Put однакове у всіх трьох формах: put – put – put. Ago показує минуле, тому без -s."},{"type":"choice","q":"Did you ___ my message?","uk":"Ти отримав моє повідомлення?","opts":["got","get","gotten"],"a":1,"why":"Після did — завжди V1 (get). Минулий час уже показує did."},{"type":"choice","q":"Sarah has ___ home.","uk":"Сари вже немає, вона пішла додому.","opts":["went","gone","go"],"a":1,"why":"Після has — V3: go – went – gone. Went — це V2, після have / has вона не стоїть."},{"type":"input","q":"Oh no, I've ___ (lose) my phone!","uk":"Ой, я загубив телефон!","a":["lost"],"why":"Після have ('ve) — V3: lose – lost – lost."},{"type":"choice","q":"Have you ever ___ a van in Dublin?","uk":"Ти колись водив фургон у Дубліні?","opts":["drove","driven","drive"],"a":1,"why":"Have + V3: drive – drove – driven. Drove — це V2, вона лише для Past Simple без have."},{"type":"input","q":"This house was ___ (build) in 1975.","uk":"Цей будинок збудували в 1975 році.","a":["built"],"why":"Пасив («був збудований»): was + V3. Build – built – built."},{"type":"input","q":"Tom ___ (break) his arm at work last year.","uk":"Том зламав руку на роботі минулого року.","a":["broke"],"why":"Last year — Past Simple, тому V2: break – broke – broken. Broken — V3, їй потрібне have або be."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я бачив цей фільм двічі.","opts":["I've saw this film twice.","I've seen this film twice.","I seen this film twice."],"a":1,"why":"Після have ('ve) — V3: see – saw – seen. Без have форма seen як минулий час не вживається."},{"type":"order","uk":"Де ти купив ці черевики?","words":["buy","you","these","where","did","boots"],"a":["Where did you buy these boots?"],"why":"Питання в Past Simple: Where + did + you + V1 (buy). Bought після did не ставимо."},{"type":"order","uk":"Ми ще не заплатили за матеріали.","words":["paid","the","we","yet","for","haven't","materials"],"a":["We haven't paid for the materials yet.","We haven't yet paid for the materials."],"why":"Після haven't — V3: pay – paid – paid. Yet («ще») зазвичай ставимо в кінці."}],"section":"past"},"past-continuous":{"id":"past-continuous","level":"A2","title":"Past Continuous","uk":"Минулий тривалий час","summary":"що тривало в певний момент: I was working when…","minutes":7,"blocks":[{"t":"p","text":"**Past Continuous** показує дію, яка **тривала** в певний момент у минулому: була в процесі й ще не закінчилася. Українською це «працював», «їхав», «ішов» у значенні «саме тоді був зайнятий цим»."},{"t":"ex","items":[["At eight o'clock I **was driving** to work.","О восьмій я їхав на роботу."],["This time yesterday we **were plastering** the ceiling.","Учора в цей час ми штукатурили стелю."],["It **was raining** all morning.","Увесь ранок ішов дощ."]]},{"t":"h","text":"Як утворюється"},{"t":"p","text":"Формула проста: **was** або **were** + **форма з -ing** (дієслово із закінченням -ing: working, driving). Was чи were — залежить від **підмета**, тобто від того, хто виконує дію."},{"t":"rule","title":"Ствердження","lines":["I / he / she / it + **was** + work**ing**","you / we / they + **were** + work**ing**"]},{"t":"rule","title":"Заперечення","lines":["I / he / she / it + **wasn't** + working","you / we / they + **weren't** + working"]},{"t":"rule","title":"Питання","lines":["**Was** + I / he / she / it + working?","**Were** + you / we / they + working?","What **were** you do**ing**?"]},{"t":"table","head":["Дієслово","Правило","Приклад"],"rows":[["більшість","+ -ing","work → work**ing**"],["на німе -e","e зникає","make → mak**ing**"],["короткі: sit, run, stop","подвоюємо","sit → si**tting**"],["на -ie","ie → y","lie → l**ying**"]]},{"t":"ex","items":[["I **wasn't sleeping**, I **was watching** TV.","Я не спав, я дивився телевізор."],["**Were** you **working** at ten last night? — **Yes, I was.**","Ти працював учора о десятій вечора? — Так."],["What **were** you **doing** when I called?","Що ти робив, коли я подзвонив?"]]},{"t":"h","text":"Дію перервали: when"},{"t":"p","text":"Найчастіше Past Continuous стоїть разом з Past Simple. Довга дія **тривала** (Past Continuous), і тут її **перервала** коротка подія (Past Simple)."},{"t":"rule","title":"Довга дія + коротка подія","lines":["довга дія: was / were + -ing","коротка подія: Past Simple","I **was cutting** the board when the phone **rang**."]},{"t":"ex","items":[["I **was cutting** the board when the phone **rang**.","Я різав дошку, коли задзвонив телефон."],["We **were having** lunch when the boss **arrived**.","Ми обідали, коли приїхав бос."],["When I **got** to the site, Mick **was mixing** the plaster.","Коли я приїхав на об'єкт, Мік замішував штукатурку."],["Kate **fell** while she **was running** for the bus.","Кейт упала, коли бігла на автобус."]]},{"t":"tip","text":"**When** («коли») зазвичай ставимо перед короткою подією: …when the phone **rang**. **While** («поки, у той час як») — перед довгою дією: …while she **was running**."},{"t":"p","text":"Порівняй з українською. У нас різницю показує вид дієслова: «пішов» (подія сталася) і «йшов» (дія тривала). В англійській те саме робить час:"},{"t":"ex","items":[["When I arrived, Tom **left**.","Коли я прийшов, Том пішов (спершу я прийшов, потім він пішов)."],["When I arrived, Tom **was leaving**.","Коли я прийшов, Том якраз виходив."]]},{"t":"tip","text":"Але не кожне «робив» — це Past Continuous. Якщо дія **повторювалася**, бери Past Simple: «Я щодня ходив у зал» — I **went** to the gym every day. Past Continuous — лише про те, що тривало в конкретний момент."},{"t":"h","text":"Дві дії одночасно: while"},{"t":"p","text":"Коли дві довгі дії тривали **паралельно**, обидві стоять у Past Continuous, а з'єднує їх **while**."},{"t":"ex","items":[["While I **was plastering**, Mick **was sanding** the walls.","Поки я штукатурив, Мік шліфував стіни."],["She **was cooking** while the kids **were doing** their homework.","Вона готувала, поки діти робили домашнє завдання."]]},{"t":"h","text":"Фон в історії"},{"t":"p","text":"Коли розповідаєш історію, Past Continuous малює «картинку» на початку: що відбувалося, яка була погода. Самі події, які йдуть одна за одною, — у Past Simple."},{"t":"ex","items":[["It **was raining** and we **were waiting** for the bus.","Ішов дощ, і ми чекали на автобус."],["Suddenly a van **stopped** and the driver **opened** the window.","Раптом зупинився фургон, і водій відчинив вікно."]]},{"t":"h","text":"Дієслова стану: без -ing"},{"t":"p","text":"Деякі дієслова означають не дію, а **стан**: знати, хотіти, любити, мати. Їх не ставлять у форму з -ing, навіть коли мова про конкретний момент. Замість Past Continuous — звичайний Past Simple."},{"t":"list","items":["**know**, **understand**, **believe** — знати, розуміти, вірити","**want**, **need**, **like**, **love**, **hate** — хотіти, потребувати, подобатися, любити, ненавидіти","**have** у значенні «мати»: I **had** a car","**belong**, **seem**, **mean** — належати, здаватися, означати"]},{"t":"tip","text":"**Have** як дія — можна з -ing: We **were having** lunch (обідали). I **was having** a shower (приймав душ). А «мати» — ні: I **had** a car, а не I was having a car."},{"t":"ex","items":[["I **didn't know** the answer.","Я не знав відповіді."],["He **wanted** to go home early.","Він хотів піти додому раніше."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"When I was arriving, he left.","right":"When I arrived, he was leaving.","why":"Хочеш сказати «коли я приїхав, він якраз виїжджав»? «Приїхав» — коротка подія, тому Past Simple (arrived). «Виїжджав» — дія, яка саме тривала, тому Past Continuous (was leaving)."},{"t":"mistake","wrong":"I was knowing the answer.","right":"I knew the answer.","why":"Know — дієслово стану, у формі з -ing його не вживають."},{"t":"mistake","wrong":"While I cooked, the phone was ringing.","right":"While I was cooking, the phone rang.","why":"Довга дія після while — Past Continuous, коротка подія («задзвонив») — Past Simple."},{"t":"mistake","wrong":"They was working.","right":"They were working.","why":"Was — для I, he, she, it. Для you, we, they — were."}],"tasks":[{"type":"choice","q":"At seven o'clock yesterday, I ___ breakfast.","uk":"Учора о сьомій я якраз снідав.","opts":["was having","were having","am having"],"a":0,"why":"Дія тривала в конкретний момент у минулому, тому Past Continuous. Для I — was."},{"type":"choice","q":"___ you sleeping when I called?","uk":"Ти спав, коли я подзвонив?","opts":["Did","Was","Were"],"a":2,"why":"Питання в Past Continuous: Were + you + форма з -ing. Did з формою -ing не вживаємо."},{"type":"choice","q":"They ___ football when it started to rain.","uk":"Вони якраз грали у футбол, коли почався дощ.","opts":["was playing","were playing","played"],"a":1,"why":"Гра тривала, а дощ її перервав: довга дія — Past Continuous. Для they — were."},{"type":"input","q":"We ___ (wait) for the bus when we saw the accident.","uk":"Ми чекали на автобус, коли побачили аварію.","a":["were waiting"],"why":"Довга дія (чекали), яку перервала коротка (побачили): were + -ing."},{"type":"input","q":"At ten last night I ___ (not / sleep). I was watching the match.","uk":"Учора о десятій вечора я не спав. Я дивився матч.","a":["wasn't sleeping","was not sleeping"],"why":"Конкретний момент у минулому, і мова про те, що (не) тривало саме тоді: wasn't + -ing."},{"type":"input","q":"What ___ you doing at nine o'clock last night?","uk":"Що ти робив учора о дев'ятій вечора?","a":["were"],"why":"Питання: What + were + you + -ing. Для you завжди were."},{"type":"choice","q":"Mick ___ his hand while he was cutting the tiles.","uk":"Мік порізав руку, коли різав плитку.","opts":["cut","was cutting","cuts"],"a":0,"why":"«Порізав» — коротка подія, тому Past Simple (cut – cut – cut). «Різав» — тривала дія, вона вже в Past Continuous."},{"type":"input","q":"While I ___ (paint) the door, Tom was fixing the lock.","uk":"Поки я фарбував двері, Том лагодив замок.","a":["was painting"],"why":"Дві дії тривали одночасно, тому обидві в Past Continuous: while I was painting."},{"type":"choice","q":"I ___ that he was married.","uk":"Я не знав, що він одружений.","opts":["didn't know","wasn't knowing","weren't knowing"],"a":0,"why":"Know — дієслово стану, з -ing його не вживаємо. Тому Past Simple: didn't know."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Поки я готував, задзвонив телефон.","opts":["While I cooked, the phone was ringing.","While I was cooking, the phone rang.","While I were cooking, the phone rang."],"a":1,"why":"Довга дія після while — Past Continuous (was cooking), коротка подія — Past Simple (rang). Для I — was."},{"type":"order","uk":"Коли я прийшов, вони обідали.","words":["when","they","having","I","lunch","were","arrived"],"a":["When I arrived, they were having lunch.","They were having lunch when I arrived.","I arrived when they were having lunch.","When they were having lunch, I arrived."],"why":"Обідали — тривала дія, тому Past Continuous (were having). Прийшов — коротка подія, тому Past Simple (arrived)."},{"type":"order","uk":"Поки Олена спала, ми дивилися фільм.","words":["while","film","were","Olena","a","we","sleeping","watching","was"],"a":["While Olena was sleeping, we were watching a film.","We were watching a film while Olena was sleeping.","While we were watching a film, Olena was sleeping.","Olena was sleeping while we were watching a film."],"why":"Дві дії тривали одночасно: обидві в Past Continuous, а з'єднує їх while."}],"section":"past"},"past-perfect":{"id":"past-perfect","level":"B1","title":"Past Perfect","uk":"Минулий доконаний час: had done","summary":"що сталося ще раніше в минулому: the bus had already left","minutes":6,"blocks":[{"t":"p","text":"**Past Perfect** (had + V3) — це «минуле в минулому». Розповідаєш про минуле, і треба показати, що одна дія сталася **ще раніше** за іншу або за певний момент. Тоді для ранішої дії беремо had + V3, а для пізнішої — звичайний Past Simple."},{"t":"ex","items":[["When I got to the stop, the bus **had** already **left**.","Коли я дійшов до зупинки, автобус уже поїхав."],["I didn't recognise Tom. He **had grown** a beard.","Я не впізнав Тома: він відпустив бороду."]]},{"t":"h","text":"Як утворюється"},{"t":"p","text":"**Had** однакове для всіх, жодних has: I had, she had, they had. **V3** — третя форма дієслова: finished, gone, seen (неправильні — у темі «Неправильні дієслова»). **Підмет** — хто або що виконує дію: I, Tom, the bus. Скорочено: I'd, she'd, they'd; hadn't."},{"t":"rule","title":"Ствердження","lines":["I / you / he / she / it / we / they + **had** + V3"]},{"t":"rule","title":"Заперечення","lines":["підмет + **hadn't** (had not) + V3"]},{"t":"rule","title":"Питання","lines":["**Had** + підмет + V3?"]},{"t":"ex","items":[["Andrii **hadn't driven** on the left before he came to Ireland.","Андрій не їздив лівим боком, доки не приїхав до Ірландії."],["**Had** you **met** Kate before the party?","Ти був знайомий з Кейт до вечірки?"]]},{"t":"tip","text":"**'d** буває і had, і would (I'd like). Підказка — наступне слово: після had іде V3 (I'd **finished**), після would — початкова форма дієслова (I'd **like**)."},{"t":"h","text":"Головне: порядок подій"},{"t":"p","text":"Порівняй. Різниця в одному слові, а події йдуть у різному порядку."},{"t":"ex","items":[["When I arrived, the bus **left**.","Коли я прийшов, автобус рушив. (Я ще його бачив.)"],["When I arrived, the bus **had left**.","Коли я прийшов, автобуса вже не було. (Він поїхав раніше.)"],["When we got to the site, the boss **went** home.","Коли ми приїхали на об'єкт, бос поїхав додому. (Відразу після нашого приїзду.)"],["When we got to the site, the boss **had gone** home.","Коли ми приїхали на об'єкт, бос уже поїхав додому."]]},{"t":"tip","text":"Українською ранішу дію показує слово «вже»: «автобус уже поїхав». В англійській already саме цього не зробить: When I came, he already left — помилка. Потрібно had + V3, а already лише підсилює: he **had** already **left**."},{"t":"h","text":"Слова-підказки"},{"t":"p","text":"Past Perfect часто стоїть поруч із **when** (коли), **before** (до того як), **after** (після того як), **by the time** (на той час, коли), **by** + час (by ten — до десятої), **already** (вже), **just** (щойно), **never … before** (ніколи раніше не)."},{"t":"ex","items":[["By the time we finished, everyone **had gone** home.","Коли ми закінчили, всі вже розійшлися додому."],["By ten o'clock we **had finished** the first coat.","До десятої ми вже нанесли перший шар."],["She **had** just **left** when I called.","Вона щойно пішла, коли я подзвонив."],["I **had** never **seen** such a big house before.","Я ніколи раніше не бачив такого великого будинку."]]},{"t":"h","text":"Коли Past Perfect не потрібен"},{"t":"p","text":"Якщо розповідаєш події **по черзі**, як вони й сталися, — просто Past Simple: I got up, had a shower and went to work. Не додавай had «для солідності»: Past Perfect потрібен, лише коли повертаєшся назад, до ранішої події."},{"t":"p","text":"З **before** і **after** порядок і так зрозумілий із самого слова, тому Past Perfect тут не обов'язковий. Обидва речення правильні:"},{"t":"ex","items":[["After he **finished** work, he went to the gym.","Після роботи він пішов у спортзал."],["After he **had finished** work, he went to the gym.","Після роботи він пішов у спортзал."]]},{"t":"h","text":"Непряма мова"},{"t":"p","text":"Коли переказуєш чужі слова через said або told (сказав), час часто «зсувається» назад: I've finished → she said she **had finished**; I lost my keys → he said he **had lost** his keys. Докладніше — у темі «Непряма мова: he said that…»."},{"t":"ex","items":[["She said she **had finished**.","Вона сказала, що закінчила."],["Tom told me he **had lost** his keys.","Том сказав мені, що загубив ключі."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"When I came, he already left.","right":"When I came, he had already left.","why":"Без had виходить, що він пішов саме тоді, коли ти прийшов. Щоб показати, що раніше, — had + V3."},{"t":"mistake","wrong":"I had seen him yesterday.","right":"I saw him yesterday.","why":"Звичайна подія в минулому — Past Simple. Past Perfect потрібен лише щодо іншої, пізнішої події в минулому."},{"t":"mistake","wrong":"I had got up, had a shower and went to work.","right":"I got up, had a shower and went to work.","why":"Події по черзі — тільки Past Simple."},{"t":"mistake","wrong":"He had never drove a van before.","right":"He had never driven a van before.","why":"Після had — V3: drive → drove → driven."}],"tasks":[{"type":"choice","q":"When I got to the stop, the bus ___ already left.","uk":"Коли я дійшов до зупинки, автобус уже поїхав.","opts":["had","has","was"],"a":0,"why":"Автобус поїхав раніше, ніж я дійшов: had + V3. Has — для теперішнього часу, а was left тут не має сенсу."},{"type":"choice","q":"By the time I arrived, they had ___ all the pizza.","uk":"Коли я приїхав, вони вже з'їли всю піцу.","opts":["ate","eaten","eat"],"a":1,"why":"Після had — V3: eat → ate → eaten. Ate — це V2 для Past Simple."},{"type":"input","q":"When we got to the site, the boss ___ (go) home.","uk":"Коли ми приїхали на об'єкт, бос уже поїхав додому.","a":["had gone","had already gone"],"why":"Бос поїхав раніше, ніж ми приїхали: had + V3 (go → went → gone)."},{"type":"choice","q":"Andrii ___ never driven on the left before he came to Ireland.","uk":"Андрій ніколи не їздив лівим боком, доки не приїхав до Ірландії.","opts":["had","has","was"],"a":0,"why":"Ідеться про час до іншої події в минулому (before he came), тому had + V3. Has never driven означало б «досі ніколи»."},{"type":"input","q":"I didn't know Kate. I ___ (not / meet) her before.","uk":"Я не знав Кейт: раніше ми з нею не бачилися.","a":["hadn't met","had not met"],"why":"Ідеться про час до того моменту в минулому (I didn't know Kate), тому hadn't + V3: meet → met → met."},{"type":"choice","task":"Мік пішов ще до того, як я прийшов. Яке речення про це?","q":"","opts":["When I arrived, Mick left.","When I arrived, Mick had left.","When I arrived, Mick has left."],"a":1,"why":"Had left — пішов ще до мого приходу. Просто left — пішов, коли я вже прийшов. Has left з минулим (when I arrived) не поєднується."},{"type":"choice","q":"I was hungry because I ___ breakfast.","uk":"Я був голодний, бо не снідав.","opts":["hadn't had","haven't had","didn't had"],"a":0,"why":"Не поснідав раніше, ніж відчув голод: hadn't + V3 (have → had → had). Haven't had — теперішній час, а після didn't — лише початкова форма."},{"type":"input","q":"By the time I got home, Sarah ___ (cook) dinner.","uk":"Коли я дістався додому, Сара вже приготувала вечерю.","a":["had cooked","had already cooked"],"why":"By the time — на той момент дія вже завершилася: had + V3."},{"type":"choice","q":"I ___ Sarah yesterday.","uk":"Я бачив Сару вчора.","opts":["saw","had seen","have seen"],"a":0,"why":"Звичайна подія з часом, без іншої події в минулому, — Past Simple. Had тут не потрібне, а Present Perfect з yesterday не вживаємо."},{"type":"input","q":"___ you ever been to Ireland before you moved here?","uk":"Ти колись бував в Ірландії до того, як переїхав сюди?","a":["Had"],"why":"Питання про час до іншої події в минулому (before you moved): Had + підмет + V3."},{"type":"order","uk":"Коли я прийшов, вони вже пішли.","words":["had","they","already","left","when","I","arrived"],"a":["When I arrived, they had already left.","They had already left when I arrived."],"why":"Пізніша подія (I arrived) — Past Simple, раніша — had + V3. Already стоїть між had і V3."},{"type":"order","uk":"Я ніколи раніше не бачив такого великого будинку.","words":["had","I","seen","never","such","a","big","house","before"],"a":["I had never seen such a big house before.","I had never before seen such a big house.","Never before had I seen such a big house."],"why":"Had + never + V3, а before (раніше) — у кінці речення."}],"section":"past"},"used-to":{"id":"used-to","level":"B1","title":"Used to, would, be used to","uk":"Used to: так було раніше","summary":"раніше було, а тепер ні: I used to…; звик: I'm used to…","minutes":7,"blocks":[{"t":"p","text":"**Used to** + **початкова форма дієслова** (як у словнику: work, live) означає: **раніше так було, а тепер ні**. Так говорять про звички й стани в минулому, які вже закінчилися. Українською кажемо «раніше…», «колись…»."},{"t":"ex","items":[["Olena **used to live** in Kyiv.","Олена раніше жила в Києві."],["Tom **used to smoke**, but he stopped last year.","Том колись курив, але минулого року кинув."],["There **used to be** a shop on this corner.","Колись на цьому розі був магазин."],["We **used to work** on Saturdays, but now we don't.","Раніше ми працювали по суботах, а тепер ні."]]},{"t":"rule","title":"Ствердження","lines":["I / you / he / she / we / they + **used to** + work"]},{"t":"p","text":"Used to однакове для всіх: I used to, she used to, без жодного -s. Вимова: «юст-ту», зі звуком **с**, а не «з». Не плутай з простим used «юзд» — «використав»: I **used** a drill (я скористався дрилем)."},{"t":"tip","text":"Used to буває **лише про минуле**. Про теперішні звички кажемо Present Simple: I **usually start** at eight. «I use to…» про теперішнє не кажуть."},{"t":"tip","text":"Used to не кажемо про **одну** подію, а також коли називаємо, **скільки разів** або **скільки часу** щось тривало. Тут потрібен Past Simple: I **lived** in Kyiv for ten years (а не used to live… for ten years). I **went** to Dublin three times last year."},{"t":"h","text":"Заперечення і питання: use без d"},{"t":"rule","title":"Заперечення","lines":["I / he / they + **didn't use to** + work"]},{"t":"rule","title":"Питання","lines":["**Did** + you / he / they + **use to** + work?"]},{"t":"tip","text":"Після **did** і **didn't** пишемо **use to**, без d: після did дієслово завжди в початковій формі (так само didn't **go**, а не didn't went). На слух різниці немає, тому помилку видно лише на письмі."},{"t":"ex","items":[["I **didn't use to like** coffee.","Раніше я не любив каву."],["**Did** you **use to play** football at school?","Ти в школі грав у футбол?"],["Where **did** you **use to work**?","Де ти раніше працював?"]]},{"t":"p","text":"У розмові замість didn't use to часто кажуть **never used to** («раніше ніколи не…»): Mick **never used to** eat breakfast. Тут d є, бо did немає."},{"t":"h","text":"Would: так бувало раніше"},{"t":"p","text":"У розповідях про минуле замість used to часто вживають **would** + початкова форма. Але **лише для дій, що повторювалися**: що ми робили раз у раз. Українською — «бувало» або просто «ходили», «їздили»."},{"t":"ex","items":[["Every summer we **would go** to my grandmother's village.","Щоліта ми їздили до бабусі в село."],["My dad **would** always **bring** us sweets on Fridays.","По п'ятницях тато завжди приносив нам цукерки."]]},{"t":"tip","text":"**Would** не вживаємо для **станів**: жити, мати, знати, любити, бути. Тут лише used to. Olena **used to live** in Kyiv (а не would live). I **used to have** a dog (а не would have)."},{"t":"table","head":["Що описуємо","used to","would"],"rows":[["дії, що повторювалися","так","так"],["стани: live, have, know","так","ні"]]},{"t":"h","text":"Головна пастка: be used to"},{"t":"p","text":"**Be used to** — зовсім інше значення: «**звик** до чогось», тобто для тебе це вже нормально й не важко. Тут **to** означає «до» (звик **до** чогось), тому після нього йде **іменник** (назва предмета чи явища: the cold, the job) або **форма з -ing** (working, getting), але не початкова форма дієслова."},{"t":"rule","title":"Порівняй","lines":["I **used to start** at six. — раніше починав о шостій","I'm **used to starting** at six. — звик починати о шостій"]},{"t":"rule","title":"Звик і звикаю","lines":["**be used to** + -ing / іменник = звик","**get used to** + -ing / іменник = звикаю, звикну"]},{"t":"ex","items":[["I'm **used to working** long hours.","Я звик до довгих робочих днів."],["She **isn't used to** the cold.","Вона не звикла до холоду."],["**Are** you **used to** the noise yet?","Ти вже звик до шуму?"],["I'm **getting used to** the Irish weather.","Я звикаю до ірландської погоди."],["You'll soon **get used to** driving on the left.","Ти скоро звикнеш їздити лівою стороною."]]},{"t":"tip","text":"Як не сплутати: подивись, що стоїть **перед** used to. Є **am / is / are / was / were** або **get** — значить «звик», а далі -ing чи іменник. Нічого немає (I used to) — «раніше так було», а далі початкова форма."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I use to work in Kyiv.","right":"I used to work in Kyiv.","why":"Про минуле — used to, з d. Use to без d пишемо лише після did / didn't."},{"t":"mistake","wrong":"I didn't used to smoke.","right":"I didn't use to smoke.","why":"Після didn't — початкова форма: use, без d."},{"t":"mistake","wrong":"I'm used to work long hours.","right":"I'm used to working long hours.","why":"Після be used to («звик») — форма з -ing або іменник."},{"t":"mistake","wrong":"When I was a child, I would live in Kyiv.","right":"When I was a child, I used to live in Kyiv.","why":"Would — лише для дій, що повторювалися. «Жити» — це стан, тому used to."}],"tasks":[{"type":"choice","q":"Olena ___ in Kyiv, but now she lives in Gorey.","uk":"Олена раніше жила в Києві, а тепер живе в Горі.","opts":["used to live","is used to living","use to live"],"a":0,"why":"Раніше так було, а тепер ні: used to + початкова форма. Is used to living означало б «звикла жити»."},{"type":"input","q":"My dad ___ to work in Poland.","uk":"Мій тато колись працював у Польщі.","a":["used"],"why":"Так було раніше, а тепер ні: used to + початкова форма (work)."},{"type":"choice","q":"There ___ a pub in our village, but it closed down.","uk":"Колись у нашому селі був паб, але він закрився.","opts":["used to be","would be","was used to be"],"a":0,"why":"«Був» — це стан, тому лише used to. Would — тільки для дій, що повторювалися."},{"type":"input","q":"Tom didn't ___ to drink coffee.","uk":"Раніше Том не пив каву.","a":["use"],"why":"Після didn't — початкова форма: use to, без d."},{"type":"input","q":"___ you use to live in Cork?","uk":"Ти раніше жив у Корку?","a":["Did"],"why":"Питання з used to будуємо через Did, а далі use to без d."},{"type":"choice","q":"When I was a child, I ___ a dog called Rex.","uk":"У дитинстві в мене був пес на ім'я Рекс.","opts":["would have","used to have","was used to having"],"a":1,"why":"«Мати» — це стан, а would вживаємо лише для дій, що повторювалися. Тому used to have."},{"type":"choice","q":"Every Sunday my grandad ___ take us to the river.","uk":"Щонеділі дідусь водив нас на річку.","opts":["would","was used to","uses to"],"a":0,"why":"Дія повторювалася в минулому, тому would + початкова форма. Was used to означає «звик», а uses to не буває."},{"type":"input","q":"I'm not used to ___ (get) up so early.","uk":"Я не звик вставати так рано.","a":["getting"],"why":"Be used to = «звик», після нього — форма з -ing: getting."},{"type":"choice","q":"I can't ___ used to this cold weather.","uk":"Я ніяк не можу звикнути до цієї холодної погоди.","opts":["get","be","use"],"a":0,"why":"«Звикати, звикнути» — get used to. Be used to — це результат: «уже звик»."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я звик працювати на вихідних.","opts":["I'm used to work at weekends.","I'm used to working at weekends.","I used to working at weekends."],"a":1,"why":"«Звик» — be used to (I'm used to), а після нього форма з -ing: working."},{"type":"order","uk":"Раніше Сара не працювала по суботах.","words":["didn't","on","Sarah","use","work","Saturdays","to"],"a":["Sarah didn't use to work on Saturdays.","On Saturdays Sarah didn't use to work."],"why":"Заперечення: didn't use to + початкова форма. Після didn't — use без d."},{"type":"order","uk":"Я звикаю до нової роботи.","words":["used","new","I'm","the","job","getting","to"],"a":["I'm getting used to the new job."],"why":"«Звикаю» — це процес, тому get used to, тут у формі I'm getting. Після to — іменник (the new job)."}],"section":"past"},"will":{"id":"will","level":"A2","title":"Will","uk":"Will: майбутнє й рішення","summary":"рішення зараз, прогнози, обіцянки: I'll help, it will rain","minutes":7,"blocks":[{"t":"p","text":"**Will** — найпростіший спосіб сказати про майбутнє. Це **допоміжне дієслово**: службове слово, яке саме не перекладається, а будує час (як do чи does). Після will завжди йде **початкова форма дієслова** — та, що в словнику: work, go, be. Без to, без -s, без -ing. Will вживаємо насамперед для чотирьох речей: **рішення просто зараз**, **прогноз-думка**, **обіцянка**, **пропозиція чи прохання**. Для планів, вирішених заздалегідь, є going to (наступна тема)."},{"t":"ex","items":[["I**'ll help** you with that.","Я допоможу тобі з цим."],["I think it**'ll rain** tomorrow.","Думаю, завтра буде дощ."],["I**'ll call** you tonight, I promise.","Я подзвоню тобі ввечері, обіцяю."],["**Will** you **give** me a hand?","Допоможеш мені?"]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Ствердження","lines":["I / you / he / she / we / they + **will** + work","I will = I**'ll**, she will = she**'ll**, it will = it**'ll**"]},{"t":"rule","title":"Заперечення і питання","lines":["I / he / they… + **won't** + work (won't = will not)","**Will** + you / he / they… + work?","Yes, I **will**. / No, I **won't**."]},{"t":"p","text":"Will однаковий для всіх: I will, she will, they will — жодного -s. У розмові майже завжди скорочуємо: **I'll**, **you'll**, **he'll**, **we'll**, **they'll**. А will not скорочується до **won't**."},{"t":"tip","text":"**Won't** [воунт] легко сплутати з **want** [вонт] — «хочу». I **won't** go — я не піду. I **want** to go — я хочу піти. Слухай голосну: у won't вона протяжна, як «оу»."},{"t":"ex","items":[["I**'ll be** back in ten minutes.","Я повернуся за десять хвилин."],["She **won't be** happy about this.","Вона цьому не зрадіє."],["**Will** you **be** at work tomorrow? — Yes, I **will**.","Ти завтра будеш на роботі? — Так."],["When **will** the boards **arrive**?","Коли привезуть плити?"],["It **won't take** long.","Це ненадовго."]]},{"t":"tip","text":"«Через» про майбутнє — це **in**: I'll be back **in** ten minutes (через десять хвилин), we'll finish **in** two weeks. After ten minutes кажуть здебільшого в розповіді про минуле: After ten minutes, he left (Через десять хвилин він пішов)."},{"t":"h","text":"1. Рішення просто зараз"},{"t":"p","text":"Вирішив щось **у момент розмови** — щойно почув новину чи прохання — кажи **I'll**. Українською тут часто додаємо «зараз» або навіть кажемо теперішнім часом: «Зараз візьму», «Зараз зачиняю». Англійською теперішній час тут не підходить, лише I'll."},{"t":"ex","items":[["The phone's ringing. — I**'ll get** it.","Дзвонить телефон. — Я візьму."],["It's cold in here. — I**'ll close** the window.","Тут холодно. — Я зачиню вікно."],["I'm hungry. — I**'ll make** you a sandwich.","Я голодний. — Я зроблю тобі бутерброд."],["Tea or coffee? — I**'ll have** tea, please.","Чай чи кава? — Мені чай, будь ласка."]]},{"t":"h","text":"2. Прогноз і факти про майбутнє"},{"t":"p","text":"Will — коли ти **думаєш, віриш чи припускаєш**, що щось станеться. Поруч часто стоять **I think** (думаю), **I'm sure** (я впевнений), **probably** (мабуть), **I hope** (сподіваюся). Так само will — про звичайні факти в майбутньому: Tom will be thirty in May."},{"t":"ex","items":[["You**'ll like** Wexford — it's a lovely town.","Тобі сподобається Вексфорд — гарне містечко."],["I'm sure you**'ll pass** the test.","Я впевнений, що ти складеш іспит."],["The boss **will** probably **call** later.","Бос, мабуть, подзвонить пізніше."],["I hope it **won't be** too cold tomorrow.","Сподіваюся, завтра не буде надто холодно."],["Tom **will be** thirty in May.","У травні Томові буде тридцять."]]},{"t":"tip","text":"**Probably** ставимо **після** will, але **перед** won't: He**'ll probably** be late. He **probably won't** come."},{"t":"p","text":"Коли думаєш, що чогось **не** буде, англійці зазвичай кажуть **I don't think** + will: не «думаю, що не», а «не думаю, що». I think he won't come граматично можливо, але звучить різкіше й рідше."},{"t":"ex","items":[["**I don't think** the boss **will like** it.","Думаю, босові це не сподобається."],["**I don't think** we**'ll finish** today.","Думаю, сьогодні ми не закінчимо."]]},{"t":"h","text":"3. Обіцянки, пропозиції, прохання"},{"t":"p","text":"Will — для **обіцянок** (I'll call you), коли **пропонуєш допомогу** (I'll carry it) і коли **просиш** когось (Will you…?). Між колегами Will you…? звучить нормально, а ввічливіше — Could you…?"},{"t":"ex","items":[["I **won't forget**, I promise.","Я не забуду, обіцяю."],["That box looks heavy. I**'ll carry** it for you.","Ця коробка, здається, важка. Я понесу."],["I**'ll give** you a lift to Gorey.","Я підвезу тебе до Горі."],["**Will** you **hold** this board for a second?","Потримаєш цю плиту секунду?"]]},{"t":"tip","text":"**Won't** ще означає «ніяк не хоче, не піддається» — і про людей, і про речі: The van **won't** start (фургон не заводиться). This screw **won't** go in (цей шуруп ніяк не закручується). He **won't** listen (він не хоче слухати)."},{"t":"h","text":"Пропозиції: Shall I…? Shall we…?"},{"t":"p","text":"Коли **пропонуєш** щось зробити або **радишся**, з I і we кажуть **Shall** — лише в питаннях. Українською це «Мені…?», «Може, …?», «Давай…?»."},{"t":"ex","items":[["**Shall I** open the window?","Відчинити вікно?"],["**Shall we** start? Everyone's here.","Починаємо? Усі вже тут."],["What time **shall we** meet?","О котрій зустрінемося?"]]},{"t":"tip","text":"В Ірландії часто почуєш **Will I…?** у тому самому значенні: Will I put the kettle on? — Поставити чайник? Це місцевий варіант, а Shall I…? зрозуміють скрізь."},{"t":"tip","text":"**Will can** не буває: два такі службові слова поспіль не ставлять. «Зможу» в майбутньому — **will be able to**: I'll be able to finish it tomorrow. Про домовленість на завтра часто кажуть і просто can: I can come tomorrow."},{"t":"ex","items":[["I**'ll be able to** finish the ceiling tomorrow.","Я зможу закінчити стелю завтра."],["**Will** you **be able to** help me on Monday?","Зможеш допомогти мені в понеділок?"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I will to go there tomorrow.","right":"I will go there tomorrow.","why":"Після will дієслово без to: will go."},{"t":"mistake","wrong":"I'll going to the shop.","right":"I'll go to the shop.","why":"Після will — початкова форма, без -ing. I'll going — це суміш will і I'm going."},{"t":"mistake","wrong":"He wills help us.","right":"He will help us.","why":"Will не змінюється: без -s і для he, she, it. І дієслово після нього теж без -s (не will helps)."},{"t":"mistake","wrong":"It's cold. — I close the window.","right":"It's cold. — I'll close the window.","why":"Рішення, ухвалене просто зараз, — I'll close. Теперішній час I close тут неправильний, хоч українською можна сказати «зараз зачиняю»."},{"t":"mistake","wrong":"I think it won't rain.","right":"I don't think it'll rain.","why":"Граматично можливо, але звучить незвично. Англійці зазвичай заперечують think: «не думаю, що буде дощ»."}],"tasks":[{"type":"choice","q":"I think it ___ rain later.","uk":"Думаю, пізніше буде дощ.","opts":["will","wills","will to"],"a":0,"why":"Прогноз-думка — will. Воно однакове для всіх (без -s), а дієслово після нього без to: it will rain."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Він нам допоможе.","opts":["He wills help us.","He will helps us.","He will help us."],"a":2,"why":"Will не змінюється, і дієслово після нього теж у початковій формі: he will help, без жодного -s."},{"type":"choice","q":"The phone's ringing. — OK, ___ it.","uk":"Дзвонить телефон. — Добре, я відповім.","opts":["I'll answer","I answer","I answering"],"a":0,"why":"Рішення, яке з'явилося просто зараз, у розмові, — I'll. Теперішній час тут не підходить, а форма з -ing без am не буває."},{"type":"choice","q":"Don't worry, I ___ anyone.","uk":"Не хвилюйся, я нікому не скажу.","opts":["won't tell","want tell","will not to tell"],"a":0,"why":"Обіцянка — won't (= will not) + дієслово без to. Want — це «хочу», зовсім інше слово, хоч і звучить схоже."},{"type":"choice","q":"___ I carry this for you?","uk":"Тобі це понести?","opts":["Shall","Am","Does"],"a":0,"why":"Пропонуючи допомогу, кажемо Shall I…? (Мені…?). Am з початковою формою не поєднується (am I carry — неможливо), а does не буває з I."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Думаю, він не прийде.","opts":["I don't think he'll come.","I think he don't come.","I not think he'll come."],"a":0,"why":"Англійці заперечують think: I don't think he'll come. Not без do перед дієсловом не ставлять, а he don't — неправильна форма, ще й теперішній час."},{"type":"input","q":"I think you ___ (like) this film.","uk":"Думаю, тобі сподобається цей фільм.","a":["will like","are going to like"],"why":"Думка про майбутнє — will + початкова форма: you will like (скорочено you'll like). Going to like теж правильно."},{"type":"input","q":"I promise I ___ (not / be) late again.","uk":"Обіцяю, що більше не запізнюся.","a":["won't be","am not going to be"],"why":"Обіцянка — will. Заперечення: won't (= will not) + be. I'm not going to be теж правильно."},{"type":"input","q":"We've run out of screws. — Have we? OK, I ___ (get) some.","uk":"У нас закінчилися шурупи. — Справді? Тоді я куплю.","a":["will get"],"why":"Have we? (Справді?) — новина для тебе, і рішення купити з'являється просто зараз, у розмові. Тому will: I'll get some, а не going to."},{"type":"input","q":"Sorry, I won't ___ come on Saturday.","uk":"Вибач, я не зможу прийти в суботу.","a":["be able to"],"why":"Will can не буває, тому «зможу» в майбутньому — will be able to, «не зможу» — won't be able to."},{"type":"order","uk":"Коли ти повернешся?","words":["back","you","will","when","be"],"a":["When will you be back?"],"why":"Питання: When + will + you + be back. Will стоїть перед you, як do чи does у Present Simple."},{"type":"order","uk":"Не думаю, що сьогодні буде дощ.","words":["think","rain","I","it'll","today","don't"],"a":["I don't think it'll rain today."],"why":"Заперечуємо think (I don't think), а далі звичайне ствердження з will: it'll rain."}],"section":"future"},"going-to":{"id":"going-to","level":"A2","title":"Be going to and plans","uk":"Going to і плани на майбутнє","summary":"намір, прогноз за ознаками, домовленості: I'm going to buy","minutes":7,"blocks":[{"t":"p","text":"**Be going to** + початкова форма дієслова (як у словнику: work, buy) — коли про майбутнє ти **вже вирішив заздалегідь**: намір, план. Українською «я збираюся», «я буду», «я куплю». Going to складається з трьох частин: **am / is / are** + **going to** + дієслово, і жодну з них пропустити не можна."},{"t":"ex","items":[["I**'m going to buy** a car next month.","Наступного місяця я куплю машину."],["We**'re going to watch** the match at the weekend.","На вихідних ми дивитимемося матч."],["Sarah **is going to start** a new job in May.","Сара в травні починає нову роботу."],["Tom **is going to look** for a new flat.","Том збирається шукати нову квартиру."]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Ствердження","lines":["I **am** going to + work → I**'m** going to work","he / she / it **is** going to + work","you / we / they **are** going to + work"]},{"t":"rule","title":"Заперечення","lines":["I**'m not** going to + work","he / she / it **isn't** going to + work","you / we / they **aren't** going to + work"]},{"t":"rule","title":"Питання","lines":["**Am** I / **Is** he / **Are** you + going to + work?","Yes, I **am**. / No, he **isn't**. / Yes, they **are**."]},{"t":"p","text":"Am, is чи are залежить від **підмета** — того, хто або що виконує дію: I am, Tom is, we are. Після to — завжди початкова форма, без -s і без -ing: she's going to **buy**."},{"t":"ex","items":[["**Are** you **going to stay** late today? — No, I**'m not**.","Ти сьогодні затримаєшся на роботі? — Ні."],["Mick **isn't going to come** to the party.","Мік не прийде на вечірку."],["How long **is** it **going to take**?","Скільки часу це забере?"]]},{"t":"tip","text":"У розмові going to часто звучить як **gonna**: I'm gonna call him. Так говорять, але в повідомленнях і листах пиши повністю: going to."},{"t":"tip","text":"**I'm going to Dublin** tomorrow — це просто «я їду в Дублін» (Present Continuous від go). Going to + місце — рух кудись, going to + дієслово — план."},{"t":"h","text":"Прогноз за ознаками"},{"t":"p","text":"Going to — і тоді, коли ти **бачиш ознаки**, що щось ось-ось станеться. Це не думка, а висновок з того, що перед очима: чорні хмари — буде дощ."},{"t":"ex","items":[["Careful! That ladder **is going to fall**!","Обережно! Та драбина зараз упаде!"],["It's ten to eight and I'm still at home. I**'m going to be** late.","Уже за десять восьма, а я ще вдома. Я запізнюся."],["That lorry's too wide. It**'s not going to fit** through the gate.","Та вантажівка заширока. Вона не пролізе у ворота."]]},{"t":"h","text":"Going to чи will?"},{"t":"p","text":"Головне питання — **коли ти вирішив**. Вирішив **раніше**, уже маєш план — **going to**. Вирішуєш **просто зараз**, у розмові — **will**. З прогнозами схоже: просто думка — will, бачиш ознаки — going to. Порівняй:"},{"t":"ex","items":[["We've got no milk. — Oh, really? I**'ll get** some.","У нас немає молока. — Справді? Тоді я куплю."],["Why have you got your coat on? — We've got no milk. I**'m going to get** some.","Чого ти в куртці? — Молоко закінчилося. Збираюся купити."],["I think it**'ll be** sunny tomorrow.","Думаю, завтра буде сонячно."],["The sky's getting dark. It**'s going to rain**.","Небо темніє. Зараз піде дощ."]]},{"t":"tip","text":"У першому діалозі людина щойно дізналася новину й вирішила зараз — **will**. У другому вже вирішила до розмови (тому й одяглася) — **going to**."},{"t":"h","text":"Домовленості: Present Continuous"},{"t":"p","text":"Коли про майбутнє вже **домовлено** — є час, місце, інша людина знає — найприродніше **Present Continuous**: am / is / are + **форма з -ing** (та сама, що в «зараз роблю»). Зазвичай з часом (tomorrow, at ten, on Friday), інакше можуть зрозуміти як «зараз»."},{"t":"ex","items":[["I**'m seeing** the dentist on Thursday.","У четвер я йду до стоматолога."],["We**'re starting** work on a new house in Gorey on Monday.","У понеділок ми починаємо роботу на новому будинку в Горі."],["What **are** you **doing** tonight?","Що ти робиш сьогодні ввечері?"],["Olena **is flying** to Kraków on Friday.","Олена в п'ятницю летить до Кракова."]]},{"t":"tip","text":"I'm going to meet the boss at ten — теж правильно. А **I'll meet** him at ten звучить так, ніби ти вирішуєш просто зараз. Для того, що вже в календарі, це менш природно, хоч і не помилка."},{"t":"h","text":"Розклад: Present Simple"},{"t":"p","text":"Для **розкладу** — автобуси, потяги, кіно, години роботи магазину — Present Simple, навіть коли мова про завтра. Українською так само: «автобус відходить завтра о сьомій»."},{"t":"ex","items":[["The film **starts** at eight.","Фільм починається о восьмій."],["What time **does** the train **get** to Dublin?","О котрій потяг прибуває в Дублін?"],["Lidl **closes** at ten tonight.","Лідл сьогодні зачиняється о десятій."]]},{"t":"h","text":"Коротко: що вибрати"},{"t":"table","head":["Ситуація","Форма","Приклад"],"rows":[["рішення просто зараз","will","I'll help you."],["думка про майбутнє","will","I think he'll come."],["план, намір","be going to","I'm going to buy a car."],["бачу ознаки","be going to","It's going to rain."],["домовлено, є час","Present Continuous","I'm meeting Tom at six."],["розклад","Present Simple","The bus leaves at 7:10."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I going to buy a new phone.","right":"I'm going to buy a new phone.","why":"Без am, is чи are going to не працює: I'm going to, she's going to."},{"t":"mistake","wrong":"I'm going buy a new phone.","right":"I'm going to buy a new phone.","why":"Після going обов'язково to: going to buy."},{"t":"mistake","wrong":"She's going to buys a car.","right":"She's going to buy a car.","why":"Після to — лише початкова форма, без -s, навіть для she."},{"t":"mistake","wrong":"I meet Tom tomorrow at six.","right":"I'm meeting Tom tomorrow at six.","why":"Українською «зустрічаюся завтра» — теперішній час. Англійською для домовленостей між людьми — Present Continuous, а Present Simple лише для розкладів."}],"tasks":[{"type":"choice","q":"I ___ going to buy a new phone.","uk":"Я збираюся купити новий телефон.","opts":["am","is","are"],"a":0,"why":"З I завжди am: I am going to (скорочено I'm going to)."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Ми збираємося пофарбувати кухню.","opts":["We going to paint the kitchen.","We're going paint the kitchen.","We're going to paint the kitchen."],"a":2,"why":"Потрібні всі три частини: are (we're) + going to + paint. Без are чи без to речення неправильне."},{"type":"choice","q":"Look at those black clouds! ___","uk":"Глянь на ті чорні хмари! Зараз піде дощ.","opts":["It's going to rain.","It rains.","It's raining."],"a":0,"why":"Бачимо ознаки — прогноз з going to. It's raining означає, що дощ уже йде, а It rains — про те, що буває взагалі."},{"type":"choice","q":"The bus ___ at 7:10 tomorrow morning.","uk":"Автобус відходить завтра о 7:10 ранку.","opts":["leaves","leave","leaving"],"a":0,"why":"Розклад — Present Simple, навіть про завтра. The bus — це it, тому leaves з -s."},{"type":"choice","q":"___ this weekend?","uk":"Що ти робиш на цих вихідних?","opts":["What are you doing","What do you do","What you are doing"],"a":0,"why":"Питаємо про плани на конкретні вихідні — Present Continuous. What do you do at the weekend? — про звичку («що ти зазвичай робиш»). А в питанні are стоїть перед you."},{"type":"choice","q":"I've left my wallet at home! — Have you? Don't worry, ___ for you.","uk":"Я забув гаманець удома! — Справді? Не хвилюйся, я за тебе заплачу.","opts":["I'll pay","I'm going to pay","I pay"],"a":0,"why":"Про гаманець ти дізнався щойно (Have you? — Справді?) і вирішуєш просто зараз — will: I'll pay. Going to — для вирішеного раніше, а теперішній час I pay тут не підходить."},{"type":"choice","q":"Why have you bought all this paint? — ___ the kitchen.","uk":"Навіщо ти купив стільки фарби? — Збираюся пофарбувати кухню.","opts":["I'm going to paint","I'll paint","I paint"],"a":0,"why":"Ти вирішив ще до розмови, тому й купив фарбу. План, намір — going to. I'll paint звучало б як рішення, ухвалене щойно, а I paint — як звичка."},{"type":"input","q":"He ___ going to fix it today.","uk":"Він сьогодні не збирається це лагодити.","a":["isn't","is not","'s not"],"why":"Заперечення: he + isn't (is not) + going to + дієслово."},{"type":"input","q":"___ you going to work on Saturday?","uk":"Ти збираєшся працювати в суботу?","a":["Are"],"why":"У питанні am / is / are стає перед підметом (тим, хто діє). Для you — Are you going to…?"},{"type":"input","q":"Are you going to sell your car? — No, ___.","uk":"Ти збираєшся продавати свою машину? — Ні, не збираюся.","a":["I'm not","I'm not going to","I'm not going to sell it"],"why":"Коротка відповідь повторює допоміжне дієслово з питання: Are you…? — No, I'm not. Можна й довше: No, I'm not going to."},{"type":"order","uk":"Що ти збираєшся робити після роботи?","words":["you","what","to","going","are","do","work","after"],"a":["What are you going to do after work?"],"why":"Питання: What + are + you + going to + do. Are стоїть перед you, після to — початкова форма do."},{"type":"order","uk":"Завтра о десятій я зустрічаюся з босом.","words":["meeting","I'm","boss","the","at","tomorrow","ten"],"a":["I'm meeting the boss at ten tomorrow.","I'm meeting the boss tomorrow at ten.","Tomorrow I'm meeting the boss at ten.","Tomorrow at ten I'm meeting the boss.","At ten tomorrow I'm meeting the boss."],"why":"Домовленість з конкретним часом — Present Continuous: I'm meeting. Час (at ten tomorrow) зазвичай у кінці, але можна й на початку."}],"section":"future"},"time-clauses":{"id":"time-clauses","level":"B1","title":"Future time clauses","uk":"When, as soon as, until + теперішній час","summary":"I'll call you when I get home: після when — без will","minutes":6,"blocks":[{"t":"p","text":"Головне правило теми: коли говоримо про майбутнє, після **when, as soon as, before, after, until, once, by the time** ставимо **теперішній час**, а не will. Will (чи інша форма майбутнього) — лише в іншій частині речення."},{"t":"ex","items":[["I'll call you **when** I **get** home.","Я подзвоню тобі, коли прийду додому."],["**As soon as** the plaster **is** dry, we'll paint the walls.","Щойно штукатурка висохне, ми пофарбуємо стіни."],["We'll wait **until** the rain **stops**.","Ми почекаємо, доки не скінчиться дощ."],["**After** we **finish** the ceiling, we'll do the walls.","Після того як закінчимо стелю, візьмемося за стіни."]]},{"t":"p","text":"Українською ми кажемо майбутнім в обох частинах: «Подзвоню, коли **прийду**». Англійською майбутнє вже зрозуміле з першої частини (I'll call), тому після when — теперішній час: when I **get** home, дослівно «коли я приходжу додому». Не забувай -s для he, she, it: when he **gets** home."},{"t":"rule","title":"Будова","lines":["**will** + дієслово … **when** + теперішній час","I'll call you when I **get** home.","**When** + теперішній час, **will** + дієслово","When I **get** home, I'll call you."]},{"t":"tip","text":"Частини можна міняти місцями. Якщо речення починається з when, as soon as тощо, після цієї частини ставимо **кому**: When I get home, I'll call you."},{"t":"h","text":"Слова, після яких так роблять"},{"t":"table","head":["Слово","Значення","Приклад"],"rows":[["when","коли","when I get home"],["as soon as","щойно, як тільки","as soon as he arrives"],["before","перед тим як","before you leave"],["after","після того як","after we finish"],["until (till)","доки не, аж поки","until the rain stops"],["once","щойно, коли вже","once it gets dark"],["by the time","на той час, коли","by the time we get there"],["if","якщо","if it rains"]]},{"t":"ex","items":[["Have something to eat **before** you **go**.","Поїж чогось, перш ніж іти."],["**Once** the electrician **finishes**, we can start plastering.","Щойно електрик закінчить, ми зможемо штукатурити."],["**By the time** you **get** here, I'll be ready.","Коли ти приїдеш, я вже буду готовий."],["**If** you **need** help, I'll be in the van.","Якщо буде потрібна допомога, я буду у фургоні."]]},{"t":"tip","text":"Те саме з **if**: If it **rains**, we'll stay inside (не if it will rain). Детальніше — у темі про умовні речення."},{"t":"p","text":"Правило діє і в питаннях, і в запереченнях: will стоїть у головній частині, а після when, until тощо — теперішній час."},{"t":"ex","items":[["Will you call me **as soon as** you **hear** something?","Подзвониш мені, щойно щось дізнаєшся?"],["I won't sign anything **until** I **talk** to the boss.","Я нічого не підписуватиму, доки не поговорю з босом."]]},{"t":"h","text":"Present Perfect: «коли вже зроблю»"},{"t":"p","text":"Коли треба наголосити, що перша дія **повністю закінчиться**, перш ніж почнеться друга, після when, after, as soon as, once, until ставлять **Present Perfect**: have / has + **V3** (третя форма дієслова: finished, done, gone). Значення майже те саме, просто з відтінком «коли вже»."},{"t":"ex","items":[["I'll leave **when** I**'ve finished** this wall.","Я піду, коли закінчу цю стіну."],["**Once** you**'ve tried** it, you'll love it.","Щойно спробуєш, тобі сподобається."],["Don't leave **until** you**'ve signed** the timesheet.","Не йди, доки не підпишеш табель."]]},{"t":"tip","text":"Present Perfect — лише коли одна дія закінчується **до** початку іншої. Якщо дії майже одночасні, бери простий теперішній: When I **see** Tom, I'll tell him (побачу — і відразу скажу)."},{"t":"h","text":"Until чи by"},{"t":"p","text":"Обидва українською «до», але різниця велика. **Until** — дія **триває** аж до цього моменту. **By** — дія **закінчиться** не пізніше цього моменту (може, й раніше)."},{"t":"ex","items":[["We'll work **until** six.","Ми працюватимемо до шостої (аж до)."],["We'll finish **by** six.","Ми закінчимо до шостої (не пізніше)."],["I'll wait **until** you **finish**.","Я почекаю, доки ти не закінчиш."]]},{"t":"tip","text":"**Until** уже містить «доки **не**», тому другого not не треба: Wait **until** I **come** back — «Чекай, доки я **не** повернуся». Українське «не» тут англійською не перекладаємо."},{"t":"h","text":"Коли will після when і if можна"},{"t":"p","text":"Правило стосується when у значенні «коли настане момент». Якщо **when** — питальне слово («Коли?») або після нього йде питання в непрямій формі («не знаю, коли…»), will ставимо як звичайно. Те саме з **if** у значенні «чи»."},{"t":"ex","items":[["**When will** you **finish** the bathroom?","Коли ти закінчиш ванну?"],["I don't know **when** he**'ll be** back.","Я не знаю, коли він повернеться."],["I'm not sure **if** the boss **will like** it.","Я не впевнений, чи сподобається це босові."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I'll call you when I will get home.","right":"I'll call you when I get home.","why":"Після when про майбутнє — теперішній час, хоч українською «коли прийду»."},{"t":"mistake","wrong":"We'll go as soon as he will finish.","right":"We'll go as soon as he finishes.","why":"Після as soon as — теперішній час. Для he — finishes з -es."},{"t":"mistake","wrong":"Wait until he will arrive.","right":"Wait until he arrives.","why":"Після until — теперішній час, не will."},{"t":"mistake","wrong":"Don't start until the boss doesn't come.","right":"Don't start until the boss comes.","why":"Until уже означає «доки не», тому друге заперечення зайве."},{"t":"mistake","wrong":"If it will rain, we'll stay at home.","right":"If it rains, we'll stay at home.","why":"Після if про майбутнє — так само теперішній час."}],"tasks":[{"type":"choice","q":"I'll call you when I ___ home.","uk":"Я подзвоню тобі, коли прийду додому.","opts":["get","will get","got"],"a":0,"why":"Після when про майбутнє — теперішній час: when I get home. Will — лише в іншій частині (I'll call)."},{"type":"choice","q":"We'll start as soon as the boss ___.","uk":"Ми почнемо, щойно приїде бос.","opts":["arrives","will arrive","arrive"],"a":0,"why":"Після as soon as — теперішній час. The boss — це він, тому arrives з -s."},{"type":"choice","q":"Wait here until I ___ back.","uk":"Чекай тут, доки я не повернуся.","opts":["come","don't come","will come"],"a":0,"why":"Until уже означає «доки не», тому not не потрібне. І після until — теперішній час, не will."},{"type":"choice","q":"We'll work ___ six o'clock, then go home.","uk":"Ми працюватимемо аж до шостої, а потім підемо додому.","opts":["until","by","since"],"a":0,"why":"Робота триває аж до шостої — until. By означає «не пізніше ніж» і пасує до дій, які закінчуються: finish by six."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Що ти робитимеш, коли закінчиш цю роботу?","opts":["What will you do when you finish this job?","What will you do when you will finish this job?","What do you do when you will finish this job?"],"a":0,"why":"Will — у головній частині (what will you do), а після when — теперішній час: when you finish."},{"type":"choice","q":"When ___ the plaster be dry?","uk":"Коли висохне штукатурка?","opts":["will","does","is"],"a":0,"why":"Тут when — питальне слово «Коли?», а не частина речення про час. Тому will ставимо як звичайно: When will…?"},{"type":"input","q":"We'll start plastering after the electrician ___ (finish).","uk":"Ми почнемо штукатурити після того, як закінчить електрик.","a":["finishes","has finished","is finished"],"why":"Після after про майбутнє — теперішній час (finishes) або Present Perfect (has finished), але не will."},{"type":"input","q":"If it ___ (rain) tomorrow, we won't work outside.","uk":"Якщо завтра буде дощ, ми не працюватимемо надворі.","a":["rains"],"why":"Після if про майбутнє — теперішній час, як і після when: if it rains."},{"type":"input","q":"Text me before you ___ (leave) the site.","uk":"Напиши мені, перш ніж поїдеш з об'єкта.","a":["leave"],"why":"Після before — теперішній час: before you leave, хоч українською «поїдеш»."},{"type":"input","q":"You can go home as soon as you ___ (clean) the tools.","uk":"Можеш іти додому, щойно почистиш інструменти.","a":["clean","have cleaned","'ve cleaned"],"why":"Після as soon as — теперішній час (clean) або Present Perfect (have cleaned), щоб наголосити «коли вже зробиш». Will тут не можна."},{"type":"order","uk":"Я скажу йому, щойно його побачу.","words":["I'll","him","as","tell","soon","as","I","see","him"],"a":["I'll tell him as soon as I see him.","As soon as I see him, I'll tell him."],"why":"Will — у частині «скажу» (I'll tell him), а після as soon as — теперішній час: I see him."},{"type":"order","uk":"Не торкайся стіни, доки вона не висохне.","words":["touch","don't","the","wall","until","it's","dry"],"a":["Don't touch the wall until it's dry.","Until it's dry, don't touch the wall."],"why":"Після until — теперішній час (it's dry = it is dry), і без not: until уже означає «доки не»."}],"section":"future"},"future-continuous-perfect":{"id":"future-continuous-perfect","level":"B1","title":"Future Continuous and Future Perfect","uk":"Will be doing і will have done","summary":"дія в процесі чи вже завершена: I'll be working, I'll have finished","minutes":7,"blocks":[{"t":"p","text":"Дві форми, щоб точно сказати, що буде **в певний момент майбутнього**: дія тоді ще **триватиме** (will be doing) чи вже **закінчиться** (will have done). Уяви, що дивишся на годинник завтра о шостій: що ти робиш саме тоді і що вже встиг зробити?"},{"t":"ex","items":[["This time tomorrow I**'ll be flying** to Kraków.","Завтра в цей час я летітиму до Кракова."],["By Friday we**'ll have finished** the ceiling.","До п'ятниці ми вже закінчимо стелю."]]},{"t":"h","text":"Will be + -ing: дія в процесі"},{"t":"rule","title":"Форми","lines":["**will be** + форма з -ing: I'll be working","заперечення: I **won't be** working","питання: **Will** you **be** working?"]},{"t":"p","text":"**Future Continuous** вживаємо, коли дія **триватиме** в конкретний момент майбутнього: о дев'ятій, завтра в цей час, коли ти приїдеш. Вона почнеться раніше і ще не закінчиться. Українською — «працюватиму», «якраз їхатиму». Will be однакове для всіх: I'll be, she'll be, they'll be."},{"t":"ex","items":[["Don't call me at ten — I**'ll be driving**.","Не дзвони мені о десятій — я буду за кермом."],["This time next week we**'ll be lying** on a beach in Spain.","Наступного тижня в цей час ми лежатимемо на пляжі в Іспанії."],["When you arrive, I**'ll be waiting** at the bus stop.","Коли ти приїдеш, я чекатиму на зупинці."],["Tom **won't be working** tomorrow — it's his day off.","Том завтра не працюватиме — у нього вихідний."]]},{"t":"p","text":"Порівняй з простим will: **will** — дія почнеться саме в цей момент, **will be + -ing** — у цей момент дія вже йде."},{"t":"ex","items":[["When you get home, I**'ll cook** dinner.","Коли ти прийдеш, я приготую вечерю (тоді й почну)."],["When you get home, I**'ll be cooking** dinner.","Коли ти прийдеш, я якраз готуватиму вечерю."]]},{"t":"h","text":"Ввічливе питання про плани"},{"t":"p","text":"**Will you be + -ing…?** — м'який спосіб спитати про чиїсь плани, часто перед проханням. Will you use…? може прозвучати як прохання чи навіть вимога, а Will you be using…? — просто питання: «у тебе такі плани?»"},{"t":"ex","items":[["**Will** you **be using** the van tomorrow? I need to pick up some boards.","Ти завтра користуватимешся фургоном? Мені треба забрати плити."],["**Will** you **be coming** to the site on Monday?","Ти будеш на об'єкті в понеділок?"],["How long **will** you **be staying** in Dublin?","Скільки ти пробудеш у Дубліні?"]]},{"t":"h","text":"Will have + V3: дія вже завершена"},{"t":"rule","title":"Форми","lines":["**will have** + V3: I'll have finished","заперечення: I **won't have** finished","питання: **Will** you **have** finished?"]},{"t":"p","text":"**V3** — третя форма дієслова: у правильних + -ed (finished, painted), неправильні треба знати (done, gone, left, bought). **Future Perfect** (will have + V3) вживаємо, коли дія **закінчиться до певного моменту** в майбутньому. Українською — «вже зроблю», «встигну зробити»."},{"t":"p","text":"Майже завжди поруч **by**: by Friday (до п'ятниці), by six (до шостої), by the end of the month (до кінця місяця), by then (на той час), by the time you get here (на той час, коли ти приїдеш)."},{"t":"ex","items":[["The plaster **will have dried** by tomorrow morning.","До завтрашнього ранку штукатурка вже висохне."],["By the time you get here, the film **will have started**.","Коли ти приїдеш, фільм уже почнеться."],["**Will** you **have finished** by six?","Ти встигнеш закінчити до шостої?"],["Don't worry, they **won't have left** by the time we get there.","Не хвилюйся, до нашого приїзду вони ще не поїдуть."]]},{"t":"tip","text":"Простий will з by теж правильний: We'll finish **by** Friday. Will have done наголошує, що **на той момент усе вже буде готово**. А з **by the time** + подія найчастіше потрібне саме will have done: By the time you get here, I**'ll have finished**."},{"t":"h","text":"By чи until"},{"t":"p","text":"Обидва українською «до». **By** — не пізніше ніж: дія **закінчиться** будь-коли до цього моменту. **Until** — аж до: дія **триває** весь час до цього моменту. Тому by часто з will have done, а until — з will be doing або простим will."},{"t":"ex","items":[["We**'ll have finished** by Friday.","Ми закінчимо до п'ятниці (не пізніше)."],["We**'ll be working** here until Friday.","Ми працюватимемо тут аж до п'ятниці."]]},{"t":"tip","text":"Після **by the time** і **until** — теперішній час, а не will: by the time you **get** here, until the boss **arrives**. Це правило з теми «When, as soon as, until + теперішній час»."},{"t":"h","text":"Три форми поруч"},{"t":"table","head":["Форма","Що означає","Приклад"],"rows":[["will + дієслово","дія відбудеться тоді","I'll call you at six."],["will be + -ing","о шостій дія ще триває","I'll be driving home at six."],["will have + V3","до шостої вже зроблено","I'll have left by six."]]},{"t":"ex","items":[["I**'ll call** you at six.","Я подзвоню тобі о шостій."],["I**'ll be driving** home at six.","О шостій я якраз їхатиму додому."],["I**'ll have left** the site by six.","До шостої я вже поїду з об'єкта."]]},{"t":"tip","text":"Дієслова стану — **know, like, want, need, understand, believe** — зазвичай не мають форми з -ing. Тому й will be + -ing з ними зазвичай не вживають: **I'll know** tomorrow (не I'll be knowing)."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"We'll have finished the ceiling until Friday.","right":"We'll have finished the ceiling by Friday.","why":"«До» в значенні «не пізніше ніж» — by. Until означає, що дія триває весь час аж до цього моменту."},{"t":"mistake","wrong":"By the time you get here, I'll finish.","right":"By the time you get here, I'll have finished.","why":"Хочеш сказати, що на момент твого приїзду все вже буде зроблено, — will have + V3. I'll finish звучить так, ніби тільки тоді почнеш закінчувати."},{"t":"mistake","wrong":"I'll have finish it by six.","right":"I'll have finished it by six.","why":"Після have — третя форма (V3): finished, done, gone."},{"t":"mistake","wrong":"I'll be knowing the results tomorrow.","right":"I'll know the results tomorrow.","why":"Know — дієслово стану, форми з -ing у нього зазвичай немає."}],"tasks":[{"type":"choice","q":"At eight tomorrow ___ to work.","uk":"Завтра о восьмій я якраз їхатиму на роботу.","opts":["I'll be driving","I'll driving","I'll be drive"],"a":0,"why":"Дія буде в процесі в певний момент майбутнього — will be + форма з -ing: I'll be driving. Без be або без -ing так не можна."},{"type":"choice","q":"By six o'clock ___ home.","uk":"До шостої вона вже піде додому.","opts":["she'll have gone","she'll have went","she has gone"],"a":0,"why":"Дія завершиться до певного моменту — will have + V3. V3 від go — gone (went — це V2). She has gone — теперішній час, а тут майбутнє."},{"type":"choice","q":"I'll have saved enough money ___ the summer.","uk":"До літа я вже накопичу достатньо грошей.","opts":["by","until","since"],"a":0,"why":"«До» в значенні «не пізніше ніж» — by. З will have done майже завжди by, а until — коли дія триває весь час аж до моменту."},{"type":"choice","q":"___ the drill this afternoon? I need it for an hour.","uk":"Ти сьогодні після обіду користуватимешся дрилем? Мені він потрібен на годину.","opts":["Will you be using","Will you using","Are you be using"],"a":0,"why":"Ввічливе питання про чиїсь плани — Will you be + форма з -ing? Без be або з are замість will так не можна."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Завтра я знатиму результати.","opts":["I'll know the results tomorrow.","I'll be knowing the results tomorrow.","I'll have knowing the results tomorrow."],"a":0,"why":"Know — дієслово стану, у формі з -ing його зазвичай не вживають. Тому просто will know."},{"type":"choice","q":"Don't come at seven — ___ dinner then.","uk":"Не приходь о сьомій — ми якраз вечерятимемо.","opts":["we'll be having","we'll have had","we'll having"],"a":0,"why":"О сьомій вечеря ще триватиме — will be + -ing. We'll have had означало б, що ми вже повечеряємо, і тоді якраз можна приходити."},{"type":"input","q":"This time tomorrow I'll ___ (work) in Dublin.","uk":"Завтра в цей час я якраз працюватиму в Дубліні.","a":["be working"],"why":"Завтра в цей час дія буде в процесі, тому will be + форма з -ing: I'll be working."},{"type":"input","q":"By the time you arrive, I ___ (finish).","uk":"Коли ти приїдеш, я вже закінчу.","a":["will have finished","'ll have finished","will have already finished","'ll have already finished","will already have finished","'ll already have finished","will be finished","'ll be finished"],"why":"Дія закінчиться до моменту твого приїзду — will have + V3. Після by the time — теперішній час (arrive), а will — у другій частині."},{"type":"input","q":"By the time we get there, Tom will have ___ (go) home.","uk":"Коли ми доберемося, Том уже піде додому.","a":["gone"],"why":"Після will have — V3. Від go це gone, а went — друга форма (V2), її тут не вживають."},{"type":"input","q":"We'll be working here ___ Christmas.","uk":"Ми працюватимемо тут аж до Різдва.","a":["until","till","up until","up till"],"why":"Дія триває весь час аж до моменту — until (till). By означало б «не пізніше ніж» і пасує до завершених дій."},{"type":"order","uk":"Ти працюватимеш у суботу?","words":["you","be","will","on","working","Saturday"],"a":["Will you be working on Saturday?"],"why":"Питання: Will + підмет (хто діє) + be + форма з -ing. Так ввічливо питають про чиїсь плани."},{"type":"order","uk":"До п'ятниці ми не встигнемо закінчити.","words":["won't","we","finished","have","Friday","by"],"a":["We won't have finished by Friday.","By Friday we won't have finished."],"why":"Заперечення: won't have + V3 (finished). By Friday може стояти в кінці або на початку речення."}],"section":"future"},"can-could":{"id":"can-could","level":"A2","title":"Can, could, be able to","uk":"Can і could: вміти, могти, можна","summary":"вміння, дозвіл, можливість: I can, I could, I'll be able to","minutes":7,"blocks":[{"t":"p","text":"**Can** — одне з найпотрібніших слів в англійській. Воно означає **«вмію»**, **«можу»** і **«можна»**. **Could** — його минула форма («умів, міг») і водночас ввічливіший варіант у проханнях: **Could I…?** — «Чи можна мені…?»"},{"t":"ex","items":[["I **can** drive, but I **can't** ride a motorbike.","Я вмію водити машину, але не вмію їздити на мотоциклі."],["**Can** you help me with this ladder?","Можеш допомогти мені з цією драбиною?"],["She **can't** come today. She's ill.","Вона сьогодні не може прийти. Вона хвора."],["**Can** I park here?","Тут можна паркуватися?"]]},{"t":"h","text":"Can — модальне дієслово"},{"t":"p","text":"Can — **модальне дієслово**. Так називають особливі дієслова (can, could, must, should, will), які стоять перед іншим дієсловом і додають до нього значення «можу», «треба», «варто». Вони поводяться не як звичайні дієслова. Запам'ятай три правила:"},{"t":"list","items":["**Без -s** після he, she, it: she **can** swim, а не she cans swim.","Після can — **початкова форма дієслова** (work, go) **без to**: I can **swim**, а не I can to swim.","**Без do** у питаннях і запереченнях. У питанні can стає перед **підметом** (хто або що виконує дію): **Can you** swim? Заперечення — просто **can't**."]},{"t":"rule","title":"Форми (однакові для всіх осіб)","lines":["Ствердження: She **can** swim.","Заперечення: She **can't** (cannot) swim.","Питання: **Can** she swim?","Коротко: Yes, she **can**. / No, she **can't**."]},{"t":"tip","text":"Повна форма заперечення — **cannot**, пишеться **разом**. На слух can у реченні коротке й без наголосу, а **can't** звучить чітко й наголошено. Якщо почув виразне, наголошене слово, найімовірніше, це can't."},{"t":"h","text":"Вміння: зараз і в минулому"},{"t":"p","text":"**Can** — вміння зараз. **Could** — вміння в минулому, яке тривало якийсь час: «у дитинстві вмів», «раніше міг». Заперечення **couldn't** — «не міг, не вмів»."},{"t":"ex","items":[["I **could** swim when I was six.","Я вмів плавати, коли мені було шість."],["My grandad **could** speak three languages.","Мій дідусь умів говорити трьома мовами."],["**Could** you read when you were five?","Ти вмів читати, коли тобі було п'ять?"],["I **couldn't** sleep last night.","Минулої ночі я не міг заснути."]]},{"t":"h","text":"Be able to: зможу, досі не міг"},{"t":"p","text":"У can є лише дві форми: can і could. Немає «will can», «have can» чи «to can». Коли потрібен інший час, беремо **be able to** + початкова форма дієслова (дослівно «бути здатним»). Be змінюється як завжди (will be, have been), а **able to** лишається без змін."},{"t":"table","head":["Час","Форма","Приклад"],"rows":[["зараз","can","I **can** lift it."],["минуле","could","I **could** swim at six."],["майбутнє","will be able to","I'**ll be able to** come."],["Present Perfect","have been able to","I **haven't been able to** sleep."],["після іншого дієслова","to be able to","I want **to be able to** cook."]]},{"t":"ex","items":[["I'**ll be able to** finish the job tomorrow.","Я зможу закінчити роботу завтра."],["I **haven't been able to** sleep well this week.","Цього тижня я не можу нормально виспатися."],["I'd like **to be able to** speak English better.","Я хотів би вміти краще говорити англійською."],["**Will** you **be able to** come on Saturday?","Ти зможеш прийти в суботу?"]]},{"t":"tip","text":"Про майбутнє можна сказати й просто **can**, якщо домовляєшся зараз: I **can** come tomorrow. — Я можу прийти завтра. А **will be able to** — коли вміння чи можливість з'явиться пізніше: When I get my licence, I'**ll be able to** drive to work."},{"t":"h","text":"Зміг один раз: managed to, was able to"},{"t":"p","text":"Пастка для українців. «Я зміг полагодити» про **один конкретний випадок** у минулому — це **не could**. Could означає загальне вміння («умів»). Для одного успіху, особливо коли було непросто, кажемо **managed to** («вдалося») або **was able to**."},{"t":"ex","items":[["The pipe was old, but I **managed to** fix it.","Труба була стара, але мені вдалося її полагодити."],["We **were able to** finish before the rain.","Нам вдалося закінчити до дощу."],["He **managed to** pass his driving test on his second attempt.","Він склав іспит з водіння з другої спроби."]]},{"t":"tip","text":"У запереченні простіше: **couldn't** підходить і для одного випадку: I **couldn't** find my keys this morning. Також could можна про один раз із see, hear, understand: We **could see** the sea from the roof."},{"t":"tip","text":"З **see** і **hear** англійці зазвичай додають **can** там, де українець скаже просто «бачу», «чую»: I **can't hear** you. — Я тебе не чую. **Can** you **see** the van? — Бачиш фургон?"},{"t":"h","text":"Дозвіл: можна?"},{"t":"p","text":"**Can I…?** — просто «можна?». **Could I…?** — те саме, але ввічливіше: з незнайомими, з босом, у магазині. Відповідаємо з can, а не з could: Yes, of course you **can**. А **can't** у цьому значенні — «не можна, заборонено»."},{"t":"ex","items":[["**Can** I borrow your tape measure?","Можна позичити твою рулетку?"],["**Could** I leave early today? — Yes, of course you **can**.","Можна мені сьогодні піти раніше? — Так, звісно."],["You **can** use my van tomorrow.","Завтра можеш узяти мій фургон."],["You **can't** park here. It's for residents only.","Тут не можна паркуватися. Це лише для мешканців."]]},{"t":"h","text":"Можливість: буває"},{"t":"p","text":"Can також означає, що щось **буває**, **трапляється** час від часу, а не завжди."},{"t":"ex","items":[["It **can** get very windy in Wexford.","У Вексфорді буває дуже вітряно."],["This job **can** be dangerous.","Ця робота буває небезпечною."],["The traffic in Dublin **can** be terrible in the morning.","Уранці в Дубліні бувають жахливі затори."]]},{"t":"tip","text":"Прохання **Can you…? / Could you…?** («Можеш…? Можете…?») розібрано в темі «Ввічливі прохання й пропозиції». А could у значенні «можливо, може статися» (It could rain later) — в іншій темі розділу «Модальні дієслова»."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I can to swim.","right":"I can swim.","why":"Після can дієслово без to."},{"t":"mistake","wrong":"He cans drive.","right":"He can drive.","why":"Can не змінюється: без -s навіть після he, she, it."},{"t":"mistake","wrong":"Do you can help me?","right":"Can you help me?","why":"Can сам утворює питання, do не потрібне: просто став can перед підметом."},{"t":"mistake","wrong":"I will can come tomorrow.","right":"I'll be able to come tomorrow.","why":"Два модальні дієслова поруч (will can) не ставлять. Майбутнє — will be able to, а про домовленість можна просто: I can come tomorrow."},{"t":"mistake","wrong":"I could fix the boiler yesterday.","right":"I managed to fix the boiler yesterday.","why":"Про один конкретний успіх у минулому — managed to або was able to. Could — це загальне вміння в минулому."}],"tasks":[{"type":"choice","q":"She ___ speak three languages.","uk":"Вона вміє говорити трьома мовами.","opts":["can","cans","can to"],"a":0,"why":"Can однакове для всіх осіб: без -s навіть після she. Після нього дієслово без to."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Ти вмієш водити фургон?","opts":["Can you drive a van?","Do you can drive a van?","Can you to drive a van?"],"a":0,"why":"Can сам утворює питання: став його перед підметом. Do з can не поєднується, а to після can не буває."},{"type":"choice","q":"You ___ park here. It's a fire exit.","uk":"Тут не можна паркуватися. Це пожежний вихід.","opts":["can't","don't can","couldn't"],"a":0,"why":"«Не можна, заборонено» зараз — can't. Do з can не поєднується, а couldn't — це «не міг» у минулому."},{"type":"choice","q":"When I was a child, I ___ climb trees really fast.","uk":"У дитинстві я вмів дуже швидко лазити по деревах.","opts":["can","could","managed to"],"a":1,"why":"Загальне вміння в минулому, яке тривало (у дитинстві), — could. Managed to — про один конкретний випадок, can — про теперішнє."},{"type":"choice","q":"The roof was slippery, but we ___ to finish the job.","uk":"Дах був слизький, але нам вдалося закінчити роботу.","opts":["could","managed","can"],"a":1,"why":"Один конкретний успіх попри труднощі — managed to («вдалося»). Could і can тут не підходять: після них to не ставлять, а could ще й означає загальне вміння."},{"type":"choice","q":"After the course, you ___ drive a forklift.","uk":"Після курсу ти зможеш керувати навантажувачем.","opts":["will can","will be able to","can to"],"a":1,"why":"Два модальні дієслова поруч (will can) не ставлять. Вміння, яке з'явиться в майбутньому, — will be able to."},{"type":"input","q":"My little brother ___ (not / can) read yet. He's only four.","uk":"Мій молодший брат ще не вміє читати. Йому лише чотири.","a":["can't","cannot"],"why":"Заперечення від can — can't (повна форма cannot, пишеться разом). Doesn't тут не потрібне."},{"type":"input","q":"I ___ (not / can / sleep) last night because of the noise.","uk":"Минулої ночі я не міг заснути через шум.","a":["couldn't sleep","could not sleep","wasn't able to sleep","was not able to sleep"],"why":"«Не міг» у минулому — couldn't + дієслово. У запереченні couldn't підходить і для одного конкретного випадку."},{"type":"input","q":"I hope I'll ___ (can) speak English well next year.","uk":"Сподіваюся, наступного року я зможу добре говорити англійською.","a":["be able to"],"why":"Після will can не ставлять. «Зможу» — will be able to, тому після I'll пишемо be able to."},{"type":"input","q":"I ___ (not / be) able to contact Mick since Monday.","uk":"Я не можу зв'язатися з Міком з понеділка.","a":["haven't been","have not been"],"why":"Since Monday — від минулого до тепер, тобто Present Perfect. У can такої форми немає, тому haven't been able to."},{"type":"order","uk":"Можна позичити твою драбину?","words":["borrow","I","your","could","ladder"],"a":["Could I borrow your ladder?"],"why":"Ввічливо просимо дозволу: Could + I + дієслово без to."},{"type":"order","uk":"Узимку дороги бувають дуже слизькими.","words":["roads","the","can","in","be","very","slippery","winter"],"a":["The roads can be very slippery in winter.","In winter the roads can be very slippery.","The roads in winter can be very slippery."],"why":"Can тут означає «буває». Порядок: підмет + can + be. In winter можна поставити в кінці або на початку."}],"section":"modals"},"must-have-to":{"id":"must-have-to","level":"A2","title":"Must, have to, mustn't, don't have to","uk":"Must і have to: треба й не можна","summary":"треба, не можна, не обов'язково: must, have to, mustn't, had to","minutes":7,"blocks":[{"t":"p","text":"**Must** і **have to** обидва означають «треба», «мушу», «маю». У ствердженні різниця невелика, і часто підходять обидва. А от у запереченні вони розходяться повністю: **mustn't** — «не можна, заборонено», а **don't have to** — «не треба, можна не робити». Це найважливіше в темі."},{"t":"ex","items":[["I **must** call my mum tonight.","Я мушу сьогодні ввечері подзвонити мамі."],["We **have to** wear helmets on site.","На об'єкті ми мусимо носити каски."],["You **mustn't** smoke in the van.","У фургоні не можна курити."],["You **don't have to** come in on Saturday.","У суботу можеш не приходити на роботу."]]},{"t":"h","text":"Must: як утворюється"},{"t":"p","text":"Must — **модальне дієслово**, як can: однакове для всіх осіб (без -s), після нього **початкова форма дієслова** (work, go) **без to**, а заперечення без do: просто **mustn't**. У mustn't перше t не вимовляється: звучить приблизно «масн(т)»."},{"t":"rule","title":"Must для всіх осіб","lines":["I / you / he / she / we / they + **must** + go","заперечення: **mustn't** (must not) + go"]},{"t":"h","text":"Have to: як утворюється"},{"t":"p","text":"**Have to** поводиться як звичайне дієслово have: після he, she, it — **has to**, а заперечення й питання — з **do / does**, як у Present Simple. Після нього — початкова форма дієслова. На слух have to звучить як «хефте», has to — як «хесте»."},{"t":"table","head":["Форма","I / you / we / they","he / she / it"],"rows":[["ствердження","I **have to** go","she **has to** go"],["заперечення","I **don't have to** go","she **doesn't have to** go"],["питання","**Do** I **have to** go?","**Does** she **have to** go?"]]},{"t":"p","text":"Спитати «чи треба?» найприродніше саме через have to: **Do I have to**…? Must I…? граматично можливе, але звучить старомодно, у розмові його майже не почуєш."},{"t":"ex","items":[["**Do I have to** bring my own gloves?","Мені треба брати свої рукавиці?"],["What time **do we have to** start?","О котрій нам треба починати?"]]},{"t":"h","text":"Must чи have to?"},{"t":"p","text":"**Must** — обов'язок «від себе»: ти сам вирішив, що це важливо, або щиро радиш іншому. **Have to** — обов'язок ззовні: так вимагає правило, закон, бос чи обставини. Якщо сумніваєшся, кажи **have to**: у розмові воно звучить природніше й майже ніколи не буде помилкою."},{"t":"ex","items":[["I **must** stop eating so much chocolate.","Мені треба перестати їсти стільки шоколаду."],["You **must** see the Cliffs of Moher. They're amazing!","Ти обов'язково маєш побачити скелі Мохер. Вони неймовірні!"],["I **have to** be on site at half seven.","Я маю бути на об'єкті о пів на восьму."],["In Ireland you **have to** drive on the left.","В Ірландії треба їздити лівим боком дороги."],["Sarah **has to** wear glasses for driving.","Сарі треба носити окуляри за кермом."]]},{"t":"tip","text":"**Must** часто пишуть в офіційних правилах і на табличках: All visitors **must** report to the site office. Але коли ти сам розповідаєш про правила, кажи have to: We **have to** sign in every morning."},{"t":"h","text":"Головна пастка: mustn't і don't have to"},{"t":"p","text":"Українське «не треба» може означати і «не можна», і «немає потреби». В англійській це два зовсім різні вирази:"},{"t":"table","head":["Вираз","Значення"],"rows":[["**mustn't**","не можна, заборонено"],["**don't have to**","не обов'язково, можна не робити"]]},{"t":"ex","items":[["You **mustn't** use your phone while you're driving.","Не можна користуватися телефоном за кермом."],["You **don't have to** bring tools. We've got everything.","Інструменти можеш не брати. У нас усе є."],["You **mustn't** tell anyone. It's a secret.","Нікому не можна про це казати. Це таємниця."],["Tomorrow's Saturday. I **don't have to** get up early.","Завтра субота. Мені не треба рано вставати."]]},{"t":"tip","text":"Перевірка: підстав слово «заборонено». Якщо сенс зберігся — **mustn't**. Якщо виходить «можна не робити, як хочеш» — **don't have to**."},{"t":"p","text":"**Can't** теж означає «не можна» за правилами, і в розмові його кажуть навіть частіше, ніж mustn't: You **can't** smoke here."},{"t":"h","text":"Минуле й майбутнє: had to, will have to"},{"t":"p","text":"У must **немає минулої форми**. «Мусив, довелося» — завжди **had to**, питання — **Did** you **have to**…? Майбутнє — **will have to** («доведеться»): will must не буває."},{"t":"table","head":["Час","Треба","Не треба"],"rows":[["зараз","must / have to","don't have to"],["минуле","had to","didn't have to"],["майбутнє","will have to","won't have to"]]},{"t":"ex","items":[["I **had to** work late yesterday.","Учора мені довелося працювати допізна."],["We **didn't have to** pay for parking.","Нам не довелося платити за паркування."],["**Did** you **have to** show your ID?","Тобі довелося показувати посвідчення?"],["You'**ll have to** ask the boss.","Тобі доведеться спитати боса."]]},{"t":"h","text":"Have got to — розмовний варіант"},{"t":"p","text":"У Британії та Ірландії в розмові часто кажуть **have got to** (скорочено **'ve got to**, **'s got to**). Значення те саме, що в have to, але лише для теперішнього часу. Для минулого — все одно had to."},{"t":"ex","items":[["I'**ve got to** go. See you tomorrow.","Мені треба йти. До завтра."],["She'**s got to** finish it by Friday.","Їй треба закінчити це до п'ятниці."]]},{"t":"tip","text":"У must є й інше значення — «мабуть, напевно»: You **must** be tired. — Ти, мабуть, утомився. Про це — у темі «Наскільки ти впевнений: might, must, can't»."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"You mustn't come if you're busy.","right":"You don't have to come if you're busy.","why":"Mustn't — це заборона («не смій приходити»). «Можеш не приходити» — don't have to."},{"t":"mistake","wrong":"I must to go now.","right":"I must go now.","why":"Після must дієслово без to. To є лише в have to."},{"t":"mistake","wrong":"Did you must work on Sunday?","right":"Did you have to work on Sunday?","why":"У must немає минулого часу і питань з do чи did. Для минулого — had to, питання — Did you have to…?"},{"t":"mistake","wrong":"I musted leave early.","right":"I had to leave early.","why":"Must не змінюється і не має форми на -ed. «Мусив, довелося» — had to."},{"t":"mistake","wrong":"She have to work today.","right":"She has to work today.","why":"Have to змінюється, як have: після he, she, it — has to."}],"tasks":[{"type":"choice","q":"She ___ wear a uniform at work.","uk":"Вона мусить носити форму на роботі.","opts":["has to","have to","has"],"a":0,"why":"Have to змінюється, як have: після she — has to. Без to (she has wear) речення неправильне."},{"type":"choice","q":"I really ___ go to the dentist. My tooth hurts.","uk":"Мені справді треба піти до стоматолога. Болить зуб.","opts":["must","must to","musts"],"a":0,"why":"Must однакове для всіх осіб, без -s, а після нього дієслово без to."},{"type":"choice","q":"You ___ smoke inside the building. It's against the law.","uk":"У будівлі не можна курити. Це заборонено законом.","opts":["mustn't","don't have to","haven't to"],"a":0,"why":"Заборона — mustn't. Don't have to означало б «можна не курити, як хочеш», а haven't to так не кажуть."},{"type":"choice","q":"Tomorrow is a bank holiday, so we ___ go to work.","uk":"Завтра державне свято, тож нам не треба йти на роботу.","opts":["mustn't","don't have to","must"],"a":1,"why":"Немає потреби — don't have to. Mustn't означало б, що йти на роботу заборонено."},{"type":"choice","q":"Yesterday I ___ stay late to finish the ceiling.","uk":"Учора мені довелося залишитися допізна, щоб закінчити стелю.","opts":["must","had to","musted"],"a":1,"why":"У must немає минулого часу. «Довелося, мусив» — had to."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Тобі довелося за це платити?","opts":["Did you have to pay for it?","Did you must pay for it?","Did you had to pay for it?"],"a":0,"why":"Питання в минулому — Did you have to…? Must з did не поєднується, а після did дієслово в початковій формі: have, не had."},{"type":"input","q":"My brother ___ (have to) get up at five every day.","uk":"Моєму братові щодня треба вставати о п'ятій.","a":["has to","has got to"],"why":"My brother — це he, тому has to. Після нього дієслово в початковій формі: get up."},{"type":"input","q":"You ___ (not / have to) bring lunch. The boss is buying pizza.","uk":"Обід можеш не брати. Бос пригощає піцою.","a":["don't have to","haven't got to"],"why":"Немає потреби — don't have to. Mustn't тут означало б «заборонено брати обід»."},{"type":"input","q":"You ___ (not / must) touch that cable! It's live.","uk":"Цей кабель чіпати не можна! Він під напругою.","a":["mustn't","must not"],"why":"Тут заборона, бо небезпечно, тому mustn't (must not) + дієслово без to."},{"type":"input","q":"We ___ (not / have to) wait long. The bus came quickly.","uk":"Нам не довелося довго чекати. Автобус приїхав швидко.","a":["didn't have to","did not have to"],"why":"Минуле, «не довелося» — didn't have to. У must немає минулої форми."},{"type":"order","uk":"Мені треба вдягати каску?","words":["I","wear","have","a","do","helmet","to"],"a":["Do I have to wear a helmet?"],"why":"Питання з have to — через do: Do + I + have to + дієслово."},{"type":"order","uk":"Нам доведеться почекати до завтра.","words":["will","we","wait","have","to","until","tomorrow"],"a":["We will have to wait until tomorrow."],"why":"У must немає форми майбутнього часу (will must не буває). «Доведеться» — will have to + дієслово."}],"section":"modals"},"should":{"id":"should","level":"A2","title":"Should, ought to, had better","uk":"Should: поради","summary":"поради: You should rest. You'd better hurry. I should have…","minutes":6,"blocks":[{"t":"p","text":"**Should** — головне слово для **порад**: «варто», «слід», «треба б». Ним кажуть, що, на твою думку, правильно або розумно зробити. Це м'якше, ніж must чи have to: не наказ і не правило, а порада."},{"t":"ex","items":[["You **should** see a doctor.","Тобі варто піти до лікаря."],["You **shouldn't** lift that on your own.","Не варто піднімати це самому."],["We **should** leave early to avoid the traffic.","Нам варто виїхати раніше, щоб не стояти в заторах."],["**Should** I call him? — Yes, I think you **should**.","Мені йому подзвонити? — Так, думаю, варто."]]},{"t":"h","text":"Як утворюється"},{"t":"p","text":"Should — **модальне дієслово**, як can і must: однакове для всіх осіб (без -s), після нього **початкова форма дієслова** (rest, go) **без to**, питання й заперечення — без do. У питанні should стає перед **підметом** (хто або що виконує дію)."},{"t":"rule","title":"Форми","lines":["Ствердження: He **should** rest.","Заперечення: He **shouldn't** (should not) rest.","Питання: **Should** he rest?","Коротко: Yes, he **should**. / No, he **shouldn't**."]},{"t":"h","text":"Порада й думка: I think you should…"},{"t":"p","text":"Should часто поєднують з **I think**: I think you **should**… — м'яка, дружня порада. Зверни увагу: «думаю, не варто» англійською зазвичай **I don't think** you should…, тобто «не» переходить до think. I think you shouldn't… теж правильно, але звучить різкіше."},{"t":"ex","items":[["I think you **should** take a day off.","Думаю, тобі варто взяти вихідний."],["I **don't think** you **should** drive. You're too tired.","Не думаю, що тобі варто сідати за кермо. Ти надто втомлений."],["People **shouldn't** park on the pavement.","Не слід паркуватися на тротуарі."]]},{"t":"h","text":"Should I…? — просимо поради"},{"t":"p","text":"Коли не знаєш, як вчинити, питай **Should I…?** («Мені варто…?»). З питальними словами порядок такий самий: **What should I** do? **Where should I** put it?"},{"t":"ex","items":[["**Should I** tell the boss?","Мені сказати босові?"],["**What should I** wear to the interview?","Що мені вдягнути на співбесіду?"],["Which bus **should I** take?","Яким автобусом мені їхати?"]]},{"t":"h","text":"Ought to — те саме, офіційніше"},{"t":"p","text":"**Ought to** означає те саме, що should, але звучить трохи офіційніше, і в розмові його чуєш рідше. Головна різниця — **to**: should go, але ought **to** go. Заперечення ought not to трапляється рідко, зазвичай просто кажуть shouldn't."},{"t":"ex","items":[["You **ought to** check the forecast before you go.","Тобі варто перевірити прогноз погоди, перш ніж їхати."],["We **ought to** tell him the truth.","Нам слід сказати йому правду."]]},{"t":"h","text":"Had better — порада з попередженням"},{"t":"p","text":"**Had better** (у розмові майже завжди **'d better**) — сильна порада з попередженням: «краще зроби, бо інакше буде погано». Хоч там had, мова **не про минуле**, а про зараз чи найближчий час. Після had better — початкова форма дієслова **без to**."},{"t":"rule","title":"Had better: форми","lines":["I / you / he / she / we / they + **'d better** + go","заперечення: **'d better not** + go","повна форма: You **had better** go."]},{"t":"ex","items":[["You'**d better** wear gloves, or you'll cut your hands.","Краще вдягни рукавиці, бо поріжеш руки."],["We'**d better** hurry. The last bus is at ten.","Нам краще поквапитися. Останній автобус о десятій."],["You'**d better not** tell Mick about it.","Краще не розповідай про це Мікові."],["I'**d better** go. It's getting late.","Мені краще піти, вже пізно."]]},{"t":"tip","text":"**Should** — для загальних порад, **had better** — для конкретної ситуації тут і зараз, коли є ризик. Загальна порада: You **should** drink more water. Попередження: It's going to rain. You'**d better** take a coat."},{"t":"tip","text":"Іноді should — не порада, а очікування: «має бути», «мало б». The plaster **should** be dry by Monday. — До понеділка штукатурка має висохнути."},{"t":"h","text":"Should have + V3: треба було"},{"t":"p","text":"Щоб сказати «треба було» (а ти не зробив) чи «не треба було» (а ти зробив), бери **should have** + **V3** — третю форму дієслова (called, done, gone). Це вже рівень B1, тож поки головне — впізнавати. У розмові should have звучить коротко: **should've**."},{"t":"ex","items":[["I **should have brought** my jacket. It's freezing!","Треба було взяти куртку. Страшенно холодно!"],["You **shouldn't have paid** so much for it.","Не треба було платити за це так багато."],["We **should have left** earlier.","Нам треба було виїхати раніше."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"You should to rest.","right":"You should rest.","why":"Після should дієслово без to. To є лише в ought to."},{"t":"mistake","wrong":"Do I should wait?","right":"Should I wait?","why":"Should сам утворює питання: став його перед підметом, do не потрібне."},{"t":"mistake","wrong":"You had better to go.","right":"You'd better go.","why":"Після had better дієслово без to."},{"t":"mistake","wrong":"We'd better not to wake the baby.","right":"We'd better not wake the baby.","why":"Заперечення — 'd better not + дієслово, теж без to."},{"t":"mistake","wrong":"I should called him.","right":"I should have called him.","why":"«Треба було» — should have + V3. Пропускати have не можна."}],"tasks":[{"type":"choice","q":"You look tired. You ___ go to bed early.","uk":"Ти втомлений на вигляд. Тобі варто раніше лягти спати.","opts":["should","should to","shoulds"],"a":0,"why":"Порада — should + дієслово без to. Should однакове для всіх осіб і не має -s."},{"type":"choice","q":"He ___ work so much. He never sees his kids.","uk":"Йому не варто стільки працювати. Він ніколи не бачить своїх дітей.","opts":["shouldn't","doesn't should","shoulds not"],"a":0,"why":"Заперечення — shouldn't (should not) + дієслово. Does з should не поєднується, і -s у should не буває."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Мені подзвонити босові?","opts":["Should I call the boss?","Do I should call the boss?","Should I to call the boss?"],"a":0,"why":"Should сам утворює питання: став його перед підметом. Do не потрібне, а to після should не буває."},{"type":"choice","q":"You ___ to see a doctor about that cough.","uk":"Тобі слід показатися лікарю з цим кашлем.","opts":["ought","should","had better"],"a":0,"why":"Перед to підходить лише ought: ought to see. Після should і had better to не ставлять (should see, had better see)."},{"type":"choice","q":"It's going to rain. We'd better ___ the tools in the van.","uk":"Скоро піде дощ. Нам краще покласти інструменти у фургон.","opts":["put","to put","putting"],"a":0,"why":"Після had better ('d better) — початкова форма дієслова без to."},{"type":"choice","q":"Look at the time! We ___ go, or we'll miss the train.","uk":"Глянь, котра година! Нам краще йти, бо запізнимося на потяг.","opts":["had better","had better to","have better"],"a":0,"why":"Вираз завжди had better (скорочено 'd better), навіть про теперішнє, і без to перед дієсловом."},{"type":"input","q":"I don't think you ___ (should) buy that car. It's too old.","uk":"Не думаю, що тобі варто купувати цю машину. Вона надто стара.","a":["should","ought to"],"why":"«Не» вже стоїть у I don't think, тому далі should без not: I don't think you should…"},{"type":"input","q":"You'd better ___ (not / be) late again.","uk":"Краще тобі більше не запізнюватися.","a":["not be"],"why":"Заперечення — 'd better not + дієслово. Ні to, ні don't тут не потрібні."},{"type":"input","q":"I ___ (should / call) you yesterday. Sorry.","uk":"Треба було тобі вчора подзвонити. Вибач.","a":["should have called","should've called"],"why":"«Треба було» (а ти не зробив) — should have + V3: should have called."},{"type":"order","uk":"Куди мені поставити ці коробки?","words":["should","where","I","put","these","boxes"],"a":["Where should I put these boxes?"],"why":"Питальне слово + should + підмет + дієслово: Where should I put…?"},{"type":"order","uk":"Нам уже слід іти.","words":["leave","ought","we","to","now"],"a":["We ought to leave now."],"why":"Ought завжди з to: ought to + дієслово."},{"type":"order","uk":"Думаю, тобі варто поговорити з босом.","words":["think","you","I","talk","should","to","the","boss"],"a":["I think you should talk to the boss.","You should talk to the boss, I think."],"why":"I think + you should + дієслово. Should стоїть між підметом (you) і дієсловом (talk)."}],"section":"modals"},"might-must-cant":{"id":"might-must-cant","level":"B1","title":"Might, may, must, can't: how sure you are","uk":"Наскільки ти впевнений: might, must, can't","summary":"здогадки: he might be late, you must be tired, it can't be Tom","minutes":8,"blocks":[{"t":"p","text":"Коли ти не знаєш чогось напевно, а лише **здогадуєшся**, в англійській для кожного рівня впевненості є своє слово: **might** (можливо), **must** (напевно, майже точно), **can't** (не може бути). Це **модальні дієслова** — короткі слова, які стоять перед іншим дієсловом і додають до нього відтінок: можливість, обов'язок, упевненість."},{"t":"h","text":"Шкала впевненості"},{"t":"table","head":["Наскільки впевнений","Англійською","Українською"],"rows":[["100%: так","He **is** at home.","Він удома."],["майже точно так","He **must** be at home.","Він, мабуть, удома."],["50 на 50","He **might** be at home.","Може, він удома."],["майже точно ні","He **can't** be at home.","Не може бути, щоб він був удома."],["100%: ні","He **isn't** at home.","Його немає вдома."]]},{"t":"p","text":"**Is** та **isn't** — це факт: ти знаєш точно. **Must** і **can't** — ти сам не бачив, але маєш причину бути **майже впевненим**. **Might** — лише один з можливих варіантів, 50 на 50."},{"t":"h","text":"Might, may, could — можливо"},{"t":"rule","title":"Можливо","lines":["might / may / could + початкова форма дієслова","He **might be** late. It **may rain**."]},{"t":"p","text":"Усі три означають «можливо», «може бути». У розмові найчастіше чути **might**, **may** звучить трохи офіційніше, а **could** — коли називаєш один з можливих варіантів. Після них іде **початкова форма дієслова** — та, що в словнику (be, go, know): без to і без -s навіть з he, she, it. He might **be**, а не He mights be."},{"t":"ex","items":[["Tom **might be** late. There's a lot of traffic.","Том, можливо, запізниться: на дорогах великі затори."],["I **might go** to Dublin at the weekend.","Можливо, я поїду до Дубліна на вихідних."],["Take a jacket. It **may rain** later.","Візьми куртку. Пізніше може піти дощ."],["Where are the keys? — They **could be** in the van.","Де ключі? — Може, у фургоні."]]},{"t":"rule","title":"Можливо, ні","lines":["might not / may not + початкова форма дієслова"]},{"t":"ex","items":[["He **might not know** about the meeting.","Він, можливо, не знає про нараду."],["The shop **may not be** open on Sunday.","Магазин у неділю, можливо, не працює."]]},{"t":"tip","text":"«Можливо, ні» — це лише **might not** або **may not**. **Couldn't** у здогадках означає інше: «не може бути», як can't."},{"t":"h","text":"Must — мабуть, точно так"},{"t":"p","text":"Ти вже знаєш must у значенні «мусиш»: You must wear a helmet. Але в здогадках must означає «мабуть», «напевно», «очевидно»: ти не знаєш цього точно, а **робиш висновок** з того, що бачиш чи чуєш. Найчастіше так кажуть **must be**."},{"t":"ex","items":[["You **must be** tired after twelve hours on site.","Ти, мабуть, утомився після дванадцяти годин на об'єкті."],["The lights are on. Someone **must be** in the office.","Світло горить. Мабуть, в офісі хтось є."],["Kate is from Dublin, so she **must know** the city well.","Кейт з Дубліна, тож вона, напевно, добре знає місто."],["That van **must cost** a fortune.","Цей фургон, напевно, коштує шалених грошей."]]},{"t":"rule","title":"Що відбувається саме зараз","lines":["must / might / can't + be + форма з -ing","(форма з -ing: driving, working, sleeping)"]},{"t":"ex","items":[["Mick isn't answering. He **must be driving**.","Мік не відповідає. Мабуть, він за кермом."],["Don't call Sarah now. She **might be sleeping**.","Не телефонуй зараз Сарі: вона, може, спить."]]},{"t":"h","text":"Can't — не може бути"},{"t":"p","text":"Коли ти майже впевнений, що **ні**, кажи **can't** (повна форма cannot) — майже дослівно як українське «не може бути». А от **mustn't** тут не підходить: воно означає заборону, «не можна» (You mustn't smoke here)."},{"t":"ex","items":[["That **can't be** Tom. He's in Poland this week.","Це не може бути Том: він цього тижня в Польщі."],["You **can't be** hungry. You've just had lunch.","Не може бути, щоб ти зголоднів: ти ж щойно пообідав."],["This **can't be** the right address. It's an empty field.","Це не може бути правильна адреса: тут порожнє поле."],["Twenty euro for a coffee? That **can't be** right.","Двадцять євро за каву? Не може бути."]]},{"t":"h","text":"Can чи might?"},{"t":"p","text":"**Can be** у ствердженні означає «буває», «іноді таке трапляється» — загалом, а не в конкретний момент. Для здогадки про конкретну ситуацію (зараз, сьогодні, завтра) бери **might**, **may** або **could**. А от **can't** («не може бути») для здогадок підходить."},{"t":"ex","items":[["Wexford **can be** very windy in winter.","У Вексфорді взимку буває дуже вітряно."],["Someone's at the door. It **might be** Tom.","Хтось біля дверей. Може, це Том."]]},{"t":"h","text":"Здогадки про минуле"},{"t":"rule","title":"Модальне дієслово + have + V3","lines":["**must have** + V3 — мабуть, так і було","**might / may / could have** + V3 — можливо, було","**can't / couldn't have** + V3 — не може бути, щоб було"]},{"t":"p","text":"**V3** — третя форма дієслова: gone, left, seen, finished. Після модального дієслова **завжди have**, навіть з he, she, it: He must **have** gone. У швидкій розмові have звучить коротко, тому інколи пишуть must've, might've."},{"t":"ex","items":[["His van is gone. He **must have left** already.","Його фургона немає. Мабуть, він уже поїхав."],["The ground is wet. It **must have rained** last night.","Земля мокра. Мабуть, уночі йшов дощ."],["Where's the ladder? — Tom **may have taken** it.","Де драбина? — Може, її взяв Том."],["I **might have left** my keys in the van.","Може, я залишив ключі у фургоні."],["Andrii **can't have finished** the whole wall. He only started an hour ago.","Не може бути, щоб Андрій закінчив усю стіну: він почав лише годину тому."]]},{"t":"h","text":"Питання"},{"t":"p","text":"У питаннях-здогадках must і can't майже не вживають. Коли питаєш про можливу причину чи варіант, починай з **Could …?** або кажи простіше: **Do you think …?** (Як думаєш…?)"},{"t":"ex","items":[["**Could** he **be** stuck in traffic?","Може, він застряг у заторі?"],["**Do you think** he's still at work?","Як думаєш, він ще на роботі?"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"He mustn't be at home. His car isn't here.","right":"He can't be at home. His car isn't here.","why":"Mustn't — це заборона, «не можна». Коли впевнений, що ні, кажи can't."},{"t":"mistake","wrong":"Someone's at the door. It can be Tom.","right":"Someone's at the door. It might be Tom.","why":"Для здогадки про конкретний момент — might, may або could. Can be означає «буває взагалі»."},{"t":"mistake","wrong":"He must to be at work.","right":"He must be at work.","why":"Після must, might, may, can't — початкова форма дієслова без to."},{"t":"mistake","wrong":"He must has gone home.","right":"He must have gone home.","why":"Модальне дієслово не змінюється, а після нього завжди have, навіть з he, she, it."}],"tasks":[{"type":"choice","q":"Sarah's been working since six. She ___ be hungry.","uk":"Сара працює з шостої ранку. Вона, мабуть, зголодніла.","opts":["must","can't","mustn't"],"a":0,"why":"Ти робиш висновок з фактів і майже впевнений, що так, тому must. Can't — «не може бути», а mustn't — заборона."},{"type":"choice","q":"That ___ be Andrii's car. He sold it last month.","uk":"Це не може бути машина Андрія: він продав її минулого місяця.","opts":["must","can't","mustn't"],"a":1,"why":"Ти впевнений, що ні, тому can't. Mustn't означає заборону («не можна») і для здогадок не підходить."},{"type":"choice","q":"I'm not sure where Mick is. He ___ be at lunch.","uk":"Не знаю, де Мік. Може, він на обіді.","opts":["must","could","can't"],"a":1,"why":"«Не знаю, може» — це 50 на 50, тому could (так само might або may). Must і can't — коли ти майже впевнений."},{"type":"choice","q":"Don't wait for me. I ___ be late tonight.","uk":"Не чекай на мене. Можливо, я сьогодні запізнюся.","opts":["can","might","must"],"a":1,"why":"Здогадка про конкретний вечір — might. Can be означає «буває взагалі», а must означало б, що ти майже впевнений."},{"type":"input","q":"Olena ___ be at work. I've just seen her in Lidl.","uk":"Олена не може бути на роботі: я щойно бачив її в Lidl.","a":["can't","couldn't"],"why":"Ти впевнений, що ні (щойно бачив її в магазині), тому can't. Не mustn't: це заборона."},{"type":"order","uk":"Він, можливо, сьогодні не прийде.","words":["come","might","today","he","not"],"a":["He might not come today.","Today he might not come."],"why":"«Можливо, ні» — might not + початкова форма дієслова. Not стоїть одразу після might."},{"type":"input","q":"Kate isn't answering. She ___ (might / talk) to a customer right now.","uk":"Кейт не відповідає. Може, вона саме зараз розмовляє з клієнтом.","a":["might be talking"],"why":"Здогадка про те, що відбувається саме зараз: might + be + форма з -ing."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Він, мабуть, забув.","opts":["He must has forgotten.","He must have forgotten.","He must to have forgotten."],"a":1,"why":"Про минуле: must have + V3. Після must завжди have (навіть з he) і без to."},{"type":"input","q":"The door's locked. Everyone ___ (must / go) home.","uk":"Двері замкнені. Мабуть, усі пішли додому.","a":["must have gone"],"why":"Висновок про минуле: must have + V3. Go — неправильне дієслово: go, went, gone."},{"type":"input","q":"I can't find my keys. I ___ (might / put) them in my other jacket.","uk":"Не можу знайти ключі. Може, я поклав їх в іншу куртку.","a":["might have put"],"why":"«Можливо, так було» — might have + V3. Put має однакові форми: put, put, put."},{"type":"input","q":"Tom ___ (can't / see) my message. His phone's been off all day.","uk":"Не може бути, щоб Том бачив моє повідомлення: його телефон увесь день вимкнений.","a":["can't have seen","couldn't have seen"],"why":"Впевнений, що ні, про минуле: can't have + V3. See — неправильне дієслово: see, saw, seen."},{"type":"order","uk":"Може, це неправильна адреса?","words":["be","address","could","the","it","wrong"],"a":["Could it be the wrong address?"],"why":"У питанні-здогадці could стоїть на початку, далі it і початкова форма be."}],"section":"modals"},"requests-offers":{"id":"requests-offers","level":"A2","title":"Requests, offers and suggestions","uk":"Ввічливі прохання й пропозиції","summary":"Could you…? Shall I…? Let's…: просимо й пропонуємо ввічливо","minutes":7,"blocks":[{"t":"p","text":"Українською «Дай дриль» між колегами звучить нормально. Англійською Give me the drill звучить **різко**, як наказ. Англомовні люди майже завжди «загортають» прохання в питання або хоча б додають please. На роботі з англомовним босом і колегами це важливо: від цього залежить, як тебе сприймають."},{"t":"table","head":["Як звучить","Як сказати"],"rows":[["як наказ","Give me the drill."],["нормально","Pass me the drill, please."],["ввічливо","Can you pass me the drill?"],["дуже ввічливо","Could you pass me the drill?"]]},{"t":"h","text":"Прохання: Can you…? Could you…?"},{"t":"p","text":"Найпростіше — **Can you** + початкова форма дієслова (pass, help)? Ввічливіше й м'якше — **Could you**…? Тут could — не минулий час, а ввічлива форма. **Please** ставлять у кінці, одразу після you (Could you **please**…?) або на початку: **Please** could you…?"},{"t":"ex","items":[["**Can you** hold this for a second?","Можеш секунду це потримати?"],["**Could you** pass me the drill, please?","Можеш, будь ласка, передати мені дриль?"],["**Could you** say that again, please?","Можете, будь ласка, повторити?"],["**Could you** send me the address?","Можете надіслати мені адресу?"]]},{"t":"h","text":"Дуже ввічливо: Would you mind + -ing?"},{"t":"p","text":"**Would you mind** + **форма з -ing** (opening, waiting) — дуже ввічливе прохання, дослівно «Ви не заперечували б…?». Після mind дієслово завжди з -ing, ніколи не з to."},{"t":"ex","items":[["**Would you mind opening** the window?","Ви не могли б відчинити вікно?"],["**Would you mind moving** your car?","Ви не могли б переставити машину?"]]},{"t":"tip","text":"Пастка з відповіддю: mind означає «заперечувати», тож «так, звісно» на Would you mind…? — це **Not at all.** або **Of course not.** («Ні, не заперечую»). Yes тут означало б «так, я проти». У розмові часто кажуть просто **Sure** або **No problem** — і роблять."},{"t":"h","text":"Дозвіл: Can I…? Do you mind if I…?"},{"t":"p","text":"Попросити дозволу: **Can I**…? (просто), **Could I**…? (ввічливіше), **Do you mind if I**…? («Ти не проти, якщо я…?»). Після if I — звичайна форма дієслова, як у Present Simple: Do you mind if I **open** the window?"},{"t":"ex","items":[["**Can I** use your charger?","Можна взяти твою зарядку?"],["**Could I** have a glass of water, please?","Можна мені склянку води, будь ласка?"],["**Do you mind if I** leave a bit early today?","Ви не проти, якщо я сьогодні піду трохи раніше?"]]},{"t":"h","text":"Пропонуємо допомогу: Shall I…? I'll…"},{"t":"p","text":"Запропонувати свою допомогу: **Shall I**…? («Мені…? Може, я…?») або одразу **I'll** + дієслово («Я зроблю»). I'll тут — рішення, прийняте просто зараз. У магазині продавець питає **Can I help you?** — «Вам чимось допомогти?»"},{"t":"ex","items":[["**Shall I** carry that for you?","Допомогти тобі це донести?"],["It's cold in here. **Shall I** close the window?","Тут холодно. Зачинити вікно?"],["Don't worry, **I'll** clean up.","Не хвилюйся, я приберу."],["**I'll** give you a lift to the station.","Я підвезу тебе до вокзалу."],["**Can I** help you? — No, thanks. I'm just looking.","Вам чимось допомогти? — Ні, дякую. Я просто дивлюся."]]},{"t":"tip","text":"В Ірландії замість Shall I…? часто кажуть **Will I…?**: Will I put the kettle on? — «Поставити чайник?». Це місцева особливість: розумій її, а сам можеш казати Shall I…?"},{"t":"h","text":"Would you like…? — пригощаємо й запрошуємо"},{"t":"p","text":"Щоб запропонувати щось (чай, їжу) або запросити, кажи **Would you like** + іменник або **to** + дієслово. **Do you want…?** граматично правильне, але звучить простіше й прямолінійніше. Так кажуть друзям і рідним, а з незнайомими, клієнтами, босом краще Would you like…?"},{"t":"ex","items":[["**Would you like** a cup of tea?","Хочете чашку чаю?"],["**Would you like to** join us for lunch?","Не хочеш пообідати з нами?"],["**Do you want** a coffee, Mick?","Каву будеш, Міку?"]]},{"t":"tip","text":"Відповідай **Yes, please.** або **No, thanks.**, а не голим Yes чи No. І не плутай: **Would you like…?** — «хочеш (зараз)?», а **Do you like…?** — «тобі подобається (взагалі)?»."},{"t":"h","text":"Пропонуємо разом: Let's…, Why don't we…?"},{"t":"p","text":"Запропонувати зробити щось **разом** можна кількома способами. Головне — запам'ятати, яка форма дієслова йде після виразу:"},{"t":"table","head":["Вираз","Що далі","Приклад"],"rows":[["Let's…","початкова форма","Let's **go**."],["Let's not…","початкова форма","Let's **not wait**."],["Shall we…?","початкова форма","Shall we **start**?"],["Why don't we…?","початкова форма","Why don't we **ask** Tom?"],["How about…?","форма з -ing","How about **going** out?"]]},{"t":"ex","items":[["**Let's** take a break.","Зробімо перерву."],["**Let's not** start until the plaster's dry.","Давай не починати, поки штукатурка не висохне."],["**Shall we** start? It's nine already.","Почнемо? Уже дев'ята."],["**Why don't we** get a pizza tonight?","Може, візьмемо сьогодні піцу?"],["**How about going** to the beach on Sunday?","Як щодо того, щоб у неділю поїхати на пляж?"]]},{"t":"h","text":"Як відповідати"},{"t":"list","items":["Погодитися: **Sure.** / **No problem.** / **Of course.** / **Good idea.**","Ввічливо відмовити: **I'm afraid I can't.** / **Sorry, I can't right now.**","На **Would you mind…?**: **Not at all.** / **Of course not.** А на **Do you mind if I…?**: **No, go ahead.** («Ні, будь ласка»)","На **Would you like…?** і **Shall I…?**: **Yes, please.** / **No, thanks.**"]},{"t":"tip","text":"**I'm afraid** у відповіді — не «я боюся», а м'яке «на жаль»: I'm afraid I can't come tomorrow. — На жаль, я не зможу завтра прийти."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Would you mind to help me?","right":"Would you mind helping me?","why":"Після mind — форма з -ing, без to."},{"t":"mistake","wrong":"Can you to open the door?","right":"Can you open the door?","why":"Після can і could дієслово без to."},{"t":"mistake","wrong":"How about go to the pub?","right":"How about going to the pub?","why":"Після How about — форма з -ing."},{"t":"mistake","wrong":"Let's to start.","right":"Let's start.","why":"Після let's — початкова форма дієслова без to."},{"t":"tip","text":"Не помилка, а стиль: **Do you want a tea?** граматично правильне, і друзям так кажуть постійно. Але незнайомій людині, клієнтові чи босові краще: **Would you like a cup of tea?** Так само з проханнями: голе Give me… звучить як наказ, а Could you…? — нормально."}],"tasks":[{"type":"choice","q":"___ you pass me that hammer, please?","uk":"Можеш, будь ласка, передати мені той молоток?","opts":["Could","Do","Shall"],"a":0,"why":"Прохання будуємо з could або can: Could you…? Do you pass…? і Shall you pass…? так не просять."},{"type":"choice","q":"Would you mind ___ the door?","uk":"Ви не могли б зачинити двері?","opts":["closing","to close","close"],"a":0,"why":"Після Would you mind — форма з -ing: closing."},{"type":"choice","q":"It's heavy. ___ I help you with it?","uk":"Воно важке. Може, тобі допомогти?","opts":["Shall","Do","Would"],"a":0,"why":"Пропонуємо допомогу — Shall I…? (або Can I…?). Do I help… і Would I help… так не пропонують."},{"type":"choice","q":"Why don't we ___ the bus? It's cheaper.","uk":"Може, поїдемо автобусом? Так дешевше.","opts":["take","taking","to take"],"a":0,"why":"Після Why don't we — початкова форма дієслова: take. Форма з -ing — після How about."},{"type":"choice","q":"Would you mind waiting a minute? — ___","uk":"Ви не проти хвилинку зачекати? — Ні, звісно, не проти.","opts":["Not at all.","Yes, I would.","Yes, I mind."],"a":0,"why":"Mind — «заперечувати». Not at all = «зовсім не заперечую», тобто «так, зачекаю». Yes, I would означало б «так, я проти»."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Хочете чогось випити?","opts":["Would you like something to drink?","Would you like drink something?","Do you like something to drink?"],"a":0,"why":"Пропонуємо — Would you like + іменник або to + дієслово. Do you like означає «тобі подобається (взагалі)»."},{"type":"input","q":"Do you mind ___ I sit here?","uk":"Ви не проти, якщо я тут сяду?","a":["if"],"why":"Попросити дозволу — Do you mind if I + дієслово (як у Present Simple)."},{"type":"input","q":"How about ___ (watch) a film tonight?","uk":"Як щодо того, щоб сьогодні подивитися фільм?","a":["watching"],"why":"Після How about — форма з -ing: watching."},{"type":"input","q":"Let's ___ (not / tell) him yet.","uk":"Давай поки не будемо йому казати.","a":["not tell"],"why":"Заперечення з let's — let's not + початкова форма. Ні to, ні don't тут не потрібні."},{"type":"input","q":"The phone's ringing. ___ (I / get) it.","uk":"Телефон дзвонить. Я візьму.","a":["I'll get","I will get"],"why":"Пропонуємо зробити щось просто зараз, рішення щойно прийняте — I'll + дієслово: I'll get it."},{"type":"order","uk":"Можете, будь ласка, говорити повільніше?","words":["you","could","more","speak","slowly","please"],"a":["Could you speak more slowly, please?","Could you please speak more slowly?","Please could you speak more slowly?"],"why":"Ввічливе прохання: Could you + дієслово. Please — у кінці, одразу після you або на самому початку."},{"type":"order","uk":"Ти не проти, якщо я відчиню вікно?","words":["mind","you","do","if","I","open","the","window"],"a":["Do you mind if I open the window?"],"why":"Дозвіл: Do you mind + if I + дієслово в Present Simple (open, без -ing)."}],"section":"modals"},"adjectives-adverbs":{"id":"adjectives-adverbs","level":"A2","title":"Adjectives and adverbs","uk":"Прикметники і прислівники","summary":"a careful worker, he works carefully; good і well, bored і boring","minutes":8,"blocks":[{"t":"p","text":"**Прикметник** відповідає на питання «який?» і описує людину або річ: a **careful** worker — акуратний працівник. **Прислівник** відповідає на «як?» і описує дію: he works **carefully** — працює акуратно. В українській з «акуратний» робимо «акуратно», а в англійській до прикметника зазвичай додаємо **-ly**."},{"t":"rule","title":"Головне правило","lines":["прикметник + іменник: a **quick** job","дієслово + прислівник: work **quickly**"]},{"t":"ex","items":[["He's a **careful** worker.","Він акуратний працівник."],["He works **carefully**.","Він працює акуратно."],["It was a **quick** job.","Це була швидка робота."],["We did it **quickly**.","Ми зробили її швидко."]]},{"t":"tip","text":"Прислівник зазвичай стоїть **після дієслова** або після того, на що спрямована дія: He speaks English **well**. He did the job **quickly**. А не He speaks well English."},{"t":"h","text":"Як утворити прислівник"},{"t":"table","head":["Прикметник","Що робимо","Приклад"],"rows":[["більшість","+ ly","slow → slow**ly**"],["на -e","залишаємо e, + ly","nice → nice**ly**"],["на -y","y → i, + ly","easy → eas**ily**"],["на -le","e → y","gentle → gent**ly**"],["на -l (-ful)","+ ly, виходить -lly","careful → careful**ly**"],["на -ic","+ ally","basic → basic**ally**"]]},{"t":"ex","items":[["We found the house **easily**.","Ми легко знайшли будинок."],["Close the door **gently**, please.","Зачини двері тихенько, будь ласка."],["**Luckily**, nobody was hurt.","На щастя, ніхто не постраждав."],["**Basically**, the job is finished.","По суті, роботу закінчено."]]},{"t":"tip","text":"Обережно: **friendly**, **lovely**, **lonely** — це прикметники, хоч і закінчуються на -ly: a **friendly** boss. Прислівника від них немає, тому кажуть in a friendly way."},{"t":"h","text":"Без -ly: good → well, fast, hard"},{"t":"p","text":"Деякі прислівники утворюються не за правилом. Найважливіший: **good → well** (добре). А **fast, hard, late, early** однакові і для прикметника, і для прислівника."},{"t":"table","head":["Прикметник","Прислівник","Приклад"],"rows":[["good","**well**","He works **well**."],["fast","**fast**","She drives **fast**."],["hard","**hard**","We work **hard**."],["late","**late**","The bus came **late**."],["early","**early**","I get up **early**."]]},{"t":"ex","items":[["Mick is a **good** plasterer. He works really **well**.","Мік — хороший штукатур. Він дуже добре працює."],["Tom drives too **fast**.","Том їздить надто швидко."],["We worked **hard** all week.","Ми цілий тиждень важко працювали."],["I start **early** and finish **late**.","Я рано починаю і пізно закінчую."]]},{"t":"tip","text":"**Well** буває і прикметником у значенні «здоровий»: I don't feel **well** — мені недобре, я погано почуваюся."},{"t":"h","text":"Пастки: hardly і lately"},{"t":"p","text":"Hard і late мають «двійників» з -ly, але значення в них зовсім інше: **hardly** — «майже не», **lately** — «останнім часом». Тому «важко працює» — works **hard**, а «пізно прийшов» — came **late**."},{"t":"ex","items":[["He works **hard**.","Він старанно працює."],["He **hardly** works.","Він майже не працює."],["I can **hardly** hear you.","Я тебе майже не чую."],["Have you seen Tom **lately**?","Ти бачив Тома останнім часом?"]]},{"t":"h","text":"Після look, feel, sound — прикметник"},{"t":"p","text":"Деякі дієслова описують не дію, а **стан** або **враження**: be, look (виглядати), feel (почуватися), seem (здаватися), sound (звучати), taste (мати смак), smell (пахнути), get (ставати). Після них ставимо **прикметник**, бо він описує саму людину чи річ. В українській тут часто «-о» («звучить добре»), а в англійській прикметник: sounds **good**."},{"t":"ex","items":[["You **look tired**.","Вигляд у тебе втомлений."],["That **sounds good**.","Звучить добре."],["This soup **tastes great**.","Цей суп дуже смачний."],["The paint **smells awful**.","Фарба жахливо пахне."],["It's **getting cold**.","Стає холодно."]]},{"t":"tip","text":"Порівняй: He **looks angry** — у нього сердитий вигляд (прикметник, бо це про нього). He **looked at me angrily** — він сердито на мене подивився (прислівник, бо це про дію)."},{"t":"h","text":"-ed чи -ing: bored чи boring"},{"t":"p","text":"Прикметники на **-ed** кажуть, що **людина відчуває**: I'm bored — мені нудно. На **-ing** — що **викликає** це відчуття: the job is boring — робота нудна. Обережно: I'm boring означає «я нудна людина»."},{"t":"table","head":["-ed: що я відчуваю","-ing: яке воно"],"rows":[["bored — мені нудно","boring — нудний"],["tired — я втомився","tiring — виснажливий"],["interested — мені цікаво","interesting — цікавий"],["confused — я заплутався","confusing — заплутаний"],["surprised — я здивований","surprising — несподіваний"],["excited — я в захваті","exciting — захопливий"]]},{"t":"ex","items":[["I'm **tired**. It was a **tiring** day.","Я втомився. Це був виснажливий день."],["Are you **interested** in football?","Тебе цікавить футбол?"],["The film was really **interesting**.","Фільм був дуже цікавий."],["These instructions are **confusing**. I'm totally **confused**.","Ця інструкція заплутана. Я зовсім заплутався."]]},{"t":"h","text":"Кілька прикметників поспіль"},{"t":"p","text":"Прикметник стоїть **перед** іменником, як і в українській: a red car. Він ніколи не змінюється: one big van, two big vans (не bigs). Якщо прикметників кілька, природний порядок такий:"},{"t":"rule","title":"Порядок","lines":["думка → розмір → вік → колір → матеріал → іменник","a **nice big old white** van"]},{"t":"ex","items":[["He drives a **nice big old white** van.","Він їздить на гарному великому старому білому фургоні."],["We need a **long metal** ladder.","Нам потрібна довга металева драбина."],["She's got a **lovely little** dog.","У неї чудовий маленький песик."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"He works very good.","right":"He works very well.","why":"Як працює — це про дію, тому прислівник well. Good ставимо перед іменником (a good worker) або після be (The job is good)."},{"t":"mistake","wrong":"I'm boring at work.","right":"I'm bored at work.","why":"Bored — тобі нудно. I'm boring означає «я нудна людина»."},{"t":"mistake","wrong":"Drive careful!","right":"Drive carefully!","why":"Як їхати — це про дію, тому прислівник з -ly."},{"t":"mistake","wrong":"I feel badly today.","right":"I feel bad today.","why":"Після feel, look, sound ставимо прикметник: feel bad, feel tired, feel good."},{"t":"mistake","wrong":"He's got a car red.","right":"He's got a red car.","why":"Прикметник завжди стоїть перед іменником, як і в українській."}],"tasks":[{"type":"choice","q":"Mick is a very ___ driver.","uk":"Мік — дуже обережний водій.","opts":["careful","carefully"],"a":0,"why":"Driver — іменник (хто?), а іменник описуємо прикметником: a careful driver."},{"type":"choice","q":"He did the job really ___.","uk":"Він дуже добре зробив роботу.","opts":["good","well"],"a":1,"why":"Як зробив — це про дію, тому прислівник well. Good описує іменник: a good job."},{"type":"choice","q":"The meeting was really ___.","uk":"Нарада була дуже нудна.","opts":["bored","boring"],"a":1,"why":"Нарада викликає нудьгу — прикметник на -ing. Bored — про людину, якій нудно."},{"type":"choice","q":"Your plan sounds ___.","uk":"Твій план звучить добре.","opts":["good","well"],"a":0,"why":"Після sound (як і після look, feel, seem) ставимо прикметник: sounds good."},{"type":"choice","q":"He ___ works. He's always on his phone.","uk":"Він майже не працює: весь час сидить у телефоні.","opts":["hard","hardly"],"a":1,"why":"Hardly — «майже не». Hard — «старанно, важко»: He works hard."},{"type":"input","q":"The boss explained everything very ___ (clear).","uk":"Бос усе дуже зрозуміло пояснив.","a":["clearly"],"why":"Як пояснив — це про дію, тому прислівник: clear + -ly."},{"type":"input","q":"I slept ___ (terrible) last night.","uk":"Я жахливо спав минулої ночі.","a":["terribly"],"why":"Прикметник на -le: e змінюємо на y — terrible → terribly."},{"type":"input","q":"It's raining ___ (heavy).","uk":"Іде сильний дощ.","a":["heavily"],"why":"Прикметник на -y: y → i, потім -ly — heavy → heavily."},{"type":"input","q":"I'm really ___ (interest) in history.","uk":"Мене дуже цікавить історія.","a":["interested"],"why":"Про те, що людина відчуває, — прикметник на -ed: I'm interested. Interesting — про саму історію."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Ми купили великий білий фургон.","opts":["We bought a van big white.","We bought a big white van.","We bought a white big van."],"a":1,"why":"Прикметники стоять перед іменником, і розмір іде перед кольором: a big white van."},{"type":"order","uk":"Ти сьогодні маєш утомлений вигляд.","words":["tired","look","today","you"],"a":["You look tired today.","Today you look tired."],"why":"Після look — прикметник (tired), а не прислівник. Today зазвичай ставимо в кінці."},{"type":"order","uk":"Він дуже добре говорить англійською.","words":["English","speaks","very","he","well"],"a":["He speaks English very well."],"why":"Well стоїть після дієслова і того, на що спрямована дія: speaks English very well. Між speaks і English його не ставимо."}],"section":"describe"},"comparatives":{"id":"comparatives","level":"A2","title":"Comparatives and superlatives","uk":"Ступені порівняння","summary":"порівняння: cheaper, more expensive, the best, as big as","minutes":7,"blocks":[{"t":"p","text":"Коли порівнюємо **дві** речі, беремо **вищий ступінь**: cheaper — дешевший. Коли виділяємо **одну з багатьох** — **найвищий**: the cheapest — найдешевший. Як і в українській (дешевий — дешевший — найдешевший), слово змінюється: додаємо **-er / -est** або ставимо перед ним **more / the most**."},{"t":"ex","items":[["This ladder is **cheaper than** that one.","Ця драбина дешевша за ту."],["Dublin is **bigger than** Wexford.","Дублін більший за Вексфорд."],["It's **the cheapest** shop in Gorey.","Це найдешевший магазин у Горі."],["Today is **the coldest** day of the year.","Сьогодні найхолодніший день року."]]},{"t":"h","text":"Короткі слова: -er, -est"},{"t":"rule","title":"Короткий прикметник","lines":["вищий: cheap**er** (than …)","найвищий: **the** cheap**est**"]},{"t":"p","text":"Так змінюються **короткі** прикметники: з одного складу (cheap, old, long, warm) і з двох складів на -y (easy, busy, heavy). Коли порівнюєш з чимось, після прикметника ставимо **than** — «ніж», «за». Перед найвищим ступенем майже завжди **the**."},{"t":"table","head":["Прикметник","Правило","Приклад"],"rows":[["більшість","+ er, + est","cheap → cheap**er**, cheap**est**"],["на -e","+ r, + st","nice → nice**r**, nice**st**"],["одна голосна + приголосна","подвоюємо приголосну","big → big**ger**, big**gest**"],["на -y","y → i","easy → eas**ier**, eas**iest**"]]},{"t":"ex","items":[["The bus is **cheaper**, but the train is **faster**.","Автобус дешевший, але потяг швидший."],["It's **hotter** in Spain than in Ireland.","В Іспанії спекотніше, ніж в Ірландії."],["Friday is **the busiest** day of the week.","П'ятниця — найзавантаженіший день тижня."],["Kate is **the nicest** person on the team.","Кейт — наймиліша людина в команді."]]},{"t":"h","text":"Довші слова: more, the most"},{"t":"rule","title":"Довгий прикметник","lines":["вищий: **more** expensive (than …)","найвищий: **the most** expensive"]},{"t":"p","text":"Для довших прикметників — з двох складів і більше (крім тих, що на -y): expensive, dangerous, modern, careful. Саме слово не змінюється, а перед ним ставимо **more** (більш) або **the most** (найбільш) — як у нас «більш небезпечний». Так само з прислівниками на -ly: more slowly."},{"t":"ex","items":[["This van is **more expensive than** mine.","Цей фургон дорожчий за мій."],["Working on the roof is **more dangerous**.","Працювати на даху небезпечніше."],["It's **the most comfortable** chair in the house.","Це найзручніше крісло в домі."],["Can you speak **more slowly**, please?","Можеш говорити повільніше, будь ласка?"]]},{"t":"tip","text":"Кілька слів із двох складів (**quiet**, **simple**, **narrow**, **clever**) мають обидві форми: quieter або more quiet. Обидві правильні."},{"t":"tip","text":"**More** і **-er** разом не вживаємо: або cheaper, або more expensive. More cheaper, more better — помилка."},{"t":"h","text":"Неправильні форми"},{"t":"table","head":["Звичайна","Вищий","Найвищий"],"rows":[["good (добрий)","**better**","**the best**"],["well (добре)","**better**","**the best**"],["bad (поганий)","**worse**","**the worst**"],["far (далеко)","**further**","**the furthest**"],["much, many (багато)","**more**","**the most**"],["little (мало)","**less**","**the least**"]]},{"t":"ex","items":[["I feel **better** today.","Сьогодні я почуваюся краще."],["That was **the worst** day of my life.","Це був найгірший день у моєму житті."],["This is **the best** pizza in Wexford.","Це найкраща піца у Вексфорді."],["My house is **further** from the site **than** yours.","Мій дім далі від об'єкта, ніж твій."],["I spend **less** money on food now.","Тепер я витрачаю менше грошей на їжу."]]},{"t":"tip","text":"У значенні «далі» є ще **farther**, **the farthest**, але в британській англійській частіше кажуть **further**."},{"t":"h","text":"As … as — такий самий, як"},{"t":"rule","title":"Порівняння «так само»","lines":["**as** + прикметник + **as** — такий самий, як","**not as** + прикметник + **as** — не такий, як"]},{"t":"ex","items":[["Tom is **as tall as** his dad.","Том такий самий високий, як його тато."],["The bus isn't **as fast as** the train.","Автобус не такий швидкий, як потяг."],["My new boots aren't **as good as** the old ones.","Мої нові черевики не такі хороші, як старі."]]},{"t":"tip","text":"Після as + прикметник знову **as**: as fast **as**. **Than** ставимо лише після вищого ступеня: faster **than**, more expensive **than**, better **than**."},{"t":"tip","text":"Після than і as у розмові кажуть **me, him, her, us**: He's taller **than me**. He's as fast **as me**. Можна й повніше: than I am."},{"t":"h","text":"Набагато чи трохи"},{"t":"p","text":"Щоб сказати «набагато дешевший» або «трохи більший», перед вищим ступенем ставимо **much** / **a lot** / **far** (набагато, значно) або **a bit** / **a little** (трохи). **Very** тут не підходить: very cheaper — помилка."},{"t":"ex","items":[["The train is **a lot faster** than the bus.","Потяг набагато швидший за автобус."],["It's **a bit colder** today.","Сьогодні трохи холодніше."],["My new job is **far better**.","Моя нова робота значно краща."]]},{"t":"h","text":"The … the — чим …, тим …"},{"t":"rule","title":"Чим …, тим …","lines":["**the** + вищий ступінь …, **the** + вищий ступінь …"]},{"t":"ex","items":[["**The sooner, the better.**","Чим раніше, тим краще."],["**The more** you practise, **the better** you speak.","Чим більше практикуєш, тим краще говориш."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"This one is more better.","right":"This one is better.","why":"Better уже означає «кращий». More не додаємо."},{"t":"mistake","wrong":"This van is more cheap.","right":"This van is cheaper.","why":"Cheap — короткий прикметник (один склад), тому -er, а не more."},{"t":"mistake","wrong":"It's the most good café in town.","right":"It's the best café in town.","why":"Good — неправильний: good, better, the best."},{"t":"mistake","wrong":"He's as fast than me.","right":"He's as fast as me.","why":"Після as + прикметник знову as. Than — лише після вищого ступеня: faster than."},{"t":"mistake","wrong":"He is taller then me.","right":"He is taller than me.","why":"Than — «ніж», then — «потім», «тоді». Звучать схоже, але це різні слова."}],"tasks":[{"type":"choice","q":"My room is ___ than yours.","uk":"Моя кімната більша за твою.","opts":["bigger","more big","biggest"],"a":0,"why":"Порівнюємо дві кімнати, big — короткий прикметник: -er з подвоєною g. More тут не потрібне."},{"type":"choice","q":"Mick is ___ man on the site.","uk":"Мік — найстарший чоловік на об'єкті.","opts":["the oldest","the most old","older"],"a":0,"why":"Один з багатьох — найвищий ступінь. Old короткий, тому the + -est: the oldest."},{"type":"input","q":"This box is ___ (heavy) than that one.","uk":"Ця коробка важча за ту.","a":["heavier"],"why":"Прикметник на -y: y змінюємо на i і додаємо -er — heavy → heavier."},{"type":"input","q":"It was the ___ (hot) day of the summer.","uk":"Це був найспекотніший день літа.","a":["hottest"],"why":"Одна голосна + приголосна в кінці: подвоюємо t — hot → hottest."},{"type":"input","q":"It's the ___ (expensive) hotel in Wexford.","uk":"Це найдорожчий готель у Вексфорді.","a":["most expensive"],"why":"Expensive — довгий прикметник, тому the most + слово без змін."},{"type":"choice","q":"My English is ___ than it was last year.","uk":"Моя англійська краща, ніж була торік.","opts":["more good","better","more better"],"a":1,"why":"Good — неправильний: good, better, the best. More до better не додаємо."},{"type":"input","q":"The traffic is ___ (bad) today than yesterday.","uk":"Сьогодні затори гірші, ніж учора.","a":["worse"],"why":"Bad — неправильний: bad, worse, the worst."},{"type":"choice","q":"This hotel isn't as nice ___ the last one.","uk":"Цей готель не такий гарний, як попередній.","opts":["than","as","then"],"a":1,"why":"Конструкція not as … as: після as + прикметник знову as. Than — лише після вищого ступеня (nicer than)."},{"type":"choice","q":"Petrol is ___ more expensive this year.","uk":"Цього року бензин набагато дорожчий.","opts":["very","much","most"],"a":1,"why":"«Набагато» перед вищим ступенем — much (або a lot, far). Very з вищим ступенем не вживаємо."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Він вищий за мене.","opts":["He's taller then me.","He's more tall than me.","He's taller than me."],"a":2,"why":"Tall короткий, тому taller. «Ніж» — than; then означає «потім»."},{"type":"order","uk":"Новий фургон не такий великий, як старий.","words":["the","new","van","isn't","as","big","as","the","old","one"],"a":["The new van isn't as big as the old one."],"why":"Not as + прикметник + as: isn't as big as. One замінює слово van, щоб не повторювати його."},{"type":"order","uk":"Чим раніше почнемо, тим швидше закінчимо.","words":["the","earlier","we","start","the","sooner","we","finish"],"a":["The earlier we start, the sooner we finish.","The sooner we start, the earlier we finish."],"why":"«Чим …, тим …» — the + вищий ступінь на початку кожної частини: the earlier …, the sooner …"}],"section":"describe"},"too-enough-so-such":{"id":"too-enough-so-such","level":"B1","title":"Too, enough, so, such","uk":"Too, enough, so, such: занадто, досить, такий","summary":"занадто, досить, такий: too heavy, big enough, such a cold day","minutes":7,"blocks":[{"t":"p","text":"Чотири короткі слова, без яких не обходиться жодна розмова: **too** — занадто (і це проблема), **enough** — достатньо, **so** і **such** — так, такий (підсилюють). Значення прості, а помилки бувають через **місце** в реченні: що стоїть перед цим словом, а що після."},{"t":"h","text":"Too — занадто"},{"t":"rule","title":"Занадто","lines":["**too** + прикметник / прислівник: too heavy, too fast","**too much** + незлічуване: too much noise","**too many** + множина: too many people"]},{"t":"p","text":"**Too** завжди означає, що це **заважає**: занадто важке — не піднімеш. Якщо просто «дуже», кажи **very**: It's very heavy (важке, але впораємося). It's too heavy (не впораємося). **Незлічуване** — те, що не порахуєш поштучно: money, work, time, noise. Для нього **much**, а для того, що рахуємо (people, cars), — **many**."},{"t":"ex","items":[["This bag is **too heavy**. I can't lift it.","Ця сумка надто важка: я не можу її підняти."],["You're driving **too fast**. Slow down!","Ти їдеш надто швидко. Пригальмуй!"],["There's **too much** dust in here.","Тут забагато пилу."],["There are **too many** cars on the road today.","Сьогодні на дорозі забагато машин."],["I ate **too much**.","Я переїв."]]},{"t":"tip","text":"Перед прикметником — лише **too**: too cold, too expensive. **Too much** і **too many** — перед іменником (too much work) або в кінці речення (I ate too much)."},{"t":"tip","text":"Не плутай з **too** «теж» у кінці речення: I'm tired **too** — я теж утомився. Me **too**! — Я теж!"},{"t":"h","text":"Enough — достатньо"},{"t":"rule","title":"Достатньо","lines":["прикметник / прислівник + **enough**: big enough","**enough** + іменник: enough time"]},{"t":"p","text":"Головне — місце. Enough стоїть **після** прикметника чи прислівника, але **перед** іменником. В українській «достатньо» зазвичай спереду («достатньо великий», «достатньо часу»), тому тут легко помилитися. «Недостатньо» — **not enough**."},{"t":"ex","items":[["Is the van **big enough** for all the boards?","Фургон достатньо великий для всіх листів гіпсокартону?"],["He isn't **old enough** to drive.","Він ще замалий, щоб водити машину."],["We don't have **enough time**.","У нас недостатньо часу."],["Have we got **enough plasterboard**?","У нас вистачить гіпсокартону?"],["You're not speaking **loudly enough**.","Ти говориш недостатньо голосно."],["Thanks, that's **enough**.","Дякую, досить."]]},{"t":"h","text":"Too і enough + to + дієслово"},{"t":"rule","title":"Для чого занадто або достатньо","lines":["too + прикметник + **to** + дієслово","прикметник + enough + **to** + дієслово"]},{"t":"ex","items":[["It's **too cold to work** outside today.","Сьогодні надто холодно, щоб працювати надворі."],["He's **too tired to drive**.","Він надто втомлений, щоб сідати за кермо."],["The ladder isn't **long enough to reach** the roof.","Драбина недостатньо довга, щоб дістати до даху."],["This box is **too heavy for me to lift**.","Ця коробка надто важка, щоб я її підняв."]]},{"t":"tip","text":"Українське «щоб» тут — просто **to** + дієслово. А щоб сказати, для кого, додай **for** + me, him, her…: too heavy **for me** to lift. It у кінці не додаємо: to lift, а не to lift it."},{"t":"h","text":"So і such — так, такий"},{"t":"p","text":"Обидва підсилюють, як українські «так», «такий», «настільки». Різниця в тому, **що стоїть після**: після so — прикметник чи прислівник без іменника, після such — іменник (часто з прикметником перед ним)."},{"t":"rule","title":"So чи such","lines":["**so** + прикметник / прислівник: so cold, so fast","**such a** + прикметник + іменник: such a cold day","**such** + прикметник + множина: such nice people","**such** + прикметник + незлічуване: such bad weather","**so much / so many** + іменник: so much work"]},{"t":"ex","items":[["It's **so cold** today!","Сьогодні так холодно!"],["It's **such a cold day**!","Такий холодний день!"],["They're **such nice people**.","Вони такі приємні люди."],["Thanks, that's **such good news**!","Дякую, це така добра новина!"],["I've got **so much work** this week.","У мене цього тижня так багато роботи."]]},{"t":"tip","text":"Weather, work, news, advice, money — незлічувані, тому **без a**: such bad weather, such good news. З одним злічуваним предметом — **such a**: such a long day."},{"t":"h","text":"So … that, such … that — так …, що"},{"t":"rule","title":"Наслідок","lines":["**so** + прикметник + **that** …","**such (a)** + прикметник + іменник + **that** …"]},{"t":"ex","items":[["It was **so cold that** we stopped work early.","Було так холодно, що ми раніше закінчили роботу."],["It was **such a cold day that** we stopped early.","Був такий холодний день, що ми закінчили раніше."],["The music was **so loud that** I couldn't sleep.","Музика була така гучна, що я не міг заснути."]]},{"t":"tip","text":"У розмові **that** часто пропускають: It was **so hot** we went to the beach."},{"t":"h","text":"Very, too, so, enough — різниця"},{"t":"table","head":["Слово","Значення","Приклад"],"rows":[["very","дуже (просто факт)","It's **very** cold."],["too","надто (і це проблема)","It's **too** cold to work."],["so","так (з емоцією)","It's **so** cold!"],["enough","достатньо","It's warm **enough**."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"It's very much expensive.","right":"It's very expensive.","why":"Перед прикметником much не ставимо: very expensive, too expensive. Much — перед іменником (much money) або перед вищим ступенем (much cheaper)."},{"t":"mistake","wrong":"It's too much cold today.","right":"It's too cold today.","why":"Перед прикметником — просто too. Too much — лише з іменником: too much work."},{"t":"mistake","wrong":"The room isn't enough big.","right":"The room isn't big enough.","why":"Enough стоїть після прикметника, але перед іменником: big enough, enough time."},{"t":"mistake","wrong":"It's such a cold weather.","right":"It's such cold weather.","why":"Weather — незлічуване, тому без a."},{"t":"mistake","wrong":"He's so a nice guy.","right":"He's such a nice guy.","why":"Перед a + прикметник + іменник — such. So — лише перед прикметником без іменника: He's so nice."}],"tasks":[{"type":"choice","q":"The coffee is ___ hot. I can't drink it.","uk":"Кава надто гаряча: я не можу її пити.","opts":["too","too much","enough"],"a":0,"why":"Перед прикметником (hot) — просто too. Too much ставимо лише перед іменником."},{"type":"choice","q":"There are ___ people in the shop.","uk":"У магазині забагато людей.","opts":["too much","too many","too"],"a":1,"why":"People — їх можна порахувати, тому too many. Too much — для незлічуваного (too much noise)."},{"type":"choice","q":"This room isn't ___ for a party.","uk":"Ця кімната недостатньо велика для вечірки.","opts":["enough big","big enough","too big"],"a":1,"why":"Enough стоїть після прикметника: big enough. Too big означало б «завелика»."},{"type":"input","q":"Have we got ___ (enough / screws)?","uk":"У нас достатньо шурупів?","a":["enough screws"],"why":"З іменником enough стоїть спереду: enough screws, enough time."},{"type":"input","q":"Is the cable ___ (enough / long)?","uk":"Кабель достатньо довгий?","a":["long enough"],"why":"З прикметником enough стоїть після нього: long enough."},{"type":"input","q":"I'm ___ (tired) to go to the gym tonight.","uk":"Я надто втомлений, щоб іти сьогодні ввечері в спортзал.","a":["too tired"],"why":"Too + прикметник + to + дієслово: too tired to go."},{"type":"input","q":"There's ___ (much) noise in here. I can't hear you.","uk":"Тут забагато шуму. Я тебе не чую.","a":["too much"],"why":"Noise — незлічуване, тому much, а «забагато» — too much."},{"type":"choice","q":"It was ___ day!","uk":"Це був такий довгий день!","opts":["so a long","such a long","such long"],"a":1,"why":"Day — один злічуваний предмет з прикметником, тому such a long day. So перед a не ставимо."},{"type":"choice","q":"We've had ___ bad weather this week.","uk":"Цього тижня в нас така погана погода.","opts":["such a","such","so"],"a":1,"why":"Weather — незлічуване, тому such без a. So не ставимо перед прикметником з іменником."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Він говорив так швидко, що я не зрозумів.","opts":["He spoke so fast that I didn't understand.","He spoke such fast that I didn't understand.","He spoke too fast that I didn't understand."],"a":0,"why":"Перед прислівником без іменника — so, а «так …, що» — so … that. Too з that не поєднуємо."},{"type":"order","uk":"Він так утомився, що заснув.","words":["he","was","so","tired","that","he","fell","asleep"],"a":["He was so tired that he fell asleep."],"why":"So + прикметник + that + наслідок: so tired that he fell asleep."},{"type":"order","uk":"Ти так добре впорався.","words":["you","did","such","a","good","job"],"a":["You did such a good job."],"why":"Перед a + прикметник + іменник — such: such a good job."}],"section":"describe"},"quantifiers":{"id":"quantifiers","level":"A2","title":"Some, any, much, many, a few, a little","uk":"Кількість: some, any, much, many","summary":"some, any, much, many, a few, a little: скільки чогось","minutes":7,"blocks":[{"t":"p","text":"Ці слова відповідають на питання **«скільки?»**: **some** (трохи, кілька), **any** (якийсь, жодного), **much** і **many** (багато), **a few** і **a little** (кілька, трохи). Щоб вибрати правильне, постав собі два питання: **чи можна це порахувати поштучно** і **яке це речення** — ствердження, заперечення чи питання."},{"t":"h","text":"Злічувані й незлічувані"},{"t":"p","text":"**Злічувані** іменники — те, що рахуємо поштучно: a brick, two bricks, a day, ten days. Вони мають однину й множину. **Незлічувані** — речовини, маса й поняття, які поштучно не рахуємо: water, sand, plaster, time, money. Вони не мають множини і не вживаються з a/an."},{"t":"tip","text":"Запам'ятай слова, які в англійській незлічувані, хоч українською частину з них рахуємо (порада, новина) або вживаємо в множині (гроші, меблі): **money** (гроші), **advice** (порада), **information** (інформація), **news** (новини), **furniture** (меблі), **equipment** (обладнання), **work** (робота як заняття; а посада — a job, злічуване). Тому кажемо some advice (а не an advice) і the money **is** (а не are)."},{"t":"h","text":"Some і any"},{"t":"rule","title":"Головне правило","lines":["ствердження: I've got **some** nails.","заперечення: I haven't got **any** nails.","питання: Have you got **any** nails?"]},{"t":"p","text":"Some і any ставимо і з множиною (some nails), і з незлічуваними (some water). Українською ми їх часто взагалі не перекладаємо: «Купи хліба» — Buy **some** bread, «Є питання?» — **Any** questions? У ствердженні some означає «трохи, кілька», у запереченні any — «жодного, ніскільки», у питанні — «якийсь, хоч трохи»."},{"t":"tip","text":"У питанні буває **some**, коли ти щось **пропонуєш** або **просиш**, бо чекаєш відповіді «так»: Would you like **some** coffee? Can I borrow **some** money?"},{"t":"ex","items":[["We need **some** screws for the plasterboard.","Нам потрібні шурупи для гіпсокартону."],["There's **some** milk in the fridge.","У холодильнику є трохи молока."],["We haven't got **any** plaster left.","У нас не лишилося штукатурки."],["Are there **any** shops near the site?","Біля об'єкта є якісь магазини?"],["Have you got **any** questions?","У тебе є якісь питання?"],["Would you like **some** coffee?","Хочеш кави?"],["Can I borrow **some** money till Friday?","Можна позичити в тебе трохи грошей до п'ятниці?"]]},{"t":"tip","text":"У ствердженні **any** означає «будь-який»: You can take **any** van — «Можеш узяти будь-який фургон». Так само працюють **something / anything** (щось), **someone / anyone** (хтось), **somewhere / anywhere** (десь): I need **something** to eat. I didn't see **anyone**."},{"t":"h","text":"No і none: «зовсім немає»"},{"t":"p","text":"Замість not … any можна сказати **no** + іменник, а дієслово тоді стверджувальне: I haven't got **any** time = I've got **no** time. No звучить сильніше: «зовсім немає». **None** означає те саме, але стоїть **без іменника**: How many are left? — **None**. Перед the, them, us кажемо **none of**."},{"t":"tip","text":"В англійському реченні лише **одне** заперечення. Українською «я нічого не бачив» — нормально, а англійською або I didn't see **anything**, або I saw **nothing**. I didn't see nothing — помилка."},{"t":"ex","items":[["There are **no** chairs in the room.","У кімнаті немає стільців."],["I've got **no** idea.","Гадки не маю."],["How many are left? — **None**.","Скільки лишилося? — Жодного."],["**None of** them came to work today.","Ніхто з них сьогодні не прийшов на роботу."]]},{"t":"h","text":"Much, many, a lot of: «багато»"},{"t":"rule","title":"Багато","lines":["**many** + множина: many people, many tools","**much** + незлічуване: much time, much money","**a lot of** / **lots of** + будь-що: a lot of work","**plenty of** + будь-що (з запасом): plenty of time"]},{"t":"p","text":"У живій мові **much** і **many** звучать природно здебільшого в **запереченнях** і **питаннях**: I haven't got much time. Have you got many friends here? У звичайному ствердженні кажемо **a lot of** або розмовне **lots of**: We've got **a lot of** work today. «We've got much work» звучить штучно."},{"t":"ex","items":[["We've got **a lot of** work this week.","Цього тижня в нас багато роботи."],["There were **lots of** people in Lidl.","У Lidl було багато людей."],["I haven't got **much** time.","У мене небагато часу."],["There aren't **many** cars on the road today.","Сьогодні на дорозі небагато машин."],["Do you drink **much** coffee?","Ти п'єш багато кави?"],["Don't rush, we've got **plenty of** time.","Не поспішай, у нас часу вдосталь."]]},{"t":"tip","text":"Після **too** і **so** слова much і many природні й у ствердженні: There's **too much** dust here. I've got **so many** messages. А **a lot** без іменника — без of: Thanks **a lot**. I like it **a lot**."},{"t":"h","text":"How much і how many"},{"t":"p","text":"**How many** — для того, що рахуємо: how many bags, how many hours. **How much** — для незлічуваного: how much sand, how much time. І для **ціни**: How much is it? Гроші незлічувані, тому how much **money**, але how many **euros**, бо євро рахуємо."},{"t":"ex","items":[["**How many** hours do you work a week?","Скільки годин на тиждень ти працюєш?"],["**How much** sand is left?","Скільки піску лишилося?"],["**How much** is this drill?","Скільки коштує цей дриль?"]]},{"t":"h","text":"A few і a little — проти few і little"},{"t":"p","text":"**A few** (з множиною) і **a little** (з незлічуваними) — «кілька, трохи», і це звучить **позитивно**: небагато, але є. Без a: **few** і **little** — «мало, замало», звучить негативно. Одна буква a змінює настрій речення. У розмові замість few і little частіше кажуть **very few**, **very little** або not many, not much."},{"t":"ex","items":[["I've got **a few** friends in Dublin.","У мене є кілька друзів у Дубліні."],["Can you wait **a few** minutes?","Можеш почекати кілька хвилин?"],["I speak **a little** English.","Я трохи розмовляю англійською."],["Add **a little** water to the mix.","Додай у розчин трохи води."],["**Very few** people came.","Прийшло дуже мало людей."],["There's **very little** sand left.","Піску лишилося зовсім мало."]]},{"t":"h","text":"Every, each і all"},{"t":"list","items":["**every** + однина — «кожен, усі без винятку»: every day, every room","**each** + однина — «кожен окремо»: each worker, each wall","**all** + множина або незлічуване — «усі, весь»: all the tools, all the sand; а з часом — all day (весь день), all week (увесь тиждень)","після **every** і **each** дієслово в однині, як після he: every room **has**; так само everyone **is**"]},{"t":"ex","items":[["**Every** room has a window.","У кожній кімнаті є вікно."],["**Each** worker gets a key.","Кожен працівник отримує ключ."],["We worked **all** day.","Ми працювали весь день."],["**All** the tools are in the van.","Усі інструменти у фургоні."]]},{"t":"h","text":"Шпаргалка"},{"t":"table","head":["Значення","Злічувані","Незлічувані"],"rows":[["трохи, кілька","some, a few","some, a little"],["багато","many, a lot of","much, a lot of"],["скільки?","how many","how much"],["мало","few, not many","little, not much"],["зовсім немає","no, not any","no, not any"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"There are much people here.","right":"There are a lot of people here.","why":"People — множина, її рахуємо, тому much не підходить. У ствердженні найприродніше a lot of (many теж правильно, але звучить книжно)."},{"t":"mistake","wrong":"I know a little people here.","right":"I know a few people here.","why":"People рахуємо, тому a few. A little — лише з незлічуваним: a little time, a little water."},{"t":"mistake","wrong":"I don't have some money.","right":"I don't have any money.","why":"У запереченні — any. Some лише у ствердженні, проханнях і пропозиціях."},{"t":"mistake","wrong":"How many money have you got?","right":"How much money have you got?","why":"Money незлічуване, тому how much. How many — лише з множиною: how many euros."},{"t":"mistake","wrong":"There are a lot people in the shop.","right":"There are a lot of people in the shop.","why":"Перед іменником завжди a lot of. Без of — лише коли іменника після нього немає: I like it a lot."}],"tasks":[{"type":"choice","q":"There are ___ biscuits in the kitchen.","uk":"На кухні є печиво.","opts":["some","any","much"],"a":0,"why":"Це ствердження, тому some. Any тут не підходить, а much не буває з множиною (biscuits)."},{"type":"choice","q":"I haven't got ___ cash on me.","uk":"У мене немає з собою готівки.","opts":["some","any","many"],"a":1,"why":"Заперечення (haven't), тому any. Many не підходить, бо cash (готівка) незлічувана."},{"type":"choice","q":"We haven't got ___ time.","uk":"У нас небагато часу.","opts":["much","many","a few"],"a":0,"why":"Time незлічуване, тому much. Many і a few — лише для того, що рахуємо поштучно."},{"type":"input","q":"How ___ money did you spend?","uk":"Скільки грошей ти витратив?","a":["much"],"why":"Money незлічуване, хоч гроші й рахуємо, тому how much. How many було б з euros: how many euros."},{"type":"choice","q":"Can I have ___ water, please?","uk":"Можна мені води, будь ласка?","opts":["some","any","many"],"a":0,"why":"Це прохання: ти чекаєш відповіді «так», тому some, хоч це й питання. Many з незлічуваним water не вживаємо."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Сьогодні на об'єкті багато людей.","opts":["There are a lot people on the site today.","There are a lot of people on the site today.","There are much people on the site today."],"a":1,"why":"Перед іменником завжди a lot of. Much не буває з people, бо це множина."},{"type":"input","q":"We'll finish in a ___ days.","uk":"Ми закінчимо за кілька днів.","a":["few"],"why":"Days рахуємо, тому a few — «кілька». A little — лише з незлічуваним: a little time."},{"type":"choice","q":"Don't worry, we've still got ___ time.","uk":"Не хвилюйся, у нас ще є трохи часу.","opts":["a little","little","a few"],"a":0,"why":"«Трохи, але вистачить» — a little. Little без a означає «замало» і не пасує до don't worry. A few — лише зі злічуваним."},{"type":"input","q":"There's ___ milk left. Can you get some?","uk":"Молока зовсім не лишилося. Купиш?","a":["no","not any"],"why":"Дієслово стверджувальне (there's), тому «зовсім немає» — no. Те саме з not: There isn't any milk left."},{"type":"choice","q":"I wanted some cake, but there was ___ left.","uk":"Я хотів торта, але нічого не лишилося.","opts":["none","no","any"],"a":0,"why":"None стоїть сам, без іменника: «жодного, нічого». No потребує іменника (no cake), а any — заперечення з not."},{"type":"input","q":"Every worker ___ (need) a hard hat.","uk":"Кожному працівнику потрібна каска.","a":["needs"],"why":"Після every іменник в однині, а дієслово як після he: needs."},{"type":"order","uk":"Скільки мішків штукатурки нам потрібно?","words":["need","plaster","how","we","bags","many","do","of"],"a":["How many bags of plaster do we need?"],"why":"Мішки рахуємо, тому how many. Далі звичайне питання: do + we + need."}],"section":"describe"},"prepositions-time":{"id":"prepositions-time","level":"A2","title":"Prepositions of time","uk":"Прийменники часу: in, on, at","summary":"коли: at 8, on Monday, in May; for, since, until, by, ago","minutes":8,"blocks":[{"t":"p","text":"**Прийменник** — коротке слово перед іменником, яке показує зв'язок: «**о** восьмій», «**у** понеділок», «**до** п'ятниці». Для часу в англійській три головні прийменники: **at**, **on**, **in**. Вони не збігаються з українськими «о, у, в», тому запам'ятай систему: **at** — точка часу, **on** — день, **in** — довший період."},{"t":"h","text":"At — точний час і короткі моменти"},{"t":"p","text":"**At** ставимо перед годинами й моментами доби: at 7 o'clock, at half past six, at noon (опівдні), at midnight, at lunchtime. Також запам'ятай: **at night** (уночі), **at the weekend** (на вихідних; американці кажуть on the weekend), **at Christmas**, **at Easter** (на Різдво, на Великдень — свято загалом), **at the moment** (зараз)."},{"t":"ex","items":[["We start **at** half past seven.","Ми починаємо о пів на восьму."],["The shop closes **at** ten.","Магазин зачиняється о десятій."],["I can't sleep **at** night.","Я не можу спати вночі."],["Are you working **at** the weekend?","Ти працюєш на вихідних?"],["We're going home **at** Christmas.","На Різдво ми їдемо додому."]]},{"t":"h","text":"On — дні й дати"},{"t":"p","text":"**On** — коли називаємо конкретний **день**: день тижня, дату, святковий день (on Christmas Day, on my birthday). Множина on Mondays означає «щопонеділка». Дату пишемо on 5 May, а читаємо on the fifth of May."},{"t":"ex","items":[["The meeting is **on** Monday.","Нарада в понеділок."],["Mick gets paid **on** Fridays.","Міку платять щоп'ятниці."],["The inspector is coming **on** 12 March.","Інспектор приїде 12 березня."],["What are you doing **on** Christmas Day?","Що ти робиш у день Різдва?"],["See you **on** Monday morning.","Побачимося в понеділок уранці."]]},{"t":"h","text":"In — місяці, роки, пори року"},{"t":"p","text":"**In** — для довших проміжків: місяці (in May), роки (in 2024), пори року (in winter або in the winter), а ще частини дня: **in the morning**, **in the afternoon**, **in the evening**. Але вночі — **at night**."},{"t":"ex","items":[["Andrii came to Ireland **in** 2023.","Андрій приїхав до Ірландії у 2023 році."],["It rains a lot **in** November.","У листопаді часто йдуть дощі."],["The days are short **in** winter.","Узимку дні короткі."],["I go to the gym **in** the evening.","Я ходжу в спортзал увечері."]]},{"t":"tip","text":"Якщо названо конкретний день, перемагає **on**: **in** the morning, але **on** Monday morning; **at** night, але **on** Friday night."},{"t":"h","text":"Шпаргалка: at, on, in"},{"t":"table","head":["at","on","in"],"rows":[["at 7 o'clock","on Monday","in May"],["at lunchtime","on Mondays","in 2025"],["at night","on 5 May","in winter"],["at the weekend","on Friday night","in the morning"],["at Christmas","on Christmas Day","in the 1990s"]]},{"t":"h","text":"Без прийменника: next week, last year"},{"t":"p","text":"Перед **this, next, last, every** прийменник **не ставимо**: next week, last month, every day, this Saturday. Так само зі словами **today, tomorrow, yesterday, tonight**. Українською теж без прийменника («наступного тижня», «минулого року»), тож головне — не додавати at, on чи in за звичкою."},{"t":"ex","items":[["See you **next** week.","Побачимося наступного тижня."],["We worked in Gorey **last** month.","Минулого місяця ми працювали в Горі."],["Are you working **this** Saturday?","Ти працюєш цієї суботи?"],["I'll finish it **tomorrow** morning.","Я закінчу це завтра вранці."]]},{"t":"h","text":"«Через» і «тому»: in і ago"},{"t":"p","text":"**In** + проміжок часу про майбутнє означає «через»: in ten minutes — через десять хвилин, in two weeks — через два тижні. **Ago** означає «тому», вживається з минулим часом і стоїть **після** проміжку: two days **ago**, a year **ago**. Не кажи before two days — так англійці не говорять."},{"t":"ex","items":[["The bus leaves **in** five minutes.","Автобус відходить через п'ять хвилин."],["We're going on holiday **in** two weeks.","Через два тижні ми їдемо у відпустку."],["Mick bought the van two years **ago**.","Мік купив фургон два роки тому."],["She left ten minutes **ago**.","Вона пішла десять хвилин тому."]]},{"t":"h","text":"For і since: «скільки» і «з якого часу»"},{"t":"p","text":"**For** — **скільки** триває: for two hours, for a week, for three years. **Since** — **з якого моменту**: since Monday, since 8 o'clock, since 2023. Після since завжди момент у часі (день, година, рік, подія), а не проміжок."},{"t":"tip","text":"Українською кажемо в теперішньому часі: «я живу тут два роки», «вона працює тут з березня». Англійською тоді потрібен **Present Perfect** (have / has + V3, тобто третя форма дієслова): I **have lived** here **for** two years. She **has worked** here **since** March."},{"t":"ex","items":[["We waited **for** an hour.","Ми чекали годину."],["Tom worked in Dublin **for** two years.","Том два роки працював у Дубліні."],["We've known each other **for** ten years.","Ми знайомі десять років."],["Sarah has worked here **since** March.","Сара працює тут з березня."],["I've been here **since** eight o'clock.","Я тут з восьмої години."]]},{"t":"h","text":"During і while: «під час» і «поки»"},{"t":"p","text":"**During** — «під час, протягом» + **іменник** (подія або період): during the meeting, during lunch, during the night. During відповідає на питання «коли?», а не «скільки?»: тривалість — це for. **While** — «поки, у той час як» + **ціле речення** з підметом і дієсловом (підмет — хто або що виконує дію): while I was driving, while you're waiting."},{"t":"ex","items":[["Don't use your phone **during** the safety talk.","Не користуйся телефоном під час інструктажу з безпеки."],["It rained **during** the night.","Уночі йшов дощ."],["He called **while** I was driving.","Він подзвонив, поки я був за кермом."],["Can you hold the board **while** I fix it?","Можеш потримати лист, поки я його кріплю?"]]},{"t":"h","text":"Until і by: два різні «до»"},{"t":"p","text":"Українське «до п'ятої» англійською буває двома словами. **Until** (розмовне **till**) — дія **триває** весь час аж до цього моменту: I work until five — працюю аж до п'ятої. **By** — «не пізніше ніж»: дія станеться будь-коли **до** цього моменту: I'll finish by five — закінчу до п'ятої, можливо, й раніше. Межі проміжку — **from … to** або **from … until**: from Monday to Friday."},{"t":"ex","items":[["We work **until** four on Fridays.","По п'ятницях ми працюємо до четвертої."],["I'll wait **until** you're ready.","Я почекаю, доки ти не будеш готовий."],["The kitchen must be ready **by** Friday.","Кухня має бути готова до п'ятниці."],["Send me the photos **by** tonight.","Надішли мені фото до вечора."],["The shop is open **from** eight **till** ten.","Магазин працює з восьмої до десятої."]]},{"t":"tip","text":"Перевірка: якщо можна додати «весь час» — **until**. Якщо можна додати «не пізніше» — **by**. І ще: українське «доки **не** прийдеш» англійською без not: until you **come**."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I'll see you in Monday.","right":"I'll see you on Monday.","why":"Дні тижня й дати — з on (якщо перед ними немає next, last, this)."},{"t":"mistake","wrong":"I go to the gym on the morning.","right":"I go to the gym in the morning.","why":"Частини дня — in the morning, in the evening. On лише тоді, коли названо день: on Monday morning."},{"t":"mistake","wrong":"Let's meet at next week.","right":"Let's meet next week.","why":"Перед next, last, this, every прийменник не ставимо."},{"t":"mistake","wrong":"I've lived here since two years.","right":"I've lived here for two years.","why":"Два роки — це проміжок, тому for. Since — лише з моментом початку: since 2023."},{"t":"mistake","wrong":"We waited during two hours.","right":"We waited for two hours.","why":"During — «під час чогось» (during the film). Скільки тривало — for."},{"t":"mistake","wrong":"I'll be there until five.","right":"I'll be there by five.","why":"Якщо хочеш сказати «прийду не пізніше п'ятої» — by. Until five означає «буду там аж до п'ятої», тобто піду о п'ятій."}],"tasks":[{"type":"choice","q":"I usually get up ___ six o'clock.","uk":"Я зазвичай встаю о шостій.","opts":["in","on","at"],"a":2,"why":"Точний час (година) — at: at six o'clock."},{"type":"choice","q":"We're very busy ___ the summer.","uk":"Улітку в нас дуже багато роботи.","opts":["in","on","at"],"a":0,"why":"Пори року, місяці й роки — in: in the summer, in May, in 2025."},{"type":"choice","q":"See you ___ Friday morning.","uk":"Побачимося в п'ятницю вранці.","opts":["in","on","at"],"a":1,"why":"Названо конкретний день, тому on, хоч і є morning. Просто «вранці» було б in the morning."},{"type":"input","q":"He came to Ireland three years ___.","uk":"Він приїхав до Ірландії три роки тому.","a":["ago"],"why":"«Тому» — ago, і стоїть воно після проміжку часу: three years ago."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я подзвоню тобі наступного тижня.","opts":["I'll call you at next week.","I'll call you next week.","I'll call you in next week."],"a":1,"why":"Перед next, last, this, every прийменник не ставимо: next week."},{"type":"input","q":"I'll be back ___ ten minutes.","uk":"Я повернуся через десять хвилин.","a":["in"],"why":"«Через» про майбутнє — in + проміжок часу: in ten minutes."},{"type":"input","q":"We waited ___ two hours.","uk":"Ми чекали дві години.","a":["for"],"why":"Скільки тривало — for. During тут не підходить: during ставимо перед подією (during the film)."},{"type":"choice","q":"Sarah has lived in Wexford ___ 2022.","uk":"Сара живе у Вексфорді з 2022 року.","opts":["for","since","from"],"a":1,"why":"2022 — момент початку, тому since. For — з проміжком (for three years), а from без to чи until тут не вживаємо."},{"type":"choice","q":"Can you hold the ladder ___ I go up?","uk":"Можеш потримати драбину, поки я лізу нагору?","opts":["while","during","for"],"a":0,"why":"Після пропуску ціле речення (I go up), тому while. During і for стоять лише перед іменником."},{"type":"choice","q":"Please finish the bathroom ___ Friday.","uk":"Будь ласка, закінч ванну до п'ятниці.","opts":["until","by","since"],"a":1,"why":"Закінчити треба не пізніше п'ятниці — це by. Until — коли дія триває весь час до моменту (work until Friday)."},{"type":"order","uk":"Що ти робиш на вихідних?","words":["weekend","doing","the","what","you","at","are"],"a":["What are you doing at the weekend?"],"why":"У британській англійській — at the weekend. Питання: what + are + you + doing."},{"type":"order","uk":"Чекай тут, доки я не повернуся.","words":["back","until","here","I","wait","come"],"a":["Wait here until I come back."],"why":"«Доки не повернуся» — until I come back, без not. Після until про майбутнє вживаємо теперішній час (come)."}],"section":"prepositions"},"prepositions-place":{"id":"prepositions-place","level":"A2","title":"Prepositions of place and movement","uk":"Прийменники місця й руху","summary":"де і куди: in the van, on the wall, at work, into, across, go home","minutes":7,"blocks":[{"t":"p","text":"Прийменники місця відповідають на питання **«де?»**, а прийменники руху — **«куди?»** і **«звідки?»**. Головні три — **in**, **on**, **at**. Вони не збігаються з українськими «в» і «на»: «на роботі» — **at** work, «в автобусі» — **on** the bus, «на фото» — **in** the photo. Тому дивись не на українське слово, а на те, **як розташовано** людину чи предмет."},{"t":"h","text":"In — всередині"},{"t":"p","text":"**In** — всередині чогось, що має межі: кімната, коробка, машина, місто, країна. Також **in the photo** (на фото), **in bed** (у ліжку), **in the corner** (у кутку кімнати)."},{"t":"ex","items":[["The tools are **in** the van.","Інструменти у фургоні."],["She lives **in** Wexford.","Вона живе у Вексфорді."],["Who's that man **in** the photo?","Хто той чоловік на фото?"],["He's still **in** bed.","Він ще в ліжку."]]},{"t":"h","text":"On — на поверхні"},{"t":"p","text":"**On** — на поверхні, коли предмет торкається її: на стіні, на підлозі, на столі, на даху. Ще з on кажемо про **поверхи** (on the first floor), **сторону** (on the left, on the right) і про великий транспорт, де можна ходити: **on the bus**, on the train, on the plane."},{"t":"ex","items":[["There's a clock **on** the wall.","На стіні годинник."],["The plans are **on** the table.","Креслення на столі."],["The toilet is **on** the left.","Туалет ліворуч."],["Their flat is **on** the first floor.","Їхня квартира на другому поверсі."],["Tom is **on** the train to Dublin.","Том у поїзді до Дубліна."]]},{"t":"tip","text":"В Ірландії й Британії поверх на рівні землі — **ground floor**, а **first floor** — це наш другий поверх. І транспорт: **on** the bus, train, plane (великий, можна ходити), але **in** the car, van, taxi."},{"t":"h","text":"At — у точці, у закладі"},{"t":"p","text":"**At** — у певній **точці** або там, куди приходять з якоюсь метою, коли неважливо, всередині ти чи ні: at the bus stop, at the door, at the traffic lights, at the end of the street. Так само **at work**, **at home**, **at school**, **at the doctor's**, at a party, at the gym. Перед work, home і school артикля the немає."},{"t":"ex","items":[["I'll wait for you **at** the bus stop.","Я чекатиму на тебе на зупинці."],["There's someone **at** the door.","Хтось стоїть під дверима."],["Tom is **at** work.","Том на роботі."],["Are you **at** home?","Ти вдома?"],["Sarah is **at** the doctor's.","Сара в лікаря."]]},{"t":"tip","text":"В ірландській розмові часто почуєш **in work** (I'm in work till six) або **in school**. Це місцева звичка, тебе зрозуміють. Але в стандартній англійській «на роботі» — **at work** (а in work там означає «мати роботу, не бути безробітним»). У завданнях цього посібника пиши **at work**."},{"t":"h","text":"Де саме: над, під, поруч"},{"t":"table","head":["Прийменник","Значення","Приклад"],"rows":[["above / over","над","**above** the door"],["under / below","під / нижче","**under** the sink"],["next to","поруч, біля","**next to** the window"],["near","недалеко від","**near** the station"],["between","між","**between** the two houses"],["opposite","навпроти","**opposite** the church"],["behind","позаду, за","**behind** the house"],["in front of","перед","**in front of** the shop"]]},{"t":"p","text":"**Above** — просто вище: the light above the door. **Over** — прямо над, часто накриваючи: a dust sheet over the sofa. **Under** — під, **below** — нижче за рівнем: below zero, the flat below. І дрібниця, на якій часто помиляються: **near** без of (near the station), а **next to** — завжди з to."},{"t":"ex","items":[["Park **in front of** the shop.","Паркуйся перед магазином."],["There's a Lidl **opposite** the station.","Навпроти вокзалу є Lidl."],["Put the ladder **next to** the door.","Постав драбину біля дверей."],["Gorey is **between** Wexford and Dublin.","Горі розташоване між Вексфордом і Дубліном."],["Put a dust sheet **over** the sofa.","Накрий диван захисним покривалом."],["It's five degrees **below** zero.","П'ять градусів морозу."]]},{"t":"h","text":"Рух: куди і як"},{"t":"p","text":"Прийменники руху показують, **куди** або **як** рухаємося. Українською тут часто ті самі «в» і «на», а англійською — різні слова."},{"t":"table","head":["Прийменник","Значення","Приклад"],"rows":[["to","до, у, на (куди)","go **to** Dublin"],["from","з, від (звідки)","come **from** work"],["into","всередину","get **into** the van"],["out of","назовні, з","get **out of** the car"],["onto","на (поверхню)","climb **onto** the roof"],["off","з (поверхні)","get **off** the bus"],["through","крізь","walk **through** the park"],["across","через, на інший бік","walk **across** the road"],["along","уздовж","walk **along** the beach"],["up / down","вгору / вниз","go **up** the stairs"],["past","повз","drive **past** the church"]]},{"t":"tip","text":"**Through** — крізь щось об'ємне: тунель, ліс, місто, двері. **Across** — по поверхні з одного боку на інший: дорогу, міст, поле. І знову транспорт: get **into** / **out of** the car, але get **on** / **off** the bus."},{"t":"ex","items":[["Get **into** the van, it's raining.","Сідай у фургон, дощ іде."],["He fell **off** the ladder.","Він упав з драбини."],["Carry the plasterboard **up** the stairs.","Занеси гіпсокартон сходами нагору."],["We drove **through** Gorey.","Ми проїхали через Горі."],["Go **past** the church and turn right.","Проїдь повз церкву і поверни праворуч."],["Be careful when you walk **across** the road.","Будь обережний, коли переходиш дорогу."]]},{"t":"h","text":"Arrive in, arrive at і go home"},{"t":"p","text":"Після **arrive** ніколи не буває to. **Arrive in** — місто або країна: arrive in Dublin, arrive in Ireland. **Arrive at** — будівля чи конкретне місце: arrive at the airport, arrive at the site. А от **get to** — з to: What time did you get **to** work?"},{"t":"p","text":"**Home** після дієслів руху йде **без to**: go home, come home, get home. А «бути вдома» — be **at home** (або просто be home)."},{"t":"ex","items":[["Olena arrived **in** Ireland last year.","Олена приїхала до Ірландії минулого року."],["We arrived **at** the site at seven.","Ми приїхали на об'єкт о сьомій."],["What time do you get **home**?","О котрій ти приходиш додому?"],["Come **home** early tonight.","Приходь сьогодні додому раніше."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I'm going to home.","right":"I'm going home.","why":"Після go, come, get слово home йде без to."},{"t":"mistake","wrong":"We arrived to Dublin at six.","right":"We arrived in Dublin at six.","why":"Після arrive не буває to: arrive in — місто чи країна, arrive at — будівля чи місце."},{"t":"mistake","wrong":"Look at the man on the photo.","right":"Look at the man in the photo.","why":"Українською «на фото», а англійською — in the photo, in the picture: люди й речі «всередині» знімка."},{"t":"mistake","wrong":"I'm waiting in the bus stop.","right":"I'm waiting at the bus stop.","why":"Зупинка — точка, а не приміщення, тому at."},{"t":"mistake","wrong":"I'm in the bus.","right":"I'm on the bus.","why":"Автобус, поїзд, літак — on. In — для машини, фургона, таксі."}],"tasks":[{"type":"choice","q":"Don't leave your tools ___ the floor.","uk":"Не залишай інструменти на підлозі.","opts":["in","on","at"],"a":1,"why":"Предмети лежать на поверхні, тому on: on the floor, on the table."},{"type":"choice","q":"Turn left ___ the traffic lights.","uk":"На світлофорі поверни ліворуч.","opts":["in","on","at"],"a":2,"why":"Світлофор — точка на дорозі, тому at, як і at the bus stop."},{"type":"input","q":"Tom isn't here, he's ___ work.","uk":"Тома тут немає, він на роботі.","a":["at"],"why":"«На роботі» — at work, без the. In work почуєш в ірландській розмові, але стандартно — at work."},{"type":"choice","q":"Sarah is ___ the bus now.","uk":"Сара зараз їде автобусом.","opts":["in","on","at"],"a":1,"why":"Автобус, поїзд, літак — on. In — для машини, фургона, таксі."},{"type":"input","q":"You look great ___ this photo.","uk":"Ти класно виглядаєш на цьому фото.","a":["in"],"why":"Українською «на фото», а англійською in the photo: людина «всередині» знімка."},{"type":"choice","q":"When did you arrive ___ Ireland?","uk":"Коли ти приїхав до Ірландії?","opts":["to","in","at"],"a":1,"why":"Після arrive не буває to. Ірландія — країна, тому arrive in. Arrive at — будівля чи місце: at the airport."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я вже йду додому.","opts":["I'm going to home now.","I'm going home now.","I'm going at home now."],"a":1,"why":"Після go, come, get слово home йде без прийменника: go home."},{"type":"input","q":"The bathroom is ___ the kitchen and the bedroom.","uk":"Ванна кімната між кухнею і спальнею.","a":["between"],"why":"«Між» двома предметами — between: between the kitchen and the bedroom."},{"type":"choice","q":"Get ___ the car, quick!","uk":"Сідай у машину, швидше!","opts":["into","onto","at"],"a":0,"why":"Рух усередину — into. Onto — на поверхню (onto the roof), а at не показує руху."},{"type":"input","q":"Get ___ the bus at the next stop.","uk":"Вийди з автобуса на наступній зупинці.","a":["off"],"why":"З автобуса, поїзда, літака — get off. З машини — get out of the car."},{"type":"order","uk":"Фургон стоїть перед будинком.","words":["house","front","is","the","of","van","in","the"],"a":["The van is in front of the house."],"why":"«Перед» — три слова in front of, далі the house."},{"type":"order","uk":"О котрій ти приїхав на об'єкт?","words":["site","arrive","what","the","you","did","at","time"],"a":["What time did you arrive at the site?"],"why":"Об'єкт — конкретне місце, тому arrive at. Питання в минулому: what time + did + you + arrive."}],"section":"prepositions"},"conditionals-0-1":{"id":"conditionals-0-1","level":"B1","title":"Zero and first conditional","uk":"Умовні речення: якщо + реальне","summary":"факти й реальні умови: If it rains, we'll stop work.","minutes":8,"blocks":[{"t":"p","text":"**Умовне речення** має дві частини: **умову** (зі словом **if** — «якщо») і **результат** (що тоді станеться). У цій темі два типи для **реальних** ситуацій: **zero conditional** (нульовий тип) — для фактів, які правдиві завжди, і **first conditional** (перший тип) — для умови, яка цілком може здійснитися в майбутньому."},{"t":"ex","items":[["If you **mix** cement with water, it **gets** hard.","Якщо змішати цемент з водою, він твердне."],["If it **rains**, we**'ll stop** work.","Якщо піде дощ, ми припинимо роботу."]]},{"t":"h","text":"Zero conditional: те, що буває завжди"},{"t":"rule","title":"Нульовий тип","lines":["**If / When** + Present Simple, + Present Simple","If you **heat** ice, it **melts**."]},{"t":"p","text":"В обох частинах **Present Simple**. Так говоримо про закони природи, правила, інструкції й звички — про те, що відбувається **щоразу**, коли виконано умову. Тут **if** майже те саме, що **when** (коли): «щоразу, коли…»."},{"t":"ex","items":[["If you **heat** ice, it **melts**.","Якщо нагріти лід, він тане."],["If the plaster **dries** too fast, it **cracks**.","Якщо штукатурка висихає надто швидко, вона тріскається."],["When I **work** in the rain, my back **hurts**.","Коли я працюю під дощем, у мене болить спина."],["If you **don't pay** on time, the bank **charges** you a fee.","Якщо не платиш вчасно, банк бере з тебе комісію."]]},{"t":"h","text":"First conditional: реальна умова в майбутньому"},{"t":"rule","title":"Перший тип","lines":["If + **Present Simple**, **will** + дієслово","If it **rains**, we**'ll stop** work."]},{"t":"p","text":"Ідеться про **конкретну** ситуацію в майбутньому, яка цілком **може статися**. В умові — Present Simple, у результаті — **will** + початкова форма дієслова (work, go — як у словнику, без to і без закінчень). Will часто скорочують: I'll, you'll, we'll."},{"t":"ex","items":[["If the van **breaks down**, I**'ll call** you.","Якщо фургон зламається, я тобі подзвоню."],["If we **don't hurry**, we**'ll miss** the bus.","Якщо не поквапимося, то спізнимося на автобус."],["If Sarah **gets** the job, she**'ll move** to Dublin.","Якщо Сара отримає цю роботу, вона переїде в Дублін."]]},{"t":"h","text":"Головне: після if — без will"},{"t":"p","text":"Українською кажемо «якщо **піде** дощ» — майбутній час в обох частинах. Англійською в частині з **if** майбутнє передає **Present Simple**: If it **rains**, а не If it will rain. **Will** ставимо лише туди, де результат."},{"t":"table","head":["Українською","Англійською"],"rows":[["Якщо піде дощ…","If it **rains**…"],["Якщо ти закінчиш рано…","If you **finish** early…"],["Якщо він не прийде…","If he **doesn't come**…"],["…я тобі подзвоню.","…I**'ll call** you."]]},{"t":"tip","text":"Те саме правило після **when** (коли), **as soon as** (щойно), **before**, **after** і **until** (поки не): When I **get** home, I'll call you. Не when I will get. Але в питанні **When will** you finish? will потрібне: тут when — питальне слово «коли?»."},{"t":"h","text":"Заперечення і питання"},{"t":"rule","title":"Заперечення","lines":["If + **don't / doesn't** + дієслово, …","…, **won't** (will not) + дієслово"]},{"t":"rule","title":"Питання","lines":["**Will** + you / he / they + дієслово … if …?","What **will** you **do** if …?"]},{"t":"ex","items":[["If it **doesn't stop** raining, we **won't finish** the roof today.","Якщо дощ не припиниться, ми сьогодні не закінчимо дах."],["**Will** you **come** if Tom **invites** you?","Ти прийдеш, якщо Том тебе запросить?"],["What **will** you **do** if the bus **doesn't come**?","Що ти робитимеш, якщо автобус не приїде?"]]},{"t":"tip","text":"У частині з if — звичайний Present Simple з усіма його правилами: після he, she, it дієслово з **-s**, а в запереченні **doesn't**. If Tom **comes** late… If it **doesn't** stop…"},{"t":"h","text":"Порядок частин і кома"},{"t":"p","text":"Частини можна поміняти місцями — зміст не зміниться. Якщо речення **починається з if**, після умови ставимо **кому**. Якщо if посередині, кома не потрібна."},{"t":"ex","items":[["If it **rains** tomorrow, we**'ll work** inside.","Якщо завтра буде дощ, ми працюватимемо всередині."],["We**'ll work** inside if it **rains** tomorrow.","Ми працюватимемо всередині, якщо завтра буде дощ."]]},{"t":"h","text":"Unless — «якщо не»"},{"t":"p","text":"**Unless** означає «якщо не». Заперечення вже є в самому слові, тому дієслово після unless **стверджувальне**: unless you **hurry** = if you **don't hurry**."},{"t":"ex","items":[["We**'ll be** late **unless** we **leave** now.","Ми запізнимося, якщо не вийдемо зараз."],["**Unless** it **rains**, we**'ll finish** on Friday.","Якщо не буде дощу, ми закінчимо в п'ятницю."],["I **won't go unless** you **come** with me.","Я не піду, якщо ти не підеш зі мною."]]},{"t":"h","text":"Не лише will"},{"t":"p","text":"У частині з результатом замість will можуть бути **can** (можна, зможеш), **might** або **may** (можливо), **should** (варто) чи **наказ** (зроби, не роби). Частина з if лишається в Present Simple."},{"t":"ex","items":[["If you **finish** early, you **can go** home.","Якщо закінчиш раніше, можеш іти додому."],["If the weather **is** bad, the bus **might be** late.","Якщо буде погана погода, автобус може запізнитися."],["If your back **hurts**, you **should see** a doctor.","Якщо в тебе болить спина, тобі варто піти до лікаря."],["If you **see** Mick, **tell** him to call me.","Якщо побачиш Міка, скажи йому, щоб мені подзвонив."],["**Don't touch** the wall if the plaster **is** still wet.","Не торкайся стіни, якщо штукатурка ще мокра."]]},{"t":"h","text":"If чи when?"},{"t":"p","text":"**If** — може статися, а може й ні. **When** — точно станеться, питання лише коли. Як в українській: «якщо» і «коли»."},{"t":"ex","items":[["If I **see** Tom, I**'ll tell** him.","Якщо побачу Тома, скажу йому. (не знаю, чи побачу)"],["When I **see** Tom, I**'ll tell** him.","Коли побачу Тома, скажу йому. (точно побачу)"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"If it will rain, we'll stop work.","right":"If it rains, we'll stop work.","why":"Після if про майбутнє — Present Simple, а не will, хоч українською кажемо «якщо піде»."},{"t":"mistake","wrong":"If you will finish early, you can go home.","right":"If you finish early, you can go home.","why":"Will не ставимо в частину з if, навіть коли йдеться про завтра."},{"t":"mistake","wrong":"I call you if I will be free.","right":"I'll call you if I'm free.","why":"Навпаки: will — у частині з результатом (I'll call), а після if — Present Simple (I'm free)."},{"t":"mistake","wrong":"Unless you don't hurry, you'll miss the bus.","right":"Unless you hurry, you'll miss the bus.","why":"Unless уже означає «якщо не», друге заперечення зайве."},{"t":"mistake","wrong":"If Tom come late, the boss will be angry.","right":"If Tom comes late, the boss will be angry.","why":"Після if — звичайний Present Simple, тож для he, she, it дієслово з -s."}],"tasks":[{"type":"choice","q":"If you ___ ice, it melts.","uk":"Якщо нагріти лід, він тане.","opts":["heat","will heat","heated"],"a":0,"why":"Це факт, правдивий завжди (нульовий тип): в обох частинах Present Simple — heat і melts."},{"type":"choice","q":"If it ___ tomorrow, we'll work inside.","uk":"Якщо завтра буде дощ, ми працюватимемо всередині.","opts":["rains","will rain","rain"],"a":0,"why":"Після if про майбутнє — Present Simple, а не will, хоч українською «буде дощ». It — тому rains з -s."},{"type":"choice","q":"If you see Mick, ___ him to call me.","uk":"Якщо побачиш Міка, скажи йому, щоб мені подзвонив.","opts":["tell","telling","to tell"],"a":0,"why":"У частині з результатом може бути наказ: просто дієслово, без you і без to — tell."},{"type":"choice","q":"Unless you ___, you'll miss the bus.","uk":"Якщо не поквапишся, то спізнишся на автобус.","opts":["hurry","don't hurry","will hurry"],"a":0,"why":"Unless уже означає «якщо не», тому дієслово після нього стверджувальне. Unless you don't hurry — подвійне заперечення."},{"type":"choice","q":"I'm going to the shop now. ___ I get back, I'll make dinner.","uk":"Я зараз іду в магазин. Коли повернуся, приготую вечерю.","opts":["When","If","Unless"],"a":0,"why":"Ти точно повернешся, тому when (коли). If — для того, що може статися, а може й ні."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Я подзвоню тобі, якщо буду вільний.","opts":["I'll call you if I'm free.","I call you if I will be free.","I'll call you if I will be free."],"a":0,"why":"Will — у частині з результатом (I'll call), а після if — Present Simple (I'm free)."},{"type":"input","q":"If Tom ___ (be) late again, the boss will be furious.","uk":"Якщо Том знову запізниться, бос розлютиться.","a":["is"],"why":"Після if — Present Simple, а не will be. Tom — це він, тому is."},{"type":"input","q":"If it ___ (not / stop) raining, we won't finish the roof today.","uk":"Якщо дощ не припиниться, ми сьогодні не закінчимо дах.","a":["doesn't stop","does not stop"],"why":"Умова — Present Simple. It — тому doesn't + дієслово без -s. Won't стоїть лише в частині з результатом."},{"type":"input","q":"I ___ (call) you if I hear any news.","uk":"Я тобі подзвоню, якщо почую якісь новини.","a":["will call","shall call","am going to call"],"why":"Результат реальної умови — will + дієслово: will call. Після if лишається Present Simple: hear."},{"type":"input","q":"When the plaster ___ (dry) too fast, it cracks.","uk":"Коли штукатурка висихає надто швидко, вона тріскається.","a":["dries"],"why":"Нульовий тип — факт, обидві частини в Present Simple. The plaster — це it, а приголосна + y дає -ies: dry → dries."},{"type":"order","uk":"Я подзвоню тобі, якщо фургон зламається.","words":["I'll","call","you","if","the","van","breaks","down"],"a":["I'll call you if the van breaks down.","If the van breaks down, I'll call you."],"why":"Результат — will (I'll call), умова — Present Simple (breaks down). Якщо почати з if, після умови ставимо кому."},{"type":"order","uk":"Що ти робитимеш, якщо автобус не приїде?","words":["what","will","you","do","if","the","bus","doesn't","come"],"a":["What will you do if the bus doesn't come?","If the bus doesn't come, what will you do?"],"why":"Питання: what + will + you + do. У частині з if — Present Simple: the bus doesn't come."}],"section":"complex"},"conditionals-2":{"id":"conditionals-2","level":"B1","title":"Second conditional","uk":"Умовні речення: якби (зараз)","summary":"уявне й малоймовірне: If I had more money, I'd buy a house.","minutes":7,"blocks":[{"t":"p","text":"**Second conditional** (другий тип умовних речень) — для **уявних** ситуацій: того, чого **зараз немає**, або того, що **навряд чи станеться**. Українською це «**якби** …, то … **б**»."},{"t":"ex","items":[["If I **had** more money, I **would buy** a house.","Якби в мене було більше грошей, я купив би будинок."],["If Tom **spoke** English, he**'d get** a better job.","Якби Том розмовляв англійською, він отримав би кращу роботу."],["If I **lived** in Dublin, I**'d go** to work by tram.","Якби я жив у Дубліні, я їздив би на роботу трамваєм."]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Другий тип","lines":["If + **Past Simple**, **would** + дієслово","If I **had** a car, I **would drive** to work."]},{"t":"p","text":"У частині з if — **Past Simple**: у правильних дієслів з -ed (lived, worked), у неправильних — **V2**, друга форма (had, knew, went). Але мова **не про минуле**, а про **зараз** або **майбутнє**: минула форма просто показує «це неправда, це уявне». У результаті — **would** + початкова форма дієслова (work, go — без to і без закінчень). Would однакове для всіх: I would, she would, they would."},{"t":"tip","text":"**Would** скорочують до **'d**: I'd, you'd, he'd, we'd. Заперечення — **wouldn't** (would not)."},{"t":"h","text":"Українське «б» і would"},{"t":"p","text":"Українською «б» стоїть в обох частинах: як**би** я мав… купив **би**. Англійською **would** — лише в частині з результатом. Після **if** would не ставимо: там Past Simple."},{"t":"table","head":["Українською","Англійською"],"rows":[["Якби я мав машину…","If I **had** a car…"],["Якби він знав…","If he **knew**…"],["…я б купив будинок.","…I**'d buy** a house."],["…ми б не працювали.","…we **wouldn't work**."]]},{"t":"h","text":"Заперечення і питання"},{"t":"rule","title":"Заперечення","lines":["If + **didn't** + дієслово, …","…, **wouldn't** + дієслово"]},{"t":"rule","title":"Питання","lines":["**Would** + you / he / they + дієслово … if …?","What **would** you **do** if …?"]},{"t":"ex","items":[["If Sarah **didn't have** kids, she **would travel** more.","Якби в Сари не було дітей, вона більше подорожувала б."],["I **wouldn't work** here if they **didn't pay** well.","Я б тут не працював, якби тут погано платили."],["What **would** you **do** if you **won** the lottery?","Що б ти зробив, якби виграв у лотерею?"],["**Would** you **move** to Canada if you **got** a job there?","Ти переїхав би в Канаду, якби отримав там роботу?"]]},{"t":"h","text":"Were замість was"},{"t":"p","text":"З дієсловом **be** після if часто кажуть **were** для всіх осіб: if I **were**, if it **were**. У розмові вживають і **was** (if I was, if it was) — це теж нормально."},{"t":"ex","items":[["If Tom **were** here, he**'d know** what to do.","Якби Том був тут, він знав би, що робити."],["If it **was** warmer, we**'d work** outside.","Якби було тепліше, ми працювали б надворі."]]},{"t":"h","text":"If I were you — порада"},{"t":"p","text":"**If I were you, I'd…** — «на твоєму місці я б…». Дуже частий і ввічливий спосіб порадити. У цьому сталому виразі кажи **were**. Його можна ставити і на початок, і в кінець речення."},{"t":"ex","items":[["**If I were you**, I**'d ask** for more money.","На твоєму місці я попросив би більше грошей."],["**If I were you**, I **wouldn't sign** that contract.","На твоєму місці я б не підписував цей контракт."],["I**'d wear** gloves **if I were you**.","На твоєму місці я вдягнув би рукавиці."]]},{"t":"h","text":"Could і might замість would"},{"t":"p","text":"**Could** — «міг би, зміг би», **might** — «можливо, …б». А в частині з if **could** означає «якби міг, якби вмів»."},{"t":"ex","items":[["If I **had** a van, I **could start** my own business.","Якби в мене був фургон, я міг би відкрити власну справу."],["If you **asked** him nicely, he **might help** you.","Якби ти ввічливо його попросив, він, може, і допоміг би."],["If Olena **could drive**, she**'d buy** a car.","Якби Олена вміла водити, вона купила б машину."]]},{"t":"h","text":"Перший чи другий тип?"},{"t":"p","text":"Обидва бувають про майбутнє. Різниця в тому, як ти оцінюєш шанси. **Реально**, цілком може статися → перший тип: if + Present Simple, will. **Малоймовірно**, мрія або неправда зараз → другий: if + Past Simple, would."},{"t":"ex","items":[["If I **get** the job, I**'ll move** to Dublin.","Якщо я отримаю цю роботу, то переїду в Дублін. (співбесіда пройшла добре)"],["If I **got** a job in Canada, I**'d move** there.","Якби я отримав роботу в Канаді, я б туди переїхав. (поки що мрія)"],["If it **rains** tomorrow, we**'ll stay** at home.","Якщо завтра буде дощ, ми залишимося вдома."],["If I **won** the lottery, I**'d stop** working.","Якби я виграв у лотерею, я б кинув роботу."]]},{"t":"tip","text":"Простий тест: якщо українською природно сказати «**якби**» про зараз чи майбутнє, потрібен другий тип. Якщо «**якщо**» — перший. А «якби тоді…» про минуле — це третій тип (наступна тема)."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"If I would have money, I would buy a car.","right":"If I had money, I would buy a car.","why":"Would не ставимо в частину з if, там Past Simple: had. Українське «б» — в обох частинах, а would — лише в одній."},{"t":"mistake","wrong":"If I had more time, I will learn Spanish.","right":"If I had more time, I would learn Spanish.","why":"Уявна умова (had) — уявний результат: would, а не will."},{"t":"mistake","wrong":"If I am you, I would call him.","right":"If I were you, I would call him.","why":"Порада — сталий вираз If I were you: минула форма were, хоч ідеться про зараз."},{"t":"mistake","wrong":"If I had a car, I would to drive to work.","right":"If I had a car, I would drive to work.","why":"Після would — початкова форма дієслова без to: would drive."}],"tasks":[{"type":"choice","q":"If I ___ more money, I would buy a house.","uk":"Якби в мене було більше грошей, я купив би будинок.","opts":["had","have","would have"],"a":0,"why":"Другий тип: після if — Past Simple (had), хоч ідеться про зараз. Would після if не ставимо."},{"type":"choice","q":"If Tom spoke English, he ___ a better job.","uk":"Якби Том розмовляв англійською, він отримав би кращу роботу.","opts":["would get","will get","gets"],"a":0,"why":"Умова уявна (spoke — Past Simple), тому в результаті would + дієслово. Will — для реальних умов."},{"type":"choice","q":"___, I'd ask for more money.","uk":"На твоєму місці я попросив би більше грошей.","opts":["If I were you","If I am you","If I will be you"],"a":0,"why":"«На твоєму місці» — сталий вираз If I were you: після if минула форма were."},{"type":"choice","q":"If I had a van, I ___ start my own business.","uk":"Якби в мене був фургон, я міг би відкрити власну справу.","opts":["could","can","will"],"a":0,"why":"«Міг би» — could. Can і will — для реальних ситуацій, а тут умова уявна (had)."},{"type":"choice","q":"I've got an interview tomorrow. If I ___ the job, I'll move to Dublin.","uk":"Завтра в мене співбесіда. Якщо я отримаю цю роботу, то переїду в Дублін.","opts":["get","got","would get"],"a":0,"why":"Шанс реальний, і в другій частині will, тому це перший тип: if + Present Simple (get)."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Якби я жив ближче, я ходив би на роботу пішки.","opts":["If I lived closer, I would walk to work.","If I would live closer, I would walk to work.","If I lived closer, I will walk to work."],"a":0,"why":"Після if — Past Simple (lived), у результаті — would + дієслово (would walk)."},{"type":"input","q":"If I ___ (know) his number, I'd call him.","uk":"Якби я знав його номер, я б йому подзвонив.","a":["knew"],"why":"Після if — Past Simple. Know — неправильне дієслово, його V2 — knew."},{"type":"input","q":"If we had more people, we ___ (finish) the job faster.","uk":"Якби в нас було більше людей, ми закінчили б роботу швидше.","a":["would finish"],"why":"Результат уявної умови: would + початкова форма дієслова — would finish."},{"type":"input","q":"I ___ (not / work) here if they didn't pay well.","uk":"Я б тут не працював, якби тут погано платили.","a":["wouldn't work","would not work"],"why":"Заперечення в результаті — wouldn't + дієслово. Частина з if — у Past Simple: didn't pay."},{"type":"input","q":"If Sarah ___ (not / have) kids, she would travel more.","uk":"Якби в Сари не було дітей, вона більше подорожувала б.","a":["didn't have","did not have","had no","hadn't got","had not got"],"why":"Після if — Past Simple: заперечення didn't + початкова форма (have, а не had)."},{"type":"order","uk":"Ти працював би по неділях, якби більше платили?","words":["would","you","work","on","Sundays","if","they","paid","more"],"a":["Would you work on Sundays if they paid more?","If they paid more, would you work on Sundays?"],"why":"Питання: would + you + дієслово. Уявна умова — Past Simple: they paid."},{"type":"order","uk":"Якби я вмів водити, я купив би машину.","words":["if","I","could","drive","I","would","buy","a","car"],"a":["If I could drive, I would buy a car.","I would buy a car if I could drive."],"why":"«Якби вмів» — if I could. Результат — would + дієслово. Коли речення починається з if, після умови ставимо кому."}],"section":"complex"},"conditionals-3-wish":{"id":"conditionals-3-wish","level":"B1","title":"Third conditional and wish","uk":"Якби тоді…: третій тип і wish","summary":"жаль про минуле: If I had known… I wish I had…","minutes":8,"blocks":[{"t":"p","text":"**Third conditional** (третій тип умовних речень) — про **минуле**, якого вже не змінити. Ми уявляємо, як усе могло бути інакше: «якби я **тоді**…, то … **б**». Так часто висловлюють жаль або докір."},{"t":"ex","items":[["If I **had left** earlier, I **would have caught** the bus.","Якби я вийшов раніше, я встиг би на автобус."],["If you **had told** me, I **would have helped** you.","Якби ти мені сказав, я б тобі допоміг."]]},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Третій тип","lines":["If + **had** + V3, **would have** + V3","If I **had known**, I **would have come**."]},{"t":"p","text":"**V3** — третя форма дієслова. У правильних дієслів вона з -ed (worked, finished), у неправильних її треба знати (known, gone, seen). **Had** і **would have** однакові для всіх: I had, she had, they would have."},{"t":"table","head":["Дієслово","V2","V3"],"rows":[["know (знати)","knew","**known**"],["go (іти, їхати)","went","**gone**"],["see (бачити)","saw","**seen**"],["take (брати)","took","**taken**"],["catch (встигнути на)","caught","**caught**"],["tell (сказати)","told","**told**"],["be (бути)","was / were","**been**"]]},{"t":"tip","text":"У розмові скорочують: **I'd known** = I had known, **I'd have come** = I would have come. Як розрізнити: **'d + V3** — це had, **'d + have** — це would."},{"t":"ex","items":[["If **I'd known**, **I'd have come**.","Якби я знав, я б прийшов."]]},{"t":"h","text":"Заперечення і питання"},{"t":"rule","title":"Заперечення","lines":["If + **hadn't** + V3, …","…, **wouldn't have** + V3"]},{"t":"rule","title":"Питання","lines":["**Would** + you / he / they + **have** + V3 … if …?","What **would** you **have done** if …?"]},{"t":"ex","items":[["If it **hadn't rained**, we **would have finished** the roof.","Якби не пішов дощ, ми б закінчили дах."],["I **wouldn't have been** late if the bus **had come** on time.","Я б не запізнився, якби автобус приїхав вчасно."],["**Would** you **have taken** the job if they**'d offered** more money?","Ти погодився б на ту роботу, якби тобі запропонували більше грошей?"]]},{"t":"h","text":"Could have і might have"},{"t":"p","text":"Замість would have можна сказати **could have** (міг би) або **might have** (можливо, …б)."},{"t":"ex","items":[["If you **had asked** me, I **could have helped**.","Якби ти мене попросив, я міг би допомогти."],["If he **had worn** a helmet, he **might not have been** hurt.","Якби він був у касці, він, можливо, не травмувався б."]]},{"t":"h","text":"Другий чи третій тип?"},{"t":"p","text":"Українською обидва звучать однаково: «якби я знав». Англійською час видно з форми: про **зараз** — другий тип (knew, would call), про **тоді** — третій (had known, would have called)."},{"t":"ex","items":[["If I **knew** her number, I**'d call** her.","Якби я знав її номер (зараз), я б їй подзвонив."],["If I **had known** her number, I**'d have called** her.","Якби я знав її номер (тоді), я б їй подзвонив."]]},{"t":"h","text":"Wish: «шкода, що…»"},{"t":"p","text":"**I wish** перекладаємо «шкода, що…» або «хотів би я…». Після wish дієслово **відступає на крок у минуле**, як в умовних реченнях: про зараз — Past Simple, про минуле — had + V3."},{"t":"table","head":["Про що","Форма","Приклад"],"rows":[["зараз","wish + Past Simple","I wish I **had** a car."],["минуле","wish + had + V3","I wish I **had known**."],["хочу, щоб щось змінилося","wish + would","I wish he **would stop**."]]},{"t":"h","text":"Wish про зараз"},{"t":"ex","items":[["I **wish** I **had** a car.","Шкода, що в мене немає машини."],["I **wish** I **spoke** English better.","Хотів би я краще говорити англійською."],["I **wish** I **didn't have** to work on Saturdays.","Шкода, що мені треба працювати по суботах."],["I **wish** I **could** come with you.","Шкода, що я не можу піти з тобою."],["I **wish** I **were** taller.","Хотів би я бути вищим."]]},{"t":"tip","text":"Українською часто кажемо із запереченням: «шкода, що **немає**». Англійською навпаки — ствердження: I wish I **had** (хотів би мати). А «шкода, що **треба**» — I wish I **didn't have to**. З be можна і **were**, і **was**: I wish I were taller, I wish I was taller."},{"t":"h","text":"Wish про минуле"},{"t":"ex","items":[["I **wish** I **had studied** English at school.","Шкода, що я не вчив англійську в школі."],["I **wish** I **hadn't said** that.","Шкода, що я це сказав."],["Tom **wishes** he **had taken** that job.","Том шкодує, що не погодився на ту роботу."]]},{"t":"h","text":"Wish + would: хочу, щоб це змінилося"},{"t":"p","text":"**I wish + хтось або щось + would** — коли хочеш, щоб інша людина змінила поведінку або щоб щось нарешті сталося. Часто з роздратуванням. Про себе так не кажуть (не I wish I would, а I wish I **could**), і для станів — зросту, віку, того, що в тебе є, — would не підходить."},{"t":"ex","items":[["I **wish** he **would stop** talking.","Хоч би він уже замовк."],["I **wish** you **wouldn't leave** your tools everywhere.","От би ти не розкидав скрізь свої інструменти."],["I **wish** it **would stop** raining.","Хоч би вже дощ перестав."]]},{"t":"h","text":"If only — ще емоційніше"},{"t":"p","text":"**If only** — «якби ж», «от якби». Значення те саме, що у wish, тільки сильніше. Форми ті самі: про зараз — Past Simple, про минуле — had + V3."},{"t":"ex","items":[["**If only** I **had** more time!","Якби ж у мене було більше часу!"],["**If only** I **hadn't lost** my keys!","Якби ж я не загубив ключі!"]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"If I would have known, I would have come.","right":"If I had known, I would have come.","why":"Would не ставимо в частину з if і в третьому типі: там had + V3."},{"t":"mistake","wrong":"If I had knew, I would have told you.","right":"If I had known, I would have told you.","why":"Після had — третя форма (V3): known, а не друга, knew."},{"t":"mistake","wrong":"If I had left earlier, I would catch the bus.","right":"If I had left earlier, I would have caught the bus.","why":"Результат теж про минуле, тому would have + V3."},{"t":"mistake","wrong":"I wish I have a car.","right":"I wish I had a car.","why":"Після wish про зараз — Past Simple: had. Дієслово відступає на крок у минуле."},{"t":"mistake","wrong":"I wish I would be taller.","right":"I wish I were taller.","why":"Would після wish — про чужу поведінку чи зміни. Про себе й про стан — Past Simple: were або was."}],"tasks":[{"type":"choice","q":"If I had left earlier, I ___ the bus.","uk":"Якби я вийшов раніше, я встиг би на автобус.","opts":["would have caught","would catch","will catch"],"a":0,"why":"Минуле, якого не змінити: у результаті would have + V3 (caught)."},{"type":"choice","q":"If you ___ me, I would have helped you.","uk":"Якби ти мені сказав, я б тобі допоміг.","opts":["had told","told","would have told"],"a":0,"why":"Третій тип: після if — had + V3 (had told). Would have — лише в частині з результатом."},{"type":"choice","q":"I wish I ___ a car.","uk":"Шкода, що в мене немає машини.","opts":["had","have","would have"],"a":0,"why":"Wish про зараз: дієслово відступає в минуле — Past Simple had."},{"type":"choice","q":"I wish I ___ English at school.","uk":"Шкода, що я не вчив англійську в школі.","opts":["had studied","studied","would study"],"a":0,"why":"Жаль про минуле (у школі — це тоді): wish + had + V3."},{"type":"choice","q":"I wish he ___ talking. It's driving me mad.","uk":"Хоч би він уже замовк. Мене це бісить.","opts":["would stop","stops","will stop"],"a":0,"why":"Тебе дратує чужа поведінка, і ти хочеш, щоб вона змінилася: wish + would + дієслово."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Якби я знав, я б прийшов.","opts":["If I had known, I would have come.","If I would have known, I would have come.","If I had knew, I would have come."],"a":0,"why":"Після if — had + V3 (known, а не knew). Would have стоїть лише в частині з результатом."},{"type":"input","q":"If we had ___ (take) the motorway, we would have got there faster.","uk":"Якби ми поїхали автомагістраллю, ми б доїхали швидше.","a":["taken"],"why":"Після had — третя форма (V3). Take — неправильне дієслово: take, took, taken."},{"type":"input","q":"If it ___ (not / rain), we would have finished the roof.","uk":"Якби не пішов дощ, ми б закінчили дах.","a":["hadn't rained","had not rained"],"why":"Умова про минуле — had + V3, у запереченні hadn't + V3: hadn't rained."},{"type":"input","q":"If you had asked me, I ___ (help) you.","uk":"Якби ти мене попросив, я б тобі допоміг.","a":["would have helped"],"why":"Результат про минуле — would have + V3: would have helped."},{"type":"input","q":"I wish I ___ (not / say) that.","uk":"Шкода, що я це сказав.","a":["hadn't said","had not said"],"why":"Жаль про минуле: wish + had + V3. Українською «шкода, що сказав», англійською «хотів би, щоб не сказав»: hadn't said."},{"type":"order","uk":"Що б ти зробив, якби тобі не заплатили?","words":["what","would","you","have","done","if","they","hadn't","paid","you"],"a":["What would you have done if they hadn't paid you?","If they hadn't paid you, what would you have done?"],"why":"Питання: what + would + you + have + V3. Умова — hadn't paid. «Тобі не заплатили» англійською — «вони тобі не заплатили»: they."},{"type":"order","uk":"Якби ж я тебе послухав!","words":["if","only","I","had","listened","to","you"],"a":["If only I had listened to you!"],"why":"Жаль про минуле: if only + had + V3, як після wish."}],"section":"complex"},"passive":{"id":"passive","level":"B1","title":"Passive voice","uk":"Пасивний стан: was made, is done","summary":"важлива дія, а не виконавець: the wall was plastered","minutes":8,"blocks":[{"t":"p","text":"**Пасивний стан** (passive) — коли важливо, **що сталося** з предметом, а не **хто** це зробив. Порівняй: Mick plastered the wall (Мік поштукатурив стіну — цікавить Мік) і The wall was plastered (стіну поштукатурили — цікавить стіна)."},{"t":"ex","items":[["Mick **plastered** the wall.","Мік поштукатурив стіну."],["The wall **was plastered** yesterday.","Стіну поштукатурили вчора."],["My van **was stolen** last night.","Мій фургон учора вночі вкрали."],["English **is spoken** all over the world.","Англійською розмовляють у всьому світі."]]},{"t":"p","text":"Українською ми часто просто не називаємо виконавця: «фургон украли», «стіну поштукатурили», «будинок збудовано». А в англійському реченні завжди є **підмет** — слово перед дієсловом, про яке йдеться (у звичайному реченні це той, хто виконує дію: **Mick** plastered). Тому там, де ми кажемо «вкрали», англієць робить підметом сам предмет: **My van** was stolen."},{"t":"h","text":"Як утворюється"},{"t":"rule","title":"Формула","lines":["підмет + **be** + **V3**","The wall **was plastered**.","These houses **were built** in 1990."]},{"t":"p","text":"**V3** — третя форма дієслова. У правильних дієслів це закінчення -ed: painted, delivered, fixed. Неправильні треба знати: build → **built**, make → **made**, steal → **stolen**, do → **done**, pay → **paid**. Час речення показує **be** (is, was, will be…), а V3 не змінюється ніколи."},{"t":"h","text":"Навіщо пасив"},{"t":"list","items":["Виконавець **невідомий**: My phone **was stolen**. (Хто вкрав — невідомо.)","Виконавець **неважливий** або й так зрозумілий: The cement **was delivered** at eight. (Важливо, що привезли, а не хто був за кермом.)","Хочемо говорити саме **про предмет**: This church **was built** in 1850.","Правила, оголошення, новини: Hard hats **must be worn** on site. (На майданчику обов'язково носити каску.)"]},{"t":"h","text":"by — хто це зробив"},{"t":"p","text":"Якщо виконавця все ж треба назвати, додаємо **by** (= «ким»). Але здебільшого його просто не згадують: про стіну ніхто не скаже «was plastered by someone»."},{"t":"ex","items":[["The house **was built by** a local company.","Будинок збудувала місцева фірма."],["This kitchen **was designed by** my sister.","Цю кухню спроєктувала моя сестра."],["Hamlet **was written by** Shakespeare.","«Гамлета» написав Шекспір."]]},{"t":"h","text":"Пасив у різних часах"},{"t":"p","text":"Змінюється лише **be** — так само, як у звичайному реченні цього часу. Порівняй: активний стан (хтось робить) і пасивний (щось роблять)."},{"t":"table","head":["Час","Активний","Пасивний"],"rows":[["Present Simple","They clean it.","It **is cleaned**."],["Present Continuous","They're cleaning it.","It **is being cleaned**."],["Past Simple","They cleaned it.","It **was cleaned**."],["Present Perfect","They've cleaned it.","It **has been cleaned**."],["will","They'll clean it.","It **will be cleaned**."],["can, must, should","They must clean it.","It **must be cleaned**."]]},{"t":"ex","items":[["The site **is cleaned** every Friday.","Майданчик прибирають щоп'ятниці."],["The office **is being painted** at the moment.","Офіс зараз фарбують."],["The windows **were fitted** last week.","Вікна встановили минулого тижня."],["The invoice **has been paid**.","Рахунок уже оплачено."],["The roof **will be finished** next week.","Дах закінчать наступного тижня."],["It **can be done** in two days.","Це можна зробити за два дні."]]},{"t":"h","text":"Заперечення і питання"},{"t":"rule","title":"Заперечення","lines":["**not** після першого допоміжного дієслова","It **wasn't delivered**.","We **haven't been paid** yet.","It **won't be finished** today."]},{"t":"rule","title":"Питання","lines":["перше допоміжне дієслово + підмет + решта?","**Was** the cement **delivered**?","**Has** the invoice **been paid**?"]},{"t":"tip","text":"**Do, does, did** у пасиві з **be** не потрібні: на початок питання виносимо **be** (або has, will, can). Правильно: **Was** it **delivered**? Неправильно: Did it delivered?"},{"t":"ex","items":[["**Was** the cement **delivered**? — Yes, it **was**.","Цемент привезли? — Так."],["We **haven't been paid** yet.","Нам ще не заплатили."],["Where **were** these tiles **made**?","Де зробили цю плитку?"],["The door **wasn't locked**.","Двері не були замкнені."]]},{"t":"tip","text":"«Мені сказали», «нам дали», «йому заплатили» — англійською підметом стає людина: **I was told**, **we were given**, **he was paid**. Не «To me was told»."},{"t":"ex","items":[["I **was told** to come at eight.","Мені сказали прийти о восьмій."],["We **were given** new hard hats.","Нам видали нові каски."]]},{"t":"h","text":"get + V3 у розмові"},{"t":"p","text":"У розмові замість be часто кажуть **get**, коли щось **стається** з людиною чи річчю, часто неприємне або несподіване. Get змінюється як звичайне дієслово (get, gets, got), тому питання й заперечення будуємо з do, does, did."},{"t":"ex","items":[["We **get paid** on Fridays.","Нам платять щоп'ятниці."],["Mick **got injured** playing football.","Мік травмувався, коли грав у футбол."],["Tom **got fired** last month.","Тома звільнили минулого місяця."],["**Did** you **get paid** for the extra hours?","Тобі заплатили за понаднормові години?"]]},{"t":"h","text":"Я народився: I was born"},{"t":"p","text":"«Народився» англійською — завжди пасив: **I was born** (дослівно «я був народжений»). Тільки was або were, ніякого «I born»."},{"t":"ex","items":[["I **was born** in 1999.","Я народився в 1999 році."],["Where **was** your father **born**?","Де народився твій батько?"],["Kate **was born** in Cork.","Кейт народилася в Корку."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"The house was build in 1990.","right":"The house was built in 1990.","why":"Після be потрібна V3. Build — неправильне дієслово: build – built – built."},{"t":"mistake","wrong":"The accident was happened at night.","right":"The accident happened at night.","why":"Після happen (статися) не буває «кого/що», тому пасиву від нього немає. Так само die, arrive: he died, а не he was died."},{"t":"mistake","wrong":"I born in 1999.","right":"I was born in 1999.","why":"«Народився» — завжди was born (або were born)."},{"t":"mistake","wrong":"The work is doing now.","right":"The work is being done now.","why":"Робота сама нічого не робить — її роблять. Тому пасив: is being + V3."},{"t":"mistake","wrong":"Was delivered the cement?","right":"Was the cement delivered?","why":"Порядок у питанні: was + підмет + V3. Підмет (the cement) стоїть між was і V3."}],"tasks":[{"type":"choice","q":"The kitchen ___ last week.","uk":"Кухню пофарбували минулого тижня.","opts":["painted","was painted","is painted"],"a":1,"why":"Кухня сама себе не фарбує, її пофарбували — тому пасив. Last week — минулий час: was + V3."},{"type":"choice","q":"These flats were ___ in 2005.","uk":"Ці квартири збудували у 2005 році.","opts":["build","built","building"],"a":1,"why":"Після were у пасиві стоїть V3. Build неправильне: build – built – built."},{"type":"choice","q":"The materials ___ tomorrow.","uk":"Матеріали привезуть завтра.","opts":["will deliver","will be delivered","will delivered"],"a":1,"why":"Матеріали не привозять самі себе, тому пасив. Майбутнє: will be + V3."},{"type":"choice","q":"The road ___ at the moment.","uk":"Дорогу зараз ремонтують.","opts":["is repairing","is being repaired","was repaired"],"a":1,"why":"At the moment — дія триває зараз: is being + V3. The road is repairing означало б, що дорога сама щось ремонтує."},{"type":"choice","q":"This bridge was designed ___ a famous engineer.","uk":"Цей міст спроєктував відомий інженер.","opts":["by","from","of"],"a":0,"why":"Того, хто виконав дію, у пасиві називаємо через by (= «ким»): designed by an engineer."},{"type":"choice","q":"___ to wait here.","uk":"Мені сказали почекати тут.","opts":["I was told","Me was told","I told"],"a":0,"why":"«Мені сказали» — I was told: підметом стає людина (I), а не me. I told — це «я сказав»."},{"type":"input","q":"These bricks ___ (make) in Wexford.","uk":"Цю цеглу роблять у Вексфорді.","a":["are made"],"why":"Факт — Present Simple, пасив: are + V3 (bricks — множина). Make неправильне: make – made – made."},{"type":"input","q":"This form must ___ (sign) today.","uk":"Цю форму треба підписати сьогодні.","a":["be signed"],"why":"Після must, can, should пасив має форму be + V3: must be signed."},{"type":"input","q":"Andrii ___ (injure) at work last week.","uk":"Андрій травмувався на роботі минулого тижня.","a":["was injured","got injured","injured himself"],"why":"Минулий час пасиву: was + V3. У розмові так само часто кажуть got injured. Injured himself («травмував себе») теж правильно."},{"type":"input","q":"The bill hasn't ___ (pay) yet.","uk":"Рахунок ще не оплатили.","a":["been paid"],"why":"Present Perfect у пасиві: has/have + been + V3. Pay неправильне: pay – paid – paid."},{"type":"order","uk":"Де ти народився?","words":["born","you","where","were"],"a":["Where were you born?"],"why":"«Народився» — was/were born. У питанні were стоїть перед підметом you."},{"type":"order","uk":"Фургон полагодили вчора?","words":["fixed","the","yesterday","was","van"],"a":["Was the van fixed yesterday?"],"why":"Питання в пасиві: was + підмет (the van) + V3. Do, does, did тут не потрібні."}],"section":"complex"},"reported-speech":{"id":"reported-speech","level":"B1","title":"Reported speech","uk":"Непряма мова: he said that…","summary":"переказати чужі слова: he said he was tired","minutes":9,"blocks":[{"t":"p","text":"**Непряма мова** (reported speech) — це коли ти **переказуєш** чужі слова: «Бос сказав, що завтра роботи не буде». Українською ми просто міняємо займенники. Англійською ще й **час дієслова зазвичай зсувається на крок у минуле**, бо ти розповідаєш про те, що сказали раніше."},{"t":"ex","items":[["Tom: \"I **need** a day off.\"","Том: «Мені потрібен вихідний»."],["Tom **said** he **needed** a day off.","Том сказав, що йому потрібен вихідний."],["Sarah: \"I**'m** tired.\"","Сара: «Я втомилася»."],["Sarah **said** she **was** tired.","Сара сказала, що втомилася."]]},{"t":"tip","text":"Українською кажемо «Том сказав, що йому **потрібен** вихідний» — теперішній час. Англійською після **said** дієслово зазвичай іде в минуле: Tom said he **needed**… Це головне правило теми."},{"t":"h","text":"say чи tell"},{"t":"rule","title":"Хто кому сказав","lines":["**say** + що: He **said** (that) he was late.","**tell** + кому + що: He **told me** (that) he was late."]},{"t":"p","text":"Після **tell** обов'язково кажемо, **кому**: told **me**, told **the boss**, told **us**. Після **say** «кому» не ставимо (якщо дуже треба, то через to: said **to me**, але простіше told me). Слово **that** («що») можна пропустити, у розмові його часто пропускають."},{"t":"ex","items":[["She **said** she was busy.","Вона сказала, що зайнята."],["She **told me** she was busy.","Вона сказала мені, що зайнята."],["What did the boss **say**?","Що сказав бос?"],["Did you **tell** Mick about the meeting?","Ти сказав Міку про зустріч?"]]},{"t":"tip","text":"Запам'ятай вирази: **tell** the truth (казати правду), **tell** a lie (брехати), **tell** a joke (розповісти жарт); **say** hello (привітатися), **say** sorry (перепросити), **say** goodbye (попрощатися)."},{"t":"h","text":"Зсув часів: крок у минуле"},{"t":"table","head":["Він каже","Ти переказуєш"],"rows":[["\"I **am** tired.\"","He said he **was** tired."],["\"We **are** ready.\"","They said they **were** ready."],["\"I **work** in Gorey.\"","He said he **worked** in Gorey."],["\"I**'m working**.\"","He said he **was working**."],["\"I **will** call you.\"","He said he **would** call me."],["\"I **can** help.\"","He said he **could** help."],["\"I **have finished**.\"","He said he **had finished**."],["\"I **finished** it.\"","He said he **had finished** it."]]},{"t":"p","text":"Could, would, should, might не змінюються: «I **could** help» → He said he **could** help. А Past Simple у розмові часто залишають як є, якщо й так зрозуміло, що було раніше: He said he **finished** at five — теж нормально."},{"t":"ex","items":[["The boss **said** the cement **would** arrive at ten.","Бос сказав, що цемент привезуть о десятій."],["Andrii **told** me he **couldn't** come.","Андрій сказав мені, що не зможе прийти."],["Kate **said** she **had lost** her keys.","Кейт сказала, що загубила ключі."],["He **told** me he **was looking** for a job.","Він сказав мені, що шукає роботу."]]},{"t":"h","text":"Коли час не зсуваємо"},{"t":"p","text":"Якщо сказане **досі правда**, час можна не зсувати: He said he **lives** in Gorey — він і зараз там живе (зсунути теж не помилка: lived). А після **says** (теперішній час: «каже») час не змінюється взагалі."},{"t":"ex","items":[["Tom **says** he **can't** come today.","Том каже, що сьогодні не може прийти."],["The forecast **says** it**'ll** rain tomorrow.","За прогнозом, завтра буде дощ."],["My boss always **says** safety **comes** first.","Мій бос завжди каже, що безпека понад усе."]]},{"t":"h","text":"Займенники, час і місце"},{"t":"p","text":"Займенники міняються за змістом, як і в українській: «**I** will call **you**» → He said **he** would call **me**. Якщо переказуєш пізніше або в іншому місці, міняються й слова про час і місце:"},{"t":"table","head":["Він каже","Ти переказуєш пізніше"],"rows":[["today","that day"],["tomorrow","the next day"],["yesterday","the day before"],["now","then"],["here","there"],["this","that"]]},{"t":"tip","text":"Якщо переказуєш того самого дня, слова про час не міняй: Mick said he would come **tomorrow** — це «завтра» ще не настало. А через тиждень уже: Mick said he would come **the next day**."},{"t":"h","text":"Переказуємо питання"},{"t":"p","text":"Переказане питання — уже не питання, тому в ньому **звичайний порядок слів**: спершу **підмет** (хто або що виконує дію), потім дієслово. Do, does, did зникають, час, як завжди, зсувається, і знака питання в кінці немає. Якщо питального слова немає (відповідь «так» чи «ні»), додаємо **if** або **whether** — «чи»."},{"t":"rule","title":"Питання","lines":["asked + **where / what / when…** + підмет + дієслово","asked + **if / whether** (чи) + підмет + дієслово"]},{"t":"ex","items":[["She asked where the office **was**.","Вона спитала, де офіс."],["He asked me what time I **started**.","Він спитав мене, о котрій я починаю."],["The boss asked **if** I **had** a car.","Бос спитав, чи є в мене машина."],["Kate asked **whether** we **were** ready.","Кейт спитала, чи ми готові."]]},{"t":"h","text":"Накази й прохання"},{"t":"rule","title":"Наказ, прохання, заборона","lines":["told + кого + **to** + дієслово (наказ)","asked + кого + **to** + дієслово (прохання)","told / asked + кого + **not to** + дієслово"]},{"t":"p","text":"Після to стоїть **початкова форма дієслова** — як у словнику: work, go, be. Заборону («не роби») переказуємо через **not to**."},{"t":"ex","items":[["The boss **told** us **to clean** the site.","Бос сказав нам прибрати майданчик."],["Sarah **asked** me **to help** her.","Сара попросила мене допомогти їй."],["The boss **told** us **not to park** there.","Бос сказав нам не паркуватися там."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"He said me he was busy.","right":"He told me he was busy.","why":"Після say не ставимо одразу «кому». Хочеш сказати, кому, — told me."},{"t":"mistake","wrong":"She asked where was the office.","right":"She asked where the office was.","why":"У переказаному питанні звичайний порядок слів: спершу підмет (the office), потім дієслово (was)."},{"t":"mistake","wrong":"He told that he was tired.","right":"He said that he was tired.","why":"Після tell обов'язково «кому»: told me that… Якщо «кому» не кажемо — said."},{"t":"mistake","wrong":"He asked me do I want tea.","right":"He asked me if I wanted tea.","why":"Переказане питання — не питання: do зникає, з'являється if, а want зсувається в wanted. В Ірландії в розмові почуєш asked me did I want…, але стандартно — з if."},{"t":"mistake","wrong":"He told me don't be late.","right":"He told me not to be late.","why":"Наказ переказуємо через to + дієслово, а заборону — через not to."}],"tasks":[{"type":"choice","q":"He ___ me he was tired.","uk":"Він сказав мені, що втомився.","opts":["said","told","says"],"a":1,"why":"Є «кому» (me) — потрібне tell: told me. Said me і says me — помилка."},{"type":"choice","q":"Kate ___ she would be late.","uk":"Кейт сказала, що запізниться.","opts":["said","told","say"],"a":0,"why":"«Кому» не названо — потрібне say: Kate said. Told без «кому» не кажуть, а Kate say — неправильна форма."},{"type":"choice","q":"Sarah says she ___ come to the party. She's just texted me.","uk":"Сара каже, що не може прийти на вечірку. Вона щойно мені написала.","opts":["can't","couldn't","doesn't can"],"a":0,"why":"Says — теперішній час («каже»), тому час не зсуваємо: can't. Doesn't can не буває: can не потребує do."},{"type":"input","q":"Mick said he ___ (be) at home, but I saw him in the pub.","uk":"Мік сказав, що він удома, але я бачив його в пабі.","a":["was"],"why":"Після said час зсувається в минуле: am → was. До того ж Мік сказав неправду (я бачив його в пабі), тому is тут не підходить."},{"type":"choice","q":"Andrii said he ___ fix my car, but in the end he couldn't.","uk":"Андрій сказав, що зможе полагодити мою машину, але врешті не зміг.","opts":["can","could","will can"],"a":1,"why":"Після said can зсувається в could. Will can не буває: «буде могти» — will be able to."},{"type":"input","q":"Olena said she ___ (will) call me back, but she never did.","uk":"Олена сказала, що передзвонить мені, але так і не передзвонила.","a":["would"],"why":"Після said will зсувається в would. Обіцянка вже в минулому (she never did), тому will тут не підходить."},{"type":"choice","q":"Tom said he ___ the job, but half of it wasn't done.","uk":"Том сказав, що закінчив роботу, але половину не було зроблено.","opts":["has finished","had finished","have finished"],"a":1,"why":"Після said Present Perfect (has finished) зсувається на крок у минуле: had finished. Залишити has finished не можна: сказане не було правдою."},{"type":"choice","task":"Яке речення правильне?","q":"","opts":["She asked me how old was I.","She asked me how old I was.","She asked me how old am I."],"a":1,"why":"Переказане питання має звичайний порядок слів: how old + підмет (I) + дієслово (was)."},{"type":"input","q":"My boss asked ___ I was free on Saturday.","uk":"Мій бос спитав, чи я вільний у суботу.","a":["if","whether","me if","me whether"],"why":"Питання «так/ні» переказуємо через if або whether — «чи»."},{"type":"input","q":"Kate asked me ___ (close) the window.","uk":"Кейт попросила мене зачинити вікно.","a":["to close","if I could close","whether I could close","if I would close","whether I would close"],"why":"Прохання переказуємо так: asked + кого + to + дієслово. Можна й через питання: asked me if I could close."},{"type":"order","uk":"Вона спитала мене, де я живу.","words":["lived","asked","where","she","me","I"],"a":["She asked me where I lived."],"why":"Переказане питання: where + підмет (I) + дієслово, без do. Live після asked зсувається в lived."},{"type":"order","uk":"Мама сказала мені не хвилюватися.","words":["worry","told","to","mum","not","me","my"],"a":["My mum told me not to worry."],"why":"Заборону переказуємо так: told + кого + not to + дієслово."}],"section":"complex"},"relative-clauses":{"id":"relative-clauses","level":"B1","title":"Relative clauses: who, which, that","uk":"Підрядні з who, which, that","summary":"уточнити, про кого мова: the man who called","minutes":7,"blocks":[{"t":"p","text":"Слова **who, which, that** з'єднують два речення в одне й уточнюють, **про кого чи про що** мова. Українською це «який, яка, яке, які» або «що»: чоловік, **який** тобі дзвонив. Англійською вибір слова залежить від того, людина це чи річ."},{"t":"table","head":["Слово","Для чого","Приклад"],"rows":[["**who**","люди","the man **who** called"],["**which**","речі, тварини","the van **which** broke down"],["**that**","люди і речі","the job **that** I got"],["**whose**","чий, чия, чиє","the woman **whose** son works here"],["**where**","де, у якому (місце)","the shop **where** I work"]]},{"t":"ex","items":[["The man **who** called you is my boss.","Чоловік, який тобі дзвонив, — мій бос."],["I've lost the keys **which** were on the table.","Я загубив ключі, які лежали на столі."],["That's the woman **whose** son works with us.","Це та жінка, син якої працює з нами."],["This is the shop **where** I buy my tools.","Це магазин, де я купую інструменти."]]},{"t":"h","text":"who, which чи that"},{"t":"p","text":"**who** — тільки про людей, **which** — тільки про речі й тварин. **that** — і про людей, і про речі; у розмові його кажуть найчастіше. Українське «що» в такому реченні — **не what**: what сюди не ставлять ніколи."},{"t":"ex","items":[["The guys **that** work with me are from Poland.","Хлопці, які працюють зі мною, з Польщі."],["Where's the drill **that** was in the van?","Де дриль, який був у фургоні?"],["I need a ladder **that** reaches the ceiling.","Мені потрібна драбина, яка дістане до стелі."],["Is there anyone here **who** speaks Polish?","Тут є хтось, хто говорить польською?"]]},{"t":"h","text":"Коли who, which, that можна пропустити"},{"t":"p","text":"Подивись, що стоїть **одразу після** who, which чи that. Якщо там **інший підмет** (хто виконує дію: I, you, he, my boss), слово можна пропустити, і в розмові так зазвичай і роблять. Якщо ж одразу йде **дієслово**, то who, which чи that саме є підметом, і пропускати його **не можна**."},{"t":"rule","title":"Можна пропустити","lines":["The van (**that**) **I** bought is white.","the guy (**who**) **you** met yesterday"]},{"t":"rule","title":"Не можна пропустити","lines":["The man **who called** you is Tom.","The van **that broke** down is mine."]},{"t":"ex","items":[["The van **I bought** last year is white.","Фургон, який я купив торік, білий."],["Is this the jacket **you were** looking for?","Це та куртка, яку ти шукав?"],["The plumber **who came** yesterday was very good.","Сантехнік, який приходив учора, дуже добре попрацював."]]},{"t":"h","text":"Прийменник у кінці"},{"t":"p","text":"Українською прийменник стоїть перед «який»: хлопець, **з яким** я працюю. Англійською в розмові його ставлять **у кінець**, а who чи that зазвичай пропускають: the guy I work **with**. Варіант with whom існує, але звучить дуже офіційно."},{"t":"ex","items":[["That's the guy I work **with**.","Це хлопець, з яким я працюю."],["The flat we live **in** is quite small.","Квартира, в якій ми живемо, досить маленька."],["Is this the job you applied **for**?","Це та робота, на яку ти подавав заявку?"]]},{"t":"tip","text":"**where** уже означає «в якому», тож in після нього не потрібне: the house **where** I live або the house I live **in**, але не обидва разом."},{"t":"h","text":"Коми: уточнення чи додаткова інформація"},{"t":"p","text":"**Без ком** частина з who чи that уточнює, **про кого саме** мова: без неї незрозуміло, яку людину чи річ маємо на увазі. **З комами** — просто додаткова інформація про того, кого й так зрозуміло (мій бос, Дублін, моя мама). У частині з комами **не буває that**, і пропускати who чи which не можна."},{"t":"ex","items":[["The man **who lives upstairs** is very noisy.","Чоловік, який живе нагорі, дуже галасливий."],["My boss, **who is from Cork**, is very fair.","Мій бос, який родом з Корка, дуже справедливий."],["We stopped in Gorey, **which** is a nice little town.","Ми зупинилися в Горі — це гарне містечко."]]},{"t":"tip","text":"**which** після коми може стосуватися **всього** попереднього речення: He came on time, **which** was a surprise. — Він прийшов вчасно, що було несподіванкою. І тут теж не what."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"The man which called you is my boss.","right":"The man who called you is my boss.","why":"Про людей — who або that, не which."},{"t":"mistake","wrong":"The car what I bought is red.","right":"The car that I bought is red.","why":"What не означає «який». Кажи that, which або пропусти слово взагалі: The car I bought is red."},{"t":"mistake","wrong":"The man who he called you is Tom.","right":"The man who called you is Tom.","why":"Who вже замінює he, тому he вдруге не потрібне. Так само: the van I bought, а не the van I bought it."},{"t":"mistake","wrong":"This is the house where I live in.","right":"This is the house where I live.","why":"Where вже означає «в якому». Або where, або in у кінці: the house I live in."}],"tasks":[{"type":"choice","q":"The woman ___ lives next door is a teacher.","uk":"Жінка, яка живе по сусідству, — вчителька.","opts":["who","which","what"],"a":0,"why":"Про людину — who (або that). Which — для речей, а what у такому реченні не вживають."},{"type":"choice","q":"I don't like films ___ are too long.","uk":"Я не люблю фільми, які надто довгі.","opts":["who","which","what"],"a":1,"why":"Про речі — which (або that). Who — лише про людей, what сюди не ставлять."},{"type":"choice","q":"This is the hotel ___ we stayed.","uk":"Це готель, де ми зупинялися.","opts":["where","which","who"],"a":0,"why":"Місце, де щось відбувається, — where. З which бракувало б прийменника: the hotel which we stayed in."},{"type":"input","q":"Do you know the man ___ is talking to Tom?","uk":"Ти знаєш чоловіка, який розмовляє з Томом?","a":["who","that"],"why":"Про людину — who або that. Пропустити не можна: одразу після пропуску дієслово is."},{"type":"input","q":"The bus ___ goes to Gorey leaves at six.","uk":"Автобус, який їде до Горі, відходить о шостій.","a":["that","which"],"why":"Про річ — that або which. Після пропуску одразу дієслово goes, тому слово потрібне."},{"type":"input","q":"The man ___ van was stolen called the police.","uk":"Чоловік, у якого вкрали фургон, викликав поліцію.","a":["whose"],"why":"«Чий», «у якого» — whose: the man whose van… Не плутай з who's (= who is)."},{"type":"choice","task":"У якому реченні that можна пропустити?","q":"","opts":["The girl that lives here is Kate.","The film that we watched was great.","The bus that goes to Dublin is late."],"a":1,"why":"Після that стоїть інший підмет (we), тому that можна прибрати: The film we watched. В інших реченнях одразу дієслово, і that потрібне."},{"type":"order","uk":"Чоловік, якого ми зустріли вчора, — мій бос.","words":["boss","we","the","is","met","my","man","yesterday"],"a":["The man we met yesterday is my boss.","My boss is the man we met yesterday."],"why":"Після the man іде інший підмет (we), тому who/that можна пропустити: the man + we met yesterday + is my boss."},{"type":"input","q":"Who's the girl you were talking ___?","uk":"Хто та дівчина, з якою ти розмовляв?","a":["to","with"],"why":"Прийменник у розмові йде в кінець: the girl you were talking to — «з якою ти розмовляв»."},{"type":"order","uk":"Це компанія, на яку я працюю.","words":["for","is","I","company","this","the","work"],"a":["This is the company I work for."],"why":"Прийменник for іде в кінець: the company I work for. Who/that/which тут пропущено."},{"type":"choice","q":"My sister, ___ lives in Dublin, is a nurse.","uk":"Моя сестра, яка живе в Дубліні, медсестра.","opts":["who","that","what"],"a":0,"why":"Частина з комами — додаткова інформація. У ній про людей лише who: that після коми не ставлять."},{"type":"choice","q":"Tom passed his driving test, ___ was great news.","uk":"Том склав іспит з водіння, що було чудовою новиною.","opts":["which","what","who"],"a":0,"why":"Which після коми може стосуватися всього речення: «що було чудовою новиною». What тут не вживають."}],"section":"complex"},"gerund-infinitive":{"id":"gerund-infinitive","level":"B1","title":"Gerund or infinitive","uk":"-ing чи to + дієслово","summary":"коли -ing, а коли to: I enjoy working, I want to work","minutes":9,"blocks":[{"t":"p","text":"Коли одне дієслово йде за іншим (люблю **працювати**, хочу **піти**), друге стоїть або у **формі з -ing** (working), або з **to** (to work). Українською в обох випадках «працювати», тому вибір доводиться **запам'ятовувати**: він залежить від **першого** дієслова."},{"t":"ex","items":[["I **enjoy working** outside.","Мені подобається працювати надворі."],["I **want to work** outside.","Я хочу працювати надворі."],["We **finished plastering** at five.","Ми закінчили штукатурити о п'ятій."],["We **decided to stop** at five.","Ми вирішили зупинитися о п'ятій."]]},{"t":"p","text":"У підручниках ці форми називають так: **gerund** (герундій) — форма з -ing, яка працює майже як іменник (smoking — «куріння»); **infinitive** (інфінітив) — to + початкова форма дієслова (to work — «працювати»)."},{"t":"h","text":"Після цих дієслів — -ing"},{"t":"table","head":["Дієслово","Значення"],"rows":[["enjoy","подобатися, любити (щось робити)"],["finish","закінчити"],["mind","бути проти (Do you mind…?)"],["avoid","уникати"],["keep","постійно, не припиняти"],["suggest","пропонувати"],["practise","тренуватися, практикувати"],["miss","сумувати за, бракувати"],["consider","обмірковувати, думати про"],["give up","кинути (звичку)"],["can't stand","терпіти не можу"]]},{"t":"ex","items":[["Do you **mind waiting** a few minutes?","Ти не проти почекати кілька хвилин?"],["He **keeps making** the same mistake.","Він постійно робить ту саму помилку."],["Kate **suggested going** to Gorey for lunch.","Кейт запропонувала поїхати на обід у Горі."],["I **can't stand working** in the rain.","Терпіти не можу працювати під дощем."],["Mick **gave up smoking** last year.","Мік кинув курити торік."],["Are you **considering moving** to Dublin?","Ти думаєш про переїзд у Дублін?"]]},{"t":"tip","text":"**Go** + -ing — для занять і розваг: go **swimming**, go **shopping**, go **fishing**. We went **fishing** at the weekend."},{"t":"h","text":"Правопис форми з -ing"},{"t":"table","head":["Дієслово","З -ing","Що змінюється"],"rows":[["work","work**ing**","просто + -ing"],["make","mak**ing**","німе e зникає"],["stop","stop**ping**","подвоюємо p"],["forget","forget**ting**","подвоюємо t"],["lie","l**ying**","ie → y"]]},{"t":"tip","text":"Останню приголосну подвоюємо, коли слово закінчується на **одну голосну + одну приголосну** і наголос падає саме на цей склад: stop → stopping, get → getting, forget → forgetting. Але visit → visiting (наголос на початку), а w, x, y не подвоюємо: fix → fixing, play → playing. У британському правописі кінцеве l після однієї голосної подвоюють і без наголосу: travel → travelling."},{"t":"h","text":"Після цих дієслів — to + дієслово"},{"t":"table","head":["Дієслово","Значення"],"rows":[["want","хотіти"],["need","потребувати, треба"],["decide","вирішити"],["hope","сподіватися"],["plan","планувати"],["promise","обіцяти"],["agree","погодитися"],["refuse","відмовитися"],["learn","навчитися"],["manage","зуміти, встигнути"],["afford","дозволити собі (за гроші)"],["would like","хотів би"]]},{"t":"ex","items":[["I **need to buy** new work boots.","Мені треба купити нові робочі черевики."],["Sarah **promised to call** me.","Сара пообіцяла мені подзвонити."],["The boss **refused to pay** us extra.","Бос відмовився нам доплатити."],["We **managed to finish** on time.","Ми встигли закінчити вчасно."],["I can't **afford to buy** a new van.","Я не можу дозволити собі купити новий фургон."],["Andrii is **learning to drive**.","Андрій вчиться водити."],["I**'d like to book** a table for two.","Я хотів би забронювати столик на двох."],["I **want you to help** me with the ceiling.","Я хочу, щоб ти допоміг мені зі стелею."]]},{"t":"tip","text":"**Хочу, щоб ти…** — англійською без that і без окремого «щоб»: **want** + хтось + **to** + дієслово. I want **you to help** me, а не I want that you help me. Так само **would like**, **ask**, **tell**: The boss asked **us to stay** late."},{"t":"tip","text":"Підказка: після дієслів з **to** дія зазвичай ще **попереду** — бажання, план, рішення, обіцянка (want, plan, decide, promise). Після дієслів з **-ing** дія часто вже **є або була** (enjoy, finish, keep, give up). Це не залізне правило, але допомагає здогадатися."},{"t":"h","text":"Обидва варіанти: like, love, hate, start, begin"},{"t":"p","text":"Після **like, love, hate, start, begin** можна і -ing, і to — значення майже однакове. Але **would like** (хотів би) — завжди з to."},{"t":"ex","items":[["It **started raining**.","Почався дощ."],["It **started to rain**.","Почався дощ."],["I **love working** with my hands.","Я люблю працювати руками."],["Tom **hates getting** up early.","Том ненавидить рано вставати."]]},{"t":"h","text":"Stop, remember, forget, try: різне значення"},{"t":"table","head":["Дієслово","+ -ing","+ to"],"rows":[["stop","кинути, припинити","зупинитися, щоб…"],["remember","пам'ятати, що робив","не забути зробити"],["forget","забути, що робив","забути зробити"],["try","спробувати (як варіант)","намагатися, старатися"]]},{"t":"ex","items":[["I **stopped smoking** last year.","Я кинув курити торік."],["The driver **stopped to smoke**.","Водій зупинився покурити."],["**Remember to lock** the van.","Не забудь замкнути фургон."],["I **remember locking** the van.","Я пам'ятаю, що замикав фургон."],["Don't **forget to bring** your gloves.","Не забудь узяти рукавиці."],["If the mix is too thick, **try adding** some water.","Якщо розчин надто густий, спробуй додати трохи води."],["I **tried to lift** the board, but it was too heavy.","Я намагався підняти лист гіпсокартону, але він був заважкий."]]},{"t":"h","text":"Після прийменника — завжди -ing"},{"t":"p","text":"**Прийменники** — короткі слова на зразок **in, on, at, for, about, of, before, after, without**. Якщо після прийменника йде дієслово, воно **завжди** з -ing: не з to і не в початковій формі."},{"t":"ex","items":[["Tom is **interested in becoming** an electrician.","Том хотів би стати електриком."],["Thanks **for coming**.","Дякую, що прийшов."],["Wash your hands **before eating**.","Мий руки перед їжею."],["He left **without saying** goodbye.","Він пішов, не попрощавшись."],["I'm **tired of waiting**.","Я втомився чекати."],["**How about going** to the cinema?","Може, сходимо в кіно?"]]},{"t":"tip","text":"Пастка: у виразі **look forward to** (чекати з нетерпінням) to — це прийменник, тому далі -ing: I'm looking forward to **seeing** you."},{"t":"h","text":"To — «щоб» (мета)"},{"t":"p","text":"Щоб сказати, **навіщо** щось робиш, ставимо просто **to** + дієслово. Українське «щоб» або «для того, щоб» — це **to**. Не **for to** і не **for** + дієслово."},{"t":"ex","items":[["Olena came to Ireland **to work**.","Олена приїхала до Ірландії працювати."],["I went to Lidl **to buy** some bread.","Я пішов у Lidl купити хліба."],["We need a ladder **to reach** the ceiling.","Нам потрібна драбина, щоб дістати до стелі."]]},{"t":"tip","text":"**For** + іменник теж буває про мету: I went to Lidl **for** bread. А про призначення речі кажуть **for** + -ing: This knife is **for cutting** plasterboard."},{"t":"h","text":"-ing як підмет"},{"t":"p","text":"**Підмет** — це хто або що виконує дію, про кого чи про що речення. Коли підметом є сама дія, англійською беремо форму з -ing. Українською тут зазвичай «курити», «працювати» або іменник."},{"t":"ex","items":[["**Smoking** is bad for you.","Курити шкідливо."],["**Working** at heights can be dangerous.","Працювати на висоті буває небезпечно."],["**Learning** a language takes time.","Вивчення мови потребує часу."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I enjoy to work outside.","right":"I enjoy working outside.","why":"Після enjoy — завжди -ing."},{"t":"mistake","wrong":"I want going home.","right":"I want to go home.","why":"Після want — to + дієслово."},{"t":"mistake","wrong":"I'm learning English for to get a better job.","right":"I'm learning English to get a better job.","why":"Мету («щоб») передає просто to. For to так не кажуть."},{"t":"mistake","wrong":"Thanks for help me.","right":"Thanks for helping me.","why":"Після прийменника (for) — форма з -ing."},{"t":"mistake","wrong":"I'm interested to learn Spanish.","right":"I'm interested in learning Spanish.","why":"Interested вимагає прийменника in, а після прийменника — -ing."},{"t":"mistake","wrong":"We decided don't work on Sunday.","right":"We decided not to work on Sunday.","why":"Заперечення перед to + дієслово — просто not: not to work. Don't тут не ставимо. З -ing так само: sorry for not calling."},{"t":"mistake","wrong":"I stopped to smoke last year.","right":"I stopped smoking last year.","why":"Кинути звичку — stop + -ing. Stop + to означає «зупинитися, щоб…»."}],"tasks":[{"type":"choice","q":"I really enjoy ___ in the garden.","uk":"Мені дуже подобається працювати в саду.","opts":["working","to work","work"],"a":0,"why":"Після enjoy — завжди форма з -ing."},{"type":"choice","q":"I'm saving money ___ a car.","uk":"Я відкладаю гроші, щоб купити машину.","opts":["to buy","for buy","for to buy"],"a":0,"why":"Мета («щоб») — просто to + дієслово. For + дієслово чи for to так не кажуть."},{"type":"choice","q":"Thanks for ___ me yesterday.","uk":"Дякую, що вчора мені допоміг.","opts":["helping","help","to help"],"a":0,"why":"For — прийменник, а після прийменника дієслово завжди з -ing."},{"type":"choice","q":"I stopped ___ two years ago, and now I feel much better.","uk":"Я кинув курити два роки тому, і тепер почуваюся набагато краще.","opts":["smoking","to smoke","smoke"],"a":0,"why":"Кинути звичку — stop + -ing. Stopped to smoke означало б «зупинився, щоб покурити»."},{"type":"choice","q":"Don't forget ___ the van when you leave.","uk":"Не забудь замкнути фургон, коли йтимеш.","opts":["to lock","locking","lock"],"a":0,"why":"«Не забути зробити» — forget + to. Forget + -ing — забути те, що вже колись робив."},{"type":"choice","q":"___ too much coffee is bad for you.","uk":"Пити забагато кави шкідливо.","opts":["Drinking","Drink","Drinks"],"a":0,"why":"Дія тут — підмет речення, тому форма з -ing: Drinking."},{"type":"input","q":"Would you mind ___ (open) the window?","uk":"Ти не міг би відчинити вікно?","a":["opening"],"why":"Після mind — форма з -ing. Would you mind opening…? — ввічливе прохання."},{"type":"input","q":"We finally managed ___ (find) a flat in Gorey.","uk":"Нарешті ми зуміли знайти квартиру в Горі.","a":["to find"],"why":"Після manage (зуміти) — to + дієслово: to find."},{"type":"input","q":"Mick keeps ___ (forget) his keys.","uk":"Мік постійно забуває ключі.","a":["forgetting"],"why":"Після keep — форма з -ing. У forget наголос на останньому складі -get, тому t подвоюємо: forgetting."},{"type":"input","q":"Sarah can't afford ___ (go) on holiday this year.","uk":"Сара не може дозволити собі поїхати у відпустку цього року.","a":["to go"],"why":"Після afford (дозволити собі) — to + дієслово: to go."},{"type":"order","uk":"Він вирішив кинути курити.","words":["he","decided","to","give","up","smoking"],"a":["He decided to give up smoking.","He decided to give smoking up."],"why":"Після decide — to + дієслово (to give up), а після give up — форма з -ing (smoking)."},{"type":"order","uk":"Тобі було б цікаво працювати по суботах?","words":["would","you","be","interested","in","working","on","Saturdays"],"a":["Would you be interested in working on Saturdays?"],"why":"Після interested стоїть прийменник in, тому далі -ing: working. Питання починається з would."}],"section":"complex"},"linking-words":{"id":"linking-words","level":"B1","title":"Linking words","uk":"Сполучники: because, although, however","summary":"з'єднуємо думки: so, because, although, despite, however","minutes":9,"blocks":[{"t":"p","text":"**Linking words** — слова, що з'єднують думки: «і», «але», «бо», «хоча», «щоб». З ними ти говориш не окремими шматками (I was tired. I went to work.), а цілими реченнями: I was tired, **but** I went to work. Головне в цій темі — що стоїть **після** такого слова: ціле речення чи лише іменник. Ціле речення має **підмет** (хто або що виконує дію) і дієслово: **it was** cold, **he is** tired."},{"t":"h","text":"Найпростіші: and, but, or, so"},{"t":"table","head":["Слово","Значення","Приклад"],"rows":[["**and**","і, та","Tom **and** Mick"],["**but**","але","old **but** good"],["**or**","або, чи","today **or** tomorrow"],["**so**","тому, отже","It's late, **so** let's go."]]},{"t":"ex","items":[["I finished the wall **and** went home.","Я закінчив стіну й пішов додому."],["The work is hard, **but** the pay is good.","Робота важка, але платять добре."],["Do you want tea **or** coffee?","Тобі чай чи каву?"],["It was raining, **so** we worked inside.","Ішов дощ, тому ми працювали всередині."]]},{"t":"tip","text":"Не плутай **so** і **because**. So — наслідок (що з цього вийшло), because — причина (чому). Те саме двома способами: I was tired, **so** I went to bed. = I went to bed **because** I was tired."},{"t":"h","text":"because чи because of"},{"t":"rule","title":"Причина","lines":["**because** + речення: because **it was raining**","**because of** + іменник: because of **the rain**"]},{"t":"ex","items":[["We stopped **because** it was raining.","Ми зупинилися, бо йшов дощ."],["We stopped **because of** the rain.","Ми зупинилися через дощ."],["He was late **because of** the traffic.","Він запізнився через затори."],["I can't come **because** I'm working on Saturday.","Я не можу прийти, бо працюю в суботу."]]},{"t":"tip","text":"Підказка з української: «бо», «тому що» + речення → **because**; «через» + іменник → **because of**. В офіційних листах замість because часто пишуть **as** або **since** («оскільки»): **As** it was late, we stopped."},{"t":"h","text":"Хоча й незважаючи: although, despite"},{"t":"p","text":"Для «хоча» й «незважаючи на» є дві групи слів. **Although** і **even though** («хоча», «хоч і») — після них ціле речення. Even though звучить трохи сильніше. **Despite** і **in spite of** («незважаючи на», «попри») — після них іменник або форма з -ing (working, being), але не ціле речення."},{"t":"rule","title":"Протиставлення","lines":["**although / even though** + речення","**despite / in spite of** + іменник","**despite / in spite of** + форма з -ing"]},{"t":"ex","items":[["**Although** it was cold, we finished the job.","Хоча було холодно, ми закінчили роботу."],["She still smokes **even though** she knows it's bad for her.","Вона досі курить, хоч і знає, що це їй шкодить."],["**Despite** the cold, we finished the job.","Незважаючи на холод, ми закінчили роботу."],["We worked outside **in spite of** the rain.","Ми працювали надворі попри дощ."],["**Despite** working all day, he wasn't tired.","Незважаючи на те, що працював цілий день, він не втомився."]]},{"t":"tip","text":"Хочеш після «незважаючи на те, що» поставити ціле речення? Бери **although** або кажи **despite the fact that**: Despite the fact that it was cold, we worked outside. Довше, але правильно."},{"t":"tip","text":"**Пастка «хоча…, але…».** Українською кажемо «Хоча йшов дощ, але ми працювали». Англійською — **або although, або but**, не обидва разом: **Although** it was raining, we worked. Або: It was raining, **but** we worked."},{"t":"h","text":"however і though"},{"t":"p","text":"**However** («однак», «проте») з'єднує два окремі речення. Зазвичай воно стоїть на початку другого речення, після крапки, а після нього кома. **But** з'єднує дві частини одного речення, і кома стоїть перед ним. However звучить офіційніше (листи, повідомлення босу), а в розмові частіше кажуть but або **though** у кінці речення: It's expensive. It's good, **though**. — Дорого. Зате добре."},{"t":"rule","title":"Порівняй","lines":["It's old, **but** it works.","It's old. **However,** it works."]},{"t":"ex","items":[["The house is small. **However**, the garden is big.","Будинок маленький. Однак сад великий."],["We wanted to finish today. **However**, the plaster isn't dry yet.","Ми хотіли закінчити сьогодні. Проте штукатурка ще не висохла."],["It's a long drive. The pay is good, **though**.","Їхати далеко. Зате платять добре."]]},{"t":"h","text":"Мета: to, in order to, so that"},{"t":"p","text":"Щоб сказати, **навіщо** ти щось робиш («щоб»), найчастіше вистачає **to** + початкова форма дієслова (як у словнику: work, buy, go). **In order to** — те саме, тільки офіційніше. **So that** — коли далі ціле речення зі своїм підметом, часто з can, could або will. Через so that найпростіше сказати й «щоб не…»: so that I **don't** oversleep («щоб не проспати»). У розмові that часто пропускають: so I don't oversleep."},{"t":"rule","title":"«Щоб»","lines":["**to** + дієслово: I came **to help**.","**in order to** + дієслово (офіційніше)","**so that** + речення: so that **he can** sleep"]},{"t":"ex","items":[["I went to Lidl **to buy** some milk.","Я пішов у Lidl, щоб купити молока."],["We start early **in order to** finish by three.","Ми починаємо рано, щоб закінчити до третьої."],["Speak slowly **so that** everyone can understand.","Говори повільно, щоб усі могли зрозуміти."],["Open the windows **so that** the plaster dries faster.","Відчини вікна, щоб штукатурка швидше висохла."],["I set two alarms **so that** I don't oversleep.","Я ставлю два будильники, щоб не проспати."]]},{"t":"tip","text":"Після **for** стоїть іменник: I went out **for** a coffee. Якщо далі дієслово — тільки **to**: I went out **to get** a coffee. «For buy», «for to buy» — помилка."},{"t":"h","text":"also, too, as well — «теж, також»"},{"t":"p","text":"Усі три означають «теж, також», але стоять у різних місцях. **Too** і **as well** — у кінці речення. **Also** — у середині: перед звичайним дієсловом, але після am, is, are і після допоміжного дієслова (can, will, have). У запереченні замість too кажуть **either**: «теж не»."},{"t":"ex","items":[["I **also** do tiling.","Я також кладу плитку."],["She's **also** from Ukraine.","Вона теж з України."],["I'm tired. — I'm tired **too**.","Я втомився. — Я теж."],["Can I come **as well**?","Можна мені теж прийти?"],["I don't smoke. — I don't smoke **either**.","Я не курю. — Я теж не курю."]]},{"t":"h","text":"while і whereas"},{"t":"p","text":"**While** і **whereas** протиставляють дві речі: «тоді як», «а». Whereas звучить офіційніше. While має ще одне значення: «поки», «у той час як»."},{"t":"ex","items":[["Tom likes tea, **while** Sarah prefers coffee.","Том любить чай, а Сара — каву."],["Dublin is expensive, **whereas** Wexford is much cheaper.","Дублін дорогий, тоді як Вексфорд набагато дешевший."],["He called **while** I was driving.","Він подзвонив, поки я був за кермом."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Although it was raining, but we worked.","right":"Although it was raining, we worked.","why":"Although і but разом не вживаємо, хоч українською й кажемо «хоча…, але…». Залиш одне з них."},{"t":"mistake","wrong":"Despite it was cold, we worked outside.","right":"Although it was cold, we worked outside.","why":"Після despite не буває цілого речення. Або although it was cold, або despite the cold."},{"t":"mistake","wrong":"Despite of the rain, we worked outside.","right":"Despite the rain, we worked outside.","why":"Після despite of не буває, хоч українською й кажемо «незважаючи на». Of є лише в in spite of: in spite of the rain."},{"t":"mistake","wrong":"We stopped because of it was late.","right":"We stopped because it was late.","why":"Because of — лише перед іменником (because of the rain). Перед цілим реченням просто because."},{"t":"mistake","wrong":"I also like it too.","right":"I like it too.","why":"Also і too означають одне й те саме, тож досить одного: I also like it або I like it too."},{"t":"mistake","wrong":"I went to Lidl for buy milk.","right":"I went to Lidl to buy milk.","why":"«Щоб» + дієслово — це to. Після for стоїть іменник: for some milk."}],"tasks":[{"type":"choice","q":"I was hungry, ___ I made a sandwich.","uk":"Я був голодний, тому зробив собі бутерброд.","opts":["so","because","but"],"a":0,"why":"«Тому» — so, воно показує наслідок. Because стоїть перед причиною (I made a sandwich because I was hungry), а but означає «але»."},{"type":"choice","q":"He went to work ___ he was sick.","uk":"Він пішов на роботу, хоча був хворий.","opts":["although","despite","because of"],"a":0,"why":"Після пропуску ціле речення (he was sick), тому although. Despite і because of ставимо лише перед іменником або формою з -ing."},{"type":"input","q":"I can't come tonight ___ I'm working late.","uk":"Я не можу прийти сьогодні ввечері, бо працюю допізна.","a":["because","as","since"],"why":"Причина — ціле речення (I'm working late), тому because. Because of тут не підійде: після нього лише іменник."},{"type":"order","uk":"Ми запізнилися через затори.","words":["late","the","because","we","traffic","were","of"],"a":["We were late because of the traffic.","Because of the traffic, we were late."],"why":"«Через» + іменник (the traffic) — because of. Цю частину можна поставити і в кінці, і на початку речення."},{"type":"input","q":"We finished the job on time ___ the rain.","uk":"Ми закінчили роботу вчасно, незважаючи на дощ.","a":["despite","in spite of","regardless of"],"why":"Перед іменником (the rain) — despite або in spite of. Although тут не підійде: після нього потрібне ціле речення."},{"type":"choice","q":"Despite ___ twelve hours, Andrii wasn't tired.","uk":"Незважаючи на те, що працював дванадцять годин, Андрій не втомився.","opts":["he worked","working","work"],"a":1,"why":"Після despite — іменник або форма з -ing: despite working. Ціле речення (he worked) після despite не ставимо, для нього є although."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Хоча було пізно, ми працювали далі.","opts":["Although it was late, but we kept working.","Although it was late, we kept working.","Despite it was late, we kept working."],"a":1,"why":"Although і but разом не вживаємо, а після despite не буває цілого речення. Правильно лише although без but."},{"type":"choice","q":"The job pays well. ___, it's a long way from home.","uk":"Робота добре оплачується. Однак вона далеко від дому.","opts":["However","Although","Despite"],"a":0,"why":"However починає нове речення після крапки, і після нього кома. Although і despite не стоять окремо з комою: після них іде речення або іменник."},{"type":"input","q":"I'm saving money ___ buy a car.","uk":"Я відкладаю гроші, щоб купити машину.","a":["to","in order to","so as to","so that I can","so I can","to be able to"],"why":"«Щоб» + дієслово — to (офіційніше in order to). For тут не підійде: після for стоїть іменник, а не дієслово."},{"type":"input","q":"I'll write it down ___ I don't forget.","uk":"Я запишу, щоб не забути.","a":["so that","so","in order that"],"why":"Після «щоб» тут ціле речення зі своїм підметом (I don't forget), тому so that (у розмові просто so). To ставимо лише перед дієсловом без підмета."},{"type":"choice","q":"Tom doesn't eat meat, and Sarah doesn't ___.","uk":"Том не їсть м'яса, і Сара теж не їсть.","opts":["too","either","also"],"a":1,"why":"У запереченні «теж не» — either. Too і also вживаємо у ствердженнях."},{"type":"order","uk":"Він пішов у спортзал, хоч і був утомлений.","words":["even","he","the","tired","went","though","to","he","gym","was"],"a":["He went to the gym even though he was tired.","Even though he was tired, he went to the gym."],"why":"Even though («хоч і») + ціле речення (he was tired). Його можна поставити в кінці або на початку, тоді після цієї частини кома."}],"section":"complex"},"indirect-questions":{"id":"indirect-questions","level":"B1","title":"Indirect questions","uk":"Ввічливі непрямі питання","summary":"ввічливо спитати: Can you tell me where the station is?","minutes":6,"blocks":[{"t":"p","text":"Пряме питання (Where is the station?) — нормальне, але в незнайомої людини, у магазині, по телефону чи в боса ввічливіше спитати **непрямо**: спершу м'який початок (Can you tell me…, Do you know…), а потім саме питання. Головне правило: у другій частині **звичайний порядок слів**, як у стверджувальному реченні."},{"t":"ex","items":[["Where **is** the station?","Де вокзал?"],["Can you tell me where the station **is**?","Не підкажете, де вокзал?"],["What time **does** Lidl open?","О котрій відчиняється «Лідл»?"],["Do you know what time Lidl **opens**?","Ви не знаєте, о котрій відчиняється «Лідл»?"]]},{"t":"tip","text":"Чому це ввічливіше: ти не вимагаєш відповіді, а питаєш, чи людина знає або чи може підказати. Українською так само: «Не підкажете, де вокзал?» звучить м'якше за «Де вокзал?». Зі знайомими колегами можна й прямо."},{"t":"h","text":"Ввічливий початок"},{"t":"list","items":["**Can you tell me** …? — Скажіть / підкажіть, будь ласка…","**Could you tell me** …? — те саме, ще ввічливіше","**Do you know** …? — Ви не знаєте…?","**Do you have any idea** …? — Ви часом не знаєте…?","**I wonder** … — Цікаво… (це не питання, тому в кінці крапка)"]},{"t":"h","text":"Порядок слів: спершу підмет"},{"t":"p","text":"Після питального слова (where, what, when, how much…) ставимо **підмет** — хто або що виконує дію (the station, he, you), а вже потім дієслово. Is, are, can, will переходять **за** підмет."},{"t":"rule","title":"Порядок","lines":["Where **is the station**?","→ Can you tell me where **the station is**?","When **will he** be back?","→ Do you know when **he will** be back?"]},{"t":"ex","items":[["Could you tell me where the toilets **are**?","Підкажіть, будь ласка, де туалети?"],["Do you know when he**'ll** be back?","Ви не знаєте, коли він повернеться?"],["Can you tell me how long it **will** take?","Скажіть, скільки часу це займе?"]]},{"t":"h","text":"Без do, does, did"},{"t":"p","text":"У прямих питаннях у Present Simple і Past Simple є **допоміжне дієслово** do, does або did — службове слово, яке будує питання. У непрямому питанні воно **зникає**, а основне дієслово має звичайну форму: -s після he, she, it або **V2** для минулого (друга форма: went, bought, arrived)."},{"t":"table","head":["Пряме питання","Непряме"],"rows":[["What time **does** Lidl open?","…what time Lidl **opens**?"],["Where **does** he live?","…where he **lives**?"],["What **do** you need?","…what you **need**?"],["When **did** the van arrive?","…when the van **arrived**?"],["Where **did** Tom go?","…where Tom **went**?"]]},{"t":"ex","items":[["Could you tell me how much this drill **costs**?","Скажіть, будь ласка, скільки коштує цей дриль?"],["Do you know where Tom **went**?","Ти не знаєш, куди пішов Том?"],["I wonder why she **left** so early.","Цікаво, чому вона пішла так рано."]]},{"t":"h","text":"Питання «так чи ні»: if, whether"},{"t":"p","text":"Якщо питального слова немає і відповідь — «так» або «ні», додаємо **if** або **whether** («чи»). Do, does, did так само зникають."},{"t":"rule","title":"Так / ні","lines":["**Is** he coming?","→ Do you know **if** he**'s** coming?","**Does** he work here?","→ Can you tell me **if** he **works** here?"]},{"t":"ex","items":[["Do you know **if** the shop is open on Sunday?","Ви не знаєте, чи магазин працює в неділю?"],["Can you tell me **whether** there's a bus to Gorey?","Не підкажете, чи є автобус до Горі?"],["Do you know **if** I can park here?","Ви не знаєте, чи можна тут паркуватися?"],["I wonder **if** they're hiring.","Цікаво, чи вони набирають людей."]]},{"t":"tip","text":"Якщо питальне слово саме є підметом (who? what?), порядок і так звичайний, нічого не міняємо: Who called? → Do you know **who called**? What happened? → Can you tell me **what happened**?"},{"t":"h","text":"Знак питання чи крапка"},{"t":"p","text":"Знак питання ставимо, коли **вся фраза** — питання: Can you tell me…? Do you know…? Після **I wonder** (цікаво), **I'd like to know** (я хотів би знати) і **I don't know** (я не знаю) — крапка: це не питання, а звичайне речення. Порядок слів після них той самий: спершу підмет."},{"t":"ex","items":[["I wonder where he **is**.","Цікаво, де він."],["I'd like to know why the van **isn't** ready.","Я хотів би знати, чому фургон не готовий."],["I don't know where he **lives**.","Я не знаю, де він живе."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Can you tell me where is the station?","right":"Can you tell me where the station is?","why":"Після Can you tell me порядок слів як у звичайному реченні: спершу підмет (the station), потім is."},{"t":"mistake","wrong":"Do you know what time does the bus leave?","right":"Do you know what time the bus leaves?","why":"Do вже є на початку (Do you know). У другій частині does зникає, а -s повертається до дієслова: leaves."},{"t":"mistake","wrong":"I wonder where is he.","right":"I wonder where he is.","why":"Після I wonder — звичайний порядок слів і крапка в кінці."},{"t":"mistake","wrong":"Can you tell me does he work here?","right":"Can you tell me if he works here?","why":"Питання «так/ні» всередині іншого вводимо через if або whether, без does, а дієслово отримує -s."}],"tasks":[{"type":"choice","task":"Як найввічливіше спитати незнайому людину?","q":"","opts":["Where's the toilet?","Could you tell me where the toilet is?","Tell me where the toilet is."],"a":1,"why":"Непряме питання з Could you tell me… звучить найм'якше: ти не вимагаєш, а просиш підказати."},{"type":"choice","q":"Can you tell me where ___?","uk":"Не підкажете, де пошта?","opts":["is the post office","the post office is","does the post office"],"a":1,"why":"Після Can you tell me — звичайний порядок слів: спершу підмет (the post office), потім is."},{"type":"input","q":"Could you tell me where the changing rooms ___?","uk":"Підкажіть, будь ласка, де роздягальні?","a":["are"],"why":"У непрямому питанні дієслово стоїть після підмета, у кінці. Changing rooms — множина, тому are."},{"type":"choice","q":"Do you know what time the bus ___?","uk":"Ви не знаєте, о котрій відходить автобус?","opts":["leaves","does leave","leave"],"a":0,"why":"Do вже є на початку (Do you know). У другій частині does немає, а дієслово отримує -s: the bus leaves."},{"type":"input","q":"Do you know where Tom ___ (live)?","uk":"Ти не знаєш, де живе Том?","a":["lives","is living"],"why":"Без does: Tom — це він, тому live отримує -s, як у звичайному реченні: Tom lives."},{"type":"choice","q":"Do you know ___ Kate is working tomorrow?","uk":"Ти не знаєш, чи Кейт завтра працює?","opts":["if","what","does"],"a":0,"why":"Питання «так/ні» («чи працює?») у непрямій формі вводимо через if або whether."},{"type":"input","q":"Can you tell me ___ this train stops in Arklow?","uk":"Не підкажете, чи зупиняється цей потяг в Арклоу?","a":["if","whether"],"why":"«Чи» в непрямому питанні — if або whether. Does зникло, тому stops з -s."},{"type":"choice","q":"Do you know what time ___?","uk":"Ти не знаєш, о котрій пішов Мік?","opts":["did Mick leave","Mick left","Mick did leave"],"a":1,"why":"Did у непрямому питанні зникає, а дієслово стає в минулому часі (V2): Mick left."},{"type":"input","q":"Do you know how much Sarah ___ (pay) for her car?","uk":"Ти не знаєш, скільки Сара заплатила за машину?","a":["paid","has paid"],"why":"Без did: дієслово у V2, як у звичайному реченні: Sarah paid. Pay неправильне: pay – paid – paid."},{"type":"choice","task":"Яке речення правильне?","q":"","opts":["I wonder why she is angry?","I wonder why she is angry.","I wonder why is she angry."],"a":1,"why":"Після I wonder — звичайний порядок слів (she is). І це не питання, а думка («цікаво…»), тому в кінці крапка."},{"type":"order","uk":"Ви не знаєте, де він працює?","words":["works","know","he","do","where","you"],"a":["Do you know where he works?"],"why":"Do стоїть лише на початку (Do you know). Далі звичайний порядок: where + he + works, без does."},{"type":"order","uk":"Цікаво, чи потрібні їм ще штукатури.","words":["need","wonder","they","more","I","if","plasterers"],"a":["I wonder if they need more plasterers."],"why":"I wonder + if («чи») + підмет (they) + дієслово. Це не питання, тому в кінці крапка."}],"section":"complex"},"question-tags":{"id":"question-tags","level":"B1","title":"Question tags and short answers","uk":"Хвостики-питання: isn't it?, don't you?","summary":"хвостики isn't it?, don't you? і відповіді So do I, Neither do I","minutes":8,"blocks":[{"t":"p","text":"**Question tag** — короткий «хвостик» у кінці речення, як наше «правда?», «так?», «еге ж?». Ним просять підтвердити або просто підтримують розмову. В Ірландії й Британії їх чуєш щодня. Можна сказати й «…, right?», але з хвостиками звучиш природніше й ввічливіше."},{"t":"ex","items":[["It's cold today, **isn't it**?","Сьогодні холодно, правда?"],["You're from Ukraine, **aren't you**?","Ти з України, так?"],["You don't smoke, **do you**?","Ти ж не куриш?"]]},{"t":"h","text":"Як утворити хвостик"},{"t":"rule","title":"Формула","lines":["речення, + **допоміжне дієслово** + займенник?","ствердження → **заперечний** хвостик","заперечення → **стверджувальний** хвостик"]},{"t":"p","text":"**Допоміжне дієслово** — службове слово, яке допомагає будувати час, питання й заперечення: am, is, are, was, were, do, does, did, have, has, will, а також can, could, should. Беремо **те саме** допоміжне, що є в реченні, і ставимо після нього займенник. Ім'я замінюємо займенником: Tom → he, the van → it. Заперечний хвостик завжди скорочений: **isn't it**, а не is not it."},{"t":"table","head":["Речення","Хвостик"],"rows":[["She **is** at work,","**isn't** she?"],["They **were** late,","**weren't** they?"],["You **can** drive,","**can't** you?"],["Tom **will** come,","**won't** he?"],["You **have** finished,","**haven't** you?"],["He **isn't** here,","**is** he?"],["You **can't** swim,","**can** you?"]]},{"t":"h","text":"Немає допоміжного? Бери do, does, did"},{"t":"p","text":"У стверджувальних реченнях Present Simple і Past Simple допоміжного дієслова не видно: You live here. He called. Тоді в хвостику з'являється **do**, **does** або **did** — так само, як у питанні."},{"t":"table","head":["Речення","Хвостик"],"rows":[["You **live** here,","**don't** you?"],["She **works** in Gorey,","**doesn't** she?"],["He **called** you,","**didn't** he?"],["They **don't** know,","**do** they?"],["Tom **didn't** pay,","**did** he?"]]},{"t":"ex","items":[["You work with Mick, **don't you**?","Ти працюєш з Міком, так?"],["Kate lives in Gorey, **doesn't she**?","Кейт живе в Горі, правда?"],["The bus left at six, **didn't it**?","Автобус поїхав о шостій, так?"],["You didn't see my keys, **did you**?","Ти ж не бачив моїх ключів?"]]},{"t":"tip","text":"**Have** без got (має, обідає, приймає душ) — звичайне дієслово, тож хвостик з do: She **has** a van, **doesn't** she? А з have got — has: She**'s got** a van, **hasn't** she?"},{"t":"h","text":"Особливі випадки"},{"t":"table","head":["Речення","Хвостик"],"rows":[["**I'm** right,","**aren't I**?"],["**Let's** start,","**shall we**?"],["Close the door,","**will you**?"],["**There's** a problem,","**isn't there**?"],["He **never** helps,","**does** he?"],["**That's** your van,","**isn't it**?"]]},{"t":"list","items":["**I'm** → **aren't I?** В Ірландії почуєш і amn't I, але це місцева розмовна форма. Стандартно — aren't I.","**Let's** («давай») → завжди **shall we?**","Прохання у формі наказу → **will you?** Ввічливіше — **could you?**","**There is / there are** → у хвостику теж **there**: isn't there?","**never, nobody, nothing** роблять речення заперечним, тому хвостик стверджувальний: does he?","**this, that** у хвостику стають **it**, а **nobody, everyone** — **they**: Nobody called, did they?"]},{"t":"ex","items":[["I'm late again, **aren't I**?","Я знову запізнився, так?"],["Let's have a break, **shall we**?","Може, зробимо перерву?"],["Pass me that bucket, **will you**?","Подай-но мені те відро."],["There's a chemist near here, **isn't there**?","Тут поблизу є аптека, так?"],["Tom never helps, **does he**?","Том ніколи не допомагає, правда?"]]},{"t":"h","text":"Інтонація: питаю чи чекаю згоди"},{"t":"p","text":"Від інтонації залежить зміст. Голос іде **вниз** на хвостику — ти впевнений і просто чекаєш згоди: It's a lovely day, isn't it? ↘ Голос іде **вгору** — ти справді не знаєш і питаєш: You've got the keys, haven't you? ↗ Тобто: «Ключі ж у тебе? Бо я не певен»."},{"t":"h","text":"Як відповідати"},{"t":"p","text":"Відповідай за фактами, а не за формою хвостика: **Yes** — якщо так і є, **No** — якщо ні. Краще не просто Yes чи No, а коротка відповідь з тим самим допоміжним дієсловом."},{"t":"ex","items":[["You're Ukrainian, aren't you? — **Yes, I am.**","Ти ж українець? — Так."],["You don't smoke, do you? — **No, I don't.**","Ти ж не куриш? — Ні, не курю."],["Tom can drive, can't he? — **Yes, he can.**","Том уміє водити, так? — Так, уміє."]]},{"t":"tip","text":"Пастка: на «Ти ж не куриш?» українець часто каже «Так» у значенні «так, не курю». Англійською це **No, I don't**, бо ти не куриш. Yes, I do означало б «ні, курю»."},{"t":"h","text":"Я теж: So do I, Neither do I"},{"t":"p","text":"Щоб погодитися («я теж»), кажуть **So + допоміжне + I**. На заперечення («я теж ні») — **Neither + допоміжне + I**. Допоміжне беремо з речення співрозмовника, як у хвостику. У розмові можна простіше: **Me too** на ствердження, **Me neither** на заперечення."},{"t":"table","head":["Хтось каже","Ти погоджуєшся"],"rows":[["I'm tired.","**So am I.** / Me too."],["I like tea.","**So do I.** / Me too."],["I can swim.","**So can I.** / Me too."],["I went home early.","**So did I.** / Me too."],["I'm not hungry.","**Neither am I.** / Me neither."],["I don't smoke.","**Neither do I.** / Me neither."],["I can't drive.","**Neither can I.** / Me neither."]]},{"t":"tip","text":"Після so і neither спочатку допоміжне, потім I: **So do I**, а не So I do. Після neither дієслово стверджувальне: Neither **do** I, а не Neither don't I. **Nor do I** — те саме, що Neither do I."},{"t":"p","text":"Не погоджуєшся — скажи коротко: займенник і допоміжне з протилежним змістом."},{"t":"ex","items":[["I love Mondays. — Oh, **I don't**.","Я люблю понеділки. — А я ні."],["I can't swim. — **I can**.","Я не вмію плавати. — А я вмію."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"You work here, isn't it?","right":"You work here, don't you?","why":"Isn't it — не універсальне «правда?». Беремо допоміжне з речення: work — це Present Simple, тому don't you."},{"t":"mistake","wrong":"She's from Dublin, isn't it?","right":"She's from Dublin, isn't she?","why":"Займенник у хвостику відповідає підмету (хто або що виконує дію): she → isn't she."},{"t":"mistake","wrong":"I'm right, amn't I?","right":"I'm right, aren't I?","why":"Стандартно після I'm хвостик aren't I. Amn't I почуєш в Ірландії, але це місцева розмовна форма, сам кажи aren't I."},{"t":"mistake","wrong":"I don't like mushrooms. — Me too.","right":"I don't like mushrooms. — Me neither.","why":"На заперечення («я теж ні») — Me neither або Neither do I. Me too кажемо лише на ствердження."},{"t":"mistake","wrong":"I like football. — So I do.","right":"I like football. — So do I.","why":"У значенні «я теж» після so спочатку допоміжне, потім підмет: So do I."}],"tasks":[{"type":"choice","q":"It's cold today, ___?","uk":"Сьогодні холодно, правда?","opts":["isn't it","doesn't it","is not it"],"a":0,"why":"It's = It is. Ствердження з is → заперечний хвостик isn't it. Хвостик завжди скорочений: is not it не кажуть."},{"type":"choice","q":"Sarah lives in Wexford, ___?","uk":"Сара живе у Вексфорді, так?","opts":["isn't she","doesn't she","don't she"],"a":1,"why":"Present Simple: допоміжне does. Ствердження → заперечний хвостик, а Sarah — це she: doesn't she."},{"type":"input","q":"He called you yesterday, ___ he?","uk":"Він дзвонив тобі вчора, так?","a":["didn't"],"why":"Past Simple (called) — допоміжне did. Ствердження → заперечний хвостик: didn't he."},{"type":"input","q":"They can't come tomorrow, ___ they?","uk":"Вони ж не зможуть прийти завтра?","a":["can"],"why":"У реченні заперечення can't, тому хвостик стверджувальний з тим самим can: can they."},{"type":"choice","q":"I'm next, ___?","uk":"Я наступний, так?","opts":["aren't I","am not I","isn't I"],"a":0,"why":"Після I'm хвостик aren't I. Це виняток, його треба просто запам'ятати."},{"type":"choice","q":"Let's have a break, ___?","uk":"Може, зробимо перерву?","opts":["shall we","don't we","aren't we"],"a":0,"why":"Після Let's («давай») хвостик завжди shall we."},{"type":"input","q":"There's a Lidl in Gorey, ___ there?","uk":"У Горі ж є Lidl, так?","a":["isn't"],"why":"There is → у хвостику теж there: isn't there. It тут не ставимо."},{"type":"choice","q":"Mick never says no, ___?","uk":"Мік ніколи не відмовляє, правда?","opts":["doesn't he","does he","isn't he"],"a":1,"why":"Never робить речення заперечним, тому хвостик стверджувальний: does he."},{"type":"choice","q":"You don't smoke, do you? — ___","uk":"Ти ж не куриш? — Ні, не курю.","opts":["Yes, I do.","No, I don't.","Yes, I don't."],"a":1,"why":"Відповідаємо за фактами: не куриш — No, I don't. Yes, I do означало б «курю», а Yes з don't не поєднують."},{"type":"choice","q":"I'm really tired. — ___","uk":"Я дуже втомився. — Я теж.","opts":["So do I.","So am I.","Neither am I."],"a":1,"why":"У реченні співрозмовника am (I'm), тому So am I. Neither — лише у відповідь на заперечення."},{"type":"input","q":"I don't like this music. — Neither ___ I.","uk":"Мені не подобається ця музика. — Мені теж не подобається.","a":["do"],"why":"Present Simple, допоміжне do. Після neither дієслово стверджувальне: Neither do I, а не Neither don't I."},{"type":"order","uk":"Ти ж не замкнув фургон?","words":["lock","didn't","you","van","did","the","you"],"a":["You didn't lock the van, did you?"],"why":"Заперечення з didn't → стверджувальний хвостик did you. Хвостик стоїть у самому кінці, після коми."}],"section":"complex"},"phrasal-verbs":{"id":"phrasal-verbs","level":"B1","title":"Phrasal verbs","uk":"Фразові дієслова","summary":"pick up, turn off, give up: дієслово + частка = нове значення","minutes":8,"blocks":[{"t":"p","text":"**Фразове дієслово** — це звичайне дієслово + коротке слово-частка (**up, off, on, out, in, down, back, away**…). Разом вони мають **нове значення**, яке часто не вгадаєш з частин: give — давати, а **give up** — кинути (звичку), здатися. Look — дивитися, а **look after** — доглядати. Тому вчи їх як окремі слова."},{"t":"p","text":"В українській схожу роботу роблять префікси: писати — **за**писати — **пере**писати. В англійській такий «префікс» стоїть **після** дієслова й окремим словом: write — write **down** (записати). Носії вживають фразові дієслова постійно, особливо в розмові: на об'єкті ти почуєш **sort it out**, а не resolve the problem."},{"t":"ex","items":[["**Turn off** the light, please.","Вимкни світло, будь ласка."],["Don't **give up**!","Не здавайся!"],["Can you **pick up** that box?","Можеш підняти ту коробку?"]]},{"t":"h","text":"Найкорисніші: на роботі"},{"t":"table","head":["Дієслово","Значення"],"rows":[["set up","встановити, налаштувати"],["sort out","владнати, розібратися"],["work out","з'ясувати; тренуватися"],["carry on","продовжувати"],["fill in","заповнити (бланк)"],["find out","дізнатися"],["run out of","закінчитися (у тебе)"],["put off","відкласти на потім"],["turn up","з'явитися, прийти"],["pick up","підняти; забрати когось"],["get on with","ладнати з кимось"]]},{"t":"ex","items":[["We need to **set up** the scaffolding first.","Спершу треба поставити риштування."],["Don't worry, I'll **sort** it **out**.","Не хвилюйся, я все владнаю."],["We've **run out of** screws.","У нас закінчилися шурупи."],["**Fill in** your name and address here.","Впиши сюди своє ім'я та адресу."],["**Carry on**, you're doing great.","Продовжуй, у тебе чудово виходить."],["The new guy **turned up** late again.","Новенький знову прийшов пізно."],["I need to **find out** when the delivery is coming.","Мені треба дізнатися, коли буде доставка."],["Let's **put off** the meeting until Monday.","Давай перенесемо нараду на понеділок."]]},{"t":"h","text":"Найкорисніші: удома й щодня"},{"t":"table","head":["Дієслово","Значення"],"rows":[["get up","вставати (з ліжка)"],["put on","одягти, надягти"],["take off","зняти (одяг); злетіти"],["turn on / off","увімкнути / вимкнути"],["look for","шукати"],["look after","доглядати, наглядати"],["give up","кинути (звичку); здатися"],["check in / out","заселитися / виселитися"],["look forward to","чекати з нетерпінням"]]},{"t":"ex","items":[["Tom **gets up** at six.","Том встає о шостій."],["**Take off** your boots, please.","Зніми, будь ласка, черевики."],["What are you **looking for**?","Що ти шукаєш?"],["Olena **looks after** her mum.","Олена доглядає маму."],["You can **check in** after three.","Заселитися можна після третьої."],["Do you **get on with** your boss?","Ти ладнаєш зі своїм босом?"],["I **work out** at the gym three times a week.","Я тренуюся в спортзалі тричі на тиждень."]]},{"t":"h","text":"Роздільні: turn the light off"},{"t":"p","text":"У більшості фразових дієслів з **предметом** (тим, на що спрямована дія: світло, коробка, бланк, людина) частку можна поставити **двома способами**: одразу після дієслова або після предмета. Обидва варіанти правильні."},{"t":"rule","title":"Іменник: два варіанти","lines":["turn off **the light**","turn **the light** off"]},{"t":"rule","title":"Займенник: лише посередині","lines":["turn **it** off — правильно","turn off it — помилка"]},{"t":"tip","text":"Займенники **it, them, me, you, him, her, us** ставимо **тільки між** дієсловом і часткою: pick **me** up, fill **it** in, turn **them** off. Це найчастіша помилка з фразовими дієсловами."},{"t":"ex","items":[["**Turn off** the radio. **Turn** the radio **off**.","Вимкни радіо. (обидва варіанти правильні)"],["The radio is too loud. **Turn** it **off**.","Радіо надто гучне. Вимкни його."],["Here's the form. **Fill** it **in**, please.","Ось бланк. Заповни його, будь ласка."],["My car is in the garage. Can you **pick** me **up**?","Моя машина в ремонті. Можеш мене забрати?"],["**Put** your jacket **on**, it's cold.","Одягни куртку, холодно."]]},{"t":"tip","text":"Якщо предмет довгий (кілька слів або ціле речення), став частку одразу після дієслова: **pick up** all the tools on the floor, **find out** what time the shop opens. Частка в кінці, після довгого предмета, губиться і звучить незграбно."},{"t":"h","text":"Нероздільні: look after them"},{"t":"p","text":"Деякі фразові дієслова **не розділяються**: частка стоїть одразу після дієслова, а предмет — і іменник, і займенник — після неї: look **after** the kids → look after **them**, look **for** your keys → look for **them**. Які саме не розділяються, доведеться запам'ятати; з наших списків це **look for**, **look after**, **get on with**, **run out of**, **look forward to**. А деякі зазвичай узагалі без предмета: **get up**, **carry on**, **turn up** (прийти)."},{"t":"ex","items":[["Who **looks after** your kids?","Хто доглядає твоїх дітей?"],["I can't find my keys. Can you help me **look for** them?","Не можу знайти ключі. Допоможеш їх пошукати?"]]},{"t":"h","text":"Три частини: run out of, look forward to"},{"t":"p","text":"Деякі фразові дієслова мають **три частини**: дієслово + частка + прийменник: **run out of** (закінчитися), **get on with** (ладнати з кимось), **look forward to** (чекати з нетерпінням), **put up with** (терпіти). Предмет стоїть **у кінці**, після всіх частин: We've run out of **them**."},{"t":"tip","text":"Після **look forward to** дієслово має форму з **-ing** (seeing, working), бо to тут — прийменник, як у to Dublin, а не to перед початковою формою дієслова (to see): I look forward to **seeing** you. У листах: I look forward to **hearing** from you."},{"t":"ex","items":[["The van has **run out of** petrol.","У фургоні закінчився бензин."],["I **get on** well **with** my colleagues.","Я добре ладнаю з колегами."],["I'm **looking forward to** the weekend.","Чекаю не дочекаюся вихідних."],["I **look forward to hearing** from you.","Чекаю на вашу відповідь."],["I can't **put up with** this noise any more.","Я більше не можу терпіти цей шум."]]},{"t":"tip","text":"Одне фразове дієслово часто має **кілька значень**: **pick up** — підняти, забрати когось; **take off** — зняти (одяг), злетіти (про літак); **work out** — з'ясувати, тренуватися. Вчи їх цілими фразами: turn off the light, fill in the form, run out of petrol."},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"Turn off it, please.","right":"Turn it off, please.","why":"Займенник (it, them, me) стоїть лише між дієсловом і часткою."},{"t":"mistake","wrong":"Can you pick up me at six?","right":"Can you pick me up at six?","why":"Me — займенник, тому посередині: pick me up. З іменником можна обидва порядки: pick up Tom, pick Tom up."},{"t":"mistake","wrong":"I look forward to see you.","right":"I look forward to seeing you.","why":"Після look forward to — форма з -ing, бо to тут прийменник."},{"t":"mistake","wrong":"I'm looking my phone.","right":"I'm looking for my phone.","why":"«Шукати» — look for. Просто look без прийменника предмета не має: «дивитися на щось» — look at."},{"t":"mistake","wrong":"Can you look my dog after?","right":"Can you look after my dog?","why":"Look after не розділяється: і іменник, і займенник стоять після after: look after my dog, look after it."}],"tasks":[{"type":"choice","q":"It's dark in here. Can you ___ the light?","uk":"Тут темно. Можеш увімкнути світло?","opts":["turn on","turn off","take off"],"a":0,"why":"Увімкнути — turn on, вимкнути — turn off. Take off — зняти (одяг)."},{"type":"input","q":"Mick gave ___ smoking last year.","uk":"Мік кинув палити минулого року.","a":["up"],"why":"Кинути звичку — give up: give up smoking."},{"type":"choice","q":"We've run ___ milk.","uk":"У нас закінчилося молоко.","opts":["out of","out","off"],"a":0,"why":"«Закінчилося щось» — run out of + те, що закінчилося. Of тут обов'язкове."},{"type":"input","q":"I'm looking ___ my phone. Have you seen it?","uk":"Я шукаю свій телефон. Ти його не бачив?","a":["for"],"why":"Шукати — look for. Look at — дивитися на, look after — доглядати."},{"type":"choice","q":"Tom will ___ the new TV for us.","uk":"Том підключить нам новий телевізор.","opts":["set up","give up","put off"],"a":0,"why":"Встановити, підключити техніку — set up. Give up — кинути, put off — відкласти."},{"type":"choice","q":"Mick didn't ___ today. Is he ill?","uk":"Мік сьогодні не прийшов. Він захворів?","opts":["turn up","carry on","find out"],"a":0,"why":"З'явитися, прийти — turn up. Carry on — продовжувати, find out — дізнатися."},{"type":"input","q":"Please fill ___ this form.","uk":"Будь ласка, заповни цю форму.","a":["in","out"],"why":"Заповнити бланк — fill in (у Британії й Ірландії найчастіше) або fill out."},{"type":"choice","task":"Яке речення правильне?","q":"","uk":"Вимкни його, будь ласка.","opts":["Turn off it, please.","Turn it off, please.","Turn it, please, off."],"a":1,"why":"Займенник it стоїть між дієсловом і часткою: turn it off."},{"type":"input","q":"Can you pick ___ up at seven?","uk":"Можеш забрати мене о сьомій?","a":["me"],"why":"Займенник ставимо між дієсловом і часткою: pick me up."},{"type":"choice","q":"I'm looking forward to ___ you.","uk":"Чекаю не дочекаюся зустрічі з тобою.","opts":["see","seeing","saw"],"a":1,"why":"Після look forward to — форма з -ing, бо to тут прийменник: looking forward to seeing you."},{"type":"order","uk":"Надягни каску.","words":["hat","on","your","put","hard"],"a":["Put your hard hat on.","Put on your hard hat."],"why":"Put on — роздільне дієслово: з іменником частка може стояти до нього або після нього."},{"type":"order","uk":"Хто їх доглядає, коли ти на роботі?","words":["work","them","when","looks","at","who","you're","after"],"a":["Who looks after them when you're at work?","When you're at work, who looks after them?"],"why":"Look after не розділяється, тому them після after. «На роботі» — at work."}],"section":"everyday"},"make-do-get-have":{"id":"make-do-get-have","level":"B1","title":"Make, do, get, have","uk":"Дієслова make, do, get, have","summary":"make чи do, значення get, have lunch і have something done","minutes":8,"blocks":[{"t":"p","text":"Українською ми «робимо» і помилку, і покупки, і чай. Англійською це різні дієслова: **make** і **do**. А **get** і **have** мають стільки значень, що їх найпростіше вчити готовими словосполученнями. Тут зібрано ті, які кажуть щодня, зокрема на роботі."},{"t":"h","text":"Make — створюємо щось нове"},{"t":"p","text":"**Make** — коли в результаті з'являється щось нове: чай, шум, гроші, рішення, план. Логіка працює не завжди, тож найнадійніше запам'ятати вирази цілком."},{"t":"table","head":["Вираз","Значення"],"rows":[["make a **mistake**","помилитися"],["make a **decision**","ухвалити рішення"],["make **money**","заробляти гроші"],["make a **phone call**","подзвонити"],["make **noise**","шуміти"],["make **tea**, make **dinner**","заварити чай, приготувати вечерю"],["make **plans**","будувати плани"],["make an **effort**","докласти зусиль"],["make **sure**","переконатися, перевірити"]]},{"t":"ex","items":[["I **made** a mistake with the measurements.","Я помилився із замірами."],["We need to **make** a decision today.","Нам треба сьогодні ухвалити рішення."],["He **makes** good money in Dublin.","Він добре заробляє в Дубліні."],["Can you **make** less noise? The baby's asleep.","Можна тихіше? Дитина спить."],["**Make** sure the door is locked.","Перевір, чи замкнені двері."]]},{"t":"h","text":"Do — дія, робота, щоденні справи"},{"t":"p","text":"**Do** — коли йдеться про саму дію чи роботу, а не про результат: робота, домашні справи, навчання. А ще з загальними словами **something, anything, nothing, everything** у значенні «робити щось» кажемо **do**: Do something! I did nothing. (Make something — «змайструвати чи приготувати щось».)"},{"t":"table","head":["Вираз","Значення"],"rows":[["do **work**, do **a job**","працювати, виконувати роботу"],["do the **shopping**","робити покупки"],["do the **washing up**","мити посуд"],["do **homework**","робити домашнє завдання"],["do someone **a favour**","зробити комусь послугу"],["do your **best**","старатися з усіх сил"],["do **business**","вести бізнес"],["do **nothing**","нічого не робити"]]},{"t":"ex","items":[["I **do** the shopping on Saturdays.","Я роблю покупки по суботах."],["Who **did** the plastering in this room?","Хто штукатурив цю кімнату?"],["Who **does** the washing up in your house?","Хто у вас удома миє посуд?"],["I **did** nothing all weekend.","Я всі вихідні нічого не робив."],["Don't worry, just **do** your best.","Не хвилюйся, просто старайся як можеш."]]},{"t":"tip","text":"Підказка: робота й справи на **-ing** — це **do**: do the cleaning, do the ironing, do the plastering. А фото — ні make, ні do: **take** a photo. Перерва — **take** a break або **have** a break."},{"t":"h","text":"Get — найуніверсальніше дієслово"},{"t":"p","text":"**Get** має багато значень, і в розмові його чуєш на кожному кроці. Часто це простіше слово замість receive (отримати), buy (купити), become (стати), arrive (прибути) чи understand (зрозуміти)."},{"t":"table","head":["Значення","Приклад"],"rows":[["отримати","get a **message**, get **paid**"],["купити, взяти","get some **milk**"],["стати (змінитися)","get **tired**, get **wet**, get **dark**"],["одружитися","get **married**"],["дістатися","get **home**, get **to work**"],["зрозуміти","I **get** it."],["мати (have got)","I've **got** a van."]]},{"t":"ex","items":[["Did you **get** my message?","Ти отримав моє повідомлення?"],["Can you **get** some milk on the way home?","Можеш купити молока дорогою додому?"],["We all **got** wet on the site.","Ми всі промокли на об'єкті."],["They **got** married last year.","Вони одружилися торік."],["What time do you **get** to work?","О котрій ти приїжджаєш на роботу?"],["Sorry, I don't **get** it.","Вибач, я не розумію."]]},{"t":"tip","text":"Дістатися кудись — **get to** + місце: get to work, get to Dublin. Але **get home** і **get there** без to, так само як go home."},{"t":"h","text":"Have і have got"},{"t":"p","text":"**Have** означає «мати»: I have a van. У Британії та Ірландії в розмові частіше кажуть **have got**: I've got a van. Have you got a pen? She hasn't got a car. Але have — це ще й дія: з їжею, душем, перервою have означає «робити це». У такому значенні have got **не вживають**, а форму з -ing можна: I'm having lunch."},{"t":"table","head":["Вираз","Значення"],"rows":[["have **breakfast / lunch / dinner**","снідати / обідати / вечеряти"],["have a **shower**","приймати душ"],["have a **break**","робити перерву"],["have a **look**","подивитися"],["have **fun**, have a good time","розважатися, гарно проводити час"],["have a **chat**","поговорити, побалакати"]]},{"t":"ex","items":[["**Have** you **got** a pen?","У тебе є ручка?"],["She **hasn't got** a car.","У неї немає машини."],["We usually **have** lunch in the van.","Ми зазвичай обідаємо у фургоні."],["Let me **have** a look.","Дай гляну."],["I'm **having** a shower — can you call back?","Я в душі, можеш передзвонити?"],["**Have** fun tonight!","Гарно проведи вечір!"]]},{"t":"tip","text":"Have got — лише в значенні «мати» (і ще have got to — «мусити») і лише в теперішньому часі. Про минуле — **had**: Tom **had** a van last year. А їжа, душ, перерва — тільки have: I **have** lunch at one, а не I've got lunch."},{"t":"h","text":"Have something done — хтось робить для тебе"},{"t":"p","text":"Коли роботу робиш не сам, а за тебе робить майстер чи сервіс, кажемо **have + річ + V3**. V3 — третя форма дієслова: done, cut, serviced, painted. Українською ми кажемо «я підстригся» або «я поміняв шини», хоча робив це хтось інший. А англійською I cut my hair означає, що ти стриг себе сам. У розмові замість have часто кажуть **get**: I'm **getting** my hair cut."},{"t":"rule","title":"Формула","lines":["**have** + річ + **V3**","I **had** my car **serviced**.","розмовне: **get** + річ + **V3**"]},{"t":"ex","items":[["I **had** my car **serviced** last week.","Минулого тижня я віддав машину на ТО."],["Where do you **get** your hair **cut**?","Де ти стрижешся?"],["We're **having** the kitchen **painted**.","Нам фарбують кухню."],["You should **get** that tooth **checked**.","Тобі варто показати той зуб лікареві."]]},{"t":"h","text":"Make і let: змусити й дозволити"},{"t":"p","text":"**Make someone do** — змусити когось щось зробити. **Let someone do** — дозволити. Після обох — початкова форма дієслова (як у словнику: work, help) **без to**. Це незвично, бо після want, ask, tell, allow to потрібне: He asked me **to** stay."},{"t":"ex","items":[["His parents **made** him **learn** English.","Батьки змушували його вчити англійську."],["That film **made** me **cry**.","Я плакав від того фільму."],["**Let** me **help** you.","Дай я тобі допоможу."],["Sarah's landlord doesn't **let** her **keep** a dog.","Господар квартири не дозволяє Сарі тримати собаку."]]},{"t":"h","text":"Типові помилки"},{"t":"mistake","wrong":"I did a mistake.","right":"I made a mistake.","why":"Помилка — завжди make: make a mistake."},{"t":"mistake","wrong":"I have to make my homework.","right":"I have to do my homework.","why":"Домашнє завдання — do. Make — коли створюємо щось нове."},{"t":"mistake","wrong":"Can you make a photo of us?","right":"Can you take a photo of us?","why":"Фотографувати — take a photo. Ні make, ні do тут не кажуть."},{"t":"mistake","wrong":"I had cut my hair at the barber's.","right":"I had my hair cut at the barber's.","why":"Стриг перукар, тому have + річ + V3: had my hair cut. I had cut my hair — інший час, і стриг ти сам."},{"t":"mistake","wrong":"He made me to work late.","right":"He made me work late.","why":"Після make і let дієслово без to: made me work, let me help (а не let me to help)."}],"tasks":[{"type":"choice","q":"Sorry, I ___ a mistake.","uk":"Вибач, я помилився.","opts":["did","made","had"],"a":1,"why":"Помилка — make a mistake. Do з mistake не вживаємо, хоч українською й кажемо «зробити помилку»."},{"type":"choice","q":"I usually ___ the shopping on Saturdays.","uk":"Я зазвичай роблю покупки по суботах.","opts":["make","do","have"],"a":1,"why":"Покупки й інші щоденні справи — do: do the shopping, do the washing up."},{"type":"choice","q":"Can you ___ a photo of us?","uk":"Можеш нас сфотографувати?","opts":["make","do","take"],"a":2,"why":"Фотографувати — take a photo. Make і do з photo не вживаємо."},{"type":"input","q":"Can you ___ me a favour?","uk":"Можеш зробити мені послугу?","a":["do"],"why":"Послуга — do someone a favour. Make тут не кажуть."},{"type":"input","q":"I've ___ two brothers.","uk":"У мене двоє братів.","a":["got"],"why":"«Мати» в розмові — have got: I've got = I have got. Так часто кажуть у Британії та Ірландії замість простого I have."},{"type":"choice","q":"We usually ___ lunch at one o'clock.","uk":"Ми зазвичай обідаємо о першій.","opts":["have","have got","make"],"a":0,"why":"Обідати — have lunch. Have got означає лише «мати» і не вживається для звичних дій, а make lunch — «готувати обід»."},{"type":"input","q":"It's ___ (get) dark. Let's finish for today.","uk":"Темніє. Давай на сьогодні закінчимо.","a":["getting"],"why":"Get у значенні «ставати»: get dark — темніти. Це відбувається саме зараз, тому It's getting."},{"type":"choice","q":"What time did you get ___ last night?","uk":"О котрій ти вчора ввечері дістався додому?","opts":["home","to home","at home"],"a":0,"why":"Get home — без to, як go home. З іншими місцями to потрібне: get to work, get to Dublin."},{"type":"choice","q":"We had the windows ___ yesterday.","uk":"Нам учора замінили вікна.","opts":["replace","replaced","replacing"],"a":1,"why":"Роботу зробили за нас: have + річ + V3. Третя форма від replace — replaced."},{"type":"input","q":"The boss made us ___ (work) on Saturday.","uk":"Бос змусив нас працювати в суботу.","a":["work"],"why":"Після make + хтось дієслово без to: made us work, а не made us to work."},{"type":"choice","q":"Kate's dad didn't ___ her drive his car.","uk":"Тато Кейт не дозволяв їй водити його машину.","opts":["let","make","allow"],"a":0,"why":"«Дозволяти» — let + хтось + дієслово без to. Allow теж означає «дозволяти», але після нього потрібне to: allow her to drive."},{"type":"order","uk":"Учора мені підстригли волосся.","words":["hair","had","yesterday","my","I","cut"],"a":["I had my hair cut yesterday.","Yesterday I had my hair cut."],"why":"Стриг перукар, тому have + річ + V3: had my hair cut. Yesterday — у кінці або на початку речення."}],"section":"everyday"}}};
